window.__D("text/zohar-hebrew-translation/c023",{"p":[[9522011909,"<p>הַהֵיכָל הַשְּׁלִישִׁי, הַהֵיכָל הַזֶּה הוּא הֵיכָל שֶׁעוֹמֵד בְּאוֹר עֶלְיוֹן יוֹתֵר עַל כָּל הַקּוֹדְמִים הַלָּלוּ. בַּהֵיכָל הַזֶּה קַיָּמִים אַרְבָּעָה פְתָחִים; אֶחָד לְצַד דָּרוֹם, וְאֶחָד לְצַד מִזְרָח, וְאֶחָד לְצַד צָפוֹן, וְאֶחָד לְצַד מַעֲרָב. בְּכָל פֶּתַח וּפֶתַח יֵשׁ מְמֻנֶּה אֶחָד, שֶׁעוֹמֵד מְמֻנֶּה עַל כָּל פֶּתַח וּפֶתַח.</p>\n<p>הַפֶּתַח הָרִאשׁוֹן, זֶה פֶּתַח שֶׁעוֹמֵד בּוֹ מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ מַלְכִּיאֵ\"ל, וְהוּא שׁוֹלֵט עַל כָּל אוֹתָם פְּתָקִים שֶׁיּוֹצְאִים מִבֵּית דִּינוֹ שֶׁל הַמֶּלֶךְ לָדוּן אֶת הָעוֹלָם. (באותו פתק) מִשּׁוּם שֶׁזֶּה הוּא הַמְמֻנֶּה לְהַשְׁגִּיחַ בְּאוֹתָם הַפְּתָקִים, וּשְׁנֵי סוֹפְרִים תַּחַת יָדוֹ, אֶחָד מִיָּמִין וְאֶחָד מִשְּׂמֹאל.</p>\n<p>לָזֶה נִתְּנוּ תִקּוּנֵי הַפְּתָקִים לְהַתְקִין טֶרֶם שֶׁיֵּצְאוּ מֵהַשַּׁעַר הַזֶּה הַחוּצָה וְיִמָּסְרוּ לִידֵי אוֹתוֹ הַמְמֻנֶּה שֶׁבַּהֵיכָל הָרִאשׁוֹן. שֶׁהֲרֵי מִזְּמַן שֶׁנִּמְסְרוּ בְּיַד אוֹתוֹ הַמְמֻנֶּה שֶׁבַּהֵיכָל הָרִאשׁוֹן, הֲרֵי יָצְאוּ מִשָּׁם, וְאֵין רְשׁוּת לַהֲשִׁיבָם.</p>\n<p>שֶׁהֲרֵי מִיָּד מִזְדַּמֵּן מְמֻנֶּה שֶׁל הַצַּד הָאַחֵר הַטָּמֵא בַּעַל הַדִּין הַקָּשֶׁה הַתַּקִּיף, שֶׁלֹּא מְרַחֵם, וּשְׁמוֹ סַנְגָּדִיאֵ\"ל (וסהדיאל), וְהוּא מְמֻנֶּה עַל שַׁעַר הַהֵיכָל הָרִאשׁוֹן (האחר) שֶׁבַּצַּד הָאַחֵר, שֶׁהוּא גֵּיהִנֹּם, וְכַמָּה הֵם שׁוֹמְרֵי הַחֻקִּים מְמֻנִּים לְשׁוֹטֵט בָּעוֹלָם וּמְזֻמָּנִים לַעֲשׂוֹת דִּין.</p>\n<p>וּמִשּׁוּם כָּךְ עוֹמֵד אוֹתוֹ הַמְמֻנֶּה לְעַיֵּן בַּפְּתָקִים, וְאוֹתָם שְׁנֵי הַסּוֹפְרִים שֶׁעוֹמְדִים תַּחַת הַמְמֻנֶּה הַזֶּה, שַׁמָּשִׁיאֵ\"ל וְקָמוּאֵ\"ל, אֵלּוּ הַסּוֹפְרִים לְתַקֵּן הַפְּתָקִים, וְאוֹתוֹ הַמְמֻנֶּה עֲלֵיהֶם שֶׁהוּא מַלְכִּיאֵ\"ל. מִשּׁוּם שֶׁבְּאוֹתָם הַהֵיכָלוֹת שֶׁבַּצַּד הָאַחֵר הַטָּמֵא נִפְקְדוּ מְמֻנִּים יְדוּעִים, בְּהֵפֶךְ מֵהַמְמֻנִּים הַלָּלוּ שֶׁבַּהֵיכָלוֹת הַלָּלוּ, וְכָל אוֹתָן רוּחוֹת וְכָל אוֹתָם הַמְמֻנִּים שֶׁשָּׁם, כֻּלָּם לְהָרַע.</p>\n<p>בֹּא וּרְאֵה, הַסַּנְגָּדִיאֵ\"ל (סעדיאל) הַזֶּה, כְּשֶׁנּוֹטֵל פֶּתֶק, מִצַּד שֶׁל אוֹתוֹ הַמְמֻנֶּה שֶׁעוֹמֵד לַפֶּתַח הָרִאשׁוֹן, פּוֹתֵחַ פֶּתַח אֶחָד לְצַד הַחֲשֵׁכָה, שֶׁנִּקְרָא בְּאֵר שַׁחַת, וְשָׁם מְמֻנִּים אֶלֶף וּרְבָבוֹת מְזֻמָּנִים לִטֹּל אוֹתָם הַפְּתָקִים, וְהַמְמֻנֶּה הַזֶּה עֲלֵיהֶם. וְאָז יוֹצְאִים הַכָּרוֹזִים, וְכַמָּה שׁוֹטְרִים מְשׁוֹטְטִים בָּעוֹלָם, וְאוֹתוֹ הַדִּין נִשְׁלָם. וְעַל כֵּן הַמְמֻנֶּה הַזֶּה עוֹמֵד לְעַיֵּן בַּפְּתָקִים וּלְהַתְקִין הַנְהָגוֹת הַפְּתָקִים טֶרֶם שֶׁיֵּצְאוּ מֵהַפֶּתַח הַזֶּה, וְהַפֶּתַח הַזֶּה הוּא פֶּתַח הַדָּרוֹם.</p>\n<p>הַפֶּתַח הַשֵּׁנִי, זֶהוּ פֶּתַח שֶׁחַיִּים וּמָוֶת תְּלוּיִים בּוֹ, מִשּׁוּם שֶׁהַפֶּתַח הַזֶּה חוֹתְמִים חֲתִימוֹת שֶׁל כָּל הַפְּתָקִים. שֶׁכֵּיוָן שֶׁהַפְּתָקִים נִתְקְנוּ כָּרָאוּי, שַׁמָּשׁ אֶחָד מְזֻמָּן, שֶׁשְּׁמוֹ גַּזְרִיאֵ\"ל, וְנוֹטֵל פְּתָקִים בַּפֶּתַח הַשֵּׁנִי הַזֶּה, וְשָׁם חוֹתְמִים אוֹתוֹ.</p>\n<p>מְמֻנֶּה אֶחָד עוֹמֵד עַל אוֹתוֹ הַפֶּתַח, וּשְׁמוֹ עַזְרִיאֵ\"ל, וְכָל פֶּתַח וּפֶתַח נִקְרָא עַל שֵׁם אוֹתוֹ הַמְמֻנֶּה שֶׁנִּפְקָד עָלָיו. תַּחַת שִׁלְטוֹנוֹ וְתַחַת יָדוֹ שֶׁל הַמְמֻנֶּה הַזֶּה שְׁנֵי שַׁמָּשִׁים, שֶׁשְּׁמָם (סטריה) סָנוּרִיָּ\"א עָדִיאֵ\"ל. אֶחָד מִיָּמִין וְאֶחָד מִשְּׂמֹאל. אוֹתוֹ שֶׁמִּיָּמִין, בּוֹ תְּלוּיִים הַחַיִּים. וְאוֹתוֹ שֶׁל הַשְּׂמֹאל, בּוֹ תָּלוּי הַמָּוֶת. וּשְׁנֵי חוֹתָמוֹת בִּידֵיהֶם - חוֹתַם חַיִּים וְחוֹתַם מָוֶת. זֶה עוֹמֵד לְצַד זֶה, וְזֶה עוֹמֵד לְצַד זֶה.</p>\n<p>הַפֶּתַח הַזֶּה סָתוּם כָּל יְמוֹת הַשָּׁנָה, וּבִימֵי שַׁבָּת וּבִימֵי הַחֹדֶשׁ נִפְתָּח, לְהַרְאוֹת חַיִּים בְּאוֹתוֹ הַחוֹתָם שֶׁתְּלוּיִים בּוֹ חַיִּים, מִשּׁוּם שֶׁשַּׁבָּת וְחֹדֶשׁ מִתְקַיֵּם בָּהֶם חוֹתַם הַחַיִּים.</p>\n<p>וּבְיוֹם הַכִּפּוּרִים, שֶׁכָּל יִשְׂרָאֵל עוֹמְדִים בִּתְפִלּוֹת וּבַקָּשׁוֹת וּמִשְׁתַּדְּלִים בַּעֲבוֹדַת רִבּוֹנָם, אוֹתוֹ הַפֶּתַח סָתוּם, עַד שְׁעַת הַמִּנְחָה. כֵּיוָן שֶׁעוֹבֶרֶת תְּפִלַּת הַמִּנְחָה הַזּוֹ, מִמְּקוֹם בֵּית הַדִּין שֶׁל הֵיכַל הַזְּכוּת יוֹצֵא אֲוִיר אֶחָד, וְהַפֶּתַח הַזֶּה נִפְתָּח, וְהַמְמֻנֶּה הַזֶּה שֶׁל הַהֵיכָל הַזֶּה עוֹמֵד, וְאוֹתָם שְׁנֵי שַׁמָּשִׁים, אֶחָד מִיָּמִין וְאֶחָד מִשְּׂמֹאל, וְחוֹתְמוֹת הַחַיִּים וְהַמָּוֶת בִּידֵיהֶם וְכָל פִּתְקֵי הָעוֹלָם לִפְנֵיהֶם, וְאָז חוֹתְמִים - הֵן לְחַיִּים הֵן לְמָוֶת. וְזֶהוּ פֶּתַח הַמִּזְרָח.</p>\n<p>הַפֶּתַח הַשְּׁלִישִׁי, זֶהוּ פֶּתַח שֶׁעוֹמֵד בְּקִיּוּם לָדַעַת כָּל אוֹתָם שֶׁיַּעֲבֹר עֲלֵיהֶם דִּין, בֵּין לְמַחֲלוֹת, בֵּין לְמַכְאוֹבִים, בֵּין לְעֹנִי. דִּין שֶׁלֹּא עוֹבֵר לְמָוֶת. כְּשֶׁשַּׁעַר הַפֶּתַח הַזֶּה סָגוּר, אָז הַדִּין נִרְשָׁם עַל הָאָדָם, שֶׁלֹּא מְשִׁיבִים אוֹתוֹ, רַק בְּכֹחַ שֶׁל תְּפִלָּה חֲזָקָה וּתְשׁוּבָה שְׁלֵמָה, שֶׁכָּתוּב (איוב יב) יִסְגֹּר עַל אִישׁ וְלֹא יִפָּתֵחַ.</p>\n<p>מְמֻנֶּה אֶחָד עוֹמֵד עַל הַפֶּתַח הַזֶּה, וּשְׁמוֹ קַפְצִיאֵ\"ל, וְזֶה מְמֻנֶּה עַל הַפֶּתַח הַזֶּה כְּדֵי לִסְגֹּר אֶת הַפֶּתַח הַזֶּה עַל אוֹתוֹ הָאָדָם שֶׁרָאוּי לְהֵעָנֵשׁ, כְּדֵי שֶׁלֹּא יִתְקַבֵּל בִּתְפִלָּה עַד שֶׁיָּשׁוּב לִפְנֵי רִבּוֹנוֹ.</p>\n<p>וּבְאוֹתוֹ זְמַן שֶׁנִּגְזָר דִּין בְּבָנָיו שֶׁלֹּא חָטְאוּ, בְּאוֹתָם הַתִּינוֹקוֹת הַקְּטַנִּים, מְמֻנֶּה אֶחָד שַׁמָּשׁ תַּחַת יָדוֹ, שְׁמוֹ עִירִיאֵ\"ל, וְיוֹצֵא וּמַכְרִיז לְצַד שְׂמֹאל, עַד שֶׁמִּתְעוֹרֶרֶת רוּחַ אַחַת שֶׁהִיא רוּחַ שֶׁל פְּגָם שֶׁנִּבְרָא בִּפְגַם הַלְּבָנָה וְנִקְרָא אַסְכָּרָ\"א, וְזוֹהִי הָרוּחַ שֶׁעוֹמֶדֶת עַל דַּרְגָּה (פתח) רְבִיעִית בַּהֵיכָל הַשְּׁלִישִׁי שֶׁבְּצַד הַטֻּמְאָה, וְזֶה עוֹמֵד עַל הַהֶרֶג שֶׁלָּהֶם, וְנִרְאֶה לַתִּינוֹקוֹת כְּמוֹ אִשָּׁה שֶׁמְּגַדֶּלֶת יְלָדִים וְאוֹחֶזֶת אוֹתָם וְהוֹרֶגֶת אוֹתָם.</p>\n<p>וְאָז אוֹתָהּ נְשָׁמָה עוֹלָה, וְאוֹחֵז אוֹתָהּ הַמְמֻנֶּה הַזֶּה, וּמַעֲלֶה אוֹתָהּ לַמְמֻנֶּה שֶׁעוֹמֵד עַל הַהֵיכָל הָרְבִיעִי, וְאוֹתוֹ מְמֻנֶּה מְגַדֵּל אוֹתָם וּמִשְׁתַּעֲשֵׁעַ בָּהֶם וּמַעֲלֶה אוֹתָם לְהֵרָאוֹת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ בְּכָל שַׁבָּת וְשַׁבָּת, וּבְכָל רֹאשׁ חֹדֶשׁ וְרֹאשׁ חֹדֶשׁ, וְנִרְאִים לְפָנָיו וּמִתְבָּרְכִים מִמֶּנּוּ. וּבְשָׁעָה שֶׁרֹגֶז שׁוֹלֵט, מִסְתַּכֵּל בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא וְחָס עַל הָעוֹלָם.</p>\n<p>וְכָל אוֹתָם הַתִּינוֹקוֹת שֶׁלֹּא הִשְׁלִימוּ שָׁנִים, עַד שְׁלֹשׁ עֶשְׂרֵה שָׁנִים וְיוֹם אֶחָד, כֻּלָּם נִמְסָרִים בְּיָדוֹ שֶׁל זֶה. מִשְּׁלֹשׁ עֶשְׂרֵה שָׁנִים עַד עֶשְׂרִים, כֻּלָּם נִמְסָרִים עַל יְדֵי רוּחַ אַחֶרֶת שֶׁנִּקְרֵאת אָגִירִיסוֹ\"ן, שֶׁיּוֹצֵאת מֵהַנָּחָשׁ (העקם) הֶעָמֹק הַזֶּה שֶׁגָּרַם מָוֶת לְכָל הָעוֹלָם, וְהוּא יֵצֶר הָרָע. מֵעֶשְׂרִים שָׁנִים וָמַעְלָה, נִדּוֹן הָעוֹלָם מִבֵּית דִּין, הַמָּקוֹם שֶׁנִּקְרָא זְכוּת, הוּא בְּעַצְמוֹ בָּא, וּבַחֲטָאָיו נִדּוֹן, וְנִמְסָר בְּיַד הַנָּחָשׁ הַזֶּה שֶׁהוּא מַלְאַךְ הַמָּוֶת.</p>\n<p>(משום שהרי מעשרים שנה ומטה עד שלש עשרה שנים), הָרוּחַ הַזּוֹ שֶׁעוֹמֶדֶת בּוֹ כְּנָחָשׁ הוֹלֶכֶת אַחֲרָיו, זֶה אָגִירִיסוֹ\"ן שֶׁאָמַרְנוּ, כִּי לֹא נִשְׁמַר כְּשֶׁהָיָה יֶלֶד קָטָן כָּרָאוּי, וְרָאָה בּוֹ סִימָן שֶׁיִּפָּגֵם אַחַר כָּךְ. וְזֶה נִלְקַח בְּלִי רְשׁוּת, וְעַל זֶה כָּתוּב (משלי יג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. וְסוֹד זֶה כָּתוּב, וְהִנֵּה טוֹב מְאֹד. וְשָׁנִינוּ, (בראשית א) וְהִנֵּה טוֹב מְאֹד - זֶה מַלְאַךְ הַמָּוֶת, שֶׁמַּקְדִּים אוֹתוֹ טֶרֶם שֶׁיִּפָּגֵם לְאַחַר מִכֵּן. וְהַמְמֻנֶּה הַזֶּה שֶׁעוֹמֵד עַל הַפֶּתַח הַזֶּה מַכְנִיס נִשְׁמָתוֹ וּמַעֲלֶה אוֹתָהּ לְמַעְלָה.</p>\n<p>מִשְּׁלש עֶשְׂרֵה שָׁנִים וָמַטָּה נִדּוֹן עַל חֲטָאֵי אָבִיו, וְנִמְסָר בְּיַד הָאַסְכָּרָא הַזֶּה שֶׁאָמַרְנוּ. וְכָל אֶחָד וְאֶחָד, הֵיכָל זֶה כְּנֶגֶד הֵיכָל זֶה. זֶה בְּהֵפֶךְ מִזֶּה, כְּפִי שֶׁאָמַרְנוּ, וְהַפֶּתַח הַזֶּה הוּא לְצַד צָפוֹן.</p>\n<p>הַפֶּתַח הָרְבִיעִי, הַפֶּתַח הַזֶּה עוֹמֵד לִרְפוּאָה, וְנִקְרָא פֶּתַח הָרְפוּאָה. בַּפֶּתַח הַזֶּה עוֹמֵד מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ פְּדִיאֵ\"ל, וְזֶה עוֹמֵד עַל כָּל אוֹתָן הָרְפוּאוֹת שֶׁל הָעוֹלָם, וּלְהַכְנִיס תְּפִלּוֹת שֶׁל כָּל אוֹתָם בַּעֲלֵי מַכְאוֹבִים וּמַחֲלוֹת וָצַעַר. וְזֶהוּ עוֹלֶה עִם כָּל (לכל) אוֹתָן הַתְּפִלּוֹת, וּמַכְנִיס אוֹתָן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְזְהִוּ (איוב לג) מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף. מִשּׁוּם שֶׁאוֹתָם הָאֶלֶף עוֹמְדִים בְּאוֹתוֹ הַפֶּתַח, וְזֶה אֶחָד מֵהֶם. וְכָתוּב וַיְחֻנֶּנּוּ וַיֹּאמֶר פְּדָעֵהוּ מֵרֶדֶת שַׁחַת מָצָאתִי כֹפֶר. מִשּׁוּם שֶׁעוֹלֶה (לזו) עִם הַתְּפִלָּה הַזּוֹ וְעוֹמֵד מֵלִיץ טוֹב עַל הָאָדָם, וּמַזְכִּיר זְכוּתוֹ שֶׁעָשָׂה לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, מִשּׁוּם שֶׁזֶּהוּ שֶׁעוֹמֵד תָּמִיד לְטוֹב, וְעַל כֵּן, כָּל רְפוּאָה עוֹמֶדֶת בַּפֶּתַח שֶׁפָּדִיאֵ\"ל מְמֻנֶּה בּוֹ. הַפֶּתַח הַזֶּה הוּא לְצַד מַעֲרָב. וּמִשּׁוּם זֶה אַרְבַּעַת הַפְּתָחִים הַלָּלוּ עוֹמְדִים בַּהֵיכָל הַזֶּה.</p>\n<p>בַּהֵיכָל הַזֶּה עוֹמֶדֶת רוּחַ אַחַת שֶׁנִּקְרֵאת נֹגַהּ. זוֹהִי רוּחַ הַשּׁוֹלֶטֶת בַּהֵיכָל הַזֶּה. כָּל זִיו וְכָל תְּשׁוּקָה עוֹמְדִים בּוֹ. הָרוּחַ הַזּוֹ עוֹמֶדֶת לְכָל אוֹתָם שֶׁיֵּשׁ לָּהֶם חֵלֶק בָּעוֹלָם הַבָּא. זֶה מְעַטֵּר אֶת אוֹתָן הַנְּשָׁמוֹת בְּזִיו שֶׁל כָּבוֹד, כְּדֵי לְהוֹדִיעַ לְכָל אוֹתָן רוּחוֹת שֶׁבַּהֵיכָלוֹת הָאֲחֵרִים שֶׁזֶּהוּ בֶּן הָעוֹלָם הַבָּא, וְיַעֲבֹר בְּכֻלָּם, וְאֵין מִי שֶׁמּוֹחֶה בְיָדוֹ.</p>\n<p>הָרוּחַ הַזּוֹ הִיא רוּחַ טְהוֹרָה בְּרוּרָה מֵהַתַּחְתּוֹנִים הַלָּלוּ, וּשְׁמָהּ זָהֲרִיאֵ\"ל, מֵאוֹתוֹ שֶׁמֶן מִשְׁחַת קֹדֶשׁ שֶׁשּׁוֹפֵעַ מִן הָעוֹלָם הַבָּא שׁוֹפֵעַ בּוֹ, וּמֵאוֹתוֹ שֶׁמֶן נִבְרָא (גדל) וְצוֹמֵחַ. וְזֶהוּ נֵר, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קלד) עָרַכְתִּי נֵר לִמְשִׁיחִי. מִשּׁוּם שֶׁזֶּהוּ הַסִּדּוּר לְהַדְלִיק הַנֵּרוֹת מִלְּמַטָּה לְמַעְלָה, כְּשֶׁשּׁוֹרֶה עָלָיו אוֹר שֶׁשּׁוֹפֵעַ מִלְמַעְלָה, מִשּׁוּם שֶׁזֶּה מְסֻדָּר כְּשֶׁנִּכְלְלוּ בוֹ כָּל אוֹתָם הַתַּחְתּוֹנִים שֶׁלְּמַטָּה.</p>\n<p>וּכְשֶׁמִּסְתַּדֶּרֶת הָרוּחַ הַזּוֹ בְּכָל אוֹתָם הַתַּחְתּוֹנִים וּמְאִירָה, אָז מוֹצִיאָה מִמֶּנָּה אוֹר אֶחָד, שֶׁשְּׁמוֹ אַקַרִיאֵ\"ל (אהדיא\"ל), וְזֶה כָּלוּל בָּרוּחַ הַזּוֹ. זֶה עוֹמֵד תַּחַת הָרוּחַ (הזו) לִמְשֹׁךְ (למשח) אֶת כָּל אוֹתָן נְשָׁמוֹת שֶׁעוֹלוֹת, שֶׁיֵּשׁ לָהֶן חֵלֶק לָעוֹלָם הַבָּא וּרְאוּיוֹת לַעֲלוֹת לְמַעְלָה.</p>\n<p>מִשּׁוּם שֶׁכְּשֶׁנְּשָׁמָה עוֹלָה וְנִכְנֶסֶת לְאוֹתָם הַהֵיכָלוֹת הַתַּחְתּוֹנִים, רְשׁוּמָה הִיא בְּעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת הַתּוֹרָה שֶׁרְשׁוּמוֹת בַּנְּשָׁמָה הַזּוֹ. וּכְשֶׁנְּשָׁמָה זוֹכָה וְעוֹמֶדֶת לִפְנֵי אוֹתָהּ הָרוּחַ, הַמְמֻנֶּה הַזֶּה אַהֲדִיאֵ\"ל מוֹשֵׁחַ אוֹתָם, וְעוֹלִים וְנִכְנָסִים לְאוֹתוֹ נְהַר דִּינוּר, וְעוֹלִים וְנִקְרָבִים לְקָ רְבָּן.</p>\n<p>הָאוֹר הַזֶּה כָּלוּל בִּשְׁלֹשָׁה אוֹרוֹת, מִשּׁוּם שֶׁאוֹתוֹ שֶׁמֶן מִשְׁחָה נִכְלָל בִּשְׁלֹשָׁה גְוָנִים. וּכְשֶׁנּוֹצֵץ הָאוֹר הַזֶּה, נוֹצְצִים מִמֶּנּוּ עֶשְׂרִים וּשְׁנַיִם (אותיות) אוֹרוֹת כְּנֶגֶד עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת הַתּוֹרָה שֶׁרְשׁוּמִים בַּנְּשָׁמָה הַזּוֹ. וְעֶשְׂרִים וּשְׁנַיִם הָאוֹרוֹת הַלָּלוּ, כֻּלָּם מְמֻנִּים שַׁמָּשִׁים שֶׁעוֹמְדִים עִמּוֹ, וְכֻלָּם נִקְרָאִים עַל שֵׁם הָאוֹר הַזֶּה שֶׁעֲלֵיהֶם, וְכֻלָּם נִכְלְלוּ בוֹ. הָאוֹר הַזֶּה עִם כָּל אוֹתָם הָאוֹרוֹת נִכְלָל בָּרוּחַ הַזּוֹ, וְהָרוּחַ הַזּוֹ כְּלוּלָה בּוֹ, וּמִסְתַּכֵּל לְהִתְיַשֵּׁב בְּתוֹךְ הַהֵיכָל הָרְבִיעִי.</p>\n<p>כְּשֶׁהָרוּחַ הַזּוֹ נִכְלֶלֶת מֵהָאוֹר הַזֶּה וּמִכָּל הָאוֹרוֹת, כְּשֶׁדּוֹחִים (דוחקים) לְהִתְנוֹצֵץ, יוֹצֵאת מֵהֶם חַיָּה אַחַת קְדוֹשָׁה כְּלוּלָה בִּשְׁנֵי גְוָנִים, אַרְיֵה וְנֶשֶׁר, וְהִיא דְּיוֹקָן אֶחָד, וְזֶה נִקְרָא אֲהִיאֵ\"ל (אתיאל).</p>\n<p>וְהַחַיָּה הַקְּדוֹשָׁה הַזּוֹ, יוֹצְאִים מֵהַהִתְנוֹצְצוּת שֶׁלָּהּ, כְּשֶׁמַּגִּיעַ בָּהּ הָאוֹר שֶׁל הָרוּחַ הָעֶלְיוֹנָה, אַרְבָּעָה אוֹפַנִּים כְּלוּלִים בְּכָל הַגְּוָנִים, וְהֵם: הַדְרִיאֵ\"ל, יְהַדְרִיאֵ\"ל, אַהֲדוֹרִיָּ\"א, אָסִימוֹ\"ן (אטימו\"ן). כָּל אֵלֶּה בִּשְׁמֹנֶה כְנָפַיִם, וְאֵלֶּה הֵם מְמֻנִּים עַל כָּל חֵילוֹת הַשָּׁמַיִם, עוֹרְכֵי הַקְּרָבוֹת. מִשּׁוּם שֶׁלֹּא תִמְצָא מִלְחָמָה אַחַת בָּעוֹלָם אוֹ עֲקִירַת מַלְכוּת מִמְּקוֹמָהּ, עַד שֶׁצְּבָא הַשָּׁמַיִם וְהַכּוֹכָבִים שֶׁל שְׁאָר הָרְקִיעִים, כֻּלָּם מַרְאִים קְרָבוֹת וְסִכְסוּכִים אֵלֶּה עִם אֵלֶּה. וְאַרְבַּעַת הָאוֹפַנִּים הַלָּלוּ עוֹמְדִים עֲלֵיהֶם לְאַרְבַּעַת צִדְדֵי הָעוֹלָם.</p>\n<p>אֵלּוּ הָאַרְבָּעָה, כְּשֶׁנּוֹסְעִים לַעֲרֹךְ מִלְחָמוֹת, מִסּוֹד הַהֵיכָל שֶׁלְּמַעְלָה נוֹסְעִים, שֶׁהוּא בֵּית הַדִּין, וְנִקְרָא זְכוּת. מֵהַזֵּעָה שֶׁלָּהֶם הוֹצִיאוּ כַּמָּה צְבָאוֹת וּמַחֲנוֹת שֶׁאֵין לָהֶם חֶשְׁבּוֹן, וְכֻלָּם עוֹמְדִים תַּחַת הָאוֹפַנִּים הַלָּלוּ.</p>\n<p>מֵהֶם עוֹמְדִים עַל שִׁירָה, וּמֵהֶם שְׁלוּחִים עַל הָעוֹלָם, כְּנֶגֶד אוֹתָם הַשְּׁלוּחִים שֶׁלְּצַד הַטֻּמְאָה שֶׁיּוֹצְאִים מִתּוֹךְ הַהֵיכָל הַשְּׁלִישִׁי שֶׁלָּהּ, וְהֵם מְקַטְרְגִים עַל הָעוֹלָם לְהָרַע. וְאֵלּוּ נִמְצָאִים כְּנֶגְדָּם שֶׁלֹּא יִשְׁלְטוּ עַל אוֹתָם שֶׁעוֹסְקִים בַּתּוֹרָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים צא) כִּי מַלְאָכָיו יְצַוֶּה לָּךְ וְגוֹ'. וְכָתוּב עַל כַּפַּיִם יִשָּׂאוּנְךְ פֶּן תִּגֹּף בָּאֶבֶן וְגוֹ'. זֶה (ישעיה ח) אֶבֶן נֶגֶף צוּר מִכְשׁוֹל. וְזֶה נִקְרָא אֶבֶן נֶגֶף צוּר מִכְשׁוֹל. וְזֶה נִקְרָא (שם כח) אֶבֶן בּחַן פִּנַּת יִקְרַת, (שם ל) צוּר יִשְׂרָאֵל. וְהַכֹּל עוֹמֵד זֶה כְּנֶגֶד זֶה.</p>\n<p>מִסּוֹד הַהֵיכָל הַשְּׁלִישִׁי שֶׁבַּצַּד הָאַחֵר יוֹצְאִים שְׁתֵּי רוּחוֹת שֶׁנִּקְרָאוֹת אַ\"ף וְחֵמָ\"ה, וּמִשְּׁתֵי אֵלֶּה יוֹצְאִים כָּל אוֹתָם שְׁלוּחִים שֶׁהוֹלְכִים לְהַסְטוֹת בְּנֵי אָדָם מִדֶּרֶךְ הָאֱמֶת, וְאֵלּוּ אוֹתָם שֶׁעוֹמְדִים וּמַקְדִּימִים עַל אָדָם שֶׁהוֹלֵךְ לְדֶרֶךְ מִצְוָה, וְעַל זֶה אֵלּוּ הָאוֹפַנִּים עוֹמְדִים כְּנֶגְדָּם, כְּדֵי לְהָגֵן עַל הָאָדָם שֶׁלֹּא יִנָּזְקוּ. מִשְּׁתֵי הָרוּחוֹת הַלָּלוּ פָּחַד מֹשֶׁה כְּשֶׁהָיָה יוֹרֵד מִן הָהָר, שֶׁכָּתוּב (דברים ט) כִּי יָגֹרְתִּי מִפְּנֵי הָאַף וְהַחֵמָה.</p>\n<p>בְּאֶמְצַע הַהֵיכָל הַזֶּה יֵשׁ מָקוֹם אַחֵר שֶׁעוֹמֵד לְמַעְלָה לְמַעְלָה, בְּאַרְבָּעָה פְתָחִים לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, עֲשָׂרָה מְמֻנִּים לְכָל פֶּתַח וּפֶתַח, וּמְמֻנֶּה אֶחָד עֲלֵיהֶם. וְזֶה כָּלוּל בְּאוֹר שֶׁנִּקְרָא אַהֲדִיאֵ\"ל, וְזֶהוּ אוֹפַן בְּתוֹךְ הָאוֹפַן, מְשֻׁלָּבִים זֶה בָּזֶה.</p>\n<p>אֵלּוּ הָאַרְבָּעִים נוֹטְלִים דִּין מִבֵּית הַזְּכוּת לְהַלְקוֹת אֶת הַנְּשָׁמָה הַזּוֹ שֶׁחָטְאָה (וצריכה) לְקַבֵּל מַלְקוּת, וְאֵלּוּ עוֹמְדִים בְּשַׁלְהֶבֶת אֵשׁ לְאוֹתָן הַנְּשָׁמוֹת, וְטָסִים מִחוּץ לַהֵיכָל הַזֶּה, וּמַלְקִים אֶת הַנְּשָׁמָה הַזּוֹ, וְעוֹמֶדֶת נְזוּפָה בַּחוּץ כָּל אוֹתָם הַיָּמִים שֶׁנִּגְזְרוּ עָלֶיהָ, וְלֹא נִכְנֶסֶת לַפַּרְגּוֹד.</p>\n<p>וְהָאַרְבָּעִים הַלָּלוּ הֵם שֶׁעוֹמְדִים וְנוֹזְפִים וּמְנַדִּים אֶת כָּל אֵלּוּ שֶׁהוֹצִיאוּ מִפִּיהֶם דָּבָר שֶׁלֹּא צָרִיךְ, וְאַחַר זֶה הוֹצִיאוּ מִפִּיהֶם דָּבָר קָדוֹשׁ, דְּבַר תּוֹרָה, וּמְטַנְּפִים אֶת פִּיהֶם בָּהּ. וְאֵלּוּ עוֹמְדִים וּמְנַדִּים אוֹתָם, וְעוֹמְדִים בַּנִּדּוּי הַזֶּה אַרְבָּעִים יוֹם, שֶׁלֹּא נִשְׁמַעַת תְּפִלָּתָם.</p>\n<p>וְכֵן אֶת כָּל אֵלּוּ שֶׁחָטְאוּ אוֹתָם חֲטָאִים שֶׁצְּרִיכִים אֶת הַנְּזִיפָה, עֲשָׂרָה כָּרוֹזִים יוֹצְאִים בְּכָל יוֹם וּמַכְרִיזִים בְּכָל אוֹתָם הָרְקִיעִים וּבְכָל אוֹתָם חֲיָלוֹת וּמַחֲנוֹת: הִזָּהֲרוּ בִּפְלוֹנִי שֶׁהוּא נָזוּף! הוּא נָזוּף עַל חֵטְא פְּלוֹנִי שֶׁעָשָׂה, עַד שֶׁשָּׁב לִפְנֵי רִבּוֹנוֹ, הָרַחֲמָן יַצִּילֵנוּ.</p>\n<p>כְּשֶׁשָּׁב מֵאוֹתוֹ הַחֵטְא, מִתְכַּנְסִים כָּל הָאַרְבָּעִים הַלָּלוּ וּמַתִּירִים אוֹתוֹ, וְאָז מַכְרִיזִים עָלָיו: מִפְּלוֹנִי הֻתְּרָה הַנְּזִיפָה! מִכָּאן וָהָלְאָה הַתְּפִלָּה נִכְנֶסֶת. וְטֶרֶם שֶׁשָּׁב, הוּא נָזוּף לְמַעְלָה וּלְמַטָּה, וּשְׁמִירַת רִבּוֹנוֹ מוּסֶרֶת מִמֶּנּוּ. וַאֲפִלּוּ בַּלַּיְלָה נִשְׁמָתוֹ נְזוּפָה, שֶׁסּוֹתְמִים לָהּ אֶת כָּל שַׁעֲרֵי הַשָּׁמַיִם וְלֹא עוֹלָה, וְדוֹחִים אוֹתָהּ הַחוּצָה.</p>\n<p>הָאוֹפַן הַזֶּה שֶׁעוֹמֵד עַל הָאַרְבָּעִים הַלָּלוּ, כְּשֶׁנּוֹסֵעַ, מַגִּיעַ לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא תָּא הָרָצִי\"ם. וּכְשֶׁנִּכְנָס, נִכְנָסִים עִמּוֹ אוֹתָם הָאַרְבָּעִים שֶׁמְּמֻנִּים בְּאַרְבָּעָה פְתָחִים, וְעוֹלִים כָּל אוֹתָם הַמָּגִנִּים שֶׁל זָהָב, וְאֵלּוּ הֵם מַלְאָכִים שֶׁנִּקְרָאִים חַשְׁמַלִּי\"ם. וְאוֹתָם הַמָּגִנִּים וְהַחֲרָבוֹת וְהָרְמָחִים שֶׁרָצִים לְהָגֵן עַל יִשְׂרָאֵל מִשְּׁאָר הָעַמִּים, וְלַעֲרֹךְ בָּהֶם קְרָב וְלִנְקֹם מֵהֶם לְפִי שָׁעָה בְּלִי אֹרֶךְ.</p>\n<p>וּמִשּׁוּם כָּךְ נִקְרָא תָּא הָרָצִים, מָקוֹם שֶׁאוֹתָם הָרָצִים רָצִים וּמְמַהֲרִים לְהִלָּחֵם וְלִנְקֹם נְקָמוֹת כְּנֶגֶד רָצִים אֲחֵרִים שֶׁרָצִים לְהָרַע וּלְהַחֲלִישׁ מַזָּלוֹת כְּדֵי לִשְׁלֹט עֲלֵיהֶם. וְסוֹד זֶה - (אסתר ג) הָרָצִים יָצְאוּ דְחוּפִים. רָצִים מִצַּד זֶה וְרָצִים מִצַּד זֶה, וּבִגְלָלָם (שם ח) וְהָעִיר שׁוּשָׁן צָהֲלָה וְשָׂמֵחָה, אוֹ (שםג) נָבוֹכָה. אִם מַקְדִּימִים אֵלֶּה שֶׁכָּאן - הָעִיר שׁוּשָׁן שָׂמֵחָה. וְאִם מַקְדִּימִים אֵלֶּה שֶׁל הַצַּד הָאַחֵר - הָעִיר שׁוּשָׁן נָבוֹכָה.</p>\n<p>וַהֲרֵי בֵּאַרְנוּ שֶׁבַּכֹּל עוֹמְדִים אֵלֶּה כְּנֶגֶד אֵלֶּה, צַד זֶה כְּנֶגֶד צַד זֶה, וּמִשּׁוּם כָּךְ אֵלֶּה הֵם מָגִנִּים לַכֹּל. כְּשֶׁעוֹלִים אֵלּה בְּאֵלֶּה, יוֹצֵא אֲוִיר אֶחָד שֶׁלְּמַעְלָה, וְכֻלָּם נַעֲשִׂים מָגֵן אֶחָד, וְסִמָנְךְ - (בראשית טו) אָנֹכִי מָגֵן לָךְ.</p>\n<p>שְׁנֵים עָשָׂר גַּלְגַּלִּים הֵם שֶׁסּוֹבְבִים לְתוֹךְ הַהֵיכָל הַזֶּה, וְהֵם נִקְרָאִים שְׂרָפִים בִּשְׁנֵי גְוָנִים - לָבָן וְאָדם, רַחֲמִים וְדִין. אֵלֶּה הֵם עוֹמְדִים לְהַשְׁגִּיחַ תָּמִיד עַל כָּל אוֹתָם בַּעֲלֵי הַצַּעַר שֶׁמְּצַעֲרִים אוֹתָם שְׁאָר הָעַמִּים וְדוֹחֲקִים אוֹתָם, וְנִקְרָאִים חַלּוֹנוֹת. וְהַיְנוּ מַה שֶּׁכָּתוּב (שיר ב) מַשְׁגִּיחַ מִן הַחַלֹּנוֹת.</p>\n<p>וְאֵלּוּ עוֹמְדִים לְהִסְתַּכֵּל עַל כָּל אוֹתָם שֶׁמִּתְפַּלְלִים תְּפִלּוֹתֵיהֶם, שֶׁמַּקְדִּימִים לְבֵית הַכְּנֶסֶת, וְנִמְנִים מֵאוֹתָם הָעֲשָׂרָה הָרִאשׁוֹנִים, וְאָז עוֹלִים וְכוֹתְבִים אוֹתָם לְמַעְלָה, מִשּׁוּם שֶׁאֵלּוּ נִקְרָאִים חֲבֵרִים שֶׁלָּהֶם. וְזֶהוּ שֶׁכָּתוּב (שם ח) חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי.</p>\n<p>אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁיּוֹדְעִים לְסַדֵּר תְּפִלָּתָם כָּרָאוּי, מִשּׁוּם שֶׁכַּאֲשֶׁר הַתְּפִלָּה מַתְחִילָה לַעֲלוֹת, אֵלּוּ עוֹלִים עִם הַתְּפִלָּה הַ את וְנִכְנָסִים לְכָל אוֹתָם הָרְקִיעִים וּלְכָל אוֹתָם הַהֵיכָלוֹת, עַד שַׁעַר הַפֶּתַח הָעֶלְיוֹן. וְאוֹתָהּ תְּפִלָּה נִכְנֶסֶת לִפְנֵי הַמֶּלֶךְ לְהִתְעַטֵּר, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>בֹּא וּרְאֵה, כָּל אֵלּוּ שֶׁמִּתְפַּלְלִים תְּפִלּוֹת וּמְקַדְּשִׁים אֶת רִבּוֹנָם בְּרָצוֹן שָׁלֵם, הַתְּפִלָּה הַזּוֹ צָרִיךְ לְהוֹצִיא אוֹתָהּ מִתּוֹךְ מַחֲשָׁבָה, וּבְרָצוֹן שֶׁל דִּבּוּר וְרוּחַ, וְאָז מִתְקַדֵּשׁ שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּכְשֶׁמַּגִּיעָה לַחֲבֵרִים הַלָּלוּ, כֻּלָּם לוֹקְחִים אֶת אוֹתָהּ תְּפִלָּה, וְהוֹלְכִים עִמָּהּ עַד הַהֵיכָל הָרְבִיעִי בְּאוֹתוֹ הַפֶּתַח. וְאֵלּוּ מְשַׁבְּחִים בְּאוֹתוֹ זְמַן שֶׁמִּתְפַּלְלִים תְּפִלּוֹת וּמְקַדְּשִׁים בְּאוֹתוֹ זְמַן, אֵלּוּ הֵם שֶׁמְּמֻנִּים בַּיּוֹם עַל יִשְׂרָאֵל לִהְיוֹת עִמָּהֶם חֲבֵרִים. (ולא בלילה כאותם) וּבַלַּיְלָה בְּאוֹתָם הָאֲחֵרִים שֶׁאוֹמְרִים שִׁירָה בַּלַּיְלָה.</p>\n<p>וּבֹא רְאֵה, כָּתוּב (משלי כח) גּוֹזֵל אָבִיו וְאִמּוֹ וְאֹמֵר אֵין פָּשַׁע חָבֵר הוּא לְאִישׁ מַשְׁחִית. וַהֲרֵי פֵּרְשׁוּהָ, מִשּׁוּם שֶׁמּוֹנֵעַ בִּרְכוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא אָבִיו, כַּכָּתוּב (דבריםלב) שְׁאַל אָבִיךְ וְיַגֵּדְךְ. וְכָתוּב (משלי כג) יִשְׂמַח אָבִיךְ. וּפֵרְשׁוּהָ.</p>\n<p>חָבֵר הוּא לְאִישׁ מַשְׁחִית, מִי הָאִישׁ מַשְׁחִית? זֶהוּ אוֹתוֹ אִישׁ שֶׁפּוֹגֵם אֶת הַלְּבָנָה, וְנִקְרָא (שם טז) אִישׁ תַּהְפּוּכוֹת. (תהלים קמ) אִישׁ לָשׁוֹן. (בראשית כה) אִישׁ יוֹדֵעַ צַיִד אִישׁ שָׂדֶה. וְזֶהוּ אִישׁ מַשְׁחִית, שֶׁזֶּהוּ שֶׁמּוֹנֵעַ בְּרָכוֹת מִן הָעוֹלָם. אַף כָּךְ, מִי שֶׁמּוֹנֵעַ בְּרָכוֹת מֵהָעוֹלָם, חָבֵר הוּא לָאִישׁ מַשְׁחִית הַזֶּה שֶׁאָמַרְנוּ. וְזֶהוּ סוֹד, מִשּׁוּם שֶׁצָּרִיךְ לָאָדָם לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהִתְפַּלֵּל תְּפִלָּה כָּרָאוּי כְּדֵי שֶׁיִּתְבָּרֵךְ שְׁמוֹ הַקָּדוֹשׁ, וְיִתְחַבֵּר עִם הַחֲבֵרִים הַקְּדוֹשִׁים הַלָּלוּ וְלֹא יִפְגֹּם אֶת תְּפִלָּתוֹ, מִשּׁוּם שֶׁיִּמְנַע בְּרָכוֹת מֵהָעוֹלָם וְיִתְחַבֵּר עִם אוֹתוֹ אִישׁ מַשְׁחִית, שֶׁהוּא מוֹנֵעַ בְּרָכוֹת מִן הָעוֹלָם וְגָרַם מָוֶת לְכֻלָּם.</p>\n<p>כָּתוּב (דברים יח) וְחֹבֵר חָבֶר. מַה זֶּה וְחֹבֵר חָבֶר? זֶה אוֹתוֹ מִי שֶׁהוּא הוֹלֵךְ אַחַר הַצַּד הָאַחֵר וּמְכַשֵּׁף כְּשָׁפִים, הוּא מוֹשֵׁךְ עָלָיו רוּחַ אַחֶרֶת טְמֵאָה, וּמִתְחַבֵּר בְּאוֹתָהּ חֲבֵרוּת שֶׁל אוֹתוֹ חָבֵר רַע, וְשׁוֹרֶה בַּחֲבֵרוּת עִם אוֹתוֹ חָבֵר אִישׁ מַשְׁחִית. וְלָמָּה נִקְרָא חָבֵר? מִשּׁוּם שֶׁבְּשָׁעָה שֶׁנּוֹלָד אָדָם הוּא מִתְחַבֵּר עִמּוֹ, וְתָמִיד עִמּוֹ כְּחָבֵר. אַחַר כָּךְ נֶהִפָּךְ לוֹ חָבֵר אִישׁ מַשְׁחִית.</p>\n<p>וְכָךָֹ יֵשׁ בְּצַד הַקְּדֻשָּׁה, בְּצַד הַיָּמִין, חָבֵר טוֹב, שֶׁעוֹשֶׂה טוֹב עִם הָאָדָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וְהַחֲבֵרִים הַלָּלוּ עוֹמְדִים תָּמִיד עַל הָאָדָם בַּחֲבֵרוּת אַחַת לְהַצִּילוֹ וּלְהָגֵן עָלָיו וְלִהְיוֹת עִמּוֹ חֲבֵרִים, לְקַדֵּשׁ אֶת שֵׁם רִבּוֹנָם וּלְזַמֵּר וּלְשַׁבֵּחַ לְפָנָיו תָּמִיד.</p>\n<p>מֵאֵלּוּ יוֹצְאִים אַרְבָּעָה תוֹמְכִים אֲחֵרִים לְאוֹתָם הַשְּׁנֵים עָשָׂר שֶׁאָמַרְנוּ, הַחֲבֵרִים הַלָּלוּ. וְאֵלּוּ הֵם עוֹמְדִים לְאוֹתָם שֶׁיּוֹעֲצִים עֵצָה לְהַזִּיק לַצַּדִּיקִים. אַף עַל גַּב שֶׁלֹּא עוֹשִׂים, וְעוֹלִים וּמוֹדִיעִים הַדָּבָר לְמַעְלָה, וּמְבַטְּלִים אֶת אוֹתָהּ הָעֵצָה. וְאֵלּוּ נִקְרָאִים אֶרְאֶלִּים. וְאַף עַל גַּב שֶׁכֻּלָּם הִתְמַנּוּ לָזֶה, כָּל אֶחָד הִתְמַנָּה וְנִפְקַד עַל דְּבָרִים יְדוּעִים, וְתַחַת אֵלּוּ אֵין לָהֶם חֶשְׁבּוֹן.</p>\n<p>עִיגָאֵ\"ל. עִירִיָּ\"ה. (עזרי\"ה). עָרִיאֵ\"ל. יְהִירָאֵ \"ל. עִיגָאֵ\"ל הוּא עוֹמֵד לְצַד מִזְרָח, וְזֶה עוֹמֵד לְהַשְׁגִּיחַ עַל כָּל אוֹתָם שֶׁעוֹשִׂים מַעֲשִׂים טוֹבִים, וְעַל כָּל אֵלּוּ שֶׁחוֹשְׁבִים מַחֲשָׁבָה שֶׁל מִצְוָה, אַף עַל גַּב שֶׁלֹּא יְכוֹלִים לַעֲשׂוֹת.</p>\n<p>עִירִיָּ\"ה עוֹמֵד לְצַד דָּרוֹם, וְזֶה עוֹמֵד לְהַשְׁגִּיחַ עַל כָּל אוֹתָם שֶׁמְּנַחֲמִים אֶת הֶעָנִי אוֹ שֶׁיֵּשׁ בְּלִבָּם צַעַר עָלָיו, אַף עַל גַּב שֶׁאֵינָם יְכוֹלִים לָתֵת לוֹ. וּלְאוֹתָם שֶׁהוֹלְכִים לְדֶרֶךְ מִצְוָה, וּלְאוֹתָם שֶׁעוֹשִׂים חֶסֶד עִם מֵתִים. וְהוּא מַעֲמִיד קִיּוּם שֶׁל אֱמֶת. וְזֶה הִתְמַנָּה לְהַזְכִּיר אוֹתוֹ לְמַעְלָה וְלַחְקֹק דְּיוֹקְנוֹ לְמַעְלָה, לְהַכְנִיסוֹ לָעוֹלָם הַבָּא.</p>\n<p>עָרִיאֵ\"ל עוֹמֵד לְצַד צָפוֹן. וְזֶה עוֹמֵד לְהַשְׁגִּיחַ עַל כָּל אוֹתָם שֶׁחָשְׁבוּ לַעֲשׂוֹת רָעוֹת וְלֹא עָשׂוּ, אוֹ רוֹצִים לַחֲטֹא וּבָאוּ לַעֲשׂוֹת, וְהִתְחַזֵּק בְּיִצְרוֹ וְלֹא עָשָׂה.</p>\n<p>יְהִירָאֵ\"ל עוֹמֵד לְצַד מַעֲרָב, וְזֶה עוֹמֵד לְהַשְׁגִּיחַ עַל כָּל אוֹתָם שֶׁעוֹסְקִים בַּתּוֹרָה וּמַכְנִיסִים בְּנֵיהֶם לִלְמֹד תּוֹרָה לְבֵית הָרַב, וּלְכָל אוֹתָם שֶׁמִּסְתַּכְּלִים עַל חוֹלֶה כְּשֶׁהוּא בְּבֵית חָלְיוֹ, וּמַשְׁגִּיחִים עָלָיו וּמוֹדִיעִים לוֹ שֶׁיִּתְבּוֹנֵן בַּחֲטָאָיו וּבְמַעֲשָׂיו וְיָשׁוּב מֵהֶם לְרִבּוֹנוֹ. מִשּׁוּם שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל עִם אוֹתוֹ חוֹלֶה, שֶׁיִּסְתַּכֵּל בְּמַעֲשָׂיו וְיָשׁוּב בִּתְשׁוּבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הוּא גּוֹרֵם לוֹ לְהִנָּצֵל וּלְהָשִׁיב לוֹ אֶת רוּחוֹ. וְעַל זֶה כָּתוּב, (תהלים מא) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ ה'. מַה זֶּה בְּיוֹם רָעָה? בְּיוֹם רַע הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא בְּיוֹם רָעָה - בְּיוֹם שֶׁשּׁוֹלֶטֶת אוֹתָהּ הָרָעָה לָקַחַת אֶת נִשְׁמָתוֹ. אַשְׁרֵי מַשְׂכִּיל אֶל דָּל - זֶהוּ חוֹלֶה, כְּמוֹ שֶׁנֶּאֱמַר, (שמואל ב יג) מַדּוּעַ אַתָּה כָּכָה דַּל בֶּן הַמֶּלֶךְ. וּמִשּׁוּם כָּךְ, בְּיוֹם רָעָה יְמַלְּטֵהוּ ה'.</p>\n<p>וְאֵלּוּ (אותם שמסתכלים) שֶׁהֵם מִסְתַּכְּלִים בְּאוֹתוֹ חוֹלֶה לַהֲשִׁיבוֹ מֵחֲטָאָיו אֵצֶל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁבֵּאַרְנוּ. בַּהֵיכָל הַזֶּה עוֹמֵד עָלָיו לְהַשְׁגִּיחַ. וּבַיּוֹם שֶׁשּׁוֹרֶה הַדִּין עַל הָעוֹלָם, יִנָּצֵל מִמֶּנּוּ, כְּמוֹ שֶׁנֶּאֱמַר בְּיוֹם רָעָה יְמַלְּטֵהוּ ה'. הַיּוֹם שֶׁנִּמְסָר הַדִּין לְאוֹתָהּ רָעָה לִשְׁלֹט בּוֹ (על העולם), וְכָל אֵלּוּ עוֹמְדִים לְהַשְׁגִּיחַ, וְלָכֵן נִקְרְאוּ חֲרַכִּים.</p>\n<p>בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹמֵד בְּדִין עַל הָעוֹלָם וְאוֹתוֹ צַד הָרָע בָּא לְהַשְׂטִין, אָז מִתְכַּנְּסִים כָּל אֵלֶּה וְעוֹמְדִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאָז מִתְעַטְּרִים כֻּלָּם וְעוֹמְדִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. בְּאוֹתוֹ זְמַן מַה כָּתוּב? (שיר השיריםב) מַשְׁגִּיחַ מִן הַחַלֹּנוֹת מֵצִיץ מִן הַחֲרַכִּים. מֵצִיץ, כְּמִי שֶׁמַּשְׁגִּיחַ מִמָּקוֹם דַּק, שֶׁרוֹאֶה וְלֹא רוֹאֶה כָּל מַה שֶּׁצָּרִיךְ. וְאַחַר כָּךְ, מַשְׁגִּיחַ מִן הַחַלֹּנוֹת, מָקוֹם שֶׁל הַשְׁגָּחָה יְתֵרָה, שֶׁפּוֹתֵחַ פְּתָחִים לְרַחֵם עַל הַכֹּל. וּכְשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁגִּיחַ עַל הָעוֹלָם, מִסְתַּכֵּל בַּחַלּוֹנוֹת הַלָּלוּ וּבַחֲרַכִּים הַלָּלוּ, וְחָס עַל הַכֹּל.</p>\n<p>וְאָז, כְּשֶׁיִּשְׂרָאֵל תּוֹקְעִים בְּאוֹתוֹ שׁוֹפָר וּמִתְעוֹרֵר לְמַעְלָה אוֹתוֹ הַקּוֹל שֶׁיּוֹצֵא מִן הַשּׁוֹפָר, כָּלוּל מֵאֵשׁ וּמַיִם וְרוּחַ, וְנַעֲשֶׂה מֵהַכֹּל אוֹתוֹ הַקּוֹל, כְּדֵי לְעוֹרֵר קוֹל עֶלְיוֹן, שֶׁיּוֹצֵא מִתּוֹךְ אוֹתוֹ הַשּׁוֹפָר, שֶׁהוּא כְּמוֹ זֶה, כָּלוּל בְּאֵשׁ וּמַיִם וְרוּחַ, אָז יוֹצֵא כָּרוֹז וּמַכְרִיז בְּכָל הָרְקִיעִים וְאוֹמֵר: קוֹל דּוֹדִי הִנֵּה זֶה בָּא וְגוֹ' מַשְׁגִּיחַ מִן הַחַלֹּנוֹת מֵצִיץ מִן הַחֲרַכִּים.</p>\n<p>וְאָז כֻּלָּם יוֹדְעִים שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל יִשְׂרָאֵל, וְאוֹמְרִים: אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁיֵּשׁ לָהֶם עֵצָה בָּאָרֶץ כְּדֵי לְעוֹרֵר רַחֲמִים מִלְמַעְלָה. וְאָז כָּתוּב, (תהלים פט) אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה. יוֹדְעֵי תְרוּעָה וַדַּאי. יוֹדְעֵי תְרוּעָה, שֶׁמְּשַׁבְּרִים אֶת הַתְּרוּעָה הַזּוֹ, שֶׁהִיא דִּין הַקָּשֶׁה שֶׁהַכֹּל נִדּוֹנִים בּוֹ. אַשְׁרֵי יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, מִשּׁוּם שֶׁהֵם יוֹדְעִים אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְיוֹדְעִים לָלֶכֶת בִּדְרָכָיו וּלְיַחֵד יִחוּד כָּרָאוּי.</p>\n<p>הַחַלּוֹנוֹת הַלָּלוּ וְהַחֲרַכִּים הַלָּלוּ, כֻּלָּם עוֹמְדִים לֶאֱחֹז אֶת כָּל הַתְּפִלּוֹת שֶׁעוֹלוֹת מִלְּמַטָּה לְמַעְלָה וּלְהַשְׁגִּיחַ בָּהֶן, לְהַכְנִיסָן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעַל כֵּן, כָּל בֵּית כְּנֶסֶת שֶׁאֵין בּוֹ חַלּוֹנוֹת, אֵינוֹ מָקוֹם לְהִתְפַּלֵּל בּוֹ כָּרָאוּי.</p>\n<p>שֶׁהֲרֵי בֵּית הַכְּנֶסֶת לְמַטָּה כְּנֶגֶד בֵּית הַכְּנֶסֶת שֶׁלְּמַעְלָה. בֵּית הַכְּנֶסֶת שֶׁלְּמַעְלָה שֶׁיֵּשׁ בּוֹ חַלּוֹנוֹת, כְּמוֹ שֶׁאָמַרְנוּ - כָּךְ גַּם לְמַטָּה. לְמַעְלָה כְּנֶסֶת הַגְּדוֹלָה יֵשׁ בָּהּ שְׁנֵים עָשָׂר חַלּוֹנוֹת - כָּךְ גַּם לְבֵית הַכְּנֶסֶת הַתַּחְתּוֹן. וְהַכֹּל עוֹמְדִים זֶה כְּנֶגֶד זֶה, מִשּׁוּם שֶׁהָעוֹלָמוֹת עוֹמְדִים אֵלּוּ בַּגָּוֶן שֶׁל אֵלּוּ, וּכְבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹלֶה בַּכֹּל. וְעַל כֵּן, בְּיוֹם רָעָה יְמַלְּטֵהוּ ה'. כְּשֶׁשּׁוֹלֵט אוֹתוֹ הַצַּד הָרָע - יְמַלְּטֵהוּ ה'.</p>\n<p>כְּמוֹ כֵן, הַמְמֻנֶּה הַזֶּה יְהִירָאֵ\"ל עוֹמֵד עַל כָּל אוֹתָם שֶׁחָסִים עַל עֲנִיִּים, כְּמוֹ שֶׁנֶּאֱמַר אַשְׁרֵי מַשְׂכִּיל אֶל דָּל, וּבִשְׁבִיל זֶה הַכֹּל עוֹמֵד בַּהֵיכָל הַזֶּה, וְהַהֵיכָל הַזֶּה נִכְלָל בְּהֵיכָל אַחֵר רְבִיעִי, שֶׁשָּׁם הֵם הַגְּזֵרוֹת וְהַדִּינִים לַכֹּל. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיּוֹדֵעַ אֶת גִּנְזֵי רִבּוֹנוֹ, לְיַחֲדוֹ וּלְקַדֵּשׁ אֶת שֵׁם רִבּוֹנוֹ תָּמִיד, לְזַכּוֹתוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522011910,"<p>הַהֵיכָל הָרְבִיעִי. הַהֵיכָל הַזֶּה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹדָע שִׁלְטוֹנוֹ בָּאָרֶץ בִּגְלָלוֹ. וְזֶהוּ הַהֵיכָל שֶׁעוֹמֵד לִשְׁמֹר אֶת דַּרְכֵי הַתּוֹרָה. זֶה נִקְרָא הֵיכַל הַזְּכוּת, שֶׁבּוֹ נִדּוֹנִים כָּל דִּינֵי הָעוֹלָם וְכָל הַזְּכֻיּוֹת וְכָל הַחֲטָאִים וְכָל הָעֳנָשִׁים, וְכָל שָׂכָר טוֹב לְאוֹתָם שֶׁשּׁוֹמְרִים אֶת מִצְווֹת הַתּוֹרָה.</p>\n<p>הֵיכַל הַזְּכוּת הַזֶּה מְשֻׁנֶּה מִכָּל שְׁאָר הַהֵיכָלוֹת, וְהַהֵיכָל הַזֶּה כְּלוּלִים בּוֹ אַרְבָּעָה הֵיכָלוֹת מְשֻׁנִּים זֶה מִזֶּה, וְכֻלָּם הֵיכָל אֶחָד. בַּהֵיכָל הַזֶּה יֵשׁ רוּחַ אַחַת שֶׁנִּקְרֵאת זְכוּת אֵל. וְהַהֵיכָל הַזֶּה נִקְרָא עַל שְׁמוֹ זְכוּת, וְזֶהוּ אֵל. וְכָאן נִדּוֹנִים כָּל דִּינֵי הָעוֹלָם. וְזֶהוּ סוֹד הַכָּתוּב, (תהלים ז) וְאֵל זעֵם בְּכָל יוֹם.</p>\n<p>אַרְבָּעָה הֵיכָלוֹת, אַרְבָּעָה אֵלּוּ שֶׁהֵם בַּהֵיכָל הַזֶּה, זֶה לִפְנִים מִזֶּה, כֻּלָּם כְּלוּלִים זֶה בָּזֶה, וְכֻלָּם הֵיכָל אֶחָד, וְנִקְרָא זְכוּת. אַרְבָּעָה הַהֵיכָלוֹת הַלָּלוּ יֵשׁ לָהֶם פְּתָחִים. מְמֻנֶּה אֶחָד עֶלְיוֹן שֶׁעוֹמֵד מִחוּץ לַפֶּתַח הָרִאשׁוֹן שֶׁל הַהֵיכָל הַזֶּה, סַנְסָנִיָּ\"ה שְׁמוֹ, וְעַל הַשֵּׁם הַזֶּה יֵשׁ מְמֻנֶּה אֶחָד לַצַּד הָאַחֵר שֶׁל הַשְּׂמֹאל, שֶׁנּוֹטֵל דִּינִים בְּאוֹתוֹ הַהֵיכָל שֶׁלּוֹ לְעוֹרֵר וְלַעֲשׂוֹת בָּעוֹלָם. וּמִשּׁוּם שֶׁנּוֹטֵל מִמֶּנּוּ, נִקְרָא עַל שְׁמוֹ - סַנְסָנִיָּ\"ה. וְהוּא שׁוֹלֵט עַל אוֹתוֹ אַסְכָּרָ\"א שֶׁל תִּינוֹקוֹת.</p>\n<p>וְהַמְמֻנֶּה הָעֶלְיוֹן הַזֶּה סַנְסָנִיָּ\"ה, כְּשֶׁנּוֹטֵל דִּין, מַכְרִיז לְאוֹתָם הַמְמֻנִּים שֶׁעוֹמְדִים עַל שְׁנֵים עָשָׂר הַפְּתָחִים, וְאוֹתָם הַכָּרוֹזִים שֶׁמַּכְרִיזִים עַל כָּל אוֹתָם הַדִּינִים שֶׁנִּדּוֹנוּ מֵהֵיכַל הַזְּכוּת הַזֶּה.</p>\n<p>רוּחַ זוֹ שֶׁנּוֹטֶלֶת הַכֹּל, שֶׁנִּקְרֵאת זְכוּת אֵ\"ל שֶׁאָמַרְנוּ, הַכֹּל כָּלוּל בָּהּ. מִמֶּנָּה יוֹצְאִים שִׁבְעִים אוֹרוֹת נוֹצְצִים, וְכֻלָּם עוֹמְדִים בְּעִגּוּל כְּדֵי לְהַרְאוֹת זֶה בָּזֶה שֶׁלֹּא מְכֻסִּים זֶה מִזֶּה. כָּל הַזְּכֻיּוֹת וְכָל הָעֳנָשִׁים וְכָל הַדִּינִים, לִפְנֵי כָּל הָאוֹרוֹת הָאֵלּוּ עוֹמְדִים.</p>\n<p>מֵהֶם יוֹצְאִים שְׁנֵי אוֹרוֹת שֶׁעוֹמְדִים לִפְנֵיהֶם תָּמִיד. וְשִׁבְעִים הָאוֹרוֹת הַלָּלוּ וּשְׁנֵי אוֹרוֹת שֶׁעוֹמְדִים לִפְנֵיהֶם, הֵם לְתוֹךְ אֶמְצַע הַהֵיכָל. וְעַל סוֹד הַהֵיכָל הַזֶּה כָּתוּב, (שיר השירים ז) שָׁרְרֵךְ אֲגַן הַסַּהַר אַל יֶחְסַר הַמָּזֶג.</p>\n<p>כְּנֶגֶד אֵלּוּ יוֹצְאִים שִׁבְעִים וּשְׁנַיִם אוֹרוֹת אֲחֵרִים מִצַּד הַיָּמִין, וְשִׁבְעִים וּשְׁנַיִם אוֹרוֹת אֲחֵרִים מִצַּד הַשְּׂמֹאל. וְאֵלּוּ הָרִאשׁוֹנִים הֵם פְּנִימִיִּים לִפְנִים בְּאֶמְצַע הַהֵיכָל. לִפְנֵי הָאוֹרוֹת הַלָּלוּ נִכְנָסִים כָּל הַזְּכֻיּוֹת וְהַחוֹבוֹת לְהִטָּהֵר. כָּל הַמַּעֲשִׂים שֶׁל הָעוֹלָם יוֹצְאִים מֵהַפְּנִימִיִּים הַלָּלוּ. נִמְצְאוּ שֶׁכָּל הָאוֹרוֹת שֶׁיּוֹצְאִים מֵהָרוּחַ הָעֶלְיוֹנָה הַזּוֹ - מָאתַיִם וְשִׁשָּׁה עָשָׂר אוֹרוֹת, וְכֻלָּם כְּלוּלִים בָּרוּחַ הַזּוֹ.</p>\n<p>אוֹתָם שְׁנֵי הָאוֹרוֹת שֶׁעוֹמְדִים לִפְנֵי אוֹתָם הַשִּׁבְעִים, הֵם מְעִידִים עֵדוּת תָּמִיד, וְכוֹתְבִים פִּתְקֵי דִין שֶׁל זְכוּת אוֹ שֶׁל חוֹבָה. אֵלּוּ הַשִּׁבְעִים הֵם גּוֹזְרִים גְּזֵרוֹת וְדָנִים דִּינִים. וְכָל דִּינֵי הָעוֹלָם, הֵן לְטוֹב הֵן לְרַע, הֵם כָּאן.</p>\n<p>הָרוּחַ הַזּוֹ, שֶׁהִיא זְכוּת אֵ\"ל כְּמוֹ שֶׁאָמַרְנוּ, בָּהּ רְשׁוּמוֹת שָׁלֹשׁ אוֹתִיּוֹת שֶׁנִּדְבָּקוֹת בָּהּ מִלְמַעְלָה, שֶׁהֵן יה\"ו. וַהֲרֵי בֵּאַרְנוּ, שֶׁכַּאֲשֶׁר הָאוֹתִיּוֹת הַלָּלוּ נִדְבָּקוֹת בַּמָּקוֹם הַזֶּה שֶׁל הִתְדַּבְּקוּת הַזָּכָר בַּנְּקֵבָה, אָז נִרְשָׁמוֹת בָּרוּחַ הַזּוֹ אוֹתָן הָאוֹתִיּוֹת. וְכָאן אָמַר דָּוִד, (תהלים צב) וֵאלֹהַי לְצוּר מַחְסִי. סוֹד הָרוּחַ הַזּוֹ שֶׁנִּקְרֵאת אֵ\"ל, וְסוֹד אוֹתָן הָאוֹתִיּוֹת שֶׁרְשׁוּמוֹת בָּהּ, שֶׁנִּקְרָאוֹת יה\"ו, אֵלּוּ שְׁלֹשֶׁת הַצְּדָדִים שֶׁל הָאוֹרוֹת שֶׁאָמַרְנוּ.</p>\n<p>אוֹתָם שְׁלֹשֶׁת בָּתֵּי הַדִּין שֶׁנֶּחֱלָקִים בְּדִינִים אֲחֵרִים בְּדִבְרֵי הָעוֹלָם., בְּעֹשֶׁר, בְּעֹנִי, בְּמַחֲלוֹת בִּשְׁלֵמוּת, שֶׁהֵם אַרְבָּעָה הֵיכָלוֹת שֶׁמְּתֻקָּנִים לְכָל אוֹתָם הָאֲחֵרִים, שְׁנֵי הֵיכָלוֹת לְאֵלֶּה שְׁנֵי הַצְּדָדִים שֶׁל אוֹרוֹת אֲחֵרִים, וְהֵיכָל אֶחָד לְכָל אוֹתָם בַּעֲלֵי הָעֵינַיִם שֶׁעוֹשִׂים חֶשְׁבּוֹן מִכָּל הַמַּעֲשִׂים שֶׁל הָעוֹלָם. וְהֵיכָל אֶחָד לְסוֹפְרִים אֲחֵרִים שֶׁתַּחַת אֵלּוּ הָרִאשׁוֹנִים הַפְּנִימִיִּים. אַרְבַּעַת הַהֵיכָלוֹת הַלָּלוּ כְּלוּלִים בַּהֵיכָל הַזֶּה, שֶׁנִּקְרָא עַל שֵׁם אוֹתָהּ הָרוּחַ שֶׁל זְכוּת, כְּפִי שֶׁאָמַ רְנוּ.</p>\n<p>בְּכָל פֶּתַח וּפֶתַח שֶׁל הַהֵיכָלוֹת הַלָּלוּ יֵשׁ מְמֻנֶּה אֶחָד. בַּפֶּתַח הָרִאשׁוֹן יֵשׁ מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ נִקְרָא גַּזְרִיאֵ\"ל. (לפתחהראשוןששםהכל סנסני\"השממגו לוקח) אוֹתוֹ הַמְמֻנֶּה הָאַחֵר, אוֹתוֹ מְמֻנֶּה לְגַלּוֹת דִּינִים שֶׁנִּדּוֹנוּ וְנִגְזְרוּ לְאוֹתוֹ הַמְמֻנֶּה הָרִאשׁוֹן שֶׁשְּׁמוֹ סַנְסָנִיָּ\"ה, שֶׁמִּמֶּנּוּ נוֹטֵל הַמְמֻנֶּה הָאַחֵר הַזֶּה שֶׁעוֹמֵד עַל הַהֵיכָל שֶׁל הַצַּד הָאַחֵר, וְעוֹמֵד עַל הָאַסְכָּרָה שֶׁל תִּינוֹקוֹת, כְּפִי שֶׁאָמַ רְנוּ.</p>\n<p>וְהַמְמֻנֶּה הַזֶּה גַּזְרִיאֵ\"ל נוֹטֵל דְּבַר בֵּית הַדִּין הַפְּנִימִי, שֶׁהַכֹּל נִגְזָר שָׁם, וְאָז מוֹדִיעַ אֶת הַדָּבָר לַמְמֻנֶּה הַזֶּה שֶׁבַּחוּץ, וְכָל אוֹתָם הַכָּרוֹזִים מַכְרִיזִים וְאוֹמְרִים בְּכָל הָרְקִיעִים: כָּךְ וְכָךְ נִגְזָר מִבֵּית הַמֶּלֶךְ. עַד שֶׁנּוֹטְלִים אֶת אוֹתוֹ הַדָּבָר בַּהֵיכָל שֶׁלְּמַטָּה, וּמִשָּׁם יוֹצְאִים וּמַכְרִיזִים עַל הַדָּבָר, עַד שֶׁזֶּה נִשְׁמָע בְּכָל הָרְקִיעִים הַתַּחְתּוֹנִים, וְיוֹרְדִים וּמוֹדִיעִים אֶת הַדָּבָר לְכֻלָּם לְמַטָּה.</p>\n<p>וְנוֹטְלִים הַדָּבָר כָּל הַתַּחְתּוֹנִים, מִדַּרְגָּה לְדַרְגָּה. אֲפִלּוּ צִפֳּרֵי הַשָּׁמַיִם וְעוֹפוֹת הָאָרֶץ, כֻּלָּם לוֹקְחִים אֶת הַדָּבָר וּמוֹדִיעִים אוֹתוֹ בָּעוֹלָם, עַד שֶׁנּוֹטְלִים הַדָּבָר כָּל אוֹתָם שׁוֹמְרֵי הַחֻקִּים וּמַרְאִים אֶת זֶה בַּחֲלוֹם לַאֲנָשִׁים, וּבָא אוֹתוֹ הַדָּבָר לִזְמַן קָרוֹב.</p>\n<p>וְלִפְעָמִים אוֹתוֹ דָּבָר שֶׁצָּרִיךְ לְמַלְכֵי הָאָרֶץ, שֶׁהֵם מְמֻנִּים לָזוּן וּלְהַנְהִיג עַמִּים, שֶׁמּוֹדִיעִים אֶת אוֹתוֹ הַדָּבָר עַד הָרָקִיעַ שֶׁל הַשֶּׁמֶשׁ שֶׁלְּמַטָּה, וְעוֹמֵד שָׁם. עַד שֶׁאוֹתָם מְמֻנִּים שֶׁל הַשֶּׁמֶשׁ, שֶׁנִּתְמַנּוּ עַל הַשֶּׁמֶשׁ, לוֹקְחִים אֶת אוֹתוֹ הַדָּבָר, וּמוֹדִיעִים אוֹתוֹ לְאוֹתָם הַמְמֻנִּים הָעֶלְיוֹנִים שֶׁל הַצַּד הָאַחֵר, וְהֵם מוֹדִיעִים אֶת הַדָּבָר לְמַלְכֵי הָאָרֶץ, שֶׁהֵם בַּצַּד שֶׁלָּהֶם.</p>\n<p>וּכְשֶׁהָיוּ נְבִיאִים בָּהֶם בְּיִשְׂרָאֵל, הָיוּ נוֹטְלִים נְבוּאָתָם מִשְּׁנֵי עַמּוּדִים עֶלְיוֹנִים שֶׁהַתּוֹרָה סְמוּכָה עֲלֵיהֶם. אַחַר שֶׁהִסְתַּלְּקוּ נְבִיאִים מֵהָעוֹלָם וּבָאוּ בַּעֲלֵי הַמַּרְאֶה וּבַעֲלֵי הַחֲלוֹם, הֵם נוֹטְלִים הַדָּבָר מִמְּקוֹמוֹ, כְּפִי שֶׁאָמַרְנוּ. וּכְשֶׁהָיוּ בֵּין יִשְׂרָאֵל מְלָכִים, וְהִסְתַּלְּקוּ הַנְּבִיאִים, וְלֹא נִמְצְאוּ בַּעֲלֵי מַרְאֶה וּבַעֲלֵי חֲלוֹם, מוֹדִיעִים אֶת הַדָּבָר לְאוֹתָם מְלָכִים מֵהַפֶּתַח הַזֶּה שֶׁאָמַ רְנוּ.</p>\n<p>וְאִם תֹּאמַר, אֵיךְ נוֹטֵל הַדָּבָר מֵהַמָּקוֹם הַזֶּה? בֹּא וּרְאֵה, כָּל דַּרְגָּה וְדַרְגָּה וְכָל פֶּתַח וּפֶתַח, לְכֻלָּם יֵשׁ בַּחוּץ מְמֻנִּים יְדוּעִים שֶׁהִתְמַנּוּ (בצד שלהם) בְּכָל אוֹתָם, הָרְקִיעִים, עַד שֶׁיּוֹרְדִים לְמַטָּה לָרְקִיעִים הַתַּחְתּוֹנִים וּמוֹדִיעִים אֶת הַדָּבָר לְאוֹתָם שֶׁצָּרִיךְ, מִשּׁוּם שֶׁהֲרֵי מֵהַהֵיכָלוֹת הַלָּלוּ, שֶׁהֵם צַד הַקְּדֻשָּׁה וְסוֹד הָאֱמוּנָה, נִפְרָדוֹת דְּרָגוֹת לְמַטָּה, כֻּלָּן בְּסוֹד הָאֱמוּנָה, וְיוֹרְדוֹת מַדְרֵגוֹת עַל מַדְרֵגוֹת עַד שֶׁפּוֹרְחוֹת מִן הָעוֹלָם הַזֶּה, וְהִתְמַנּוּ בוֹ.</p>\n<p>מֵהֶם לִשְׁמֹר בְּנֵי אָדָם מִן הַצַּד הָאַחֵר וּמִנִּזְקֵי הָעוֹלָם, וּבְאוֹתָם הַדְּרָכִים שֶׁבָּהֶם הֵם הוֹלְכִים. וּמֵהֶם כְּדֵי לְסַיֵּעַ לִבְנֵי אָדָם כְּשֶׁבָּאִים לְהִטָּהֵר. וּמֵהֶם לַעֲשׂוֹת אוֹתוֹת וְנִסִּים בָּעוֹלָם, וּמֵהֶם שֶׁעוֹמְדִים כְּדֵי לְהַשְׁגִּיחַ עַל מַעֲשֵׂי בְּנֵי הָאָדָם לְהָעִיד עֵדוּת. וְכֵן (בצורה זו) נִפְרָדוֹת כַּמָּה דְרָגוֹת לְצִדֵּיהֶם, וְכֻלָּם בְּסוֹד הָאֱמוּנָה הָעֶלְיוֹנָה בִּקְדֻשָּׁה עֶלְיוֹנָה.</p>\n<p>כְּמוֹ כֵן בַּצַּד הָאַחֵר, צַד הַטֻּמְאָה, נִפְרָדוֹת דְּרָגוֹת מֵאוֹתָם הַהֵיכָלוֹת לְמַטָּה, כֻּלָּם דְּרָגוֹת לְהָרַע וּלְהַסְטוֹת אֶת הָעוֹלָם. מֵהֶם עוֹמְדִים לְהָסִית בְּנֵי אָדָם מִדֶּרֶךְ טוֹבָה לְדֶרֶךְ רָעָה, וּמֵהֶם קַיָּמִים לְטַמֵּא בְּנֵי אָדָם לְאוֹתָם שֶׁבָּאוּ לְהִטָּמֵא. כְּמוֹ שֶׁשָּׁנִינוּ, בָּא אָדָם לְהִטָּמֵא - מְטַמְּאִים אוֹתוֹ בָּעוֹלָם הַזֶּה וּמְטַמְּאִים אוֹתוֹ בְּאוֹתוֹ עוֹלָם, וְהֵם נִקְרְאוּ צוֹאָה רוֹתַחַת, כְּמוֹ שֶׁנֶּאֱמַר (ישעיהל) צֵא תֹּאמַר לוֹ. וְאוֹתָן דְּרָגוֹת שֶׁעוֹמְדוֹת לְטַמֵּא יוֹתֵר. וּמִשּׁוּם כָּךְ אֵלֶּה תָּמִיד כְּנֶגֶד אֵלֶּה, וְהַכֹּל הוּא בִּדְרָגוֹת יְדוּעוֹת כָּרָאוּי.</p>\n<p>הַפֶּתַח הַשֵּׁנִי. בַּפֶּתַח הַזֶּה יֵשׁ מְמֻנֶּה שֶׁשְּׁמוֹ דַּהֲרִיאֵ\"ל, וְהוּא לְצַד יָמִין, וְזֶהוּ מְמֻנֶּה לְהַכְנִיס אֶת כָּל הַזְּכֻיּוֹת שֶׁזָּכוּ בָהֶם בְּנֵי אָדָם, כְּדֵי שֶׁיִּדּוֹן אָדָם עֲלֵיהֶם לְטוֹב כְּשֶׁנִּדּוֹן לְטוֹב, וְאוֹתָן זְכֻיּוֹת קַיָּמוֹת רַבּוֹת עַל חֲטָאֵי בְּנֵי אָדָם, וְאָז הַמְמֻנֶּה הַזֶּה מְצַוֶּה עַל שָׂכָר וְהַחֵלֶק שֶׁל אוֹתָן הַזְּכֻיּוֹת וְהַשָּׂכָר לְטוֹב.</p>\n<p>וּמוֹצִיא אֶת אוֹתוֹ הַדִּין, וּמְמַנֶּה אֶת אוֹתוֹ מְמֻנֶּה שֶׁנִּקְרָא פָּדִיאֵ\"ל שֶׁבַּהֵיכָל הַשְּׁלִישִׁי. וְאָז אוֹמֵר לוֹ, (איובלג) פְּדָעֵהוּ מֵרֶדֶת שַׁחַת. מִשּׁוּם שֶׁכְּשֶׁאָדָם עוֹמֵד בְּבֵית חָלְיוֹ וְנִתְפָּס בִּתְפִיסַת הַמֶּלֶךְ, אָז נִדּוֹן הָאָדָם. וְכָל זְכוּת וְכָל חֵטְא שֶׁעָשָׂה אָדָם בָּעוֹלָם הַזֶּה, הַכֹּל נִכְנָס בַּהֵיכָל הַזֶּה לִהְיוֹת נִדּוֹן.</p>\n<p>וּכְשֶׁנִּדּוֹן לְטוֹב, בַּפֶּתַח הַזֶּה יוֹצֵא דִינוֹ לְטוֹב, לִימִין הַמְמֻנֶּה הַזֶּה דַּהֲרִיאֵ\"ל שֶׁעוֹמֵד בּוֹ, וּמוֹדִיעִים אֶת דִּינוֹ לְטוֹב, עַד שֶׁנִּצּוֹל. וְיוֹרֵד אוֹתוֹ הַדִּין לְכָל אוֹתָם הַמְמֻנִּים. הַדְּרָגוֹת שֶׁנּוֹדָעוֹת לְטוֹב לְמַטָּה, כֻּלָּן דְּרָגוֹת עַל דְּרָגוֹת, וְהַכֹּל - בֵּין לְטוֹב בֵּין לְרַע - מִבֵּית הַמֶּלֶךְ נִדּוֹן אוֹתוֹ אָדָם.</p>\n<p>הַפֶּתַח הַשְּׁלִישִׁי. בַּפֶּתַח הַזֶּה יֵשׁ מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ גָּדִיאֵ\"ל, וְהוּא לְצַד שְׂמֹאל, וְזֶהוּ הַמְמֻנֶּה לְהַכְנִיס (לשקל) אֶת כָּל הַחֲטָאִים וְכָל הָרָעוֹת שֶׁאָדָם סָטָה אַחֲרֵיהֶם בָּעוֹלָם הַזֶּה, וּמוֹרִיד אוֹתָם לְתוֹךְ מִשְׁקָל לְהִשָּׁקֵל עִם אוֹתָן זְכֻיּוֹת שֶׁנִּכְנְסוּ בְּיַד אוֹתוֹ הַמְמֻנֶּה הָאַחֵר שֶׁאָמַרְנוּ.</p>\n<p>וְאוֹתוֹ הַמִּשְׁקָל עוֹמֵד בְּתוֹךְ הַפֶּתַח הָרְבִיעִי, וְשָׁם נִשְׁקָלִים זְכֻיּוֹת וְחוֹבוֹת כְּאֶחָד. מִי שֶׁנִּצַּח מֵהֶם - כָּךְ יֵשׁ לוֹ מְמֻנִּים בְּאוֹתוֹ הַצַּד. אִם הַזְּכֻיּוֹת נִצְּחוּ - כַּמָּה מְמֻנִּים יֵשׁ בְּצַד יָמִין שֶׁנּוֹטְלִים אוֹתוֹ הַדִּין, וּמַעֲבִירִים אֶת הָרָעוֹת וְהַמַּחֲלוֹת מֵאוֹתוֹ אָדָם עַד שֶׁנִּצּוֹל. אִם הַחֲטָאִים נִצְּחוּ - כַּמָּה מְמֻנִּים יֵשׁ לוֹ בְּאוֹתוֹ צַד שְׂמֹאל, עַד שֶׁלּוֹקְחִים הַדָּבָר אוֹתוֹ הַצַּד הָאַחֵר וְכָל אוֹתָם שׁוֹמְרֵי הַחֻקִּים, עַד שֶׁהוּרַע מַזָּלוֹ. וְאָז יוֹרֵד אוֹתוֹ הַצַּד הָאַחֵר וְנוֹטֵל אֶת הַנְּשָׁמָה. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>הַפֶּתַח הָרְבִיעִי. בַּפֶּתַח הַזֶּה עוֹמֵד מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ ואזני\"ה (מאזני\"ה). וְזֶהוּ מִשְׁקָל שֶׁנּוֹטֵל (ששוקל) זְכֻיּוֹת וְחוֹבוֹת, וּבוֹ נִשְׁקָלִים כֻּלָּם כְּאֶחָד. וְזֶה נִקְרָא מֹאזְנֵי צֶדֶק, כְּמוֹ שֶׁכָּתוּב (ויקרא יט) מֹאזְנֵי צֶדֶק. בָּזֶה נִשְׁקָלִים כֻּלָּם לְהִדּוֹן.</p>\n<p>תַּחַת הַמְמֻנֶּה הַזֶּה יֵשׁ שְׁנֵי מְמֻנִּים, אֶחָד לְיָמִין וְאֶחָד לִשְׂמֹאל. אֶחָד לְיָמִין, הֲרִיאֵ\"ל שְׁמוֹ. אֶחָד לִשְׂמֹאל, גְּדוּדִיאֵ\"ל שְׁמוֹ. וּכְשֶׁנִּשְׁקָלִים זְכֻיּוֹת וְחוֹבוֹת - זֶה מַכְרִיעַ לְצַד יָמִין, וְזֶה מַכְרִיעַ לְצַד שְׂמֹאל. וְכֻלָּם נִכְלְלוּ בָּרוּחַ הַזּוֹ שֶׁנִּקְרֵאת זְכוּ\"ת אֵל.</p>\n<p>וּכְשֶׁכֻּלָּם נִכְלָלִים בָּהּ, מוֹצִיאָה חַיָּה (אחת) קְדוֹשָׁה, וְהַחַיָּה הַזּוֹ לוֹהֶטֶת, וּשְׁמָהּ נִקְרָא תּוּמִיאֵ\"ל. הַחַיָּה הַזּוֹ הִיא חַיָּה שֶׁעוֹמֶדֶת לְהַשְׁגִּיחַ בָּעוֹלָם בְּאוֹתָם עֵינֵי ה' שֶׁהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם. וְאוֹתָם עֵינֵי ה', כֻּלָּם נוֹטְלִים הַשְׁגָּחָה מֵאוֹתָם מַעֲשִׂים טוֹבִים שֶׁנַּעֲשׂוּ בַּסֵּתֶר, וּלְהַשְׁגִּיחַ בְּאוֹתָם מַעֲשִׂים שֶׁהֵם בִּשְׁלֵמוּת הַלֵּב, וְאַף עַל גַּב שֶׁלֹּא נַעֲשׂוּ כָּרָאוּי.</p>\n<p>הַחַיָּה הַזּוֹ עוֹמֶדֶת בְּהַשְׁגָּחַת הַתְּפִלּוֹת, מִשּׁוּם שֶׁאוֹתָן בַּקָּשׁוֹת שֶׁמְּבַקְשִׁים אֲנָשִׁים בִּתְפִלּוֹתֵיהֶן, כֻּלָּן עוֹמְדוֹת בִּידֵי הַחַיָּה הַזֹּאת, וּמַנִּיחָה אוֹתָן בַּהֵיכָל הַזֶּה. וְאוֹתָן הַבַּקָּשׁוֹת עוֹמְדוֹת בַּהֵיכָל הַזֶּה עַד אַרְבָּעִים יוֹם לְהַשְׁגִּיחַ בָּהֶן.</p>\n<p>שֶׁהֲרֵי (בסוף ארבעים יום) בְּכָל אַרְבָּעִים וְאַרְבָּעִים יוֹצֵאת הַחַיָּה הַזּוֹ וְלוֹקַחַת אֶת כָּל אוֹתָן הַבַּקָּשׁוֹת, וּמַנִּיחָה אוֹתָן לִפְנֵי אוֹתָם שִׁבְעִים וּשְׁנַיִם אוֹרוֹת, וְדָנִים אוֹתָן. וְאָז הָרוּחַ הַזּוֹ שֶׁנִּקְרֵאת זְכוּ\"ת אֵל, מְעַיֶּנֶת בָּהֶן אִם זוֹכֶה וְאִם לֹא זוֹכֶה. אִם זוֹכֶה - יוֹצֵאת הַתְּפִלָּה הַזּוֹ, וּמִתְגַּלְגֶּלֶת הַבַּקָּשָׁה הַזּוֹ, וְיוֹצְאִים עִמָּהּ שְׁנֵים עָשָׂר מְמֻנִּים, וְכָל אֶחָד וְאֶחָד תּוֹבְעִים מֵעִם אוֹתָהּ הָרוּחַ קִיּוּם בַּבַּקָּשָׁה הַזּוֹ, וּמִתְקַיֶּמֶת בָּהֶם.</p>\n<p>תַּחַת הַחַיָּה הַזּוֹ אַרְבָּעָה שְׂרָפִים לוֹהֲטִים: שְׂרַפְאֵ\"ל, בַּרְקִיאֵ\"ל, קְרִישִׁיאֵ\"ל, קְדוּמִיָּ\"ה. וְאַרְבָּעָה הַלָּלוּ שֶׁתַּחַת הַחַיָּה הַזּוֹ עוֹמְדִים לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. אֵלּוּ הָאַרְבָּעָה עוֹמְדִים לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְהֵם מְמֻנִּים לְהַשְׁגִּיחַ בְּכָל אוֹתָם שֶׁשּׁוֹמְרִים אֶת יוֹם הַשַּׁבָּת וּמְעַנְּגִים אֶת הַשַּׁבָּת כָּרָאוּי.</p>\n<p>מֵהָאַרְבָּעָה הַלָּלוּ, כְּשֶׁנּוֹסְעִים, יוֹצְאִים שְׁבִיבֵי אֵשׁ, וּמֵהַשְּׁבִיבִים הַלָּלוּ נַעֲשִׂים שִׁבְעִים וּשְׁנַיִם גַּלְגַּלִּים לוֹהֲטִים בְּאֵשׁ. מִכָּאן נַעֲשֶׂה נְהַר דִּינוּר. אֶלֶף אֲלָפִים יְשַׁמְּשׁוּ אֶת אוֹתוֹ הַנָּהָר. כָּל אוֹתָם שֶׁמְּעַנְּגִים שַׁבָּת, אַרְבַּעַת הַמְמֻנִּים הַלָּלוּ מַשְׁגִּיחִים בְּכָל אוֹתָם שֶׁמְּעַנְגִּים אֶת הַשַּׁבָּת, וְהַחַיָּה הַזּוֹ עוֹמֶדֶת עֲלֵיהֶם, וְנוֹסְעִים בִּשְׁבִילָהּ תַּחְתֶּיהָ.</p>\n<p>בְּכָל יוֹם וָיוֹם זוֹרֵם אוֹתוֹ נְהַר דִּינוּר וְשׂוֹרֵף כַּמָּה רוּחוֹת וְכַמָּה שַׁלִּיטִים. וּכְשֶׁנִּכְנֶסֶת שַׁבָּת, יוֹצֵא כָרוֹז, וְשׁוֹכֵךְ אוֹתוֹ נְהַר דִּינוּר, וְהַסְּעָרוֹת וְהַזִּיקִים וְהַשְּׁבִיבִים שׁוֹכְכִים. וְהַחַיָּה הַזּוֹ הוֹלֶכֶת וְעוֹלָה עַל אַרְבַּעַת הַשְּׂרָפִים הַלָּלוּ שֶׁאָמַרְנוּ, וְנִכְנֶסֶת לְתוֹךְ אֶמְצַע הַהֵיכָל הַזֶּה לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא עֹנֶג.</p>\n<p>מִשּׁוּם שֶׁבַּמָּקוֹם הַזֶּה, כְּשֶׁנִּכְנֶסֶת שַׁבָּת, מִסְתַּדְּרִים שָׁם כָּל שֻׁלְחֲנוֹת בְּנֵי הָעוֹלָם, שֶׁנִּקְרָאִים בְּנֵי הֵיכַל הַמֶּלֶךְ. וְאֶלֶף אֲלָפִים וְרִבּוֹא רְבָבוֹת עוֹמְדִים עַל אוֹתָם הַשֻּׁלְחָנוֹת. וְהַחַיָּה הָעֶלְיוֹנָה הַזּוֹ עַל אַרְבַּעַת הַשְּׂרָפִים הַלָּלוּ, וְנִכְנֶסֶת לְאוֹתוֹ מָקוֹם, וְרוֹאָה שָׁם אֶת כָּל אוֹתָם הַשֻּׁלְחָנוֹת (וכל אותם שעומדים עליהם), וּמַשְׁגִּיחָה בְּכָל שֻׁלְחָן וְשֻׁלְחָן, וְאֵיךְ מְעַנְּגִים אֶת כָּל שֻׁלְחָן וְשֻׁלְחָן, וְעוֹמֶדֶת וּמְבָרֶכֶת אֶת אוֹתוֹ הַשֻּׁלְחָן. וְכָל אוֹתָם אֶלֶף אֲלָפִים וְרִבּוֹא רְבָבוֹת, כֻּלָּם פּוֹתְחִים וְאוֹמְרִים אָמֵן.</p>\n<p>וּמָה הַבְּרָכָה שֶׁמְּבָרֵךְ עַל הַשֻּׁלְחָן הַזֶּה שֶׁנֶּעֱרַךְ וְנֶעֱנַג כָּרָאוּי? (ישעיהנח) אָז תִּתְעַנַּג עַל ה' וְגוֹ' כִּי פִּי ה' דִּבֵּר. וְכֻלָּם אוֹמְרִים: אָז תִּקְרָא וַה' יַעֲנֶה וְגוֹ'. רוּחַ הָעֶלְיוֹנָה שֶׁנִּקְרֵאת זְכוּ\"ת אֵל, כְּשֶׁאוֹתוֹ הַשֻּׁלְחָן מִתְעַנֵּג בְּכָל הַסְּעוּדוֹת, בַּסְּעוּדָה הָאַחֲרוֹנָה הַשְּׁלִישִׁית מְסַיֵּם וְאוֹמֵר עַל כָּל אוֹתָם הָרִאשׁוֹנִים, וְאוֹמֵר: אָז יִבָּקַע כַּשַּׁחַר אוֹרֶךְ וְגוֹ', כְּבוֹד ה' יַאַסְפֶךְ. כָּל אוֹתָם שִׁבְעִים אוֹרוֹת אֲחֵרִים בְּכָל הַצְּדָדִים פּוֹתְחִים וְאוֹמְרִים: (תהלים קכח) הִנֵּה כִּי כֵן יְבֹרַךְ גָּבֶר יְרֵא ה'.</p>\n<p>וּכְשֶׁשֻּׁלְחַן הָאָדָם אֵינוֹ עוֹמֵד בְּאוֹתוֹ מָקוֹם בַּעֲרִיכַת הָעֹנֶג כָּרָאוּי, אָז הַחַיָּה הַזּוֹ, וְאוֹתָן אַרְבַּע שֶׁתַּחְתֶּיהָ, וְכָל אוֹתָם אֶלֶף אֲלָפִים וְרִבּוֹא רְבָבוֹת, כֻּלָּם דּוֹחִים אוֹתוֹ הַחוּצָה לְאוֹתוֹ צַד הָאַחֵר, וְכַמָּה שׁוֹמְרֵי הַחֻקִּים, כֻּלָּם נוֹטְלִים אוֹתוֹ וּמַכְנִיסִים אוֹתוֹ לְאוֹתוֹ מָקוֹם, שֶׁהוּא בְּהֵפֶךְ מִזֶּה, וְנִקְרָא נֶגַע. וּכְשֶׁמַּכְנִיסִים אוֹתוֹ לְשָׁם, (פותחים ואומרים) (שם קט) וַיֶּאֱהַב קְלָלָה וַתְּבוֹאֵהוּ וְלֹא חָפֵץ בִּבְרָכָה וַתִּרְחַק מִמֶּנּוּ. יְנַקֵּשׁ נוֹשֶׁה לְכָל אֲשֶׁר לוֹ וְגוֹ', אַל יְהִי לוֹ מֹשֵׁךְ חָסֶד וְגוֹ'. הָרַחֲמָן יַצִּילֵנוּ.</p>\n<p>מִשּׁוּם שֶׁעֹנֶג שַׁבָּת, וֶאֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא (זה אלו אותם שלחנות של ענג שבת ומועדים וחגים, כלם שמחהשלהקדושברוך הוא, ומשוםכך) הוּא. וּמִשּׁוּם זֶה, כָּל אוֹתָם שֶׁמְּעַנְּגִים עֹנֶג הַשַּׁבָּת וּזְמַנִּים וּמוֹעֲדִים, אַרְבַּעַת הַלָּלוּ שֶׁעוֹמְדִים תַּחַת הַחַיָּה הַזּוֹ עוֹמְדִים כְּנֶגֶד אוֹתוֹ נְהַר דִּינוּר, וְלֹא נוֹתְנִים לְהִשָּׂרֵף שָׁם אֶת כָּל אֵלּוּ שֶׁמְּעַנְּגִים עִנּוּגֵיהֶם כָּרָאוּי.</p>\n<p>תַּחַת הָאַרְבָּעָה הַלָּלוּ יֵשׁ מְמֻנִּים אֲחֵרִים שֶׁעוֹמְדִים בַּחוּץ, שֶׁנּוֹדָעִים מִצַּד הַהֵיכָל הַזֶּה, (וכל הכרוזיםבחוץ) וּמַכְרִיזִים עַל כָּל אוֹתָם הַדִּינִים וְעַל כָּל אוֹתָן הַגְּזֵרוֹת שֶׁנִּגְזְרוּ בַּהֵיכָל הַזֶּה.</p>\n<p>הַכֹּל נִדּוֹן כָּאן, פְּרָט לִשְׁלֹשָׁה דְבָרִים שֶׁלֹּא נִתֶּנֶת רְשׁוּת כָּאן בַּהֵיכָל הַזֶּה שֶׁנִּקְרָא זְכוּת, וְאֵלּוּ הֵם: בְּנֵי, חַיֵּי וּמְזוֹנֵי. שֶׁהֲרֵי שְׁלֹשֶׁת אֵלֶּה לֹא עוֹמְדִים כָּאן, מִשּׁוּם שֶׁהֲרֵי הֵם תְּלוּיִים בְּמַזָּל. שֶׁהֲרֵי אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, שָׁם תְּלוּיִים הַחַיִּים שֶׁלְּמַעְלָה, וְשָׁם תְּלוּיִים הַמְּזוֹנוֹת, וְשָׁם תְּלוּיִים הַבָּנִים. שֶׁהֲרֵי שְׁלֹשֶׁת אֵלֶּה יוֹצְאִים מִשָּׁם וְשׁוֹפְעִים וְנִמְשָׁכִים לְמַטָּה. וּמִשּׁוּם כָּךְ הַכֹּל עוֹמֵד בַּהֵיכָל הַזֶּה, פְּרָט לִשְׁלֹשֶׁת אֵלּוּ.</p>\n<p>כְּשֶׁאָדָם הוּא בְּבֵית חָלְיוֹ, כָּאן הוּא נִדּוֹן, וְכֵן כָּל שְׁאָר הַדִּינִים שֶׁבָּעוֹלָם. וְאִם תֹּאמַר, אִם אָדָם בְּבֵית חָלְיוֹ נִדּוֹן לְחַיִּים - נוֹתְנִים לוֹ. לֹא שֶׁהַחַיִּים תְּלוּיִים כָּאן, אֶלָּא כְּשֶׁנִּדּוֹן כָּאן לְחַיִּים, אֲזַי שׁוֹפְעִים הַחַיִּים מִלְמַעְלָה וְנוֹתְנִים לוֹ (ואם לא לא נותנים). אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁיּוֹדְעִים דַּרְכֵי הַתּוֹרָה וְזוֹכִים בָּהּ לְחַיֵּי עוֹלָם, עֲלֵיהֶם כָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ.</p>"],[9522011911,"<p>הַהֵיכָל הַחֲמִישִׁי. הַהֵיכָל הַזֶּה עוֹמֵד לְהָאִיר לַתַּחְתּוֹנִים הַלָּלוּ. וְזֶהוּ הַהֵיכָל שֶׁעוֹמֵד לְהָאִיר בְּסוֹד הָאֱמוּנָה. פֶּתַח אֶחָד עוֹמֵד בַּהֵיכָל הַזֶּה וּמְמֻנֶּה אֶחָד עָלָיו, וְאוֹתוֹ מְמֻנֶּה נִקְרָא סָנֵגוֹרְיָ\"ה. הַמְמֻנֶּה הַזֶּה עוֹמֵד עַל הַפֶּתַח הַזֶּה כְּדֵי לְלַמֵּד (סנגוריה על ישראל, ובגלל זה נקרא שמוכך, שהריהואממגהעלכלאותןטובותשל ישראל להכניס סנגוריה וכו') סָנֵגוֹרְיָה שֶׁלָּהֶם לִפְנֵי רִבּוֹנָם, וְלֹא יִשְׁלֹט עֲלֵיהֶם הַצַּד הָאַחֵר.</p>\n<p>בַּהֵיכָל הַזֶּה עוֹמֶדֶת רוּחַ אַחַת שֶׁכְּלוּלָה בְּאַרְבַּע, שֶׁהֲרֵי רוּחַ זוֹ כְּלוּלָה בְּאַרְבָּעָה גְוָנִים: לָבָן, שָׁחֹר, יָרֹק וְאָדם. וְזוֹהִי רוּחַ שֶׁעוֹמֶדֶת כְּלוּלָה בַּכֹּל, וְנִקְרֵאת סוּרִיָּ\"ה. גְּדוֹלָה עַל כָּל אוֹתָם חֲיָלוֹת תַּחְתּוֹנִים. וְכֻלָּם עוֹמְדִים תַּחְתֶּיהָ וּמְמֻנִּים תַּחַת יָדָהּ.</p>\n<p>הָרוּחַ הַזּוֹ שֶׁסּוֹגֶרֶת וּפוֹתַחַת. כָּל הַמַּפְתְּחוֹת הָעֶלְיוֹנִים כֻּלָּם מְסוּרִים בְּיָדָהּ. (שלש פעמים ביום) כָּל הַחֲיָלוֹת הַתַּחְתּוֹנִים כֻּלָּם נִכְלְלוּ וְעוֹמְדִים תַּחְתֶּיהָ וּמִמֶּנָּה נִזּוֹנִים. זֶה עוֹמֵד בְּכָל סוֹדוֹת רִבּוֹנוֹ, כָּל הַגְּנָזִים הָעֶלְיוֹנִים כֻּלָּם נִמְסְרוּ בְיָדָהּ.</p>\n<p>הָרוּחַ הַזּוֹ נִקְרֵאת אַהֲבָה, וּמִשּׁוּם כָּךְ נִקְרָא הַהֵיכָל הַזֶּה הֵיכָל אַהֲבָה. מִשּׁוּם שֶׁכָּאן נִגְנְזוּ כָּל סוֹד הַסּוֹדוֹת לְמִי שֶׁצָּרִיךְ לְהִדָּבֵק בּוֹ, וְכָאן הוּא סוֹד הַכָּתוּב, (שיר השירים ז) שָׁם אֶתֵּן אֶת דֹּדַי לָךְ.</p>\n<p>הָרוּחַ הַזּוֹ הִיא הַשּׁוֹמֶרֶת אֶת כָּל הַשְּׁמִירָה שֶׁלְּמַעְלָה, וְזוֹ נִקְרֵאת (תהלים קכא) שׁוֹמֵר יִשְׂרָאֵל, (דברים ז) שׁוֹמֵר הַבְּרִית. מִשּׁוּם שֶׁכָּאן הִיא שְׁמִירַת כָּל הַגְּנָזִים הָעֶלְיוֹנִים, וְעַל כֵּן גִּנְזֵי רִבּוֹנוֹ גְּנוּזִים בָּהּ. מִזֶּה יוֹצְאִים שְׁבִילִים וּדְרָכִים לְאוֹתָם שֶׁלְּמַטָּה כְּדֵי לְעוֹרֵר בָּהֶם רוּחַ שֶׁל אַהֲבָה.</p>\n<p>אַרְבַּעַת הַגְּוָנִים הַלָּלוּ שֶׁבָּהּ נִכְלְלוּ זֶה בָּזֶה. וּכְשֶׁרוֹצִים לְהִכָּלֵל, מַכֶּה זֶה בָּזֶה, וְיוֹצֵאת מִכֻּלָּם חַיָּה קְדוֹשָׁה אַחַת שֶׁנִּקְרֵאת זֹהַר. וְהַחַיָּה הַזּוֹ עָלֶיהָ כָּתוּב, (יחזקאל א) הִיא הַחַיָּה אֲשֶׁר רָאִיתִי עַל נְהַר כְּבָר.</p>\n<p>מֵהַהֵיכָל הַזֶּה יוֹצְאוֹת כָּל הָרוּחוֹת הַקְּדוֹשׁוֹת שֶׁעוֹמְדוֹת בְּקִיּוּם שֶׁל הַנְּשִׁיקוֹת (העליונות), שֶׁהֲרֵי מֵאוֹתָן הַנְּשִׁיקוֹת יוֹצֵא אֲוִיר שֶׁל רוּחַ לְקִיּוּם הַנֶּפֶשׁ לְכָל אוֹתָן הַנְּשָׁמוֹת הָעֶלְיוֹנוֹת שֶׁנִּתְּנוּ בִּבְנֵי אָדָם, וְסוֹד אוֹתוֹ הַכָּתוּב (דברים ח) כִּי עַל כָּל מוֹצָא פִּי ה' יִחְיֶה הָאָדָם. מִשּׁוּם שֶׁבַּהֵיכָל הַזֶּה עוֹמְדוֹת כָּל הַנְּשָׁמוֹת וְכָל הָרוּחוֹת שֶׁעֲתִידוֹת לָרֶדֶת בִּבְנֵי הָאָדָם מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, וְעַל כֵּן הַהֵיכָל הַזֶּה לוֹקֵחַ כָּל אוֹתָן נְשָׁמוֹת שֶׁיּוֹצְאוֹת מֵאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא. וּמִשּׁוּם כָּךְ הַהֵיכָל הַזֶּה לֹא עוֹמֵד לְעוֹלָם בְּרֵיקָנוּת.</p>\n<p>וּמִיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, לֹא נִכְנְסוּ לְכָאן נְשָׁמוֹת אֲחֵרוֹת. וּכְשֶׁיִּסְתַּיְּמוּ אֵלֶּה, הַהֵיכָל עוֹמֵד בְּרֵיקָנוּת וְיִפָּקֵד מִלְמַעְלָה, וְאָז יָבֹא מֶלֶךְ הַמָּשִׁיחַ, וְיִתְעוֹרֵר הַהֵיכָל הַזֶּה לְמַעְלָה, וְיִתְעוֹרֵר הַהֵיכָל לְמַטָּה.</p>\n<p>וּבְסוֹד הַהֵיכָל הַזֶּה כָּתוּב, (שיר ד) שְׁנֵי שָׁדַיִךְ כִּשְׁנֵי עֳפָרִים וְגוֹ'. מִשּׁוּם שֶׁבַּהֵיכָל הַזֶּה אוֹתָהּ הָרוּחַ שֶׁאָמַרְנוּ. וְאוֹתָהּ הַחַיָּה מוֹצִיאָה שְׁנֵי אוֹרוֹת כְּלוּלִים זֶה עִם זֶה, שֶׁקְּשׁוּרִים זֶה בָּזֶה, וְנִקְרָאִים אֵ\"ל שַׁדַּ\"י. אֵלּוּ נִקְרָאִים שַׁדַּ\"י, וְאֵ\"ל שֶׁלְּמַטָּה, מִתְחַבְּרִים זֶה בָּזֶה וְנִכְנָסִים זֶה לָזֶה. וְנִקְרָא אֵ\"ל שַׁדַּ\"י, מִשּׁוּם שֶׁיּוֹצֵא מִכְּלָלוּת הַשָּׁדַיִם הַלָּלוּ.</p>\n<p>וְהָאֵ\"ל הַזֶּה, שֶׁהוּא מִצַּד הַיָּמִין, נוֹטֵל מִמָּקוֹם זֶה כָּל אוֹתָם הָרַחֲמִים שֶׁעוֹמְדִים לְהָזִין אֶת אוֹתוֹ הַהֵיכָל שֶׁלְּמַטָּה שֶׁנִּקְרָא זְכוּ\"ת, עַל שֵׁם הָרוּחַ הַזּוֹ שֶׁבּוֹ שֶׁאָמַרְנוּ. הַשַּׁדַּי הַזֶּה מֵינִיק אֶת כָּל אוֹתָם הַתַּחְתּוֹנִים וְכָל אוֹתָם הַהֵיכָלוֹת וְכָל אוֹתָם שֶׁבַּחוּץ שֶׁעוֹמְדִים בַּצַּד הַזֶּה, שֶׁנִּקְרָאִים יִתְדוֹת הַמִּשְׁכָּן, כְּמוֹ שֶׁבֵּאַרְנוּ. וְלָכֵן נִקְרָא שַׁדַּי, מִשּׁוּם שֶׁמְּסַפֵּק מָזוֹן לְכָל הַתַּחְתּוֹנִים, כְּמוֹ שֶׁהוּא מְקַבֵּל מִצַּד הַיָּמִין.</p>\n<p>מִכָּאן יוֹצְאִים אוֹתָם הָאוֹרוֹת שֶׁנִּקְרָאִים (בראשית ג) לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, מִשּׁוּם שֶׁמִּתְהַפֶּכֶת לְכַמָּה גְוָנִים, וַהֲרֵי בֵּאַרְנוּ, שֶׁאֵלֶּה מְעוֹרְרִים דִּין בַּשְּׁלִיחוּת שֶׁלְּמַעְלָה, וְהֵם בָּעוֹלָם מִצַּד הַשְּׂמֹאל, כְּשֶׁנִּפְרֶדֶת (כשמתפשטת) הָרוּחַ הַזּוֹ וּמַכָּה לְהוֹצִיא אוֹרוֹת לְכָל הַצְּדָדִים, כְּמוֹ אוֹתָם הַשָּׁדַיִם שֶׁשּׁוֹפְכוֹת חָלָב לְכָל צַד, כָּךְ גַּם מֵהָרוּחַ הַזּוֹ יוֹצְאִים לְכָל צַד, וּמוֹצִיאִים חַיָּה אַחַת אַחֶרֶת שֶׁמְּמֻנָּה עַל אֵלֶּה, שֶׁנִּקְרָא לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, וְזֶה נִקְרָא.</p>\n<p>וְאוֹתוֹ וְזֶה שֶׁמְּמֻנֶּה עַל הָעוֹלָם, בִּזְמַן שֶׁמְּמֻנֶּה הָרָעָב עַל הָעוֹלָם וְנִדּוֹן בּוֹ, אֲזַי הַחַיָּה הַזּוֹ מֻפְקֶדֶת עַל הָעוֹלָם, וּמוֹצִיאָה רוּחַ שֶׁל מָזוֹן לְכָל אוֹתָם בְּנֵי הָאֱמוּנָה שֶׁלֹּא יָמוּתוּ בָרָעָב וְסוֹעֶדֶת לִבָּם. מִשּׁוּם שֶׁהֲרֵי מֵהַצַּד הָאַחֵר, כְּשֶׁשּׁוֹלֵט הָרָעָב בָּעוֹלָם, יוֹצְאוֹת מֵהַצַּד הַזֶּה שְׁתֵּי רוּחוֹת טְמֵאוֹת שֶׁנִּקְרָאוֹת שׁוֹד וְכָפָן. וְזֶהוּ סוֹד - (איוב ה) לְשֹׁד וּלְכָפָן תִּשְׂחָק. מִשּׁוּם שֶׁאֵלּוּ עוֹמְדִים בָּעוֹלָם וְעוֹשִׂים קִטְרוּג לַאֲנָשִׁים. אֶחָד - אוֹתוֹ שֶׁשּׁוֹלֵחַ לָהֶם רָעָב וּמֵתִים. וְאֶחָד - שֶׁאֲנָשִׁים אוֹכְלִים וְלֹא שְׂבֵעִים, מִשּׁוּם שֶׁהֲרֵי רוּחַ רָעָה שׁוֹלֶטֶת בָּעוֹלָם.</p>\n<p>הַחַיָּה הַזּוֹ מוֹצִיאָה נִיצוֹץ אֶחָד שֶׁיּוֹצֵא מֵהִתְנוֹצְצוּת שֶׁל שְׁנֵי נִיצוֹצוֹת שֶׁאָמַרְנוּ, שֶׁהֵם מִתְהַפְּכִים לְכַמָּה גְוָנִים. וְהַנִּיצוֹץ הַזֶּה נִקְרָא שְׂרָפִים, וְזֶה אוֹחֵז בָּהֶם וּמַלְהִיט אוֹתָם.</p>\n<p>בַּהֵיכָל הַזֶּה יֵשׁ שְׁנֵי מְמֻנִּים, אוֹרוֹת שֶׁעוֹמְדִים עַל אֶלֶף וְרִבּוֹא רְבָבוֹת שֶׁנִּקְרָאִים גְּפָנִים, וְאֶלֶף וְרִבּוֹא רְבָבוֹת שֶׁנִּקְרָאִים רִמּוֹנִים, וְכֻלָּם עוֹמְדִים בַּחֲבִיבוּת, וְאֵלּוּ הֵם שֶׁמַּכְנִיסִים אַהֲבָה בֵּין יִשְׂרָאֵל לְמַטָּה לַקָּדוֹשׁ-בָּרוּךְ-הוּא לְמַעְלָה. וְכֻלָּם מְעוֹרְרִים אַהֲבָה וְעוֹמְדִים בְּאַהֲבָה. וּכְשֶׁמִּתְעוֹרֶרֶת אַהֲבָה מִמַּטָּה לְמַעְלָה וּמִמַּעְלָה לְמַטָּה, אָז מִתְמַלֵּא הַהֵיכָל הַזֶּה מִכַּמָּה טוֹבוֹת, מִכַּמָּה חֲסָדִים, מִכַּמָּה רַחֲמִים, וְאָז הָאַהֲבָה שֶׁלְּמַטָּה תּוֹךְ הָאַהֲבָה הָעֶלְיוֹנָה נִדְבָּקוֹת זוֹ בָּזוֹ.</p>\n<p>מִכָּאן יוֹצְאִים שְׁנֵי מְמֻנִּים שֶׁנִּקְרָאִים אַהֲבָה, עַל שֵׁם הַהֵיכָל. וְאֵלּוּ עוֹמְדִים לְהַשְׁגִּיחַ עַל כָּל אוֹתָם שֶׁמְּיַחֲדִים אֶת יִחוּד רִבּוֹנָם בְּאַהֲבָה, וּמוֹסְרִים נַפְשָׁם עָלָיו בְּאַהֲבָה, וְעוֹלִים וּמְעִידִים לְמַעְלָה. וְכָל אוֹתָם שֶׁעוֹשִׂים חֶסֶד בָּעוֹלָם, אוֹתָם הַחֲסָדִים עוֹלִים וְנִכְנָסִים לְתוֹךְ הַהֵיכָל הַזֶּה וּמִתְעַטְּרִים שָׁם, וְעוֹלִים לְהִתְעַטֵּר בְּתוֹךְ אַהֲבָה עֶלְיוֹנָה. וְעַל זֶה כָּתוּב, (תהלים קח) כִּי גָדֹל מֵעַל שָׁמַיִם חַסְדֶּךְ. בַּהֵיכָל הַזֶּה כָּתוּב, (שיר השירים ח) מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה וּנְהָרוֹת לֹא יִשְׁטְפוּהָ וְגוֹ'.</p>"],[9522011912,"<p>הַהֵיכָל הַשִּׁשִּׁי. זֶהוּ הַהֵיכָל שֶׁנִּקְרָא הֵיכַל הָרָצוֹן, שֶׁהוּא רָצוֹן שֶׁנִּקְרָא (דברים ח) מוֹצָא פִי ה', שִׂמְחָה שֶׁל הִדָּבְקוּת שֶׁל הַכֹּל. וְכָאן הוּא רְצוֹן הָרְצוֹנוֹת, בְּסוֹד הַכָּתוּב (שיר השירים ד) כְּחוּט הַשָּׁנִי שִׂפְתוֹתַיִךְ. רְצוֹן כָּל הַנְּשָׁמוֹת שֶׁיּוֹצְאוֹת מֵאוֹתוֹ מוֹצָא פִי ה'.</p>\n<p>הַהֵיכָל הַזֶּה הֵיכַל הָרָצוֹן, שֶׁשָּׁם עוֹמְדוֹת כָּל הַבַּקָּשׁוֹת וְכָל הַשְּׁאֵלוֹת שֶׁבָּעוֹלָם, מִשּׁוּם שֶׁרְצוֹן כָּל הָרְצוֹנוֹת כְּשֶׁנְּשִׁיקוֹת נִמְצָאוֹת, בְּסוֹד הַכָּתוּב (בראשית כט) וַיִּשַּׁק יַעֲקֹב לְרָחֵל. וְאָז, כְּשֶׁנּוֹשֵׁק זֶה לָזֶה, אָז נִקְרֵאת עֵת רָצוֹן, מִשּׁוּם שֶׁהֲרֵי אָז נִמְצֵאת שְׁלֵמוּת וְכָל הַפָּנִים מְאִירוֹת. וּכְשֶׁתְּפִלּוֹת עוֹלוֹת, אָז הוּא עֵת רָצוֹן לְהִמָּצֵא. וְעַל כֵּן כָּתוּב, (תהלים סט) וַאֲנִי תְפִלָּתִי לְךְ ה' עֵת רָצוֹן. שֶׁהוּא חִבּוּר זֶה עִם זֶה.</p>\n<p>בַּהֵיכָל הַזֶּה עוֹמְדִים שִׁשָּׁה פְתָחִים. אַרְבָּעָה פְתָחִים לְאַרְבָּעָה צְדָדִים שֶׁל הָעוֹלָם, וְאֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה. בַּפְּתָחִים הַלָּלוּ הִתְמַנָּה רוּחַ אֶחָד שֶׁהוּא גָּדוֹל עַל כָּל הַמְמֻנִּים בְּכָל אוֹתָם הַפְּתָחִים, וּשְׁמוֹ רָזִיאֵ\"ל. וְזֶה הִתְמַנָּה וְנִפְקַד עַל כָּל אוֹתָם הַסּוֹדוֹת הָעֶלְיוֹנִים, שֶׁמְּדַבְּרִים פֶּה לְפֶה, שֶׁנּוֹשְׁקִים זֶה לָזֶה בְּאַהֲבַת הָאַהֲבָה.</p>\n<p>הַסּוֹדוֹת הַלָּלוּ אֵינָם עוֹמְדִים לְגִלּוּי, אֲבָל כְּשֶׁנִּפְתָּחִים הַשְּׁעָרִים, אָז יוֹדְעִים כָּל הַהֵיכָלוֹת וְכָל אוֹתָן רוּחוֹת וְכָל אוֹתָם מַחֲנוֹת, שֶׁהֲרֵי נִפְתְּחוּ שַׁעֲרֵי רָצוֹן, וְלֹא נִכְנָסִים לַשְּׁעָרִים הַלָּלוּ אֶלָּא רְצוֹנוֹת שֶׁל תְּפִלּוֹת, רְצוֹנוֹת שֶׁל שֶׁבַח, רְצוֹנוֹת שֶׁל נְשָׁמוֹת קְדוֹשׁוֹת עֶלְיוֹנוֹת.</p>\n<p>זְהִוּ הֵיכָלוֹ שֶׁל מֹשֶׁה. בַּהֵיכָל הַזֶּה הִתְכַּנֵּס מֹשֶׁה בְּאַהֲבָה, וְנָשַׁק נְשִׁיקוֹת. בַּהֵיכָל הַזֶּה, (שמות יט) מֹשֶׁה יְדַבֵּר וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל.</p>\n<p>כְּשֶׁנִּדְבָּקוֹת נְשִׁיקוֹת בִּנְשִׁיקוֹת זוֹ עִם זוֹ, וְעַל כֵּן כָּתוּב, (שיר השירים א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ וְגוֹ'. אֵין נְשִׁיקוֹת שֶׁל שִׂמְחָה וְאַהֲבָה אֶלָּא כְּשֶׁנִּדְבָּקִים זֶה בָּזֶה פֶּה בְּפֶה, רוּחַ בְּרוּחַ, שֶׁאָז רוֹוִים זֶה עִם זֶה בְּתַפְנוּקֵי הַכֹּל, וּבְשִׂמְחָה, מֵהָאוֹר הָעֶלְיוֹן.</p>\n<p>בֹּא וּרְאֵה, מֹשֶׁה יְדַבֵּר - שֶׁכָּתוּב (שם ד) הִנָּךְ יָפָה רַעְיָתִי, וְכָתוּב כְּחוּט הַשָּׁנִי שִׂפְתוֹתַיִךְ. וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל - שֶׁכָּתוּב (שם א) הִנְּךְ יָפֶה דוֹדִי אַף נָעִים, וְכָתוּב (שם ה) שִׂפְתוֹתָיו שׁוֹשַׁנִּים נוֹטְפֹת מוֹר עֹבֵר.</p>\n<p>הָרוּחַ הַזּוֹ, נִמְסְרוּ בְיָדָהּ כָּל הַסּוֹדוֹת שֶׁל אוֹתָן הַנְּשָׁמוֹת הָעֶלְיוֹנוֹת שֶׁמְּעוֹרְרִים תְּשׁוּקָה שֶׁל אַהֲבָה שֶׁלְּמַעְלָה וּמַטָּה כְּאֶחָד. אוֹתָן נְשָׁמוֹת עֶלְיוֹנוֹת, כְּמוֹ רַבִּי עֲקִיבָא וַחֲבֵרָיו, שֶׁאֵלֶּה לֹא נִקְרְבוּ לִרְחֹץ בִּנְהַר דִּינוּר כְּמוֹ שֶׁשְּׁאָר הַנְּשָׁמוֹת רוֹחֲצוֹת שָׁם וְעוֹבְרוֹת בּוֹ, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>(בא וראה) הָרוּחַ הַזּוֹ מוֹצִיאָה שְׁנֵים עָשָׂר אוֹרוֹת, וְכֻלָּם עוֹמְדִים בְּסוֹד תַּחַת הָרוּחַ הַזּוֹ. בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם עוֹמְדִים אַרְבָּעָה אוֹרוֹת עֶלְיוֹנִים שֶׁשּׁוֹלְטִים לְאַרְבָּעָה צְדָדִים. בְּצַד הַדָּרוֹם עוֹמֵד אוֹר עֶלְיוֹן אֶחָד, הַיָּמִין שֶׁל כָּל הָעוֹלָם, שֶׁהֲרֵי מִמֶּנּוּ מַתְחִילִים יִשְׂרָאֵל לְהֵאָחֵז בְּסוֹד הָאֱמוּנָה, וְהוּא מִיכָאֵל, רַב כֹּחַ שֶׁל הָאוֹר הָעֶלְיוֹן, שֶׁיּוֹרֵד מִצַּד הַדָּרוֹם, שֶׁשָּׁם הָאוֹר עוֹמֵד בְּחָזְקוֹ.</p>\n<p>הַמִּיכָאֵל הַזֶּה, אוֹר הַיָּמִין, הָאַפּוֹטְרוֹפּוֹס הַגָּדוֹל שֶׁל יִשְׂרָאֵל. מִשּׁוּם שֶׁכַּאֲשֶׁר עוֹמֵד הַצַּד הָאַחֵר לְהַשְׂטִין עַל יִשְׂרָאֵל, אָז מִיכָאֵל טוֹעֵן כְּנֶגְדּוֹ, וְנַעֲשֶׂה סָנֵגוֹר עַל יִשְׂרָאֵל, וְהֵם נִצָּלִים מֵאוֹתוֹ הַקָּטֵגוֹר שֶׁל בַּעֲלֵי שִׂנְאַת יִשְׂרָאֵל.</p>\n<p>פְּרָט לַזְּמַן שֶׁחָרְבָה יְרוּשָׁלַיִם, שֶׁהֲרֵי אָז הִתְגַּבְּרוּ הַחֲטָאִים, וּמִיכָאֵל לֹא יָכֹל עִמּוֹ שֶׁל הַצַּד הָאַחֵר, שֶׁטַּעֲנָתוֹ שֶׁל מִיכָאֵל עַל יִשְׂרָאֵל נִשְׁבְּרָה, וְאָז - (איכה ב) הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב.</p>\n<p>בְּצַד הַצָּפוֹן עוֹמֵד אוֹר אַחֵר, שֶׁהֲרֵי הוּא עוֹמֵד (לטל) לְבַטֵּל דִּין מִבֵּית הַהֵיכָל הָרְבִיעִי. וְנוֹתֵן לַמְמֻנֶּה שֶׁל אוֹתוֹ הַפֶּתַח, שֶׁבְּאוֹתוֹ הַפֶּתַח עוֹמְדִים מְמֻנִּים אֲחֵרִים שֶׁהֵם בְּצַד הַטֻּמְאָה, מְחַכִּים לְאוֹתוֹ הַמְמֻנֶּה וְנוֹטְלִים דִּין. וְלִפְעָמִים שֶׁהָאוֹר הַזֶּה שֶׁבְּצַד הַצָּפוֹן הוּא עוֹשֶׂה דִּין, וְלֹא נִמְסָר בְּיַד הַצַּד הָאַחֵר, מִשּׁוּם שֶׁכָּל הַדִּינִים שֶׁנַּעֲשׂוּ בוֹ יֵשׁ לָהֶם רְפוּאוֹת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה חֶסֶד בְּאוֹתָם מְקוֹמוֹת.</p>\n<p>גַּבְרִיאֵ\"ל הוּא הָאוֹר הַזֶּה שֶׁבְּצַד הַצָּפוֹן, וּבְכָל מָקוֹם שֶׁהוּא מַכֶּה, שָׁרוּי בּוֹ חֶסֶד, מִשּׁוּם שֶׁגַּבְרִיאֵ\"ל בִּשְׁנֵי צְדָדִים, כָּלוּל בִּשְׁנֵיהֶם, וְלָכֵן מַכֶּה, וּבוֹ רְפוּאוֹת. בַּצַּד הַזֶּה עוֹמֵד סוֹד, שֶׁכָּתוּב, (דברים ח) כִּי כַּאֲשֶׁר יְיַסֵּר אִישׁ אֶת בְּנוֹ ה' אֱלֹהֶיךְ מְיַסְּרֶךָּ. וְאֵלּוּ הֵם יִסּוּרִים שֶׁל אַהֲבָה, שֶׁכְּלוּלִים בְּצַד זֶה וּבְצַד זֶה.</p>\n<p>בְּצַד הַמִּזְרָח עוֹמֵד אוֹר אַחֵר, שֶׁהוּא עוֹמֵד בְּכָל דִּבְרֵי הָרְפוּאוֹת, לְהַכְנִיס לִפְנֵי רִבּוֹנוֹ כָּל אוֹתָם שֶׁנִּשְׁכְּחוּ בְּבֵית חָלְיָם, וּלְקָרֵב זְמַנִּים וְקִצִּים לְאוֹתָן מַחֲלוֹת שֶׁהִשְׁלִימוּ אֶת נֶאֱמָנוּתָן. וְסוֹבֵב אֶת הָעוֹלָם בְּכָל יוֹם וָיוֹם כְּדֵי לְהַשְׁלִים רְפוּאוֹת בְּמִצְוַת רִבּוֹנוֹ, וְהָאוֹר הַזֶּה (הוא) שְׁמוֹ רְפָאֵ\"ל. וְאַף עַל גַּב שֶׁהֲרֵי בֵּאַרְנוּ אוֹתוֹ לְצַד אַחֵר. וְזֶה אָחוּז לְצַד זֶה וּלְצַד זֶה, לַצַּד שֶׁל מִיכָאֵל, וְלַצַּד שֶׁל גַּבְרִיאֵל.</p>\n<p>וְזְהִוּ הַמְמֻנֶּה, שֶׁבְּשָׁעָה שֶׁנִּדּוֹן אָדָם בַּהֵיכָל הָרְבִיעִי לְחַיִּים, אֲזַי הוּא מַקְדִּים בִּרְפוּאוֹת. וְהָרְפוּאוֹת הַלָּלוּ יוֹצְאוֹת מִתּוֹךְ דּחַק, מִשּׁוּם שֶׁמִּשְּׁנֵי צְדָדִים יוֹצְאוֹת, וְהַדֹּחַק הַזֶּה בָּא מִתּוֹךְ צַד שְׂמֹאל, וְהָרְפוּאָה מִתּוֹךְ צַד יָמִין. וְלָכֵן, כְּשֶׁבָּאָה רְפוּאָה לְאוֹתוֹ הַחוֹלֶה, הִיא בָּאָה לוֹ מִתּוֹךְ דּחַק רַב.</p>\n<p>וְכָךָ הוּא מִצַּד הַמַּעֲרָב. וְאַף עַל גַּב שֶׁאָמַרְנוּ שֶׁרְפָאֵל הוּא בְּצַד הַמִּזְרָח, וּפֵרְשׁוּהָ בַּצַּד הַזֶּה שֶׁל הַמַּעֲרָב - הָרְפוּאוֹת וְהַחַיִּים אֵינָם אֶלָּא בְּצַד הַמִּזְרָח, שֶׁהֲרֵי מִשָּׁם נִמְשָׁכִים הַחַיִּים לְמַטָּה.</p>\n<p>(ובצד המערב הזה) אוֹר אֶחָד שֶׁשְּׁמוֹ נוּרִיאֵ\"ל, וְהוּא אוּרִיאֵ\"ל. וְזֶהוּ כָּלוּל מִכֻּלָּם וְעוֹמֵד שָׁלִיחַ בַּכֹּל. וְיֵשׁ לוֹ שְׁלֹשָׁה צְדָדִים, אֲבָל הֵם שְׁנַיִם, כִּי כָּל אֶחָד מֵאֵלּוּ כָּלוּל בַּחֲבֵרוֹ, שֶׁאוֹתָם אַרְבָּעָה יְסוֹדוֹת הַתַּחְתּוֹנִים, מֵאוֹתָם אַרְבָּעָה יְסוֹדוֹת הָעוֹלָם, עֶלְיוֹנִים עַל הַכֹּל. וּמִשּׁוּם שֶׁכֻּלָּם קְשׁוּרִים זֶה בָּזֶה, רָמַז הַכָּתוּב וְאָמַר, (שיר השירים ז) אֶל גִּנַּת אֱגוֹז יָרַדְתִּי לִרְאוֹת.</p>\n<p>אוֹתָם שְׁנֵים עָשָׂר הָאוֹרוֹת עוֹמְדִים בְּאוֹתָהּ הָרוּחַ שֶׁאָמַרְנוּ, וְאוֹתָהּ רוּחַ עֲלֵיהֶם בִּשְׁלֵמוּת. תַּחַת אַרְבָּעָה הָאוֹרוֹת הַלָּלוּ יֵשׁ שְׁמוֹנָה אֲחֵרִים, כְּדֵי לִהְיוֹת בִּשְׁלֵמוּת, וּבְכֻלָּם יֵשׁ שְׁלֵמוּת אַחַת, (ירדתי לראות, אלו ארבעה אורות ' ' עליונים שיש תחתיהם שמונה אחרים, והם שנים, עשר אורות שעומדים תחת אותה רוח שאמרנו, ' ' ' ' ואותה רוח עליהם בשלמות, להיותבכלם שלמות,, אחת) וּכְשֶׁכֻּלָּם נִפְרָדִים, הֵם שְׁלֹשָׁה לְכָל צַד.</p>\n<p>אַרְבַּעַת הָעַמּוּדִים הַלָּלוּ עוֹמְדִים לַעֲלוֹת וּלְהֵאָחֵז אֶת הַהֵיכָל הַזֶּה לְמַעְלָה בְּמָקוֹם שֶׁנִּקְרָא שָׁמַיִם, לְחַבֵּר אֶת הַנְּשִׁיקוֹת אֵלּוּ בְּאֵלּוּ כְּאֶחָד. תַּחַת אֵלּוּ כַּמָּה דְרָגוֹת לִדְרָגוֹת, כֻּלָּם יוֹצְאִים מֵהֶם, מֵהַיְסוֹדוֹת הַתַּחְתּוֹנִים הַלָּלוּ, מֵהֶם מִצַּד הַמַּיִם, וּמֵהֶם מִצַּד הָאֵשׁ, וּמֵהֶם מִצַּד הָרוּחַ, וּמֵהֶם מִצַּד הֶעָפָר.</p>\n<p>כְּמוֹ כֵן שָׁנִינוּ, אַרְבָּעָה נִכְנְסוּ לַפַּרְדֵּס, וְכֻלָּם נִבְחֲרוּ לַמָּקוֹם הַזֶּה, לְאֵלּוּ אַרְבָּעָה הַיְסוֹדוֹת. וְכָל אֶחָד וְאֶחָד נִקְשָׁר בִּמְקוֹמוֹ; זֶה בְּצַד הָאֵשׁ, וְזֶה בְּצַד הַמַּיִם, וְזֶה בְּצַד הָרוּחַ, וְזֶה בְּצַד הֶעָפָר. וְכֻלָּם טְבוּעִים בַּיְסוֹד שֶׁלָּהֶם כְּמוֹ שֶׁנִּכְנְסוּ, פְּרָט לְאוֹתוֹ הַשָּׁלֵם הֶחָסִיד שֶׁבָּא מִצַּד הַיָּמִין, וְנִדְבַּק בַּיָּמִין וְעָלָה לְמַעְלָה.</p>\n<p>וּכְשֶׁהִגִּיעַ לַמָּקוֹם הַזֶּה שֶׁנִּקְרָא הֵיכָל אַהֲבָה, נִדְבַּק בּוֹ בִּרְצוֹן הַלֵּב. אָמַר, הַהֵיכָל הַזֶּה צָרִיךְ הוּא לְהַדְבִּיקוֹ בַּהֵיכָל שֶׁלְּמַעְלָה בְּאַהֲבָה רַבָּה, וְאָז הִשְׁתַּלֵּם בְּסוֹד הָאֱמוּנָה, וְהוּא עָלָה וְהִשְׁלִים אַהֲבָה קְטַנָּה בְּאַהֲבָה גְדוֹלָה כָּרָאוּי, וְלָכֵן מֵת בְּאַהֲבָה, וְיָצְאָה נִשְׁמָתוֹ בַּפָּסוּק הַזֶּה (דברים ו) וְאָהַבְתָּ. אַשְׁרֵי חֶלְקוֹ.</p>\n<p>כָּל אוֹתָם הָאֲחֵרִים יָרְדוּ לְמַטָּה כָּל אֶחָד וְאֶחָד, וְנֶעֶנְשׁוּ בְּאוֹתוֹ יְסוֹד שֶׁיָּרַד לְמַטָּה. אֱלִישָׁע יָרַד לְמַטָּה בְּצַד הַשְּׂמֹאל שֶׁהוּא אֵשׁ, וְיָרַד בּוֹ וְלֹא עָלָה, וּפָגַשׁ אֶת אוֹתוֹ הַצַּד הָאַחֵר שֶׁנִּקְרָא אֵל אַחֵר, וְנִמְנְעָה מִמֶּנּוּ תְּשׁוּבָה, וְגֹרַשׁ מִשּׁוּם שֶׁנִּדְבַּק בּוֹ, וְלָכֵן נִקְרָא אַחֵר, וּבֵאַרְנוּ.</p>\n<p>בֶּן עַזַּאי יָרַד בִּיסוֹד הֶעָפָר, וְטֶרֶם הִגִּיעַ לִשְׂרֵפַת הֶעָפָר שֶׁמַּגִּיעַ לְאוֹתוֹ הַצַּד הָאַחֵר, טָבַע בְּאוֹתוֹ עָפָר וּמֵת. וְלָכֵן כָּתוּב (תהלים קטז) יָקָר בְּעֵינֵי ה' הַמָּוְתָה לַחֲסִידָיו.</p>\n<p>בֶּן זוֹמָא יָרַד בִּיסוֹד הָרוּחַ, וּפָגַשׁ בְּרוּחַ אַחֶרֶת, שֶׁהִגִּיעַ לְצַד הַטֻּמְאָה, שֶׁנִּקְרָא פֶּגַע רַע, וּמִשּׁוּם כָּךְ פָּגַע בּוֹ וְלֹא הִתְיַשֵּׁב בּוֹ, וְכֻלָּם לֹא נִצְּלוּ מֵעֹנֶשׁ. וְלָכֵן אָמַר שְׁלֹמֹה, (קהלת ח) יֶשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ אֲשֶׁר יֵשׁ צַדִּיקִים שֶׁמַּגִּיעַ אֲלֵהֶם כְּמַעֲשֵׂה הָרְשָׁעִים. מִשּׁוּם שֶׁאֵלֶּה יָרְדוּ בַּדְּרָגוֹת הַלָּלוּ וְנֶעֶנְשׁוּ.</p>\n<p>בֹּא וּרְאֵה, מִשּׁוּם שֶׁרַבִּי עֲקִיבָא עָלָה לְמַעְלָה כָּרָאוּי, נִכְנַס בְּשָׁלוֹם וְיָצָא בְשָׁלוֹם. דָּוִד שָׁאַל שְׁאֵלָה, וְלֹא הִתְפָּרֵשׁ, שֶׁכָּתוּב (תהלים יז) מִמְתִים יָדְךְ ה' מִמְתִים מֵחֶלֶד חֶלְקָם בַּחַיִּים. (תוהה) עַל מַה זֶּה אֵלֶּה שֶׁנֶּהֶרְגוּ בַּהֲרוּגֵי הָעוֹלָם צַדִּיקִים, זַכָּאִים, שֶׁלֹּא חָטְאוּ חֵטְא כְּדֵי שֶׁיֵּעָנְשׁוּ. בֹּא וּרְאֵה, מִמְתִים יָדְךְ ה' מִמְתִים מֵחֶלֶד חֶלְקָם בַּחַיִּים. כָּאן הוּא שְׁנֵי צְדָדִים - יָדְךְ ה', וְחֶלֶד. יָדְךְ ה' - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהַנְּשָׁמָה מִתְכַּנֶּסֶת אֵלָיו. מִמְתִים מֵחֶלֶד - זֶה הַצַּד הָאַחֵר, שֶׁהַגּוּף הוּא שׁוֹלֵט עָלָיו, שֶׁכָּתוּב (ישעיה לח) לֹא אַבִּיט אָדָם עוֹד עִם יוֹשְׁבֵי חָדֶל.</p>\n<p>בֹּא וּרְאֵה, הַנְּשָׁמוֹת שֶׁל אֵלּוּ, לְהַשְׁלָמַת רוּחַ הַקֹּדֶשׁ, שֶׁלָּהֶם עֶשֶׂר רוּחוֹת מִלְּמַטָּה כָּרָאוּי, וְגוּפָם נִמְסָר לַמַּלְכוּת הָרְשָׁעָה, כָּל אֶחָד נוֹטֵל חֶלְקוֹ בְּסוֹד הַקָּרְבָּנוֹת.</p>\n<p>וּבֹא רְאֵה, רֹאשׁ רֵאשִׁית הָאֱמוּנָה תּוֹךְ הַמַּחֲשָׁבָה, מַכֶּה הַנִּיצוֹץ הֶחָזָק, וְעוֹלֶה תוֹךְ הַמַּחֲשָׁבָה (ומוציא) נִיצוֹצוֹת, וְזוֹרֵק נִיצוֹצוֹת לִשְׁלֹשׁ מֵאוֹת וְעֶשְׂרִים עֲבָרִים, וּבוֹרֵר פְּסֹלֶת מִתּוֹךְ הַמַּחֲשָׁבָה, וְנִבְרָר.</p>\n<p>אַף כָּךְ כְּמוֹ כֵן עוֹלֶה בַּמַּחֲשָׁבָה, כְּמוֹ שֶׁנִּבְרָר בָּהּ פְּסֹלֶת, (והתברר אף כך. אלו שבהם השתלם מה שצריך, ודאי כך עלה במחשבה והכל) וְנִבְרְרוּ אֵלֶּה, שֶׁבָּהֶם הִשְׁתַּלֵּם מַה שֶּׁצָּרִיךְ. וַדַּאי כְּשֶׁעָלָה, עָלָה בַּמַּחֲשָׁבָה, וְהַכֹּל כְּמוֹ שֶׁצָּרִיךְ. שִׂמְחָה מִצַּד זֶה, וְעֶצֶב מִצַּד זֶה.</p>\n<p>כָּתוּב, (קהלת ח) וְשִׁבַּחְתִּי אֲנִי אֶת הַשִּׂמְחָה אֲשֶׁר אֵין טוֹב לָאָדָם תַּחַת הַשֶּׁמֶשׁ כִּי אִם לֶאֱכֹל וְלִשְׁתּוֹת וְלִשְׂמוֹחַ וְהוּא יִלְוֶנּוּ בַעֲמָלוֹ יְמֵי חַיָּיו אֲשֶׁר נָתַן לוֹ הָאֱלֹהִים תַּחַת הַשָּׁמֶשׁ. וְשִׁבַּחְתִּי אֲנִי אֶת הַשִּׂמְחָה, וְכִי שְׁלֹמֹה הַמֶּלֶךְ מְשַׁבֵּחַ אֶת זֶה? אֶלָּא וְשִׁבַּחְתִּי אֲנִי אֶת הַשִּׂמְחָה - זוֹ שִׂמְחַת הַמֶּלֶךְ הַקָּדוֹשׁ בִּזְמַן שֶׁהוּא שׁוֹלֵט, בְּשַׁבָּת וּבְיָמִים טוֹבִים, שֶׁמִּכָּל הַמַּעֲשִׂים הַטּוֹבִים שֶׁאָדָם עוֹשֶׂה, אֵין טוֹב לָאָדָם תַּחַת הַשֶּׁמֶשׁ כִּי אִם לֶאֱכֹל וְלִשְׁתּוֹת וּלְהַרְאוֹת שִׂמְחָה בְּאוֹתוֹ (זמן) הַצַּד, כְּדֵי שֶׁיִּהְיֶה לוֹ חֵלֶק לָעוֹלָם הַבָּא.</p>\n<p>וְהוּא יִלְוֶנּוּ בַעֲמָלוֹ, מִי? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, הוּא יַלְוֶנּוּ וְיֵלֵךְ עִמּוֹ לְהַכְנִיסוֹ לָעוֹלָם הַבָּא. דָּבָר אַחֵר וְהוּא יַלְוֶנּוּ - מִי הוּא? אוֹתוֹ הָאָדָם שֶׁאוֹכֵל וְשׁוֹתֶה וְשָׂמֵחַ - כָּל מַה שֶּׁמּוֹצִיא לֶאֱכֹל וְלִשְׁתּוֹת, הוּא יַלְוֶנּוּ לַקָּדוֹשׁ- בָּרוּךְ-הוּא בְּהַלְוָאָה, וְהוּא יִתֵּן לוֹ כִּפְלֵי כִפְלַיִם מִכָּל מַה שֶּׁהוֹצִיא בָּזֶה. בִּשְׁנֵי אֵלֶּה מַלְוֶה אָדָם לַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁחָס עַל הֶעָנִי, וּכְשֶׁמּוֹצִיא בְּשַׁבָּתוֹת וּזְמַנִּים, שֶׁהֲרֵי הַכֹּל הִלְוָה לַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (משלי יט) מַלְוֵה ה' חוֹנֵן דָּל וּגְמֻלוֹ יְשַׁלֶּם לוֹ.</p>\n<p>וּמִשּׁוּם כָּךְ, זוֹ שִׂמְחָה וְזֶה עֶצֶב. זֶה חַיִּים וְזֶה מָוֶת. זֶה טוֹב וְזֶה רַע. זֶה גַּן עֵדֶן וְזֶה גֵיהִנֹּם. וְהַכֹּל זֶה הֶפֶךְ שֶׁל זֶה. וְלָכֵן גּוּפָם הָיָה בְּעֶצֶב, וְהַנְּשָׁמָה בְּשִׂמְחָה. וּכְשֶׁהָיוּ עֲשָׂרָה הָאֵלּוּ, שֶׁנִּקְרָאִים הֲרוּגֵי מַלְכוּת, הֲרוּגִים הָיוּ מִצַּד אַחֵר, וְהִשְׁלִימוּ מָקוֹם אַחֵר שֶׁל קְדֻשָּׁה. וּמִשּׁוּם כָּךְ הַכֹּל גָּלוּי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְנַעֲשֶׂה כָּרָאוּי.</p>\n<p>בַּהֵיכָל הַזֶּה עוֹמְדִים אוֹתָם שְׁנֵים עָשָׂר. אַרְבָּעָה אֵלּוּ לְמַעְלָה, וּשְׁמוֹנָה עִמָּהֶם, מִשּׁוּם שֶׁכָּל אֶחָד נוֹטֵל עִמּוֹ שְׁנַיִם, כְּמוֹ שֶׁסִּדּוּר (של שני) הַדְּגָלִים וְכֵן בַּסִּדּוּר שֶׁלְּמַטָּה, עַד סוֹף כָּל הַדְּרָגוֹת.</p>\n<p>בַּהֵיכָל הַזֶּה נִכְנָסוֹת כָּל אוֹתָן תְּפִלּוֹת, וְכָל אוֹתָן רְצוֹנוֹת שֶׁל שְׁבָחִים שֶׁנַּעֲשׂוּ בְּאַהֲבָה, וּכְשֶׁנִּכְנָסִים לַהֵיכָל הַזֶּה, כֻּלָּם נִדְבָּקִים בּוֹ (בקדוש'ברוך'הוא). וּבְכָל יוֹם וּבְכָל זְמַן כְּשֶׁמִּתְחַבְּרוֹת הַנְּשִׁיקוֹת, אֲזַי הוּא זְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ בְּנִשְׁמוֹת הַצַּדִּיקִים. וּמַהוּ הַשַּׁעֲשׁוּעַ? שֶׁמְּעוֹרְרִים הַנְּשִׁיקוֹת הַלָּלוּ, וְהֵן קוֹדְמוֹת לְאוֹתוֹ הָעֹנֶג, וְלָכֵן כָּתוּב (ישעיהנח) אָז תִּתְעַנַּג עַל ה', וּבֵאַרְנוּ.</p>\n<p>הַהֵיכָל הַזֶּה כְּלָל שֶׁל כָּל הַהֵיכָלוֹת הַתַּחְתּוֹנִים, כֻּלָּם כְּלוּלִים בַּהֵיכָל הַזֶּה. הַהֵיכָל הָרִאשׁוֹן, שֶׁשָּׁם עוֹמֶדֶת אוֹתָהּ הָרוּחַ שֶׁאָמַרְנוּ, וְכָל אוֹתָן הַחַיּוֹת שֶׁבָּהּ, נִסְמֶכֶת בִּשְׁנֵי עַמּוּדִים לְצַד מִזְרָח, וּבִשְׁנֵי עַמּוּדִים לְצַד דָּרוֹם, וּבִשְׁנֵי עַמּוּדִים לְצַד מַעֲרָב, וּבִשְׁנֵי עַמּוּדִים לְצַד צָפוֹן, וְהֵם שְׁמוֹנָה. וְאֵלּוּ נִקְרָאִים יִתְדוֹת הַמִּשְׁכָּן, וְעוֹמְדִים בַּחוּץ.</p>\n<p>כְּשֶׁבָּא הַמֶּלֶךְ הָעֶלְיוֹן, נוֹסְעוֹת אוֹתָן הַיְתֵדוֹת, וְנֶעֱקָרִים מִמְּקוֹמָם אוֹתָם הַמֵּיתָרִים, שֶׁהֵם שְׁמוֹנָה אֲחֵרִים פְּרָט לְאוֹתָן הַיְתֵדוֹת שֶׁאָמַרְנוּ, וְאוֹתָהּ הָרוּחַ הָרִאשׁוֹנָה שֶׁבְּתוֹךְ הַהֵיכָל הַזֶּה קוֹדֶמֶת וְנִכְנֶסֶת וְנִכְלֶלֶת בְּתוֹךְ אוֹתָהּ (שניה ברוח אחרת שבו) רוּחַ שְׁנִיָּה שֶׁבּוֹ.</p>\n<p>אוֹתָם שְׁנֵי הָעַמּוּדִים שֶׁלְּצַד מִזְרָח הֵם קַרְעִיאֵ\"ל, שֶׁהִתְמַנָּה בַּחוּץ עַל שְׁנֵים עָשָׂר אֶלֶף מְמֻנִּים, שֶׁכֻּלָּם נִקְרָאִים יִתְדוֹת הַמִּשְׁכָּן. זֶה לְיָמִין. וְלִשְׂמֹאל - שַׁמְעִיאֵ\"ל, וְהִתְמַנָּה עַל שְׁנֵים עָשָׂר אֲלָפִים מְמֻנִּים אֲחֵרִים, וְכֻלָּם יְתֵדוֹת כְּמוֹ שֶׁאָמַרְנוּ. (אותם ממגים אחרים) הַתּוֹמְכִים שֶׁהִתְמַנּוּ לְצַד דָּרוֹם, אֶחָד סַעֲדִיאֵ\"ל וְאֶחָד סְטָרִיאֵ\"ל (סעריהא\"ל), כָּל אֶחָד וְאֶחָד עַל שְׁנֵים עָשָׂר אֶלֶף מְמֻנִּים אֲחֵרִים. אֵלּוּ לֹא מָעֳבָרִים מִשִּׁלְטוֹנָם לְעוֹלָמִים.</p>\n<p>אֵלּוּ כֻּלָּם מְמֻנִּים עַל קִיּוּם הָעוֹלָם. אֵלּוּ מֵאוֹתָם שֶׁעוֹמְדִים בְּקִיּוּם, שֶׁאוֹתָם שֶׁנָּשְׂאוּ שֶׁשּׁוֹקְלִים בְּמִשְׁקָל זְכָרִים וּנְקֵבוֹת זֶה עִם זוֹ (אלו הם ששוקלים במשקל זכרים ונקבות להגשא זה עם זו), וְאֵלּוּ נִקְרָאִים מֹאזְנַיִם. עַל זֶה כָּתוּב, (תהלים סב) בְּמֹאזְנַיִם לַעֲלוֹת, וְלֹא אוֹתָם שֶׁכָּתוּב בָּהֶם, (ויקראיט) מֹאזְנֵי צֶדֶק, שֶׁאָמַרְנוּ. כָּל אוֹתָם שֶׁשְּׁקוּלִים זֶה עִם זֶה, וְלֹא שׁוֹקֵל זֶה יוֹתֵר מִזֶּה, עוֹלִים וּמִתְחַבְּרִים כְּאֶחָד, וְהֵם חִבּוּר שֶׁל זָכָר וּנְקֵבָה כְּאֶחָד, וְעַל זֶה - בְּמֹאזְנַיִם לַעֲלוֹת. וְאַף עַל גַּב שֶׁלִּפְעָמִים מִסְתַּיֵּעַ הַדָּבָר וְשׁוֹקֵל זֶה יוֹתֵר מִזֶּה, עוֹלִים וּמִתְחַבְּרִים כְּאֶחָד, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>אוֹתָם שְׁנֵי עַמּוּדִים שֶׁלְּצַד צָפוֹן - פַּתְחִיאֵ\"ל, עֲטָרִיאֵ\"ל. וּמְמֻנִּים כָּל אֶחָד וְאֶחָד עַל שְׁנֵים עָשָׂר אֲלָפִים מְמֻנִּים אֲחֵרִים, וְהֵם יִתְדוֹת הַמִּשְׁכָּן, וּבְאֵלּוּ הָאַחֲרוֹנִים שֶׁאָמַרְנוּ. אוֹתָם שְׁנֵי מְמֻנִּים תּוֹמְכִים אֲחֵרִים שֶׁלְּצַד מַעֲרָב הֵם פְּדָתִיאֵ\"ל וְתוֹמִיהָאֵ\"ל, וְהִתְמַנּוּ כָּל אֶחָד עַל שְׁנֵים עָשָׂר אַלְפֵי מְמֻנִּים אֲחֵרִים, וְכֻלָּם יִתְדוֹת הַמִּשְׁכָּן כְּפִי שֶׁאָמַרְנוּ.</p>\n<p>אֵלּוּ הֵם שֶׁשּׁוֹפְכִים דְּמָעוֹת עַל כָּל אוֹתָם שֶׁמְּגָרְשִׁים אֶת נְשׁוֹתֵיהֶם הָרִאשׁוֹנוֹת, מִשּׁוּם שֶׁאוֹתָן שֶׁבַע הַבְּרָכוֹת שֶׁנִּמְסְרוּ לָהּ, הוּסְרוּ וְלֹא הִתְקַיְּמוּ, מִשּׁוּם שֶׁהִתְגָּרְשָׁה, וְלֹא נִדְבְּקוּ הַבַּעַל וְהָאִשָּׁה כְּאֶחָד, וְלָכֵן כֻּלָּם שׁוֹפְכִים דְּמָעוֹת. שֶׁהַגֵּרוּשִׁים מַרְאִים שֶׁאוֹתָן שֶׁבַע בְּרָכוֹת כְּאִלּוּ שֶׁהָעָבְרוּ מִמָּקוֹם אַחֵר. אָז בְּאוֹתָהּ שָׁעָה יוֹצֵא קוֹל וְאוֹמֵר: (ישעיה נ) אֵי זֶה סֵפֶר כְּרִיתוּת אִמְּכֶם אֲשֶׁר שִׁלַּחְתִּיהָ.</p>\n<p>הַהֵיכָל הַשֵּׁנִי, שֶׁאָמַרְנוּ שֶׁכּוֹלֵל אֶת הַהֵיכָל הָרִאשׁוֹן לְהִתְיַחֵד בּוֹ. וְכָל אוֹתָן הַחַיּוֹת, כָּךְ גַּם יֵשׁ לוֹ שְׁמוֹנָה עַמּוּדִים כְּמוֹ הָרִאשׁוֹנִים, וְכֻלָּם מְמֻנִּים כָּל אֶחָד וְאֶחָד עַל שְׁנֵים עָשָׂר אַלְפֵי מְמֻנִּים אֲחֵרִים כְּמוֹ אֵלּוּ הָרִאשׁוֹנִים שֶׁאָמַרְנוּ. שְׁנֵי עַמּוּדִים הֵם לְצַד מִזְרָח, שְׁנֵי עַמּוּדִים לְצַד דָּרוֹם, וּשְׁנֵי עַמּוּדִים לְצַד צָפוֹן, וּשְׁנֵי עַמּוּדִים לְצַד מַעֲרָב.</p>\n<p>שְׁנֵי הָעַמּוּדִים הַלָּלוּ שֶׁל צַד מִזְרָח - יְהָדָנִיאֵ\"ל, גְּזוּרִיָּ\"ה. שְׁנֵים עָשָׂר אַלְפֵי מְמֻנִּים שֶׁל כָּל אֶחָד, וְכֻלָּם יְתֵדוֹת. אוֹתָם שְׁנֵי עַמּוּדִים שֶׁלְּצַד דָּרוֹם - אַהֲרִיאֵ\"ל בָּרְהִיאֵ\"ל. כָּל אֶחָד וְאֶחָד עַל שְׁנֵים עָשָׂר אֲלָפִים כָּרִאשׁוֹנִים.</p>\n<p>אֵלּוּ מְמֻנִּים עַל מַשְׁבֵּר, וְנוֹטְלִים אוֹתָם קוֹלוֹת הַנָּשִׁים, וּמַנִּיחִים אוֹתָם לִפְנֵי אוֹתוֹ הַהֵיכָל, וּכְשֶׁאוֹתוֹ הַצַּד הָאַחֵר בָּא לְקַטְרֵג בַּשָּׁעָה הַזּוֹ, שֶׁהִיא שְׁעַת סַכָּנָה, עוֹמְדִים אֵלֶּה וּמַכְנִיסִים אֶת הַקּוֹלוֹת הַלָּלוּ לַמְמֻנֶּה שֶׁל הַפֶּתַח, וְלֹא יָכוֹל אוֹתוֹ הַצַּד הָאַחֵר לְקַטְרֵג. וְלִפְעָמִים שֶׁמַּקְדִּים אוֹתוֹ הַצַּד הָאַחֵר, וְנִכְנָס וּמְקַטְרֵג, וְיָכוֹל לְהַזִּיק.</p>\n<p>שְׁנֵי הָעַמּוּדִים הַלָּלוּ שֶׁלְּצַד צָפוֹן - חַלְחָלִיאֵ\"ל, (סלסליא\"ל) קַרְסָפִיהָאֵ\"ל. הֵם מְמֻנִּים כָּל אֶחָד עַל שְׁנֵים עָשָׂר אֲלָפִים אֲחֵרִים. שֶׁלְּצַד מַעֲרָב הֵם סוּגַדְיָ\"ה, (סוגרי\"א) גְּדַרְיָ\"ה. וְאֵלּוּ עַל שְׁנֵים עָשָׂר אֲלָפִים אֲחֵרִים.</p>\n<p>וְאֵלּוּ מְמֻנִּים עַל אוֹתוֹ דַּם בְּרִית, כְּשֶׁנִּמּוֹל אוֹתוֹ וָלָד לִשְׁמֹנָה יָמִים, וְאֵלּוּ נוֹטְלִים אוֹתוֹ הַדָּם וּמַנִּיחִים אוֹתוֹ לִפְנֵי הַהֵיכָל הַזֶּה. וּכְשֶׁמִּתְעוֹרֵר רֹגֶז בָּעוֹלָם, מַשְׁגִּיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא עַל אוֹתוֹ הַדָּם, וְלֹא נִתֶּנֶת רְשׁוּת לְאוֹתוֹ צַד הָאַחֵר לְהִכָּנֵס לְשָׁם.</p>\n<p>בֹּא וּרְאֵה, בִּזְמַן שֶׁנִּמּוֹל אוֹתוֹ אָדָם לִשְׁמֹנָה יָמִים וְשָׁרְתָה עָלָיו שַׁבָּת, הַמַּלְכוּת הַקְּדוֹשָׁה, אוֹתָהּ הָעָרְלָה שֶׁגּוֹזְרִים וְזוֹרְקִים אוֹתָהּ הַחוּצָה, אָז עוֹמֵד אוֹתוֹ צַד הָאַחֵר וְרוֹאֶה שֶׁזֶּהוּ חֶלְקוֹ מֵהַקָּרְבָּן הַזֶּה, וְאָז נִשְׁבָּר וְלֹא יָכוֹל לִשְׁלֹט וּלְקַטְרֵג עָלָיו, וְעוֹלֶה וְנַעֲשֶׂה סָנֵגוֹר עַל יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>הַהֵיכָל הַשְּׁלִישִׁי. הֵיכָל זֶה שֶׁעוֹמֵד לְהַכְלִיל וּלְיַחֵד בּוֹ אוֹתוֹ הֵיכָל שֵׁנִי, וְאוֹתָהּ רוּחַ, וְכָל אוֹתָן חַיּוֹת שֶׁבָּהּ, כֻּלָּם כְּלוּלִים וּמִתְיַחֲדִים זֶה עִם זֶה, וְהֵם רוּחַ אַחַת שֶׁכְּלוּלָה זוֹ בָּזוֹ, כָּךְ גַּם יֵשׁ לוֹ שְׁמֹנָה עַמּוּדִים לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְכֻלָּם נִקְרָאִים יִתְדוֹת הַמִּשְׁכָּן. שְׁנֵי הָעַמּוּדִים שֶׁלְּצַד דָּרוֹם הֵם שַׁכְנִיאֵ\"ל, עֲזוּזְיָ\"ה. (והם ממגים על שנים עשר אלף ממגים אחרים, כל אחד כאותם האחרים) שְׁנֵי הָעַמּוּדִים שֶׁלְּצַד מִזְרָח - יְהוֹדִיָּ\"ה, עַזְרִיאֵ\"ל. וְאֵלּוּ עוֹמְדִים כָּל אֶחָד וְאֶחָד עַל שְׁנֵים עָשָׂר אַלְפֵי מְמֻנִּים אֲחֵרִים, וְכֻלָּם נִקְרָאִים יִתְדוֹת הַמִּשְׁכָּן.</p>\n<p>וְאֵלּוּ הִתְמַנּוּ עַל אוֹתוֹ הֶבֶל הַתִּינוֹקוֹת שֶׁלּוֹמְדִים תּוֹרָה לְקַיֵּם אֶת הָעוֹלָם, וְאֵלּוּ נוֹטְלִים אוֹתוֹ הַהֶבֶל וּמַעֲלִים אוֹתוֹ לְמַעְלָה. וְכָל הֶבֶל וְהֶבֶל שֶׁל אוֹתָם תִּינוֹקוֹת שֶׁלּוֹמְדִים בַּתּוֹרָה לְקַיֵּם אֶת הָעוֹלָם, נַעֲשֶׂה מִמֶּנּוּ רוּחַ אַחַת, וְעוֹלָה אוֹתָהּ רוּחַ לְמַעְלָה וּמִתְעַטֶּרֶת בַּעֲטָרָה קְדוֹשָׁה, וּמִתְמַנֶּה שׁוֹמֵר הָעוֹלָם, וְכֵן כֻּלָּם.</p>\n<p>שְׁנֵי הָעַמּוּדִים שֶׁהֵם לְצַד צָפוֹן - עַזְפִּיאֵ\"ל, (קטצירהא\"ל) קְטָטָרִיהָאֵ\"ל. וְהֵם מְמֻנִּים עַל שְׁנֵים עָשָׂר אַלְפֵי מְמֻנִּים אֲחֵרִים, כָּל אֶחָד וְאֶחָד כְּפִי שֶׁאָמַרְנוּ. שְׁנֵי הָעַמּוּדִים שֶׁלְּצַד מַעֲרָב הֵם עֲסִסְנִיָּ\"ה, אַדִּירִירִיָּ\"ה (אדירי\"ה). וְאֵלּוּ מְמֻנִּים עַל שְׁנֵים עָשָׂר אֲלָפִים מְמֻנִּים אֲחֵרִים, כָּל אֶחָד וְאֶחָד כְּפִי שֶׁאָמַרְנוּ.</p>\n<p>אֵלּוּ הִתְמַנּוּ לְהַכְרִיז בְּכָל הָרְקִיעִים לְכָל אוֹתָם שֶׁמַּעֲבִירִים אֶת בְּנֵיהֶם מֵהַתּוֹרָה וּמַעֲבִירִים אוֹתָם שֶׁלֹּא יִלְמְדוּ אוֹתָהּ. אָז יוֹצְאִים כָּל הַמְמֻנִּים הַלָּלוּ, וּמַכְרִיזִים וְאוֹמְרִים: אוֹי לִפְלוֹנִי שֶׁהֶעֱבִיר אֶת בְּנוֹ מֵהַתּוֹרָה! אוֹי לוֹ שֶׁאָבַד מֵהָעוֹלָם הַזֶּה וּמֵהָעוֹלָם הַבָּא!</p>\n<p>הַהֵיכָל הָרְבִיעִי. הַהֵיכָל הַזֶּה הוּא הֵיכָל שֶׁעוֹמֵד בְּאוֹר יוֹתֵר. הַהֵיכָל הַזֶּה סוֹבְבִים אוֹתוֹ שְׁלֹשִׁים וּשְׁתַּיִם יְתֵדוֹת עֶלְיוֹנוֹת, וַחֲמֵשׁ מֵאוֹת אֶלֶף אֲחֵרוֹת שֶׁמְּמֻנּוֹת תַּחַת אֵלֶּה, וְאַרְבַּע אֲחֵרוֹת עֶלְיוֹנוֹת עַל כֻּלָּן, וְכֻלָּן הֵן יְתֵדוֹת שֶׁל הַהֵיכָל הַזֶּה. אֵלּוּ הָאַרְבָּעָה הֵם: חַסְדִיהָאֵ\"ל, קָסִירִיָּ\"ה (קסדי\"ה), קְדוּמְיָ\"ה, דַּהֲרִיאֵ\"ל. אֵלּוּ הָאַרְבָּעָה מְמֻנִּים עַל כֻּלָּם, וְכָל הָאֲחֵרִים, כֻּלָּם מְמֻנִּים תַּחְתֵּיהֶם.</p>\n<p>וְעַל יְדֵי אֵלֶּה נוֹדָע הַדִּין לַעֲשׂוֹת בָּעוֹלָם, וְעַל אֵלּוּ כָּתוּב, (דניאל ד) וּמַאֲמַר קְדוֹשִׁים שְׁאֵלָה. לְאַרְבָּעָה הַלָּלוּ בָּאִים כָּל אוֹתָם הַחֲיָלוֹת שֶׁמְּמֻנִּים עַל הַדִּין לִשְׁאֹל אֵיךְ נִגְזַר הַדִּין בָּעוֹלָם. כָּל אוֹתָם הַדִּינִים שֶׁלֹּא נִתְּנוּ בִּפְתָקִים לְקִיּוּם הָעוֹלָם, וְעַל כֵּן כֻּלָּם בָּאִים לִשְׁאֹל, וּמִשּׁוּם כָּךְ כֻּלָּם מְמֻנִּים עַל זֶה.</p>\n<p>אוֹתָם שְׁלֹשִׁים וּשְׁנַיִם הָאֲחֵרִים הֵם מְמֻנִּים עַל כָּל אוֹתָם שֶׁעוֹסְקִים בַּתּוֹרָה תָּמִיד, וְלֹא פוֹסְקִים בַּיּוֹם וּבַלַּיְלָה. וְאֵלּוּ הָאֲחֵרִים כֻּלָּם שֶׁתַּחְתֵּיהֶם, הֵם מְמֻנִּים עַל כָּל אוֹתָם שֶׁקּוֹבְעִים זְמַנִּים יְדוּעִים לַתּוֹרָה. וְעַל זֶה הֵם כֻּלָּם מְמֻנִּים, וּלְהַעֲנִישׁ אֶת כֻּלָּם, אֶת כָּל אוֹתָם שֶׁיָּכְלוּ לְהִשְׁתַּדֵּל בַּתּוֹרָה וְלֹא מִשְׁתַּדְּלִים.</p>\n<p>הַהֵיכָל הַחֲמִישִׁי. בַּהֵיכָל הַזֶּה עוֹמְדִים שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה מְמֻנִּים, כְּחֶשְׁבּוֹן יְמוֹת הַשָּׁנָה. וּמֵעֲלֵיהֶם אַרְבָּעָה עַמּוּדִים עֶלְיוֹנִים עַל כֻּלָּם. וְאֵלֶּה הֵם: קְרָשִׁיהָאֵ\"ל, סַרְטִיהָאֵ\"ל, עֲסִירִיָּ\"ה, קַדְמִיאֵ\"ל. וְאֵלּוּ נִקְרָאִים יְתֵדוֹת שֶׁל הַהֵיכָל הַזֶּה.</p>\n<p>אֵלּוּ הִתְמַנּוּ לְבַדֵּחַ אֶת הָעוֹלָם (אלו), כְּשֶׁנְּשָׁמָה נוֹסֶפֶת מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת. וְהִיא יוֹצֵאת. כְּשֶׁהִיא יוֹצֵאת, יוֹצְאִים אֵלֶּה עִמָּהּ, וּמַעֲבִירִים מִיִּשְׂרָאֵל כָּל עַצְבוּת וְכָל יְגִיעָה וְכָל מְרִירוּת הַנֶּפֶשׁ וְכָל הָרֹגֶז שֶׁל הָעוֹלָם, וְאֵלֶּה הֵם מְשַׂמְּחֵי הָעוֹלָם.</p>\n<p>כָּל אוֹתָם שֶׁלְּמַטָּה מֵהָאַרְבָּעָה הַלָּלוּ, כֻּלָּם הִתְמַנּוּ לְהַעֲבִיר דִּין מֵאוֹתָם בַּעֲלֵי הַדִּין וּמֵאוֹתָם שֶׁטּוֹרְדִים אוֹתָם בַּגֵּיהִנֹּם שֶׁיַּעֲלוּ מֵהֶם אֶת הַדִּין. וְעַל כֵּן כָּל הַיְתֵדוֹת הַלָּלוּ, כֻּלָּן עוֹמְדוֹת בְּשִׂמְחָה וְיוֹצְאוֹת מִשִּׂמְחָה, וְכָל הַהֵיכָלוֹת עוֹמְדִים לְהִתְעַטֵּר לְמַעְלָה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>הַהֵיכָל הַשִּׁשִּׁי. הַהֵיכָל הַזֶּה הֵיכָל שֶׁעוֹמֵד עַל כָּל הַהֵיכָלוֹת הַתַּחְתּוֹנִים. בָּזֶה מֵאָה אֲחֵרִים שֶׁעוֹמְדִים בַּחוּץ, שֶׁנִּקְרָאִים יְתֵדוֹת כְּאוֹתָם הָאֲחֵרִים. וְהֵם מֵאָה לְצַד יָמִין, וּמֵאָה אֲחֵרִים לְצַד שְׂמֹאל.</p>\n<p>שְׁנֵי מְמֻנִּים עֶלְיוֹנִים לְצַד יָמִין, וּשְׁנֵי מְמֻנִּים אֲחֵרִים עֶלְיוֹנִים לְצַד שְׂמֹאל. אֵלּוּ שֶׁל הַיָּמִין הֵם מַלְכִּיאֵ\"ל, שְׁמַעְיָהאֵ\"ל. וְאֵלּוּ שֶׁל הַשְּׂמֹאל נִקְרָאִים מִסַרְסָנִיָּ\"ה, צַפְצָפִיָּ\"ה. אֵלֶּה הֵם יְתֵדוֹת עֶלְיוֹנוֹת, מִיָּמִין וּמִשְּׂמֹאל.</p>\n<p>וְאֵלֶּה הֵם שֶׁעוֹמְדִים וּמְזֻמָּנִים בָּעוֹלָם. בְּאוֹתוֹ זְמַן שֶׁמַּגִּיעַ זְמַנּוֹ שֶׁל צַדִּיק לְהִסְתַּלֵּק מֵהָעוֹלָם וְנִתְּנָה רְשׁוּת לַצַּד הָאַחֵר, אֵלּוּ הָאַרְבָּעָה עוֹמְדִים לְהִזְדַּמֵּן לְשָׁם כְּדֵי שֶׁתֵּצֵא נִשְׁמָתוֹ בִּנְשִׁיקָה, וְלֹא תִצְטַעֵר בִּשְׁלִיטָתוֹ שֶׁל הַצַּד הָאַחֵר. אַשְׁרֵיהֶם הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁרִבּוֹנָם מַקְדִּים עֲלֵיהֶם אֶת שְׁלִיטָתָם, לִהְיוֹת שְׁמוּרִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>מֵהַהֵיכָל הַזֶּה מַתְחִילִים כָּל הַסּוֹדוֹת וְכָל הַדְּרָגוֹת הָעֶלְיוֹנוֹת וְהַתַּחְתּוֹנוֹת לְהִתְחַבֵּר, כְּדֵי שֶׁיִּמָּצֵא הַכֹּל, מַעְלָה וּמַטָּה בִּשְׁלֵמוּת, לִהְיוֹת הַכֹּל אֶחָד וְחִבּוּר אֶחָד, לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי, וּלְהִשְׁתַּלֵּם שֶׁיָּאִיר הַשֶּׁפַע הָעֶלְיוֹן בַּתַּחְתּוֹן (להשפיע אורות עליון בתחתון) וְאוֹר הַמְּאוֹרוֹת כְּאֶחָד, (ומאירים המאורות כלם כאחד) שֶׁלֹּא יָזוּזוּ זֶה מִזֶּה, וְאָז שׁוֹפֵעַ וְנִמְשָׁךְ מַה שֶּׁנִּמְשָׁךְ, שֶׁלֹּא נוֹדַע וְלֹא הִתְגַּלָּה, כְּדֵי שֶׁיִּתְקָרֵב (שיתקדש) וְיִתְיַחֵד זֶה עִם זֶה לִהְיוֹת הַכֹּל בְּיִחוּד שָׁלֵם כָּרָאוּי.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיּוֹדֵעַ בְּסוֹדוֹת רִבּוֹנוֹ לְהַכִּירוֹ כָּרָאוּי, שֶׁהֲרֵי הֵם אוֹכְלִים חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וְעַל זֶה כָּתוּב, (ישעיה סה) הִנֵּה עֲבָדַי יֹאכֵלוּ. אַשְׁרֵי הַצַּדִּיקִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה יָמִים וְלֵילוֹת, מִשּׁוּם שֶׁהֵם יוֹדְעִים אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְיוֹדְעִים לְיַחֵד הַיִּחוּד הַקָּדוֹשׁ כָּרָאוּי. שֶׁכָּל מִי שֶׁיּוֹדֵעַ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ בִּשְׁלֵמוּת כָּרָאוּי, אַשְׁרָיו בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>הַקֶּשֶׁר שֶׁל כָּל הַהֵיכָלוֹת הַלָּלוּ כָּאן נִקְשָׁרִים, (יעקב קשר של כל האמונה, רוח שעומדת כנגד רוח שהיא למטה, וזו הרוח שהיא למעלה עומדת כנגד רוח עליונה שכל הרוחות עומדות בה. זהו יעקב שהוא רוח אמצעית של כל הרוחות, והוא לוקח ההיכל הששי באותן נשיקות של דבקות רוח ברוח, כמו שגאמר (שיר השירים א) ישקני מגשיקות פיהו. וכל נשיקה היא) (כאן הקשר של כל האמונה. יעקב הוא רוח אמצעית של כל הרוחות, הוא נוטל את ההיכל הששי הזה באותן הגשיקות) לְהִדָּבֵק רוּחַ בְּרוּחַ, הַתַּחְתּוֹן בָּעֶלְיוֹן. וּבַנְּשִׁיקוֹת הַלָּלוּ מִתְעַלָּה הָרוּחַ שֶׁלְּמַטָּה לְהִדָּבֵק בָּרוּחַ שֶׁלְּמַעְלָה. וּכְשֶׁנִּדְבָּקוֹת רוּחַ בְּרוּחַ, אָז הָרוּחַ הָעֶלְיוֹנָה הַנִּסְתֶּרֶת שׁוֹרָה עַל הָרוּחַ הַזּוֹ שֶׁל הָאֶמְצַע. וְטֶרֶם שֶׁמִּתְעוֹרֶרֶת לְהִדָּבֵק רוּחַ בְּרוּחַ, הָרוּחַ הָעֶלְיוֹנָה אֵינָהּ שׁוֹרָה עַל (זו) הָרוּחַ שֶׁל הָאֶמְצַע.</p>\n<p>וְסוֹד זֶה, כְּשֶׁנֶּאֱחָזוֹת רוּחַ בְּרוּחַ, אָז שׁוֹרוֹת הַנְּשִׁיקוֹת לְהִתְחַבֵּר, וּמִתְעוֹרְרִים שְׁאָר הָאֵיבָרִים בִּתְשׁוּקָה, וְרוּחַ זוֹ מִתְדַּבֶּקֶת בְּזוֹ. וְאָז הָאֵיבָרִים כֻּלָּם מִתְעוֹרְרִים אֵלֶּה בְּאֵלֶּה, לְהִקָּשֵׁר אֵיבָר בְּאֵיבָר.</p>\n<p>וְאִם תֹּאמַר, מִי מְעוֹרֵר? הָאֵיבָרִים הַתַּחְתּוֹנִים אוֹ הָאֵיבָרִים הָעֶלְיוֹנִים? הָאֵיבָרִים הַתַּחְתּוֹנִים מִתְעוֹרְרִים תָּמִיד לָעֶלְיוֹנִים. מִי שֶׁהוּא בַּחֲשֵׁכָה, תָּאֵב תָּמִיד לִהְיוֹת בְּאוֹר. שַׁלְהֶבֶת שְׁחֹרָה שֶׁלְּמַטָּה מִתְעוֹרֶרֶת תָּמִיד לְשַׁלְהֶבֶת לְבָנָה שֶׁלְּמַעְלָה כְּדֵי לְהִדָּבֵק בָּהּ וְלִשְׁרוֹת תַּחְתֶּיהָ, וְסוֹד זֶה - (תהלים פג) אֱלֹהִים אַל דֳּמִי לָךְ אַל תֶּחֱרַשׁ וְאַל תִּשְׁקֹט אֵל.</p>\n<p>כְּשֶׁנָּטַל יַעֲקֹב אֶת הַהֵיכָל הַשִּׁשִּׁי הַזֶּה, אָז נִקְרָא בְשֵׁם קָדוֹשׁ עֶלְיוֹן שָׁלֵם - וַה'. וְאִם תֹּאמַר, שְׁלֵמוּת הַכֹּל? לֹא כֵן, אֶלָּא כְּשֶׁנִּשְׁלְמוּ כָּל הַהֵיכָלוֹת אֵלֶּה בְּאֵלֶּה, אָז הַכֹּל נִקְרָא בְּשֵׁם שָׁלֵם, יְהֹוָ\"ה אֱלֹהִים. וְזֶהוּ שֵׁם שָׁלֵם מֵהַכֹּל. וְטֶרֶם שֶׁהִתְחַבְּרוּ זֶה עִם זֶה, הֵיכָלוֹת בְּהֵיכָלוֹת, לֹא נִקְרָא בַּשֵּׁם הַשָּׁלֵם הַזֶּה. וּכְשֶׁמִּתְחַבְּרִים כְּאֶחָד אֵלֶּה בְּאֵלֶּה, אָז מִשְׁתַּלֵּם הַכֹּל מִמַּעְלָה וּמַטָּה, וְאוֹר שֶׁלְּמַעְלָה לְמַעְלָה יוֹרֵד וְשׁוֹרֶה עַל הַכֹּל, וְנִקְשָׁר הַכֹּל כְּאֶחָד (להיות הכל כאחד) לִהְיוֹת הַכֹּל אֶחָד.</p>\n<p>וְסוֹד הַדָּבָר - יַעֲקֹב נָטַל אַרְבַּע נָשִׁים, וְכָלַל אוֹתָן בְּתוֹכוֹ. וְאַף עַל גַּב שֶׁבֵּאַרְנוּ אֶת הַדָּבָר הַזֶּה בְּסוֹד אַחֵר, שֶׁהוּא עוֹמֵד בֵּין שְׁנֵי עוֹלָמוֹת. וְסוֹד הַכֹּל - כְּשֶׁיַּעֲקֹב נָטַל אֶת הַהֵיכָל הַזֶּה, שֶׁהוּא שִׁשִּׁי, נָטַל וְכָלַל בְּתוֹכוֹ כָּל אוֹתָן אַרְבַּע נָשִׁים, אַרְבָּעָה מַלְאָכִים, וְכֻלָּם דְּבוּקִים בַּהֵיכָל הַזֶּה. אֵלּוּ הֵם אַרְבָּעָה רָאשֵׁי הַנְּהָרוֹת, שֶׁכָּתוּב (בראשית ב) וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים. אֵלּוּ אַרְבָּעָה רָאשִׁים, אוֹתָן אַרְבַּע נָשִׁים שֶׁנָּטַל יַעֲקֹב, (כמו שאמרנו, ולו צריך, והוא) נָטַל הַהֵיכָל הַזֶּה.</p>\n<p>וְאָז נִקְרָא הַהֵיכָל הַזֶּה וַה', כְּשֶׁהוּא לְטוֹב, כְּמוֹ שֶׁנֶּאֱמַר (שמות יג) וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם. (בראשית יח) וַה' אָמָר הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם. וּכְשֶׁהִתְחַבֵּר יִצְחָק בְּהֵיכַל בֵּית הַדִּין שֶׁנִּקְרָא זְכוּ\"ת, אָז נִקְרָא הַכֹּל וַה', לְהַעֲנִישׁ אֶת הָרְשָׁעִים, כְּמוֹ שֶׁנֶּאֱמַר, (שם יט) וַה' הִמְטִיר עַל סְדם וְגוֹ'. וְהַכֹּל בְּסוֹד אֶחָד כָּרָאוּי.</p>\n<p>וּכְשֶׁיַּעָקֹב נָטַל אֶת הַהֵיכָל הַזֶּה, אָז הַכֹּל נִקְרָא רָצוֹן שָׁלוֹם, (וסימנך (אסתר ב) ובהגיע תור אסתר) וְזוֹהִי עֵת רָצוֹן. וּמִכָּאן וָהָלְאָה מַתְחִילִים הַהֵיכָלוֹת לְהִתְחַבֵּר וּלְהִקָּשֵׁר אֵלּוּ בְּאֵלּוּ. וְאַף עַל גַּב שֶׁשָּׁנִינוּ דְּרוֹמִית מִזְרָחִית. וְהַכֹּל הוּא כְּאֶחָד. כָּאן הוּא רוּחַ בְּרוּחַ, דְּבֵקוּת אַחַת. מִכָּאן הִתְחִיל אַבְרָהָם שֶׁהוּא יָמִין, שֶׁנִּקְרָא אַהֲבָה (רבה, כמו שאמרנו. והוא נטל ההיכל שגקרא אהב\"ה.) אָז, (יחזקאל טז) שָׁדַיִם נָכֹנוּ, וְהִתְמַלְּאוּ מִכָּל טוּב, לְסַפֵּק וּלְהָזִין הַכֹּל מִכָּאן. וּכְשֶׁאֵלֶּה הַשָּׁדַיִם נָכוֹנוּ וְהִתְמַלְּאוּ מִתּוֹךְ אַהֲבָה עֶלְיוֹנָה, אָז נִקְרָא הֵיכָל זֶה אֵל שַׁדַּ\"י כְּפִי שֶׁאָמַרְנוּ. וּבָזֶה קִבֵּל כָּל הָעוֹלָם סִפּוּק כְּשֶׁנִּבְרָא.</p>\n<p>שֶׁהֲרֵי כְּשֶׁנִּבְרָא הָעוֹלָם, לֹא יָכֹל לַעֲמֹד בְּקִיּוּם, וְלֹא הָיָה עוֹמֵד עַד שֶׁהִתְגַּלָּה הַהֵיכָל הַזֶּה שֶׁנָּטַל אַבְרָהָם. וּכְשֶׁנִּתְגַּלָּה אַבְרָהָם בַּהֵיכָל הַזֶּה (כדי שלעולם יהיה ספוק) אָז אָמַר לָעוֹלָם דַּי, הֲרֵי סִפּוּק לְהָזִין מִמֶּנּוּ הָעוֹלָם וּלְהִתְקַיֵּם. וּמִשּׁוּם כָּךְ נִקְרָא אֵל שַׁדַּי, אֵל שַׁדַּ\"י לַכֹּל בּוֹ. (ולהזון ממגו. בא וראה, היכל זה עתיד וכו').</p>\n<p>וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַלֵּא אוֹתוֹ (בו) וּלְהַתְקִינוֹ לֶעָתִיד לָבא, שֶׁכָּתוּב (ישעיה סו) לְמַעַן תִּינְקוּ וּשְׂבַעְתֶּם מִשֹּׁד תַּנְחֻמֶיהָ לְמַעַן תָּמֹצּוּ וְהִתְעַנַּגְתֶּם מִזִּיו כְּבוֹדָהּ. שֹׁד תַּנְחֻמֶיהָ וְזִיז כְּבוֹדָהּ, הַכֹּל הוּא בַּהֵיכָל הַזֶּה. וְאָז בְּאוֹתוֹ זְמַן כָּתוּב, (בראשית כא) מִי מִלֵּל לְאַבְרָהָם הֵינִיקָה בָנִים שָׂרָה, שֶׁהֲרֵי הַיְנִיקָה תְּלוּיָה בּוֹ בְּאַבְרָהָם.</p>\n<p>יִצְחָק, שֶׁהוּא הַשְּׂמֹאל שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הַמָּקוֹם שֶׁמִּמֶּנּוּ מִתְעוֹרְרִים כָּל הַדִּינִים שֶׁל הָעוֹלָם, וְהוּא זְרוֹעַ שְׂמֹאל, רֵאשִׁית כָּל הַדִּינִים, וְכָל הַדִּינִים מִתְעוֹרְרִים מִשָּׁם, זֶהוּ שֶׁנּוֹטֵל וְאוֹחֵז בְּאוֹתוֹ הֵיכָל שֶׁנִּקְרָא זְכוּת, לְהִתְחַבֵּר דִּין בְּדִין וְלִהְיוֹת הַכֹּל קֶשֶׁר אֶחָד, מִשּׁוּם שֶׁזֶּהוּ דִּין שֶׁלְּמַעְלָה, וּרְשִׁימוֹת הַדִּין תְּלוּיִים בּוֹ.</p>\n<p>וְכָאן נִרְשָׁם הַשֵּׁם הַקָּדוֹשׁ שֶׁנִּקְרָא אֱלֹהִים. מִשּׁוּם שֶׁיֵּשׁ אֱלֹהִים חַיִּים שֶׁהוּא לְמַעְלָה לְמַעְלָה נִסְתָּר מֵהַכֹּל. וְיֵשׁ אֱלֹהִים שֶׁהוּא בֵּית דִּין שֶׁלְּמַעְלָה, וֵאלֹהִים שֶׁהוּא בֵּית דִּין שֶׁלְּמַטָּה. זֶהוּ שֶׁכָּתוּב, (תהליםנח) אַךְ יֵשׁ אֱלֹהִים שּׁפְטִים בָּאָרֶץ. אֱלֹהִים עֶלְיוֹן, סוֹד שֶׁל אֱלֹהִים חַיִּים, כּוֹלֵל אֶת אֵלֶּה שֶׁלְּמַטָּה, וְהַכֹּל הוּא אֶחָד.</p>\n<p>בַּהֵיכָל הַזֶּה מִתְעוֹרֵר יִצְחָק, וְכָל שִׁבְעִים וּשְׁנַיִם הָאוֹרוֹת שֶׁכְּלוּלִים בּוֹ שֶׁמֵּהֶם נִגְזָרִים כָּל הַדִּינִים (של העולם שלמטה) שֶׁל מַטָּה שֶׁל הָעוֹלָם, שֶׁכָּתוּב (דניאל ד) בִּגְזֵרַת מַלְאָכִים הַדָּבָר. וְלָמָּה נִקְרְאוּ עִירִין? אֶלָּא מִשּׁוּם שֶׁכֻּלָּם עוֹמְדִים בָּעִיר הַזּוֹ, (תהלים מח) עִיר ה' צְבָאוֹת. עִיר אֱלֹהֵינוּ. כָּל אוֹתָם הַהֵיכָלוֹת לְמַעְלָה, כָּל אֶחָד וְאֶחָד נִקְרָא עִיר, כְּמוֹ שֶׁנֶּאֱמַר (דניאלד) מַלְאָךְ וְקָדוֹשׁ. וְאֵלּוּ הֵם עִירִין שֶׁעוֹמְדִים לִפְנַי וְלִפְנִים שֶׁל הַהֵיכָל, שֶׁעוֹמְדִים בְּעִיר. מִשּׁוּם כָּךְ נִקְרָאִים עִירִי\"ן.</p>\n<p>הַהֵיכָל הַזֶּה נִכְלָל בְּיִצְחָק, וְהַכֹּל הוּא בַּהֵיכָל שֶׁל אַבְרָהָם, מִשּׁוּם שֶׁהַיָּמִין מַכְלִיל אֶת הַשְּׂמֹאל. וּבֹא רְאֵה, כָּל אֶחָד וְאֶחָד כּוֹלֵל אֶת חֲבֵרוֹ, וַהֲרֵי בֵּאַרְנוּ שֶׁבִּגְלַל זֶה אַבְרָהָם עָקַד אֶת יִצְחָק, כְּדֵי לְהַכְלִיל בּוֹ דִּין (בימין) וּלְהִמָּצֵא שְׂמֹאל כָּלוּל בְּיָמִין, (ולהמצאהימין על השמאל ולהשליט וכו') וּלְהַשְׁלִיט אֶת הַיָּמִין עַל הַשְּׂמֹאל.</p>\n<p>וְעַל כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא צִוָּה אֶת אַבְרָהָם לְהַקְרִיב אֶת בְּנוֹ לְדִין וּלְהִתְחַזֵּק עָלָיו, וְלֹא צִוָּה אֶת יִצְחָק אֶלָּא אֶת אַבְרָהָם, וְעַל כֵּן נִמְצָא זֶה בְּדִין וְזֶה בְּחֶסֶד, וְהַכֹּל אֶחָד, וְנִכְלְלוּ זֶה בָּזֶה, וְכָךְ נִכְלְלוּ הַהֵיכָלוֹת הַתַּחְתּוֹנִים בָּעֶלְיוֹנִים.</p>\n<p>כְּשֶׁנָּטַל יִצְחָק אֶת הַהֵיכָל הַזֶּה, אֲזַי הַכֹּל הוּא לְטוֹב. דִּין בִּזְכוּת. וְעַל כָּךְ צָרִיךְ אָדָם שֶׁדָּן דִּין לָדוּן דִּין בִּזְכוּת, מִשּׁוּם שֶׁהוּא סוֹד עֶלְיוֹן שְׁלֵמוּת הַדִּין. מִשּׁוּם שֶׁאֵין שְׁלֵמוּת שֶׁל דִּין אֶלָּא בִּזְכוּת, זֶה בְּלִי זֶה אֵינוֹ שְׁלֵמוּת. דִּין בִּזְכוּת זוֹהִי שְׁלֵמוּת הָאֱמוּנָה כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה, כְּשֶׁדִּין מִתְעוֹרֵר בָּעוֹלָם, צְרִיכִים יִשְׂרָאֵל לְמַטָּה לְעוֹרֵר רַחֲמִים מִתּוֹךְ שׁוֹפָר כְּמוֹ הַסּוֹד הָעֶלְיוֹן, וַהֲרֵי בֵּאַרְנוּ. וּצְרִיכִים לְחַבֵּר דִּין כְּנֶגֶד זְכוּת, מִשּׁוּם שֶׁכְּשֶׁעוֹמֵד דִּין בִּזְכוּת, הַכֹּל הוּא בְּחִבּוּר אֶחָד, וּמַעְלָה וּמַטָּה בִּשְׁלֵמוּת, וְאָז - (איוב א) וְעוֹלָתָה קָפְצָה פִּיהָ, שֶׁאֵין לָהּ רְשׁוּת לְהַסְטִין וּלְקַטְרֵג בָּעוֹלָם. וְאָז הַכֹּל בְּיִחוּד אֶחָד כָּרָאוּי, וְדִין בְּלִי זְכוּת אֵינוֹ דִּין.</p>\n<p>וְזְהִוּ שֶׁיִּשְׂרָאֵל, שֶׁיֵּשׁ לָהֶם דִּין בִּזְכוּת. אֲבָל לִשְׁאָר הָעַמִּים אֵין לָהֶם דִּין בִּזְכוּת, וְעַל כֵּן אָסוּר לָנוּ לְסַדֵּר דִּינִים שֶׁלָּנוּ בְּעֶרְכָּאוֹת שֶׁל עַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, שֶׁהֲרֵי אֵין לָהֶם חֵלֶק בְּצַד הָאֱמוּנָה שֶׁלָּנוּ, שֶׁכָּתוּב (תהליםקמז) לֹא עָשָׂה כֵן לְכָל גּוֹי וּמִשְׁפָּטִים בַּל יְדָעוּם. וּמִצַּד שֶׁל יִשְׂרָאֵל, כָּל מִי שֶׁדָּן דִּין וְלֹא הִכְלִיל בּוֹ זְכוּת - זֶהוּ חוֹטֵא, שֶׁגּוֹרֵעַ סוֹד הָאֱמוּנָה, וּמַסְטֶה עַצְמוֹ לְאוֹתוֹ צַד שֶׁאֵין בּוֹ דִּין בְּלִי זְכוּת.</p>\n<p>וּבֹא רְאֵה, כְּשֶׁעָמְדוּ סַנְהֶדְרִין לְמַטָּה לָדוּן דִּינֵי נְפָשׁוֹת, הִצְטָרְכוּ לִפְתֹּחַ בִּזְכוּת כְּדֵי לְהַכְלִיל זְכוּת בְּדִין. וְעוֹד, שֶׁהֲרֵי נִקְרְאוּ מִבֵּית הַזְּכוּת. וְעַל כֵּן הִשְׁתַּדְּלוּתָם לִפְתֹּחַ בִּזְכוּת, וּמַתְחִילִים בַּזְּכוּת מִן הַקָּטָן, וְאַחַר כָּךְ נִשְׁלָם הַדִּין מִן הָעֶלְיוֹן, לִהְיוֹת זְכוּת כְּלוּלָה בַּדִּין. זֶה לְמַעְלָה וְזֶה לְמַטָּה. דִּין בִּזְכוּת - שְׁלֵמוּת הַדִּין. זֶה לְלֹא זֶה אֵינוֹ שְׁלֵמוּת. וּמִשּׁוּם זֶה יִצְחָק וְרִבְקָה הֵם כְּאֶחָד, זֶה דִין וְזוֹ זְכוּת, לִהְיוֹת שְׁלֵמוּת כְּאֶחָד. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרָה שְׁלֵמָה לָלֶכֶת בְּדֶרֶךְ אֱמֶת, כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>בֹּא וּרְאֵה שֶׁהֵם לֹא דָנִים דִּין אֶלָּא בִּזְכוּת, וּלְעַיֵּן זְכוּת בָּרִאשׁוֹנָה לִהְיוֹת כָּלוּל זֶה בָּזֶה. וְסַנְהֶדְרִין מְהַפְּכִים בִּזְכוּת בַּדִּין, לְהַכְלִיל הַכֹּל כְּאֶחָד, כְּדֵי שֶׁלֹּא יִשְׁלֹט הַצַּד הָאַחֵר. שֶׁהֲרֵי כְּשֶׁזְּכוּת לֹא נִמְצֵאת, הַצַּד הָאַחֵר נִמְצָא, שֶׁנִּקְרָא חוֹבָה, וּמִתְחַבֶּרֶת בַּדִּין וּמִתְחַזֶּקֶת, וְזֶהוּ דִּין בְּחוֹבָה.</p>\n<p>וְעַל כֵּן, בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה צְרִיכִים לְחַבֵּר זְכוּת בְּדִין, שֶׁלֹּא תִתְגַּבֵּר הַחוֹבָה. וּמִשּׁוּם כָּךְ צְרִיכִים שֶׁזְּכוּת וְדִין שֶׁיִּהְיוּ כְאֶחָד, מִשּׁוּם שֶׁהוּא שָׁלֵם. שֶׁכְּשֶׁהַצַּד הָאַחֵר שׁוֹלֵט, אֵינוֹ שָׁלֵם, אֶלָּא קִטְרוּג, כְּמוֹ שֶׁהוּא קִטְרוּג, וְהֵם אַרְבַּע מִיתוֹת. וּכְשֶׁהַצַּד שֶׁהוּא זְכוּת שׁוֹלֵט, הַכֹּל הוּא שָׁלֵם - (מלכים ב כ) שָׁלוֹם וֶאֱמֶת, (תהלים קג) חֶסֶד וְרַחֲמִים.</p>\n<p>וּכְשֶׁמִּתְחַבֵּר הַצַּד הָאַחֵר בְּדִין, שׁוֹלֵט בְּקִטְרוּג בְּאוֹתָן אַרְבַּע מִיתוֹת בֵּית דִּין: סְקִילָה, שְׂרֵפָה, הֶרֶג וְחֶנֶק. כֻּלָּן שִׁלְטוֹן הַקִּטְרוּגּ הָרָע. סְקִילָה, מִשּׁוּם שֶׁהוּא (ישעיה ח) אֶבֶן נֶגֶף. שְׂרֵפָה, מִשּׁוּם שֶׁהוּא (שם) צוּר מִכְשׁוֹל, אֵשׁ חֲזָקָה. הֶרֶג, זֶה חֶרֶב (דברים לב) תֹּאכַל בָּשָׂר. תֹּאכַל בָּשָׂר וַדַּאי, שֶׁשּׁוֹלֶטֶת בַּבָּשָׂר, וְזֶהוּ (בראשיתו) קֵץ כָּל בָּשָׂר. חֶנֶק, מִשּׁוּם שֶׁהוּא (שם כא) קִלְלַת אֱלֹהִי\"ם. אוֹתוֹ שֶׁשּׁוֹלֵט עַל חֶנֶק, עַל צְלִיבָה. וּבֵאַרְנוּ, מִשּׁוּם שֶׁלֹּא נִשְׁאָר אֶלָּא בָּשָׂר לְבַדּוֹ, וְאוֹתוֹ קִלְלַת אֱלֹהִים שׁוֹלֵט בְּבָשָׂר, מָרָה שְׁחֹרָה. וּמִשּׁוּם כָּךְ זֶה לְטוֹב וְזֶה לְרַע.</p>\n<p>וְהִצְטָרְכוּ יִשְׂרָאֵל, שֶׁבָּהֶם סוֹד הָאֱמוּנָה, לְהִשָּׁמֵר כְּדֵי שֶׁיִּשְׁלֹט צַד הָאֱמוּנָה, וְלֹא יִתְּנוּ מָקוֹם לַצַּד הָאַחֵר לִשְׁלֹט. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'.</p>\n<p>הַנְּבִיאִים, שֶׁהֵם צְדָדִים עֶלְיוֹנִים, שְׁתֵּי יְרֵכַיִם שֶׁתּוֹמְכוֹת בַּתּוֹרָה הַקְּדוֹשָׁה, הֵם נוֹטְלִים אֶת הַהֵיכָל שֶׁבֵּין שְׁתֵּי רוּחוֹת, שֶׁהֵן נֹגַהּ וְזהַר, וְאוֹתָן שְׁתֵּי יְרֵכַיִם לְמַטָּה לִתְמֹךְ אוֹתָם הַהֵיכָלוֹת שֶׁלְּמַעְלָה, שֶׁנִּקְרְאוּ תוֹרָה שֶׁבְּעַל פֶּה. כְּמוֹ שֶׁיֵּשׁ תּוֹמְכִים לַתּוֹרָה, שֶׁהִיא תּוֹרָה שֶׁבִּכְתָב, כָּךְ יֵשׁ תּוֹמְכִים עוֹמְדִים לַתּוֹרָה, שֶׁהִיא תּוֹרָה שֶׁבְּעַל פֶּה. וְנִכְלְלוּ זֶה בָּזֶה. אָז שְׁנֵי הַתּוֹמְכִים הַלָּלוּ שֶׁלְּמַטָּה, כְּשֶׁמִּתְחַבְּרִים בָּעֶלְיוֹנִים הַלָּלוּ, נִרְשָׁם בָּהֶם צַד הַנְּבוּאָה. וּמִיהוּ? (רמז) מַרְאֶה, שֶׁהוּא כְּמוֹ הַנְּבוּאָה.</p>\n<p>וְכָל אוֹתָם בַּעֲלֵי הַמַּרְאֶה יוֹנְקִים מִכָּאן. לְמַעְלָה נְבוּאָה, וְכָאן מַרְאֶה. וְעַל כֵּן זֶהוּ כְּמוֹ זֶה, וְזֶה כְּמוֹ זֶה. וּכְשֶׁמִּתְחַבְּרִים זֶה בָּזֶה, אָז שׁוֹלֵט עַל הַמָּקוֹם הַזֶּה (נרשם) הַשֵּׁם הַקָּדוֹשׁ שֶׁנִּקְרָא צְבָאוֹת. מִשּׁוּם שֶׁכָּל אוֹתָם חֲיָלוֹת קְדוֹשִׁים, כֻּלָּם עוֹמְדִים כָּאן, וְכֻלָּם נִקְרְאוּ מִצַּד הַנְּבוּאָה. מַרְאֶה וַחֲלוֹם מִצַּד הַנְּבוּאָה הָיוּ.</p>\n<p>וְאַף עַל גַּב שֶׁאֲנַחְנוּ אוֹמְרִים שֶׁבְּתוֹךְ אוֹתָהּ בְּרִית הַקֹּדֶשׁ שׁוֹרֶה הַשֵּׁם הַזֶּה מִשּׁוּם שֶׁכָּל הַחֲיָלוֹת יוֹצְאִים מֵהָאוֹת הַזּוֹ, עִם כָּל זֶה, הַיְּרֵכִים, שֶׁהֵן עוֹמְדוֹת בַּחוּץ, קְרוּיוֹת עַל הַשֵּׁם הַזֶּה, וְאֵלּוּ הֵם שֶׁנִּקְרָאִים בָּרַיְתוֹת. שֶׁהֲרֵי בָּרַיְתָא מִחוּץ לַמִּשְׁנָה. מִשְׁנָיוֹת עוֹמְדוֹת לְתוֹךְ הַבָּרַיְתוֹת, וְנִקְרָאוֹת יְרֵכַיִם בָּתִּים חִיצוֹנִיִּים, כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>מִשְׁנָה הִיא סוֹד שֶׁעוֹמֵד לִפְנִים, שֶׁעִקַּר הַכֹּל לוֹמְדִים מִשָּׁם, וְכֵן הַתַּנָּאִים. וְסוֹד (זה) שֶׁל זֶה - (שיר ח) אֶנְהָגְךְ אֲבִיאֲךְ אֶל בֵּית אִמִּי תְּלַמְּדֵנִי. אֶל בֵּית אִמִּי - זֶה קֹדֶשׁ הַקְּדָשִׁים. תְּלַמְּדֵנִי - זֶהוּ סוֹד הַמִּשְׁנָה. שֶׁכְּשֶׁנִּכְנָס הַנָּהָר הַזֶּה שֶׁשּׁוֹפֵעַ וְיוֹצֵא לְאוֹתוֹ בֵּית קֹדֶשׁ הַקְּדָשִׁים, כָּתוּב תְּלַמְּדֵנִי. וְזֶהוּ הַסּוֹד שֶׁנִּקְרָא מִשְׁנָה, כְּמוֹ שֶׁנֶּאֱמַר (דברים יז) אֶת מִשְׁנֵה הַתּוֹרָה הַ את.</p>\n<p>כְּשֶׁנִּמְשְׁכָה הַחוּצָה, נִקְרֵאת בָּרַיְתָא. שְׁתֵּי הַיְרֵכַיִם הֵן בָּרַיְתוֹת, סוֹד הַסּוֹדוֹת שֶׁלֹּא נִתְּנָה רְשׁוּת לְגַלּוֹת, מִשּׁוּם שֶׁלֹּא נִמְסָר סוֹד זֶה, רַק לַחֲכָמִים עֶלְיוֹנִים. אוֹי אִם יִתְגַּלֶּה - וְאוֹי אִם לֹא יִתְגַּלֶּה, מִשּׁוּם שֶׁהוּא סוֹד מֵהַסּוֹדוֹת הָעֶלְיוֹנִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַנְהִיג בּוֹ אֶת הָעוֹלָם.</p>\n<p>בַּיִת רִאשׁוֹן עָמַד בִּימֵי שְׁלֹמֹה כְּנֶגֶד הָעוֹלָם הָעֶלְיוֹן, וְהוּא נִקְרָא בַּיִת רִאשׁוֹן, וְהַכֹּל הִשְׁתַּמֵּשׁ בְּבֵית קֹדֶשׁ הַקְּדָשִׁים, הַמָּקוֹם שֶׁבּוֹ הִשְׁתַּמֵּשׁ הַשֶּׁמֶשׁ בַּלְּבָנָה. וְסוֹדוֹת עֶלְיוֹנִים כֻּלָּם בִּשְׁלֵמוּת, וְהָעוֹלָם עוֹמֵד בִּשְׁלֵמוּת. וְאַחַר כָּךְ הַחֲטָאִים גָּרְמוּ, וְנִמְשְׁכוּ הַסּוֹדוֹת וְנִדְחוּ מִבֵּית קֹדֶשׁ הַקְּדָשִׁים הַחוּצָה. כְּשֶׁנִּדְחוּ לַיְרֵכַיִם, אָז עָמְדוּ בַּחוּץ, שֶׁנִּקְרְאוּ בָּתִּים חִיצוֹנִיִּים, וְהִצְטָרְכוּ לַבָּרַיְתוֹת.</p>\n<p>בַּיִת שֵׁנִי עָמְדוּ בַּבָּתִּים הַחִיצוֹנִיִּים בַּיְרֵכִים, וּמֵהֶם חָזְרוּ, וּשְׁרוּיִים (היו) בְּבֵית קֹדֶשׁ הַקְּדָשִׁים, וְהוּא בַּיִת שֵׁנִי. וְאוֹתָם אֲחֵרִים נִשְׁאֲרוּ בַּחוּץ בַּבָּרַיְתָא, בֵּין הַיְרֵכַיִם. (ואלו עקרם משנה, שהיא בית שני, ובריתא אלו ששרו בבית הירכים והיו וכו') וְהָיוּ לוֹמְדִים מֵהַמִּשְׁנָה, וְהֻנְהֲגוּ מִמֶּנָּה, וְהַיְנוּ סוֹד הַכָּתוּב, (ישעיה ב) כִּי מִצִּיּוֹן תֵּצֵא תוֹרָה.</p>\n<p>וְאַחַר כָּךְ גָּרְמוּ הַחֲטָאִים, הָעֳבַר שִׁלְטוֹן הַבַּיִת הַשֵּׁנִי, (ואף על גב) שֶׁשִּׁלְטוֹנוֹ לֹא הָיָה כְּמוֹ בַּיִת רִאשׁוֹן שֶׁהָיָה בּוֹ שָׁלוֹם תָּמִיד, מִשּׁוּם שֶׁהַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ תָּמִיד הָיָה בְתוֹכוֹ, וְלָכֵן הָיָה בְשָׁלוֹם. בְּבַיִת שֵׁנִי לֹא הָיָה בּוֹ שָׁלוֹם כָּךְ, מִשּׁוּם שֶׁבָּעָרְלָה יֵשׁ תָּמִיד קִטְרוּג. וְלָכֵן הָיוּ כֹהֲנִים מְזֻמָּנִים בְּתוֹכוֹ לְקַטְרֵג בָּעָרְלָה הַזּוֹ, וְלָהֶם הִצְטָרֵךְ דִּבּוּר לְקַטְרֵג כְּנֶגְדָּהּ וּלְהָגֵן עַל בַּיִת שֵׁנִי, וְהַכֹּל בְּסוֹד כָּרָאוּי.</p>\n<p>אַחַר כָּךְ גָּרְמוּ הַחֲטָאִים וְשָׁלְטָה אוֹתָהּ עָרְלָה, וְנִדְחוּ מִבַּיִת שֵׁנִי הַחוּצָה, וְיָרְדוּ מִשָּׁם לַחֲמוּקֵי הַיְרֵכַיִם לְמַטָּה (ואחר כך ירדו משם ונדחו מאותם החמוקי של מטה) עַד שֶׁהָיוּ שְׁרוּיים לְמַטָּה בָּרַגְלַיִם, וּכְשֶׁיָּשְׁבוּ בָרַגְלַיִם, אָז - (זכריהיד) וְעָמְדוּ רַגְלָיו בַּיּוֹם הַהוּא, וְהָעוֹלָם יִתְנַהֵג בַּכֹּל בְּסוֹד עֶלְיוֹן כָּרָאוּי. וְאַף עַל גַּב שֶׁנִּדְחוּ וְלֹא נֶעֶזְבוּ מִמֶּנּוּ, וּלְעוֹלָמִים נֶאֶחְזוּ בוֹ.</p>\n<p>וּמִי שֶׁיּוֹדֵעַ וּמוֹדֵד בַּשִּׁעוּר שֶׁל קַו הַמִּדָּה אֹרֶךְ הַהֶמְשֵׁךְ שֶׁל הַיְרֵכַיִם עַד הָרַגְלַיִם, יָכוֹל לָדַעַת אֶת מִדַּת הַגָּלוּת שֶׁנִּמְשֶׁכֶת. וְזֶהוּ סוֹדּ בֵּין קוֹצְרֵי הַשָּׂדֶה, וְהַכֹּל בְּסוֹד עֶלְיוֹן. וּמִשּׁוּם כָּךְ כָּל הַבָּרַיְתוֹת וְכָל הַתַּנָּאִים וְכָל הָאָמוֹרָאִים עוֹמְדִים בִּמְקוֹם כָּרָאוּי, אֵלּוּ לִפְנִים וְאֵלּוּ לַחוּץ, בְּאוֹתָם חֲמוּקֵי הַיְרֵכַיִם (ואלו לחוץ) וּלְמַטָּה מֵהַבִּרְכַּיִם. וּבְכֻלָּם נִקְרָא תּוֹרָה שֶׁבְּעַל פֶּה, וּבְכֻלָּם יָרְדוּ יִשְׂרָאֵל וְגָלוּ.</p>\n<p>וְאָז, כְּשֶׁתִּסְתַּיֵּם הַגָּלוּת בְּהַמְשָׁכַת הָרַגְלַיִם, אָז - וְעָמְדוּ רַגְלָיו בַיּוֹם הַהוּא, וְתָעֳבַר אוֹתָהּ רוּחַ טֻמְאָה עָרְלָה מִן הָעוֹלָם, וְיַחְזְרוּ יִשְׂרָאֵל לְבַדָּם לִשְׁלֹט כָּרָאוּי, מִשּׁוּם שֶׁאוֹתָהּ עָרְלָה הוֹרִידָה אוֹתָם לְמַטָּה עַד עַכְשָׁו. וּמִכָּאן וָהָלְאָה, שֶׁהָעָרְלָה הַזּוֹ תִּתְקַצֵּץ וְתַעֲבֹר מִתּוֹךְ הָעוֹלָם, אָז - (דבריםלג) וַיִּשְׁכֹּן יִשְׂרָאֵל בֶּטַח בָּדָד עֵין יַעֲקֹב. בְּאוֹתָהּ עֵין יַעֲקֹב, וְלֹא יִמָּצֵא מְקַטְרֵג עֲלֵיהֶם. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>יוֹסֵף הַצַּדִּיק עַמּוּד הָעוֹלָם, הוּא נָטַל בִּרְשׁוּת הֵיכָל טָמִיר וְגָנוּז, וּבִרְשׁוּתוֹ עוֹמֵד הַהֵיכָל הַשְּׁבִיעִי. וְאַף עַל גַּב שֶׁאָמַרְנוּ שֶׁהַהֵיכָל שֶׁל לִבְנַת הַסַּפִּיר עוֹמֵד בִּרְשׁוּתוֹ - כָּךְ הוּא, שֶׁבּוֹ מִתְתַּקֵּן. אֲבָל בֹּא וּרְאֵה, הַנְּבִיאִים שֶׁאָמַרְנוּ, כְּשֶׁמִּתְחַבְּרִים לְמַטָּה, שְׁתֵּי דְרָגוֹת נִפְרָדוֹת מֵהֶם, מַרְאֶה וַחֲלוֹם, וְעוֹמְדִים בַּיְרֵכַיִם. בְּאוֹתָם חֲמוּקִים עוֹמְדִים מַרְאֶה, וְאוֹתוֹ שֶׁנִּקְרָא נְבוּאָה קְטַנָּה. מֵהַיְרֵכַיִם וּלְמַטָּה (למטה) עוֹמֵד חֲלוֹם, עַד שֶׁיַּגִּיעוּ רַגְלַיִם בְּרַגְלַיִם, וְשָׁם עוֹמֵד הֵיכָל תַּחְתּוֹן שֶׁנִּקְרָא לִבְנַת הַסַּפִּיר.</p>\n<p>הַכֹּל יְרֵכַיִם בִּירֵכַיִם, לְהִשְׁתַּלֵּם אֶחָד עִם אֶחָד, וְכֻלָּם הַדְּרָגוֹת שֶׁל הַנְּבוּאָה, שֶׁהֲרֵי מִשָּׁם יוֹצְאִים וְשׁוֹרִים, וְנַעֲשֶׂה מֵהֶם מַרְאֶה, וְשׁוֹרִים עַל הַמָּקוֹם הַזֶּה וְנַעֲשֶׂה מֵהֶם חֲלוֹם. יוֹסֵף הַצַּדִּיק הוּא שְׁלֵמוּת הַכֹּל, הוּא נָטַל הַכֹּל. מִשּׁוּם שֶׁהַכֹּל הִתְתַּקֵּן בִּגְלָלוֹ, הַכֹּל מִשְׁתּוֹקֵק בִּתְשׁוּקָה בִּגְלָלוֹ.</p>\n<p>בֹּא וּרְאֵה, בְּשָׁעָה שֶׁיּוֹסֵף הַצַּדִּיק עָמַד לְתַקֵּן הַכֹּל, אָז הוּא נָטַל הַכֹּל. וּכְשֶׁהִתְחַבֵּר בְּהֵיכָלוֹ, אָז כֻּלָּם מִתְעוֹרְרִים לִטֹּל תְּשׁוּקָה וְרָצוֹן, עֶלְיוֹנִים וְתַחְתּוֹנִים, וְהַכֹּל הֵם בְּרָצוֹן אֶחָד וּשְׁלֵמוּת אַחַת, לְשַׂמֵּחַ (להיות) עֶלְיוֹנִים וְתַחְתּוֹנִים בְּרָצוֹן אֶחָד כָּרָאוּי. וְכָל הַתַּחְתּוֹנִים עוֹמְדִים בְּקִיּוּם בִּשְׁבִילוֹ, וְלָכֵן כָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. וְעַל הַיְסוֹד הַזֶּה עוֹמֵד הָעוֹלָם הַזֶּה.</p>\n<p>לִבְנַ\"ת הַסַּפִּי\"ר הַזּוֹ לֹא עוֹמֶדֶת בְּקִיּוּם, עַד שֶׁיּוֹסֵף הַצַּדִּיק הַזֶּה מִתְתַּקֵּן. וּכְשֶׁהוּא מִתְתַּקֵּן, אָז כֻּלָּם מִתְתַּקְּנִים. זֶהוּ הַיְסוֹד שֶׁל כָּל הַבִּנְיָן. וְעַל זֶה כָּתוּב, (בראשית ב) וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע, וְלֹא כָתוּב וַיִּיצֶר, וְלֹא כָתוּב וַיִּבְרָא. מִשּׁוּם שֶׁזֶּה עוֹמֵד עַל יְסוֹד, וּלְאַחַר שֶׁהַיְסוֹד נִתְקָן, הַכֹּל נִבְנֶה עָלָיו. וּמִשּׁוּם זֶה הַכֹּל עוֹמֵד בָּזֶה, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב (שם) וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע, שֶׁהָיְתָה מֵהַצַּד הָאֲחוֹרִי וְהִתְקִינָהּ לַחֲזֹר פָּנִים בְּפָנִים. כָּךְ בֵּאַרְנוּ. אֲבָל וַיִּבֶן, הִסְתַּכֵּל לְהַעֲלוֹתָהּ לְאוֹתָהּ דַּרְגָּה שֶׁל הָעוֹלָם הָעֶלְיוֹן שָׁרוּי בָּהּ, לִהְיוֹת זוֹ כְּמוֹ זוֹ.</p>\n<p>עוֹד וַיִּבֶן - הִסְתַּכֵּל בְּצִדּוֹ וְהִתְקִין וְכִוֵּן אֶת כָּל רוּחוֹתֶיהָ לִזְרֹעַ וּלְהַשְׁקוֹת וּלְהוֹלִיד, וְלַעֲשׂוֹת לָהּ כָּל צְרָכֶיהָ כְּמוֹ שֶׁצָּרִיךְ. וְאַחַר כָּךְ וַיְבִיאֶהָ, בַּמֶּה? בַּצַּדִּיק הַזֶּה, שֶׁכָּתוּב (אסתר ב) וּבָזֶה הַנַּעֲרָה בָּאָה אֶל הַמֶּלֶךְ. שֶׁזֶּה הִמְשִׁיךְ אֶת הַכֹּל לַעֲלוֹת וּלְהִתְעַטֵּר בִּשְׁלֵמוּת. כָּאן מְנִיעַת כָּל הַחֲטָאִים, וְכָאן מְנִיעַת כָּל הַתְּשׁוּקוֹת הָרָעוֹת.</p>\n<p>מַה שֶּׁאֵינוֹ בְּאוֹתוֹ הַהֵיכָל הַשִּׁשִּׁי, בַּצַּד הָאַחֵר, שֶׁשָּׁם כָּל הָעִנּוּגִים הָרָעִים וְכָל הַצְּדָדִים שֶׁל הָעֹנֶג שֶׁל הָעוֹלָם הַזֶּה, וּכְשֶׁהָעוֹלָם הַזֶּה מִתְנַהֵג בָּהֶם, אֲנָשִׁים נִכְשָׁלִים בָּהֶם (ומשום שבני אדם טועים בהם, נכשלים בהם) לְאוֹתוֹ הָעוֹלָם, שֶׁרוֹאִים כַּמָּה עִנּוּגִים וּתְשׁוּקוֹת שֶׁהַגּוּף נֶהֱנֶה וּמִתְעַנֵּג מֵהֶם, וְטוֹעִים אַחֲרֵיהֶם. זֶהוּ שֶׁכָּתוּב, (בראשית ג) וַתֵּרֶא הָאִשָּׁה כִּי טוֹב הָעֵץ לְמַאֲכָל וְגוֹ'. שֶׁהֲרֵי כָּל הַתְּשׁוּקוֹת וְכָל הָעִנּוּגִים שֶׁל הָעוֹלָם תְּלוּיִים בּוֹ.</p>\n<p>וְעַל כֵּן כְּמוֹ זֶה יֵשׁ דְּבָרִים שֶׁהַגּוּף נֶהֱנֶה מֵהֶם, וְנִכְנָסִים לַגּוּף וְלֹא לַנְּשָׁמָה. וְיֵשׁ דְּבָרִים שֶׁהַנְּשָׁמָה נֶהֱנֵית מֵהֶם וְלֹא הַגּוּף, וְעַל כֵּן הַדְּרָגוֹת נִפְרָדוֹת זוֹ מִזּוֹ. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁלּוֹקְחִים דֶּרֶךְ יְשָׁרָה, וּמוֹנְעִים עַצְמָם מֵאוֹתוֹ הַצַּד, וְנִדְבָּקִים בְּצַד הַקְּדֻשָּׁה.</p>\n<p>בַּהֵיכָל הַזֶּה כְּלוּלִים כָּל שְׁאָר הַשֵּׁמוֹת שֶׁל כָּל אֵלּוּ הַהֵיכָלוֹת (וחילות) שֶׁלְּמַטָּה. שְׁנֵי שֵׁמוֹת הֵם שֶׁכָּלְלוּ אֶת שְׁאָר הַשֵּׁמוֹת הָאֲחֵרִים. אֶחָד זָכָר מִתְחַבֵּר מַעְלָה בְּמַטָּה, וְיַעֲקֹב נָטַל אֶת הֵיכָלוֹ בְּאוֹתָן נְשִׁיקוֹת בְּסוֹד עֶלְיוֹן, וְאָז כּוֹלֵל אֶת כָּל שְׁאָר הַשֵּׁמוֹת, וְנִקְרָא יְהֹוָ\"ה אֱלֹהִי\"ם, וְזֶה נִקְרָא שֵׁם מָלֵא, כְּמוֹ שֶׁבֵּאַרְנוּ. וְאֶחָד כְּשֶׁמִּתְחַבֵּר יְסוֹד הָעוֹלָם בְּהֵיכָלוֹ, וְכֻלָּם מִתְעוֹרְרִים בַּחֲבִיבוּת וּבִתְשׁוּקָה אֵלָיו, וְכֻלָּם כְּלוּלִים בּוֹ, אָז כּוֹלֵל שְׁאָר הַשֵּׁמוֹת וְנִקְרָא יְהֹוָ\"ה צְבָאוֹת. וְזֶה נִקְרָא שֵׁם קָדוֹשׁ שָׁלֵם, וְלֹא שָׁלֵם כְּמוֹ הָאַחֵר הַזֶּה.</p>\n<p>מַה בֵּין זֶה לָזֶה? זֶה שׁוֹלֵט עֶלְיוֹן בַּתַּחְתּוֹן, גּוּף בְּגוּף, (וזה הוא שולט בכל) כְּמוֹ שֶׁאָמַרְנוּ. וְזֶה שׁוֹלֵט מִמְּקוֹם סִיּוּם הַגּוּף וּלְמַטָּה בְּאוֹתָם הֵיכָלוֹת וּבַכֹּל שֶׁלְּמַטָּה, וְסוֹד זֶה - בַּיִת רִאשׁוֹן וּבַיִת שֵׁנִי. וּמִשּׁוּם כָּךְ, הַהֵיכָל הַזֶּה כּוֹלֵל אֶת כָּל שְׁאָר הַשֵּׁמוֹת שֶׁלְּמַטָּה, (וכל השמות אנו כוללים בשם הזה, כל השמות שלמטה) כְּמוֹ שֶׁבֵּאַרְנוּ. וְעַל כָּךְ הַשֵּׁמוֹת הַלָּלוּ - זֶה עוֹלֶה וְזֶה יוֹרֵד. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁיּוֹדְעִים דַּרְכֵי הַתּוֹרָה.</p>\n<p>הַיְסוֹד הַזֶּה הִתְתַּקֵּן לִשְׁנֵי צְדָדִים. אֶחָד לְתַקֵּן אֶת כָּל הַשְּׁאָר שֶׁלְּמַטָּה, וְאֶחָד לְתַקֵּן אֶת הַהֵיכָל הַשְּׁבִיעִי וּלְתַקֵּן זֶה בָּזֶה שֶׁיִּהְיֶה הַכֹּל בְּרָצוֹן אֶחָד כָּרָאוּי. עַד כָּאן הַיִּחוּד שֶׁל שְׁנֵי צְדָדִים, שֶׁלְּמַעְלָה וּלְמַטָּה, לְהִתְיַחֵד כְּאֶחָד בִּשְׁלֵמוּת, לָלֶכֶת בְּדֶרֶךְ יְשָׁרָה.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיּוֹדֵעַ לְיַחֵד אֶת הַיִּחוּד וּלְסַדֵּר אֶת סִדּוּר הָאֱמוּנָה לָלֶכֶת בְּדֶרֶךְ יְשָׁרָה. אַשְׁרָיו בָּעוֹלָם הַזֶה וּבָעוֹלָם הַבָּא. וְעַל כָּךְ כָּתוּב, (תהלים פה) חֶסֶד וֶאֱמֶת נִפְגָּשׁוּ צֶדֶק וְשָׁלוֹם נָשָׁקוּ. וְאָז - אֱמֶת מֵאֶרֶץ תִּצְמָח וְצֶדֶק מִשָּׁמַיִם נִשְׁקָף. גַּם ה' יִתֵּן הַטּוֹב וְאַרְצֵנוּ תִּתֵּן יְבוּלָהּ.</p>"],[9522011913,"<p>הַהֵיכָל הַשְּׁבִיעִי. הַהֵיכָל הַזֶּה הוּא הַהֵיכָל הַפְּנִימִי מִכָּל הַהֵיכָלוֹת הַלָּלוּ. הַהֵיכָל הַזֶּה הוּא נִסְתָּר, וְאֵין בּוֹ דְּיוֹקָן מַמָּשׁ וְלֹא גוּף כְּלָל. כָּאן הַנִּסְתָּר שֶׁתּוֹךְ סוֹד הַסּוֹדוֹת. זֶהוּ סוֹד שֶׁהוּא מָקוֹם לְהִכָּנֵס לְשָׁם בְּתוֹךְ אוֹתָם הַצִּנּוֹרוֹת שֶׁלְּמַעְלָה. הָרוּחַ שֶׁל כָּל הָרוּחוֹת, רָצוֹן שֶׁל כָּל הָרְצוֹנוֹת, לְהִתְחַבֵּר הַכֹּל כְּאֶחָד. רוּחַ הַחַיִּים (של זה) בָּזֶה, וְלִהְיוֹת הַכֹּל תִּקּוּן אֶחָד.</p>\n<p>הַהֵיכָל הַזֶּה נִקְרָא בֵּית קָדְשֵׁי הַקְּדָשִׁים, הַמָּקוֹם לְקַבֵּל אֶת (הגשמה העליונה) הַנְּשָׁמוֹת הָעֶלְיוֹנוֹת, שֶׁנִּקְרֵאת כָּךְ לְעוֹרֵר אֵלָיו אֶת הָעוֹלָם הַבָּא.</p>\n<p>הָעוֹלָם הַזֶּה נִקְרָא עוֹלָם. עוֹלָם - עֲלִיָּה, שֶׁעוֹלֶה הָעוֹלָם הַתַּחְתּוֹן לָעוֹלָם הָעֶלְיוֹן, וּמִסְתַּתֵּר בְּתוֹכוֹ וְנֶעְלָם בּוֹ, וְנִגְלֶה בַסֵּתֶר. עוֹלָם - שֶׁהוּא עוֹלֶה עִם כָּל אוֹתָם שֶׁקְּרֵבִים לוֹ וְנִסְתָּרִים תּוֹךְ סֵתֶר עֶלְיוֹן. עוֹלָם עֶלְיוֹן - עוֹלֶה וּמִסְתַּתֵּר בְּרָצוֹן עֶלְיוֹן תּוֹךְ סֵתֶר כָּל הַנִּסְתָּרִים, שֶׁלֹּא נוֹדַע כְּלָל (כלל) וְלֹא הִתְגַּלָּה, וְאֵין מִי שֶׁמַּכִּיר אוֹתוֹ.</p>\n<p>הַפָּרֹכֶת, שֶׁהִיא מָסָךְ פָּרוּס, מְכַסָּה אֶת תּוֹךְ סֵתֶר הַנִּסְתָּר. הַכַּפֹּרֶת פְּרוּסָה תּוֹךְ הַסְּתָרִים הָעֶלְיוֹנִים לְהַסְתִּיר הַנִּסְתָּרִים, שֶׁהֲרֵי הֵם טְמִירִים וְנִסְתָּרִים. (הפרכת פרוסהבתוך סתרים עליונים לשמר הסתום, שזה נסתר וסתום) לִפְנִים מִן הַכַּפֹּרֶת יֵשׁ מָקוֹם נִסְתָּר וְטָמוּן וְגָנוּז לְהַכְנִיסוֹ לְתוֹכוֹ. שֶׁמֶן מִשְׁחַת עֶלְיוֹן, רוּחַ הַחַיִּים, עַל יַד אוֹתוֹ הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, וְאוֹתוֹ נָהָר נִקְרָא מַבּוּעַ הַבְּאֵר, שֶׁלֹּא פוֹסְקִים מֵימָיו לְעוֹלָמִים. וּכְשֶׁזֶּה נִכְנָס וְשׁוֹפֵעַ כָּל אוֹתוֹ מִשְׁחַת קֹדֶשׁ מִלְמַעְלָה מִמָּקוֹם שֶׁל קֹדֶשׁ הַקְּדָשִׁים, אוֹר שֶׁל שֶׁפַע יוֹרֵד וּבָא לְתוֹךְ אוֹתָם הַצִּנּוֹרוֹת, וְזֶה מִתְמַלֵּא מִשָּׁם כִּנְקֵבָה שֶׁמִּתְעַבֶּרֶת וּמִתְמַלֵּאת מִן הַזָּכָר.</p>\n<p>אַף כָּךְ גַּם הַהֵיכָל הַזֶּה מִתְתַּקֵּן תָּמִיד לְקַבֵּל כִּנְקֵבָה שֶׁמְּקַבֶּלֶת מִן הַזָּכָר. הַקַּבָּלָה שֶׁמְּקַבֶּלֶת אֶת כָּל הָרוּחוֹת וְהַנְּשָׁמוֹת הַקְּדוֹשׁוֹת שֶׁיּוֹרְדוֹת לָעוֹלָם, וְהִתְעַבְּרוּ (והתעכבו) שָׁם כָּל אוֹתוֹ זְמַן שֶׁצָּרִיךְ.</p>\n<p>יִתְעַכְּבוּ עַד שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ, וִיקַבְּלוּ כָּל אוֹתָן הַנְּשָׁמוֹת, וְיָבאוּ וְיִשְׂמַח הָעוֹלָם כְּמִקֹּדֶם, וְאָז יִשְׂמַח הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמִקֹּדֶם, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) יִשְׂמַח ה' בְּמַעֲשָׂיו.</p>\n<p>בַּהֵיכָל הַזֶּה קַיָּמִים הָעִנּוּגִים וְהַתַּפְנוּקִים שֶׁל הָרוּחוֹת, וְהַשַּׁעֲשׁוּעַ שֶׁמִּשְׁתַּעֲשֵׁעַ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגַן עֵדֶן. כָּאן הִיא תְּשׁוּקַת הַכֹּל וְעֹנֶג הַכֹּל לְהִתְחַבֵּר הַכֹּל כְּאֶחָד וְלִהְיוֹת הַכֹּל כְּאֶחָד, הַקֶּשֶׁר שֶׁל הַכֹּל בְּיִחוּד אֶחָד כָּאן עוֹמֵד.</p>\n<p>שֶׁכְּשֶׁכָּל הָאֵיבָרִים מִתְחַבְּרִים בָּאֵיבָרִים הָעֶלְיוֹנִים, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, אֵין לָהֶם תְּשׁוּקָה וְאֵין לָהֶם עֹנֶג, רַק בַּיִּחוּד שֶׁל הַהֵיכָל הַזֶּה, וְהַכֹּל כָּאן תָּלוּי. כְּשֶׁהַהִתְחַבְּרוּת שֶׁל כָּאן מִתְיַחֶדֶת בְּיִחוּד אֶחָד, אֲזַי כָּל אוֹר הָאֵיבָרִים וְכָל הֶאָרַת הַפָּנִים וְכָל הַשְּׂמָחוֹת, כֻּלָּם מְאִירִים וּשְׂמֵחִים.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיּוֹדֵעַ לְסַדֵּר סִדּוּרִים וּלְתַקֵּן אֶת תִּקּוּנֵי הַהִשְׁתַּלְּמוּת כָּרָאוּי, אַהֲבָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וְאָז כָּל הַדִּינִים וְכָל הַגְּזֵרוֹת הָרָעוֹת עוֹבְרוֹת וּמִתְבַּטְּלוֹת מִן הָעוֹלָם.</p>\n<p>הֵיכָל זֶה הֵיכָל שֶׁל תְּשׁוּקָה, הֵיכָל שֶׁל עֹנֶג, הֵיכָל שֶׁל שַׁעֲשׁוּעַ עֶלְיוֹן וְתַחְתּוֹן כְּאֶחָד. וּמְקַבְּלִים כֻּלָּם הָאוֹר שֶׁל הַנֵּר הָעֶלְיוֹן שֶׁמֵּאִיר לַכֹּל וּלְהִתְיַחֵד הַכֹּל כְּמוֹ שֶׁצָּרִיךְ בְּיִחוּד שָׁלֵם. וְעַל זֶה הֵיכָל זֶה עוֹמֵד בְּסֵתֶר הַכֹּל, גָּנוּז מֵהַכֹּל. אַף עַל גַּב שֶׁכֻּלָּם מֻסְתָּרִים, זֶה מֻסְתָּר וְגָנוּז יוֹתֵר, לִהְיוֹת בְּרִית קִיּוּם הַכֹּל כְּאֶחָד, זָכָר וּנְקֵבָה, לִהְיוֹת שְׁלֵמִים.</p>\n<p>הַהֵיכָל הַזֶּה נִקְרָא אֲרוֹן הַבְּרִית, שֶׁהוּא אֲדוֹן כָּל הָאָרֶץ. מִשּׁוּם שֶׁזֶּהוּ מָקוֹם שֶׁיּוֹצְאוֹת מִמֶּנּוּ כָּל הַנְּשָׁמוֹת שֶׁל הָעוֹלָם לְיַחֵד יִחוּד לְמַטָּה, וּלְהַמְשִׁיךְ אֶת הַיִּחוּד שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִמַּעְלָה לְמַטָּה לָתֵת לַצַּדִּיק, מִשּׁוּם שֶׁיָּצְאוּ מִצַּדִּיק וְנִכְנָסוֹת לַצַּדִּיק, וְאַחַר כָּךְ יָצְאוּ מִצַּדִּיק וְנִכְנָסוֹת לַמָּקוֹם שֶׁיָּצְאוּ מִשָּׁם.</p>\n<p>אֲרוֹן הַבְּרִית הַזֶּה לוֹקֵחַ הַכֹּל מִצַּדִּיק, וְאַחַר כָּךְ יוֹצְאוֹת מִמֶּנּוּ וְנִכְנָסוֹת לַצַּדִּיק שֶׁלְּמַטָּה. אַחַר כָּךְ יוֹצְאוֹת מֵהַצַּדִּיק שֶׁלְּמַטָּה וְנִכְנָסוֹת לַאֲרוֹן הַבְּרִית הַזֶּה, שֶׁיִּהְיוּ כָּל הַנְּשָׁמוֹת כְּלוּלוֹת מִמַּעְלָה וּמִמַּטָּה לִהְיוֹת שְׁלֵמוּת מִכָּל הַצְּדָדִים. וַאֲרוֹן הַבְּרִית הַזֶּה לוֹקֵחַ מֵהַצַּדִּיק אוֹתָן נְשָׁמוֹת מִשְּׁנֵי צְדָדִים.</p>\n<p>בֹּא וּרְאֵה, מַבּוּעַ הַבְּאֵר אֵינוֹ נִפְרָד מֵהַבְּאֵר לְעוֹלָמִים, וְלָכֵן הַמָּקוֹם הַזֶּה הוּא תִּקּוּן שֶׁל הַכֹּל, הַקִּיּוּם שֶׁל כָּל הַגּוּף, לִהְיוֹת שָׁלֵם בַּכֹּל כָּרָאוּי. כָּאן הוּא הַיִּחוּד וְהַקֶּשֶׁר כְּאֶחָד לִהְיוֹת מַעְלָה וּמַטָּה אֶחָד בְּקֶשֶׁר אֶחָד, שֶׁאֵין נִפְרָדִים כָּל הָאֵיבָרִים זֶה מִזֶּה, וּלְהִמָּצֵא הַכֹּל פָּנִים בְּפָנִים.</p>\n<p>וְעַל זֶה שָׁנִינוּ, מִי שֶׁמְּשַׁמֵּשׁ מִטָּתוֹ מֵאָחוֹר, מַכְחִישׁ אֶת תִּקּוּן הַהִסְתַּכְּלוּת פָּנִים בְּפָנִים, לְהָאִיר הַכֹּל כְּאֶחָד וּלְהִמָּצֵא הַכֹּל פָּנִים בְּפָנִים בִּדְבֵקוּת כָּרָאוּי, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) וְדָבַק בְּאִשְׁתּוֹ. בְּאִשְׁתּוֹ דַּוְקָא, וְלֹא אֲחוֹרֵי אִשְׁתּוֹ.</p>\n<p>שְׁנַיִם הֵם. יַעֲקֹב הוּא לְמַעְלָה, וְיוֹסֵף הוּא לְמַטָּה. שְׁתֵּי תְשׁוּקוֹת הֵן, אֶחָד הַהֵיכָל הַשִּׁשִּׁי, וְאֶחָד הַהֵיכָל הַשְּׁבִיעִי הַזֶּה. הַתְּשׁוּקָה שֶׁלְּמַעְלָה בְּאוֹתָן נְשִׁיקוֹת שֶׁנּוֹטֵל יַעֲקֹב. הַתְּשׁוּקָה שֶׁלְּמַטָּה בַּשִּׁמּוּשׁ הַזֶּה שֶׁנּוֹטֵל יוֹסֵף. מִשְּׁנֵי הַצְּדָדִים הַלָּלוּ נוֹטֵל (זה) אֲרוֹן הַבְּרִית אֶת רוּחַ הַחַיִּים. מֵהַצַּד שֶׁל יַעֲקֹב נוֹטֵל אֶת רוּחַ הַחַיִּים שֶׁלְּמַעְלָה שֶׁנִּדְבָּק בּוֹ בְּאוֹתָן נְשִׁיקוֹת, וּמַכְנִיס (באותן נשיקות) (ונכנס) אֶת רוּחַ הַחַיִּים שֶׁלְּמַעְלָה בּוֹ לְהִזּוֹן מִמֶּנּוּ. מֵהַצַּד שֶׁל יוֹסֵף שֶׁהוּא לְמַטָּה, בְּסִיּוּם הַגּוּף, בַּהֵיכָל הַזֶּה נוֹטֵל רוּחוֹת וּנְשָׁמוֹת לְהָרִיק לְמַטָּה לָעוֹלָם הַזֶּה.</p>\n<p>שְׁנֵי הַצְּדָדִים הַלָּלוּ נִפְרָדִים לִשְׁנֵי צְדָדִים. הַצַּד שֶׁל יַעֲקֹב מִתְפַּשֵּׁט וְנוֹתֵן כֹּחַ לִנְבּעַ בְּאוֹתָם שָׁדַיִם שֶׁמִּתְמַלְּאִים מֵאוֹתָהּ רוּחַ הַחַיִּים, וּמֵינִיק בָּהֶם אֶת אוֹתָם מַלְאָכִים קְדוֹשִׁים, שֶׁהֵם חַיִּים וְקַיָּמִים לְעוֹלָמִים, וְקַיָּמִים בְּקִיּוּם בּוֹ. הַצַּד שֶׁל יוֹסֵף נִכְנָס בִּתְשׁוּקָה וְנוֹתֵן כֹּחַ לִפְנִים, וְעוֹשֶׂה נְשָׁמוֹת וְרוּחוֹת לָרֶדֶת לְמַטָּה וּלְהָזִין בָּהֶם בְּנֵי הָעוֹלָם.</p>\n<p>וְעַל כֵּן קַיָּמִים שְׁנֵי הַצְּדָדִים הַלָּלוּ, זֶה לְמַעְלָה וְזֶה לְמַטָּה. זֶה לְהָזִין לְמַעְלָה, וְזֶה לָזוּן לְמַטָּה. כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ. (ולכן) וְהַכֹּל הוּא אֶחָד וְסוֹד אֶחָד הוּא. וְעִם כָּל זֶה, יוֹסֵף זָן אֶת כָּל הַגּוּף וּמַשְׁקֶה אוֹתוֹ. שֶׁמֵּרוּחַ הַחַיִּים הַזּוֹ שֶׁל הַהִדָּבְקוּת שֶׁל יַעֲקֹב יוֹרֵד לְמַטָּה, וּבוֹ נִדְבָּק אֲרוֹן הַבְּרִית הַזֶּה בְּרָצוֹן לְמַעְלָה, וְיוֹרֶדֶת אוֹתָהּ רוּחַ חַיִּים לְמַטָּה בְּאוֹתָהּ הִתְדַּבְּקוּת שֶׁל יוֹסֵף, וּכְשֶׁהַכֹּל מִתְחַבֵּר כְּאֶחָד, מִתְמַלְּאִים אוֹתָם הַשָּׁדַיִם לְהָנִיק לַכֹּל, וּמִשּׁוּם כָּךְ הַכֹּל הוּא אֶחָד. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיּוֹדֵעַ לִקְשֹׁר קְשָׁרִים וּלְיַחֵד יִחוּד בִּתְפִלָּתוֹ בִּרְצוֹן הַלֵּב כָּרָאוּי כְּדֵי לְהַדְבִּיק אֵיבָר בְּאֵיבָר, רוּחַ בְּרוּחַ, הַכֹּל בִּכְלָל אֶחָד, לִהְיוֹת הַכֹּל אֶחָד כָּרָאוּי.</p>\n<p>בֹּא וּרְאֵה, הַהֵיכָל הַזֶּה, כְּשֶׁהָרוּחוֹת הַקְּדוֹשׁוֹת הַלָּלוּ וְכָל אוֹתָם הֵיכָלוֹת וּמֶרְכָּבוֹת כֻּלָּם מִתְיַחֲדִים כְּאֶחָד וְנִמְצָאִים בְּקֶשֶׁר אֶחָד, אֲזַי הָרוּחַ הָעֶלְיוֹנָה הַזּוֹ שֶׁל כֻּלָּם, שֶׁהִיא נְקֻדָּה אַחַת נִסְתֶּרֶת בָּהֶם, וְלֹא מִתְגַּלָּה, וְנַעֲשֵׂית רוּחַ נִסְתֶּרֶת כְּמוֹ הָעֶלְיוֹנָה. וְסִימָנְךְ - הָאֱגוֹז, יִחוּד בַּקֶּשֶׁר שֶׁל הַכֹּל כְּפִי שֶׁאָמַרְנוּ, לְהִקָּשֵׁר זֶה בָּזֶה, לִהְיוֹת הַכֹּל שָׁלֵם בִּשְׁלֵמוּת (זכר ונקבה) כְּאֶחָד.</p>\n<p>וַהֲרֵי בֵּאַרְנוּ כְּמוֹ כֵן, הַקָּרְבָּן עוֹלֶה לְיַחֵד (יחוד) קָרְבָּן וּלְיַחֵד (ולספק) אֶת כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ מֵאוֹתוֹ הֶעָשָׁן שֶׁעוֹלֶה - הַכֹּהֵן שֶׁהוּא לְיָמִין בַּקֶּשֶׁר שֶׁל הַיִּחוּד בְּרָצוֹן, וְהַלְוִיִּם בְּשִׁירָה. כְּלוּלִים זֶה בָּזֶה, הֵיכָל בְּהֵיכָל, רוּחַ בְּרוּחַ, עַד שֶׁמִּתְחַבְּרִים בִּמְקוֹמָם אֵיבָר בְּאֵיבָר, לִהְיוֹת הַכֹּל כָּלוּל כְּאֶחָד כָּרָאוּי.</p>\n<p>וַהֲרֵי בֵּאַרְנוּ, שֶׁכְּשֶׁנִּשְׁלָם הַכֹּל כְּאֶחָד, הָאֵיבָרִים הָעֶלְיוֹנִים בַּתַּחְתּוֹנִים, אָז הַנְּשָׁמָה הָעֶלְיוֹנָה שֶׁל הַכֹּל מִתְעוֹרֶרֶת וְנִכְנֶסֶת בְּכֻלָּם וּמְאִירָה לַכֹּל, וְכָל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים מִתְבָּרְכִים, וְאוֹתוֹ שֶׁלֹּא נוֹדָע וְלֹא נִכְנָס בְּחֶשְׁבּוֹן, הָרָצוֹן שֶׁאֵינוֹ נִתְפָּס לְעוֹלָמִים, אָז הַכֹּל עוֹלֶה עַד אֵין סוֹף, וְנִקְשָׁר הַכֹּל בְּקֶשֶׁר אֶחָד, וּמִתְבַּשֵּׂם אוֹתוֹ הָרָצוֹן לְתוֹךְ וּבִפְנִים בַּסֵּתֶר.</p>\n<p>אוֹר הַנְּשָׁמָה הָעֶלְיוֹנָה עוֹלֶה לִפְנַי וְלִפְנִים וּמֵאִיר לַכֹּל. בְּתוֹךְ הָאוֹר הַזֶּה נִכְנָס סֵתֶר הַמַּחֲשָׁבָה שֶׁכּוֹלֵל אֶת הַכֹּל, וְלִפְנַי וְלִפְנִים בְּאוֹתוֹ רְצוֹן הַמַּחֲשָׁבָה מֵאִיר וּמִתְבַּשֵּׂם, וְתוֹפֵס וְלֹא תוֹפֵס, וְעוֹלֶה (הרצוןהזה) מִתּוֹךְ רְצוֹן הַמַּחֲשָׁבָה לִתְפֹּס בּוֹ. וּכְשֶׁזֶּה עוֹלֶה, הָאוֹר שֶׁלְּמַטָּה תּוֹפֵס בּוֹ.</p>\n<p>וְכֵן הַכֹּל, לְהִתְקַשֵּׁר וּלְהִתְמַלֵּא וּלְהִתְבָּרֵךְ הַכֹּל כְּאֶחָד כָּרָאוּי. וְאָז נִקְשָׁרִים זֶה עִם זֶה כְּפִי שֶׁאָמַרְנוּ, הֵיכָלוֹת בְּהֵיכָלוֹת, תַּחְתּוֹנִים בָּעֶלְיוֹנִים, סוֹד שֶׁל זָכָר וּנְקֵבָה כְּאֶחָד, הָאוֹר הָעֶלְיוֹן בָּאוֹר שֶׁנִּסְתָּר וְגָנוּז בּוֹ יוֹתֵר, וְאוֹתוֹ הַגָּנוּז כָּלוּל בְּמַה שֶּׁגָּנוּז יוֹתֵר, עַד שֶׁהַכֹּל נִמְצָא כָּרָאוּי בְּיִחוּד אֶחָד.</p>\n<p>וְלָכֵן מֹשֶׁה הָיָה יוֹדֵעַ לְסַדֵּר אֶת סִדּוּר רִבּוֹנוֹ מִכָּל בְּנֵי הָעוֹלָם. כְּשֶׁהִצְטָרֵךְ לְהַאֲרִיךְ - הֶאֱרִיךְ. לְקַצֵּר - קִצֵּר. כְּמוֹ שֶׁבֵּאַרְנוּ, (במדבר יב) אֵל נָא רְפָא נָא לָהּ. שָׁנִינוּ, מִי שֶׁמַּאֲרִיךְ בִּתְפִלָּתוֹ וּמְעַיֵּן בָּהּ, בַּסּוֹף בָּא לִידֵי כְאֵב לֵב. וְשָׁנִינוּ, מִי שֶׁמַּאֲרִיךְ בִּתְפִלָּתוֹ, מַאֲרִיכִים יָמָיו.</p>\n<p>וְסוֹד הַדָּבָר - מִי שֶׁמַּאֲרִיךְ בְּמָקוֹם שֶׁצָּרִיךְ לְקַצֵּר בָּא לִידֵי כְּאֵב לֵב, אֵיזֶה לֵב? זֶהוּ שֶׁכָּתוּב, (משלי טו) וְטוֹב לֵב מִשְׁתֶּה תָמִיד. מִשּׁוּם שֶׁהוּא מָקוֹם שֶׁצָּרִיךְ לְקַצֵּר וְלֹא לְהַאֲרִיךְ בּוֹ, שֶׁהֲרֵי הַכֹּל עוֹמֵד לְמַעְלָה, וְצָרִיךְ שֶׁלֹּא לְהַמְשִׁיכוֹ, לִקְשֹׁר אוֹתוֹ בַּקֶּשֶׁר שֶׁלְּמַעְלָה לְלֹא אֲרִיכוּת, שֶׁיִּהְיֶה הַכֹּל אֶחָד בְּיִחוּד אֶחָד. וְכֵיוָן שֶׁנִּקְשָׁר כְּאֶחָד, אָז אֵין צֹרֶךְ לְהַאֲרִיךְ בָּאֹרֶךְ וּלְהִתְחַנֵּן בְּתַחֲנוּנִים. וּכְשֶׁמַּאֲרִיךְ בָּאֹרֶךְ בְּמָקוֹם שֶׁצָּרִיךְ, הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל תְּפִלָּתוֹ, וְזֶהוּ כְּבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁיִּחוּד הַתְּפִלָּה קוֹשֵׁר קְשָׁרִים וּמַרְבֶּה בִּרָכוֹת לְמַעְלָה וּלְמַטָּה.</p>\n<p>בְּתוֹךָֹ הַהֵיכָל הַזֶּה קַיֶּמֶת נְקוּדָה אַחַת נִסְתֶּרֶת, וְהַנְּקֻדָּה הַזּוֹ הִיא רוּחַ לְקַבֵּל רוּחַ אַחֶרֶת עֶלְיוֹנָה. וּכְשֶׁשּׁוֹרָה רוּחַ בְּרוּחַ, אָז נִכְנָסוֹת זוֹ בָּזוֹ וְהֵן אַחַת וּדְבֵקוּת אַחַת. וְנִרְכָּבוֹת זוֹ בָּזוֹ לִהְיוֹת אַחַת, כְּמוֹ הָעֵץ הַזֶּה שֶׁמַּרְכִּיבִים זֶה בָּזֶה וְהֵם אֶחָד, מִין בְּמִינוֹ. אוֹי לְמִי שֶׁמַּרְכִּיב מִין בְּשֶׁאֵינוֹ מִינוֹ, כְּמוֹ אוֹתָם בְּנֵי אַהֲרֹן שֶׁרָצוּ לְהַרְכִּיב עֵץ בְּאַחֵר שֶׁאֵינוֹ מִינוֹ.</p>\n<p>וּמִי שֶׁמַּרְכִּיב מִין בְּמִינוֹ, וְיוֹדֵעַ לִקְשֹׁר קֶשֶׁר בְּקִשְׁרוֹ, הֵיכָל בְּהֵיכָלוֹ, דַּרְגָּה בְּדַרְגָּתָהּ - לָזֶה יֵשׁ חֵלֶק בָּעוֹלָם הַבָּא, כְּמוֹ שֶׁבֵּאַרְנוּ, וְלָכֵן זוֹהִי שְׁלֵמוּת הַכֹּל. וּכְשֶׁנִּשְׁלָם זֶה בָּזֶה וְהוּא הַכֹּל מַעֲשֶׂה אֶחָד, מִין בְּמִינוֹ שֶׁיּוֹצֵא מֵהַשְּׁלֵמוּת הַזּוֹ, הוּא נִקְרָא מַעֲשֵׂה מֶרְכָּבָה.</p>\n<p>וְסוֹד זֶה - (בראשית ב) וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם. שֵׁם מָלֵא. וְאָדָם הוּא מַעֲשֵׂה שֶׁל הַמֶּרְכָּבָה הַזּוֹ, שֶׁמַּרְכִּיב זֶה בָּזֶה, מַעֲשֶׂה שֶׁל שְׁלֵמוּת הַכֹּל. וּכְשֶׁנִּשְׁלָמִים זֶה בָּזֶה, אָז ה' אֱלֹהִים, שֵׁם מָלֵא. אַשְׁרֵי מִי שֶׁיּוֹדֵעַ לִקְשֹׁר אֶת קִשְׁרֵי הָאֱמוּנָה וּלְיַחֵד אֶת הַיִּחוּד כָּרָאוּי.</p>\n<p>בֹּא וּרְאֵה, כְּמוֹ שֶׁיֶּשְׁנָם שֵׁמוֹת קְדוֹשִׁים עֶלְיוֹנִים מִתְחַבְּרִים אֵלּוּ בְּאֵלּוּ, כָּךְ הוּא הַשֵּׁם הַקָּדוֹשׁ, הִתְפָּרֵשׁ לְמַעְלָה וְהִתְפָּרֵשׁ לְמַטָּה. הַשֵּׁם הַזֶּה הוּא לְמַעְלָה, וְהַשֵּׁם הַזֶּה הוּא בָּאֶמְצַע, וְהַשֵּׁם הַזֶּה הוּא לְמַטָּה. יְהֹוָ\"ה שֶׁהוּא סוֹד הַשֵּׁם הַקָּדוֹשׁ הוּא אֶחָד, הַסּוֹד שֶׁל הַכֹּל. הָעוֹלָם הָעֶלְיוֹן בַּסֵּתֶר הַנִּסְתָּר שֶׁעָלָיו, שֶׁהִשְׁתַּתֵּף עִמּוֹ, וְהוּא אֶחָד. הָעוֹלָם הַתַּחְתּוֹן בְּסֵתֶר הָאֶמְצַע, סוֹד הַמֶּרְכָּבָה הַקְּדוֹשָׁה הָעֶלְיוֹנָה שֶׁעָלֶיהָ, וּבֵאַרְנוּ. (באוראה, סודשםהקדושזהייאלהים. שםזההואלמעלה, שם זה הוא באמצע, שם זה הוא למטה. למעלה סוד עולם הבאבסתום של הסתימות שעליו והוא אחד. למטה סוד עולם התחתון ועולם העליון שעליו משתתף עמו והוא אחד. באמצע בסוד המרכבה הקדושה העליונה, ומבאר.)</p>\n<p>מֵהַצַד הַזֶּה יוֹצְאוֹת אַרְבַּע מֶרְכָּבוֹת, וּמֵהַצַּד הַזֶּה אַרְבַּע מֶרְכָּבוֹת יוֹצְאוֹת, מִשּׁוּם שֶׁכָּל אַחַת וְאַחַת נִפְרֶדֶת לְאַרְבָּעָה, כָּל מֶרְכָּבָה הֵן אַרְבַּע, כְּשֶׁמִּסְתַּכְּלִים בַּדְּרָגוֹת. וְכֵן כֻּלָּם הָאַרְבַּע בְּאַרְבַּע, בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ שֶׁהוּא אֲדנָ\"י, בְּאוֹתָן מֶרְכָּבוֹת שֶׁעוֹמְדוֹת וְנוֹסְעוֹת בַּשֵּׁם הַזֶּה, וְהֵן נִקְרָאוֹת (זכריה ו) הָרֵי נְחֹשֶׁת, מִשּׁוּם שֶׁיֵּשׁ הָרִים וְיֵשׁ הָרִים. יֵשׁ הָרִים עֶלְיוֹנִים וְיֵשׁ הָרִים תַּחְתּוֹנִים. וְהֵם עוֹמְדִים בִּשְׁלֹשָׁה צְדָדִים, וְיוֹצְאִים מִתּוֹךְ זָהָב וָכֶסֶף וּנְחֹשֶׁת.</p>\n<p>הַנְּחֹשֶׁת לְמַטָּה, מִשּׁוּם שֶׁאוֹתָן מֶרְכָּבוֹת שֶׁיּוֹצְאוֹת מִתּוֹךְ אָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד שֶׁבְּתוֹךְ הַהֵיכָל הָרִאשׁוֹן, שֶׁהֵן אַרְבַּע מֶרְכָּבוֹת שֶׁיּוֹצְאוֹת מִתּוֹךְ אוֹתָן שְׁתֵּי רוּחוֹת יָמִין וּשְׂמֹאל, מִתּוֹךְ לִבְנַת הַסַּפִּיר, כְּמוֹ שֶׁאָמַרְנוּ. אֵלּוּ שְׁתֵּי הָרוּחוֹת שֶׁאָמַרְנוּ שָׁם, הֵן נִקְרָאוֹת שְׁנֵי הָרִים, וְהֵם הָרֵי נְחֹשֶׁת.</p>\n<p>מֵאוֹתָן שְׁתֵּי רוּחוֹת שֶׁנִּקְרָאוֹת הָרֵי נְחֹשֶׁת, יוֹצְאוֹת אוֹתָן אַרְבַּע מֶרְכָּבוֹת שֶׁמִּשְׁתַּמְּשׁוֹת בְּאוֹתוֹ הַשֵּׁם שֶׁל אָלֶ\"ף דָּלֶ\"ת שֶׁנִּשְׁקָע בְּסַנְדַּלְפוֹ\"ן, בַּעַל הַפָּנִים. וְכֻלָּם שְׁלִיחִים עַל אֵלֶּה בָּעוֹלָם בְּסוֹד סוּסִים וּמֶרְכָּבוֹת, מִשּׁוּם שֶׁיֵּשׁ מֶרְכָּבָה עַל סוּסִים שֶׁמַּסִּיעִים אוֹתָהּ.</p>\n<p>וְהַשֵּׁם הַקָּדוֹשׁ הַזֶּה נִכְלָל בְּיוֹ\"ד הֵ\"א, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁנִּכְלָל אָלֶ\"ף דָּלֶ\"ת בְּיוֹ\"ד הֵ\"א, וְהוּא יְאֲהַדוֹנָהִ\"י. וַהֲרֵי נִתְבָּאֵר, אֱלֹהִים לֹא נִכְלָל בְּשֵׁם אַחֵר, מִשּׁוּם שֶׁיֵּשׁ אֱלֹהִים חַיִּים, וּמִזֶּה מִתְפַּשֵּׁט לְכַמָּה צְדָדִים, וְלֹא מִתְכַּנֵּס, אֶלָּא מִתְפַּשֵּׁט.</p>\n<p>הַשֵּׁם שֶׁכּוֹלֵל אֶת כָּל הַשֵּׁמוֹת - יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, בְּסוֹד הָאוֹתִיּוֹת הַצֵּרוּף שֶׁל הַשֵּׁם הַקָּדוֹשׁ, שֶׁבּוֹ הָיָה יוֹדֵעַ הַכֹּהֵן לְצָרֵף בְּכָל צְדָדָיו, עַד שֶׁעוֹלִים הַשֵּׁמוֹת בְּכַמָּה צְדָדִים בְּאַרְבָּעִים וּשְׁנַיִם גְּוָנִים בְּהִשְׁתַּטְּחוּת הַמְּנוֹרָה שֶׁל הַנִּיצוֹץ הֶחָזָק, שֶׁזֶּהוּ שֶׁכּוֹלֵל אֶת כָּל הַשֵּׁמוֹת.</p>\n<p>וְהַשֵּׁם הַזֶּה כּוֹלֵל אֶת כָּל הַשֵּׁמוֹת. אאלדהניי\"ם סִימָן. בָּאוֹתִיּוֹת הַלָּלוּ כְּלוּלוֹת אֲחֵרוֹת מְחֻבָּרוֹת, וְאֵלּוּ יוֹצְאוֹת וְאֵלּוּ נִכְנָסוֹת. אַחַר כָּךְ כְּשֶׁנּוֹטָה וּמִתְפַּשֶּׁטֶת הַמְּנוֹרָה שֶׁל הַנִּיצוֹץ הֶחָזָק, מִצְטָרְפוֹת הָאוֹתִיּוֹת בְּתוֹכָהּ, וְנִכְנָסוֹת אוֹתִיּוֹת וְיוֹצְאוֹת אוֹתִיּוֹת בְּסוֹד תֵּשַׁע הָאוֹתִיּוֹת הַלָּלוּ. וְאֵלּוּ נִמְסְרוּ לִקְדוֹשִׁים עֶלְיוֹנִים לָלֶכֶת בַּדֶּרֶךְ שֶׁל סוֹד הָאוֹתִיּוֹת, לְצָרֵף יִחוּד שֶׁל שְׁמוֹת הָאוֹתִיּוֹת כְּמוֹ שֶׁהָיָה יוֹדֵעַ הַכֹּהֵן לְצָרֵף שֵׁמוֹת בְּאוֹתִיּוֹת רְשׁוּמוֹת.</p>\n<p>וִידֵי אָדָם מִתַּחַת כַּנְפֵיהֶם (יחזקאל א). כֻּלָּן יְדֵי אָדָם. הֲרֵי בֵּאַרְנוּ, שֶׁאוֹתָם (שרפים) רוּחוֹת וְחַיּוֹת וְאוֹפַנִּים, (כרובים וחיות ואופגים) כֻּלָּם עִם כְּנָפַיִם, וְיָדַיִם תַּחַת הַכְּנָפַיִם שֶׁלָּהֶם לְקַבֵּל תְּפִלּוֹת וּלְקַבֵּל בַּעֲלֵי תְשׁוּבָה. יְדֵי אָדָם, אֲתָרִים וּמְקוֹמוֹת לְקַבֵּל בְּנֵי אָדָם בִּתְפִלּוֹתֵיהֶם וּבַקָּשׁוֹתֵיהֶם, וְלִפְתֹּחַ פְּתָחִים לְקַבֵּל אוֹתָם, לְיַחֵד וְלִקְשֹׁר קְשָׁרִים וְלַעֲשׂוֹת רְצוֹנָם.</p>\n<p>וְהָאֲתָרִים וְהַמְּקוֹמוֹת הַלָּלוּ שֶׁנִּקְרָאִים יְדֵי אָדָם, שֶׁעוֹמְדִים לִבְנֵי אָדָם, אֵלּוּ הֵם שֵׁמוֹת קְדוֹשִׁים שֶׁשּׁוֹלְטִים בְּכָל דַּרְגָּה וְדַרְגָּה, (משום) שֶׁבָּהֶם נִכְנָסִים בְּנֵי אָדָם בִּתְפִלּוֹתֵיהֶם וּבְבַקָּשׁוֹתֵיהֶם בְּכָל הַשְּׁעָרִים הָעֶלְיוֹנִים, וּבָזֶה שׁוֹלְטִים הַתַּחְתּוֹנִים לְמַעְלָה. וְסוֹד זֶה - (תהלים קיט) יָדֶיךְ עָשׂוּנִי וַיְכוֹנְנוּנִי, וְאֵלּוּ שֵׁמוֹת קְדוֹשִׁים.</p>\n<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה נְטֵה אֶת יָדְךְ עַל הַשָּׁמַיִם (שמות ט). וְכִי אֵיךְ יָכֹל לְהָרִים יָדוֹ עַל הַשָּׁמַיִם? אֶלָּא נְטֵה - הַרְכֵּן, כְּמוֹ שֶׁנֶּאֱמַר (תהלים יח) וַיֵּט שָׁמַיִם וַיֵּרַד. הַמְשָׁכָה מִלְמַעְלָה לְמַטָּה. יָדְךְ - מְקוֹמְךְ, מְקוֹם הַדַּרְגָּה שֶׁלְּךְ שֶׁאַתָּה שָׁרוּי בְּתוֹכָהּ, וְזֶה בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ. וְכָל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים בְּסוֹד הַשֵּׁמוֹת נוֹסְעִים וְעוֹמְדִים, וּבָהֶם נִכְנָסִים בְּנֵי אָדָם לַהֵיכָלוֹת הָעֶלְיוֹנִים, וְאֵין מִי שֶׁיִּמְחֶה בִידֵיהֶם. אַשְׁרֵי אוֹתָם שֶׁיּוֹדְעִים לְסַדֵּר אֶת יִחוּד רִבּוֹנָם כָּרָאוּי וְלָלֶכֶת בְּדֶרֶךְ אֱמֶת, כְּדֵי שֶׁלֹּא יִטְעוּ בְּסוֹד הָאֱמוּנָה.</p>\n<p>בֹּא וּרְאֵה, בַּהֵיכָלוֹת הַלָּלוּ יֵשׁ סוֹד עֶלְיוֹן בְּתוֹךְ הָאֱמוּנָה, וְכֻלָּם חַיּוֹת וּמֶרְכָּבוֹת, כֻּלָּם מְשֻׁנִּים זֶה מִזֶּה לְהִכָּלֵל אֵלֶּה בְּאֵלֶּה לְטוֹב לְהִתְתַּקֵּן, וְסִימָנְךְ - (אסתרב) וַיְשַׁנֶּהָ וְאֶת נַעֲרוֹתֶיהָ לְטוֹב. בְּשִׁבְעַת הַהֵיכָלוֹת הַלָּלוּ הַשְּׁלֵמוּת שֶׁלְּמַעְלָה, כְּשֶׁנִּשְׁתַּלֵּם זֶה בָּזֶה וְנִכְנָסוֹת תְּפִלּוֹת וּבַקָּשׁוֹת שֶׁל מִי שֶׁיּוֹדֵעַ לְסַדֵּר אוֹתָן, לְהַתְקִינָן לְמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר וְאֵת שֶׁבַע הַנְּעָרוֹת הָרְאֻיוֹת לָתֶת לָהּ מִבֵּית הַמֶּלֶךְ.</p>\n<p>הַהֵיכָל הָרִאשׁוֹן - (ישעיה מה) יוֹצֵר אוֹר וּבוֹרֵא חֹשֶׁךְ. הָאוֹר שֶׁל הָאֶבֶן הַטּוֹבָה סַפִּיר, שֶׁאֶבֶן טוֹבָה נוֹצֶצֶת לִשְׁנֵי צְדָדִים, כְּמוֹ שֶׁבֵּאַרְנוּ, לְיָמִין וְלִשְׂמֹאל, אוֹר וְחֹשֶׁךְ. (תהלים קד) מָה רַבּוּ מַעֲשֶׂיךְ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ, כֻּלָּם אוֹפַנִּים וְגַלְגַלִּים, מָלְאָה הָאָרֶץ קִנְיָנֶיךְ וְגוֹ'. הַמֶּלֶךְ הַמְּרוֹמָם לְבַדּוֹ מֵאָז, הַשֵּׁם הַקָּדוֹשׁ יְאַהֲדוֹנָהִ\"י, הַכְּלָל שֶׁל הַשֵּׁם הַקָּדוֹשׁ, שָׁלֵם בִּשְׁנֵי שֵׁמוֹת, וְזֶהוּ שֶׁעוֹלֶה בָּאֲוִיר וּמִתְנַשֵּׂא מִימוֹת עוֹלָם.</p>\n<p>הַהֵיכָל הַשֵּׁנִי - אֵל בָּרוּךְ גְּדוֹל דֵּעָה, אוֹרְפָנִיאֵ\"ל, (הסודשכוללאותיות קטגות) שֶׁכּוֹלֵל הַסּוֹדוֹת שֶׁל אוֹתִיּוֹת קְטַנּוֹת שֶׁל אַלְפָא בֵּיתָא. כָּאן הֵם שֶׁאוֹמְרִים קָדוֹשׁ וּבָרוּךְ. וְכָאן הִיא הַקְּדֻשָּׁה וּבָרוּךְ כְּבוֹד ה'. הַהֵיכָל הַשְּׁלִישִׁי - לָאֵל בָּרוּךְ נְעִימוֹת יִתֵּנוּ.</p>\n<p>הַהֵיכָל הָרְבִיעִי - הַמְחַדֵּשׁ בְּטוּבוֹ בְּכָל יוֹם תָּמִיד מַעֲשֵׂה בְרֵאשִׁית. מִשּׁוּם שֶׁכָּאן מִתְגַּלְגְּלִים הָאוֹרוֹת וְהַדִּינִים שֶׁל הָעוֹלָם. מִי שֶׁהוּא לְחַיִּים, מִתְקַדֵּשׁ כְּמִקֹּדֶם לְהִתְקַיֵּם בָּעוֹלָם בְּאוֹר הַיָּמִין שֶׁנִּקְרָא אֵל, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>הַהֵיכָל הַחֲמִישִׁי - הַהֵיכָל הַזֶּה נִקְרָא אַהֲבַת עוֹלָם, וְזוֹהִי מְשִׁיכָה שֶׁל אַהֲבָה שֶׁל הַהֵיכָל שֶׁנִּקְרָא אַהֲבָה, וְזוֹהִי אַהֲבַת עוֹלָם אֲהַבְתָּנוּ ה' אֱלֹהֵינוּ, בָּרוּךְ אַתָּה ה' הַבּוֹחֵר בְּעַמּוֹ יִשְׂרָאֵל בְּאַהֲבָה, בְּסוֹד שֶׁל אֵ\"ל שַׁדַּ\"י.</p>\n<p>הַהֵיכָל הַשִּׁשִּׁי - אֱמֶת וְיַצִּיב וְנָכוֹן וְקַיָּם. וּצְרִיכִים שֶׁלֹּא לְהַפְסִיק בֵּין הֵיכָלוֹת אֵלּוּ (לאלו). שֶׁהֲרֵי בְּהַמְשָׁכַת הַתְּפִלָּה וְהָרָצוֹן מִתְחַבְּרִים כְּאֶחָד, וְנִקְשָׁרִים אֵלֶּה בְּאֵלֶּה בְּסוֹד הַשֵּׁמוֹת הַקְּדוֹשִׁים שֶׁשּׁוֹלְטִים בְּכָל אֶחָד וְאֶחָד.</p>\n<p>הַהֵיכָל הַשְּׁבִיעִי - אֲדנָי שְׂפָתַי תִּפְתָּח. סוֹד הַסּוֹדוֹת בְּלַחַשׁ, שֶׁלֹּא נִשְׁמָע הַקּוֹל. כָּאן הוּא רְצוֹן הַלֵּב, לְהִתְכַּוֵּן וּלְהַעֲלוֹת רָצוֹן מִמַּטָּה לְמַעְלָה עַד אֵין סוֹף, וְלִקְשֹׁר שְׁבִיעִי בִּשְׁבִיעִי (וכל אחד באחד) זֶה בָּזֶה (ממטה למעלה), וְאַחַ ר כָּךְ מִמַּעְלָה לְמַטָּה, לִמְשֹׁךְ בְּרָכוֹת לְכָל הָעוֹלָמוֹת מִמְּקוֹר הַחַיִּים, (שהוא שביעי למעלה) שֶׁהוּא הַהֵיכָל הַשְּׁבִיעִי הָעֶלְיוֹן (וזוהשכינה) בִּרְצוֹן הַלֵּב וּבִסְתִימַת הָעֵינַיִם שֶׁל סוֹד הָאוֹתִיּוֹת שֶׁל שִׁבְעָה שֵׁמוֹת עֶלְיוֹנִים קְדוֹשִׁים.</p>\n<p>הַהֵיכָל הַשְּׁבִיעִי הָעֶלְיוֹן הַזֶּה, שֶׁהוּא מְקוֹר הַחַיִּים, זוֹהִי הַבְּרָכָה הָרִאשׁוֹנָה, וְזֶהוּ הַהֵיכָל הָרִאשׁוֹן, רֵאשִׁית הַכֹּל מִמַּעְלָה לְמַטָּה, וְלִטֹּל הַשְּׁבִיעִי מִלְּמַטָּה לְחַבֵּר זֶה בָּזֶה, שְׁבִיעִי בִּשְׁבִיעִי. שֶׁהֲרֵי מִזֶּה שֶׁלְּמַטָּה נִכְנָס מִי שֶׁנִּכְנָס לַהֵיכָל הָעֶלְיוֹן.</p>\n<p>וְזְהִוּ סוֹד בָּרוּךְ - רִבּוּי שֶׁל כָּל הַתַּחְתּוֹנִים, כָּלוּל בְּחַיּוֹת וּשְׂרָפִים וְאוֹפַנִּים, וְכָל הַהֵיכָלוֹת רִבּוּי שֶׁל סוֹד קֹדֶשׁ הַקְּדָשִׁים שֶׁשּׁוֹרֶה בְתוֹכוֹ בִּגְנִיזָה, וְאָז נִקְרָא בָּרוּ\"ךְ בְּכָל הָרִבּוּיִים הַלָּלוּ וְהַבְּרָכוֹת וְהַסּוֹדוֹת שֶׁנִּשְׁלְמוּ בוֹ.</p>\n<p>אַתָּ\"ה - הָעִטּוּר שֶׁל סֵתֶר הָאוֹתִיּוֹת, הַכְּלָל שֶׁל כָּל כ\"ב הָאוֹתִיּוֹת. וְזֶהוּ אָ\"ת. ה' שֶׁכּוֹלֵל אוֹתָם מִלְמַעְלָה בַּה' הַ את, וְכוֹנֵס אוֹתָם לְתוֹכוֹ, וְזוֹהִי אָ\"ת ה'. וּכְשֶׁהִיא בִּשְׁלֵמוּת בְּאוֹתוֹ נָהָר שֶׁאוֹחֵז בָּהּ, הִיא עוֹלָה לְהִתְעַטֵּר לְמַעְלָה, וְזֶהוּ סוֹד הַכָּתוּב (אסתר ב) וּבָזֶה הַנַּעֲרָה בָּאָה אֶל הַמֶּלֶךְ, וְאָז - אֵת כָּל אֲשֶׁר תֹּאמַר יִנָּתֶן לָהּ. וְזֶהוּ סוֹד בָּרוּךְ אַתָּה, וְצָרִיךְ לְהִתְכַּוֵּן בַּסּוֹד הַזֶּה וְלִקְשֹׁר אֶת הָרָצוֹן בַּסּוֹד הַזֶּה.</p>\n<p>יְיָ אֱלֹהֵינוּ - זֶהוּ קֶשֶׁר וְיִחוּד שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן לְמַעְלָה. בָּזֶה, כְּשֶׁהַנַּעֲרָה בָּאָה אֶל הַמֶּלֶךְ, אֵת כָּל אֲשֶׁר תֹּאמַר יִנָּתֶן לָהּ.</p>\n<p>וֵאלֹהֵי אֲבוֹתֵינוּ - זֶהוּ סוֹד הָאָבוֹת לְבָרֵךְ אוֹתָהּ. וְזֶהוּ סוֹד אֱלֹהֵי אַבְרָהָם אֱלֹהֵי יִצְחָק וֵאלֹהֵי יַעֲקֹב. כְּמוֹ שֶׁהַנַּעֲרָה הַזּוֹ לֹא נֶעֱזֶבֶת מֵהַתַּחְתּוֹנִים, כָּךְ גַּם לֹא נֶעֱזֶבֶת מֵהָאָבוֹת לְעוֹלָמִים. הִיא אֲחוּזָה בָהֶם (לשמר אותם ולעטר אותה) לְעַטֵּר אוֹתָהּ.</p>\n<p>וּמִשּׁוּם שֶׁהִתְבָּרְכָה מִכָּל אֶחָד מֵהֶם, צָרִיךְ לְהַזְכִּירָהּ עַל כָּל אֶחָד וְאֶחָד. וְאַחַר כָּךְ יִתְכַּנְּסוּ כֻלָּם בְּחִבּוּר אֶחָד (לתוך מעי אמא) וּמִתְעַטְּרִים עִמָּהּ. הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא - הֲרֵי כֻּלָּם כְּאֶחָד לַעֲלוֹת לְמַעְלָה בָּרִאשׁוֹנָה מִמַּעְלָה לְמַטָּה, וְעַכְשָׁו מִמַּטָּה לְמַעְלָה, לְהַכְלִיל אוֹתָם עִמָּהּ. שֶׁכֵּיוָן שֶׁאָמַר הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא, כֻּלָּם כְּלוּלִים בָּהּ. וְאָז - אֵל עֶלְיוֹן גּוֹמֵל חֲסָדִים טוֹבִים קוֹנֵה הַכֹּל. וְזֶהוּ כְּלַל הַכֹּל.</p>\n<p>וְזוֹכֵר חַסְדֵי אָבוֹת - שֶׁהִשְׁתַּהוּ עִמָּהּ (שגמצאו כאחד) וְנִכְנְסוּ לְמֵעֶיהָ וְהִתְבָּרְכוּ שָׁם. וְאַחַר כָּךְ שׁוֹרֶה אוֹתָם וּמוֹצִיא אוֹתָם כְּשֶׁהֵם מִתְבָּרְכִים מִתּוֹכָהּ. וּבְאוֹתָהּ הִשְׁתַּחֲוָיָה שֶׁאוֹמֵר בָּרוּךְ אַתָּה ה' מָגֵן אַבְרָהָם, כָּאן יוֹצְאִים כֻּלָּם בִּכְלָל, שֶׁהֲרֵי בַּיָּמִין כֻּלָּם מִתְבָּרְכִים כָּרָאוּי.</p>\n<p>בֹּא וּרְאֵה, הַהֵיכָל הַשְּׁבִיעִי הַזֶּה סוֹד הַמֶּלֶךְ הָעֶלְיוֹן, וּמִתְעַטְּרִים בּוֹ הָאָבוֹת, כְּמוֹ שֶׁאָמַרְנוּ, וְנִכְלְלוּ בוֹ. וְעַד עַכְשָׁו נִכְלְלוּ, וְצָרִיךְ לְהוֹצִיא אוֹתָם הוּא הַהֵיכָל הַזֶּה, וּכְשֶׁמּוֹצִיא אוֹתָם מְבֹרָכִים (מתברכים) מִשּׁוּם הַנַּעֲרָה הַזּוֹ, אָז הִיא אוֹחֶזֶת בָּהֶם בְּכָל אוֹתָן הַבְּרָכוֹת. וְאַף עַל גַּב שֶׁהֲרֵי נִכְלְלוּ הֵיכָלוֹת בְּהֵיכָלוֹת, עַכְשָׁו נֶאֶחְזוּ בְּאוֹתָן בְּרָכוֹת כְּאֶחָד, וּכְשֶׁאוֹמֵר מֶלֶךְ עוֹזֵר וּמוֹשִׁיעַ וּמָגֵן, אָז מוֹצִיאָה אוֹתָם מְבֹרָכִים.</p>\n<p>וְזְהִוּ הֵיכָל אֶחָד הַשְּׁבִיעִי בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן בּוּכ\"וּ, 'בְּרָכָה 'וָחֶסֶד 'כֹּחַ 'וּמִשְׁפָּט, הַכְּלָל הַסּוֹד (של סוד), וְהַסּוֹד הַזֶּה הוּא הַסּוֹד (שהיא) שֶׁל אֶהְיֶ\"ה, הַכְּלָל שֶׁל הַכֹּל. מִשּׁוּם שֶׁהָאוֹתִיּוֹת הַלָּלוּ הֵן כְּלָל שֶׁל הַכֹּל, מִשּׁוּם שֶׁהָאוֹתִיּוֹת הַלָּלוּ הוֹצִיאוּ אֶת אֵלֶּה (אותם) שֶׁיָּצְאוּ מֵהֶן, הַכְּלָל שֶׁל הָאָבוֹת, וְזוֹהִי שֶׁמִּתְחַבֶּרֶת עִמָּן, שֶׁנִּקְרֵאת בְּרָכָה.</p>\n<p>כֵּיוָן שֶׁאָמַר בָּרוּךְ אַתָּה ה' מָגֵן אַבְרָהָם, הֲרֵי הִיא אוֹחֶזֶת בְּרָכוֹת מֵהֶם בְּסוֹד הַהֵיכָל הַחֲמִישִׁי אַהֲבָה, שֶׁהוּא יָמִין, וְהוּא חֲמִישִׁי, לְהִתְקַשֵּׁר בָּאַהֲבָה שֶׁל הַבְּרָכוֹת שֶׁל הַיָּמִין. וְכָךְ צָרִיךְ, מִמַּעְלָה לְמַטָּה לְהִתְבָּרֵךְ. בָּרִאשׁוֹנָה נִכְלְלוּ הֵיכָל בְּהֵיכָל כְּפִי שֶׁאָמַרְנוּ, וְעַכְשָׁו נוֹטְלִים בְּרָכוֹת שֶׁיִּמָּצְאוּ אֵלֶּה לִפְנֵי אֵלֶּה. וְאַף עַל גַּב שֶׁיֵּשׁ מִי שֶׁנּוֹטֵל (שגטל) בָּרִאשׁוֹנָה, כֵּיוָן שֶׁנִּמְצְאוּ מִצַּד הַיָּמִין בְּרָכוֹת, בַּהֵיכָל הַחֲמִישִׁי מַתְחִיל לְהֵאָחֵז.</p>\n<p>וְאַחַר כָּךְ בְּצַד הַשְּׂמֹאל, בְּסוֹד זֶה אַתָּה גִבּוֹר. וְזֶהוּ חִבּוּר שֶׁל אַתָּה וְגִבּוֹר, שְׁנֵי דִינִים. וְכֵיוָן שֶׁנִּמְשָׁכוֹת הַבְּרָכוֹת, נִכְלָל בְּרַחֲמִים, וְנִמְצָא בְּאוֹתוֹ הַצַּד הַכֹּל כְּאֶחָד, וְזֶהוּ מְחַיֵּה מֵתִים, סוֹמֵךְ נוֹפְלִים וְרוֹפֵא חוֹלִים וְכוּ'.</p>\n<p>וְזְהִוּ בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ שֶׁנִּקְרָא אֲכַדְטַ\"ם, סוֹד הוּא בְּאוֹתִיּוֹת הַשֵּׁם שֶׁנִּקְרָא אֱלֹהִי\"ם. מִשּׁוּם שֶׁהָאוֹתִיּוֹת הַלָּלוּ עוֹלוֹת לְהִתְעַטֵּר לְמַעְלָה, וּמוֹצִיאוֹת אוֹתָן אֵלּוּ לְהִקָּרֵא בָהֶם, וְעוֹלוֹת לְהִתְעַטֵּר לְמַעְלָה אֱלֹהִים חַיִּים, וְגוֹרֵעַ בָּאוֹתִיּוֹת. לְאַחֵד בִּגְרִיעוּת. וּמִכָּאן לְהִתְפַּשֵּׁט לְמַטָּה, לִטֹּל מִתּוֹךְ הָאוֹתִיּוֹת הָאֲחֵרוֹת הָאֵלּוּ וְלַעֲלוֹת מֵהָאוֹתִיּוֹת הַלָּלוּ לַשֵּׁם שֶׁל אֱלֹהִים.</p>\n<p>כֵּיוָן שֶׁנִּמְשָׁכוֹת הָאוֹתִיּוֹת בַּחֲמִישִׁי וּבָרְבִיעִי מִמַּעְלָה כְּפִי שֶׁאָמַרְנוּ, מַתְחִיל וְאוֹחֵז בְּרָכוֹת מֵהָאֶמְצַע שֶׁל הַכֹּל, מֵהַהֵיכָל הַשִּׁשִּׁי, וְאוֹחֵז בְּרָכוֹת בָּזֶה וּבַבָּא. וּמִשּׁוּם כָּךְ (בכל אתה קדוש, ונכלל) אַתָּה קָדוֹשׁ, נִכְלָל אַתָּה בְּקָדוֹשׁ.</p>\n<p>וְשִׁמְךָ קָדוֹשׁ. כֵּיוָן שֶׁאָמַר אַתָּה קָדוֹשׁ, לָמָּה וְשִׁמְךְ קָדוֹשׁ? הַיְנוּ שֵׁם, הַיְנוּ אַתָּה. אֶלָּא הֲרֵי שָׁנִינוּ, בְּכָל מָקוֹם שֶׁנִּמְצָא יִחוּד וְקִשּׁוּר, צְרִיכִים קְדֻשָּׁה וְתוֹסֶפֶת קְדֻשָּׁה, וְאוֹתָהּ הַתּוֹסֶפֶת הָעִקָּר הִיא יוֹתֵר מֵהַכֹּל, וּמִשּׁוּם כָּךְ בְּכֻלָּם כָּתוּב אַתָּה, וְלֹא יוֹתֵר, וְכָאן בַּמָּקוֹם הַזֶּה אוֹמֵר קְדֻשָּׁה וְתוֹסֶפֶת קְדֻשָּׁה. אַתָּה קָדוֹשׁ - קְדֻשָּׁה. וְשִׁמְךְ קָדוֹשׁ - תּוֹסֶפֶת קְדֻשָּׁה. וּקְדוֹשִׁים בְּכָל יוֹם - אֵלּוּ שְׁאָר הַקְּדוֹשִׁים הָעֶלְיוֹנִים שֶׁבְּכָל הֵיכָל וְהֵיכָל שֶׁמִּתְקַדְּשִׁים מֵהַתּוֹסֶפֶת הַזּוֹ. מִשּׁוּם שֶׁקְּדֻשָּׁה הָרִאשׁוֹנָה הִיא לָהּ, וְתוֹסֶפֶת קְדֻשָּׁה - לְקַדֵּשׁ כָּל אֵלּוּ הַשְּׁאָר שֶׁאָמַרְנוּ.</p>\n<p>וְאַחַר כָּךְ הַכֹּל מִתְקַדֵּשׁ מִלְמַעְלָה, וּמִכָּל הָאָבוֹת, נִקְשָׁר בְּקֶשֶׁר אֶחָד, וְהַיְנוּ בָּרוּךְ אַתָּה ה' הָאֵל הַקָדוֹשׁ. כָּאן הַכֹּל קֶשֶׁר אֶחָד, מִשּׁוּם שֶׁאוֹמֵר בָּרוּךְ אַתָּה ה' הָאֵל הַקָּדוֹשׁ. וְעַל כֵּן נִקְרָא צְרוֹר וְקֶשֶׁר שֶׁל הַכֹּל בְּיִחוּד אֶחָד. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיּוֹדֵעַ לְסַדֵּר אֶת שִׁבְחוֹ שֶׁל רִבּוֹנוֹ בַּמָּקוֹם שֶׁצָּרִיךְ. עַד כָּאן הַדְּבֵקוּת וּבְרָכוֹת וּקְדֻשָּׁה כְּאֶחָד בָּאָבוֹת.</p>\n<p>מִכָּאן וָהָלְאָה עוֹמְדוֹת שְׁאֵלוֹת וּבַקָּשׁוֹת. הָרֵאשִׁית שֶׁצָּרִיךְ אָדָם לִשְׁאֹל, לָדַעַת בְּדִבְרֵי רִבּוֹנוֹ, כְּדֵי לְהַרְאוֹת תְּשׁוּקָתוֹ אֵלָיו וְלֹא נִפְרָד מִמֶּנּוּ. מִשּׁוּם שֶׁצָּרִיךְ אָדָם לְהִשְׁתַּתֵּף בִּקְדֻשַּׁת הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן לְהִתְעַטֵּר בּוֹ, וְהוּא הַשֵּׁם שֶׁל הַבְּרָכוֹת וְהַקִּדּוּשִׁים, כּוּז\"וּ. סוֹד הַשֵּׁם הַקָּדוֹשׁ יְהֹוָה שֶׁהוּא קָדוֹשׁ בִּקְדֻשָּׁה. וְהָאוֹתִיּוֹת הַלָּלוּ (האחרות) הוֹצִיאוּ מִמֶּנּוּ אֶת הָאוֹתִיּוֹת הָאֲחֵרוֹת הַלָּלוּ, הַחִבּוּר שֶׁל אֵלּוּ, כְּמוֹ חִבּוּר שֶׁל זָכָר בִּנְקֵבָה. וְהַקְּדוֹשִׁים הָעֶלְיוֹנִים הַלָּלוּ סוֹד הַקְּדֻשָּׁה.</p>\n<p>הָאוֹתִיּוֹת הָאֲחֵרוֹת הַלָּלוּ נִקְרָאוֹת טַ\"ל. טַל הַשָּׁמַיִם. סוֹד הַחֶשְׁבּוֹן שֶׁל הָאוֹתִיּוֹת שֶׁלּוֹ, מִשּׁוּם שֶׁכָּאן לְמַטָּה עוֹמְדִים כָּל הַדְּבָרִים בְּחֶשְׁבּוֹן, וְלֹא חֶשְׁבּוֹן, אֶלָּא לַלְּבָנָה. וּמִשּׁוּם כָּךְ צָרִיךְ לְהִתְקַשֵּׁר בִּקְדֻשַּׁת רִבּוֹנוֹ, וְלֹא יִפָּרֵד אָדָם מִמֶּנּוּ. וּכְשֶׁשּׁוֹאֵל, רֵאשִׁית הַשְּׁאֵלוֹת לְהַכִּיר אֶת רִבּוֹנוֹ, לְהַרְאוֹת שֶׁתְּשׁוּקָתוֹ אֵלָיו. מִכָּאן וָהָלְאָה יִפָּרֵד מְעַט מְעַט, וְיִשְׁאַל שְׁאֵלָתוֹ מַה שֶּׁצָּרִיךְ לִשְׁאֹל.</p>\n<p>וְכָל שְׁאֵלוֹתָיו יִהְיוּ אַחַר שֶׁיְּסַדֵּר אֶת הַסִּדּוּר הַזֶּה שֶׁאָמַרְנוּ. כְּמוֹ כֵן כָּל שְׁאֵלוֹתָיו יִהְיוּ בְתַחֲנוּנִים וּבַקָּשׁוֹת לִפְנֵי רִבּוֹנוֹ, וְלֹא יַצְדִּיק (ירחיק) עַצְמוֹ מִמֶּנּוּ. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיּוֹדֵעַ לְסַדֵּר סִדּוּר זֶה, לָלֶכֶת בְּדֶרֶךְ יְשָׁרָה כָּרָאוּי.</p>\n<p>כְּמוֹ שֶׁהָאֵשׁ נֶאֱחֶזֶת בְּמַיִם, וּמַיִם בְּאֵשׁ. דָּרוֹם בְּצָפוֹן, וְצָפוֹן בְּדָרוֹם. מִזְרָח בְּמַעֲרָב, וּמַעֲרָב בְּמִזְרָח. כָּךְ גַּם מִתְקַשֵּׁר הַכֹּל כְּאֶחָד, וְהַיִּחוּד נִשְׁלָם זֶה עִם זֶה.</p>\n<p>וְכָל אוֹתָם שֶׁיּוֹדְעִים לְסַדֵּר תְּפִלָּתָם כָּרָאוּי, לִכְלֹל אֶת הַהֵיכָלוֹת אֵלּוּ בְאֵלּוּ וְלִקְשֹׁר זֶה בָּזֶה, הָאָדָם הַזֶּה נִקְשָׁר בָּהֶם וּמְקָרְבוֹ לְהִכָּלֵל בָּהֶם. שְׁאֵלָה הוּא שׁוֹאֵל, וְנוֹתְנִים לוֹ. אַשְׁרֵי חֶלְקוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>אַחַר שֶׁסִּיֵּם הַבַּקָּשׁוֹת וְהַגּוּף שָׁלֵם בְּכָל הַצְּדָדִים בְּשִׂמְחַת הַלֵּב וְהוּא שָׁאַל וְסִיֵּם אֶת הַבַּקָּשׁוֹת, יַחֲזֹר לְהַמְשִׁיךְ לְמַטָּה בְּרָכוֹת וּשְׂמָחוֹת בְּסוֹד הַהֵיכָל הַשְּׁלִישִׁי, לְהַמְשִׁיךְ לְמַטָּה, וְזֶה הוּא רְצֵה ה' אֱלֹהֵינוּ בְּעַמְּ\"ךְ יִשְׂרָאֵ\"ל. זֶהוּ (משום) שֶׁמַּעֲמָדוֹת הֵם הַתּוֹמְכִים שֶׁל הַגּוּף. הָרֵאשִׁית לְמַטָּה מִן הַגּוּף שְׁתֵּי יְרֵכַיִם, עַד שֶׁמַּגִּיעִים לַבִּרְכַּיִם.</p>\n<p>וְאֵלּוּ הֵם סוֹד הַמַּעֲמָדוֹת שֶׁעוֹמְדִים עַל הַקָּרְבָּן. וְכָאן הוּא סוֹד שֶׁל רֵאשִׁיתָם שֶׁל שְׁתֵּי הַיְרֵכַיִם מִלְמַעְלָה עַד לַבִּרְכַּיִם, חִבּוּר הַנְּבִיאִים. וְהַמַּרְאוֹת בְּסוֹד הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁנִּקְרָא (צבאו\"ת בא\"ת ב\"ש) הַשְׁתָּפָ\"א. שֶׁהוּא סוֹד הַשֵּׁם שֶׁנִּקְרָא צְבָאוֹת. זֶה עוֹלֶה וְזֶה יוֹרֵד. זֶה נְבִיאִים וְזֶה מַרְאוֹת.</p>\n<p>וְכָאן הוּא סוֹד עֶלְיוֹן שֶׁל הַבָּרַיְתוֹת שֶׁאָמַרְנוּ, וּכְשֶׁמַּגִּיעַ אָדָם לַבִּרְכַּיִם, יִכְרַע בָּרוּךְ אַתָּה ה' הַמַּחֲזִיר שְׁכִינָתוֹ לְצִיּוֹן, וַהֲרֵי כָּאן חָזְרוּ הַבָּרַיְתוֹת לַמִּשְׁנָה וְהִתְבָּרְכוּ כְּאֶחָד.</p>\n<p>בַּהֵיכָל הַשֵּׁנִי לְמַטָּה, שֶׁנִּפְקְדוּ בוֹ הַנְּשָׁמוֹת לַעֲלוֹת, לְהֵרָאוֹת בְּמַרְאֵה הַחֲלוֹם. מוֹדִים - לִכְרֹעַ בִּרְכַּיִם, לְהוֹדוֹת עַל הַנְּשָׁמוֹת, כְּמוֹ שֶׁאוֹמְרִים עַל נִשְׁמוֹתֵינוּ הַפְּקוּדוֹת, (כיוןשגשאלמאדונו) (ס\"אהיכל שני להמשיך ברכות למטה מודים אנחנו לך, והיכל זה הוא שגפקדות בו הגשמות לעלות להראותבמראה החלום. כאן צריךבן אדםלכרע בברכיו להודות על הגשמות, וזהו על נשמותינו הפקודות) עַד שֶׁמַּגִּיעַ לְהַטּוֹב שִׁמְךְ וּלְךְ נָאֶה לְהוֹדוֹת.</p>\n<p>וְזְהִוּ תּוֹךְ סוֹד הַשֵּׁם הַקָּדוֹשׁ שֶׁנִּקְרָא בָּ\"ם בְּמוּכָ\"ן. זֶה נִקְרָא אֵל אֱלֹהִים, שֶׁהוּא בְּסוֹד עֶלְיוֹן. (יהושע כב) אֵל אֱלֹהִי\"ם יְהֹוָ\"ה הוּא יֹדֵעַ. הַכְּלָל שֶׁל הָאוֹתִיּוֹת הָאֲחֵרוֹת הַלָּלוּ שֶׁיּוֹצְאוֹת מֵהֶם, (וכאן הוא סוד אחד שכל הירכים מברכות) וּלְמַטָּה סוֹד הַחֲלוֹם. הַסּוֹד לְאוֹתוֹ מָקוֹם לְהַכְנִיס בָּהֶם נְשָׁמוֹת. וּצְרִיכִים לְהַמְשִׁיךְ בַּבְּרָכוֹת הַלָּלוּ כְּדֵי לִמְצֹא מְנוּחָה בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>הַהֵיכָל הַתַּחְתּוֹן לְמַטָּה - שִׂים שָׁלוֹם טוֹבָה וּבְרָכָה. כָּאן הוּא כְּלַל הַשָּׁלוֹם. שָׁלוֹם לְמַעְלָה, שָׁלוֹם לְמַטָּה, שָׁלוֹם לְכָל הַצְּדָדִים, שָׁלוֹם בְּפָמַלְיָא שֶׁל מַעְלָה, שָׁלוֹם בְּפָמַלְיָא שֶׁל מַטָּה, וְהַהֵיכָל הַזֶּה הוּא פָּמַלְיָא שֶׁל מַטָּה. (שהוא היכל שלמטה, וזה בחבור וכו') בְּחִבּוּר אֶחָד בְּפָמַלְיָא (בהיכל) שֶׁל מַעְלָה. וּמִכָּאן שׁוֹפֵעַ לְכָל אוֹתָם הַתַּחְתּוֹנִים שֶׁבַּחוּץ.</p>\n<p>וְכָאן נִכְלָל וְנִרְשָׁם הַכֹּל כְּאֶחָד, מַעְלָה וּמַטָּה, בְּאוֹר אֶחָד, לְהִשְׁתַּלֵּם שֵׁם מָלֵא, ה' אֱלֹהִים. הַשֵּׁם הַזֶּה שֶׁהוּא שָׁלֵם בְּכָל אוֹתָם הַהֵיכָלוֹת, בְּכָל אוֹתָם הָאוֹרוֹת הָעֶלְיוֹנִים שֶׁיִּהְיוּ כֻלָּם אֶחָד. (שים שלום טובה וברכה)</p>\n<p>הָאָדָם הַזֶּה, כְּשֶׁנִּשְׁאָל מֵהַהֵיכָל הַזֶּה לָצֵאת הַחוּצָה, יָשִׂים עַצְמוֹ כְּמִי שֶׁיּוֹצֵא מֵחֶבְרַת הַמֶּלֶךְ וּמִתּוֹךְ הֵיכָלוֹ, וְיַנְמִיךְ אֶת עַצְמוֹ לְפָנָיו. אֲבָל יְשַׂמַּח אֶת עַצְמוֹ, שֶׁהֲרֵי הוּא רִאשׁוֹן לִטֹּל עֲטָרָה שֶׁל מְשִׁיכַת הַבְּרָכוֹת שֶׁשּׁוֹפְעוֹת מִיִּחוּד שֶׁל רִבּוֹנוֹ. זֶהוּ הַבֵּן שֶׁהוּא מֵהֵיכַל הַמֶּלֶךְ, שֶׁהֲרֵי בַּשָּׁעָה הַזֹּאת שֶׁיּוֹצֵא מִלִּפְנֵי הַמֶּלֶךְ, וְהַכֹּל קָשׁוּר בְּכָל הַצְּדָדִים הַלָּלוּ בְּקֶשֶׁר שֶׁל יִחוּד וּבְרָכוֹת וּקְדֻשָּׁה וְתוֹסֶפֶת קְדֻשָּׁה. כִּתְבוּ עַל אָדָם פְּלוֹנִי הַזֶּה, מֵאוֹתָם שֶׁנִּקְרָאִים חוֹשְׁבֵי שְׁמוֹ.</p>\n<p>מִי הֵם חוֹשְׁבֵי שְׁמוֹ? אוֹתָם שֶׁחוֹשְׁבִים וּמְכַוְּנִים בַּסּוֹד שֶׁל שְׁמוֹ, לְיַחֵד הֵיכָלוֹת בְּהֵיכָלוֹת, לִקְשֹׁר קְשָׁרִים וּלְיַחֵד אֶת כֻּלָּם בְּיִחוּד אֶחָד. וְאֵלּוּ הֵם חוֹשְׁבֵי שְׁמוֹ, כְּמוֹ שֶׁנֶּאֱמַר (מלאכי ג) וּלְחֹשְׁבֵי שְׁמוֹ. אָז כּוֹתְבִים אוֹתוֹ, וְנִרְשָׁם וְנוֹדָע לְמַעְלָה, וְהוּא (נרשם) נִשְׁלָם לְמַעְלָה וּלְמַטָּה.</p>\n<p>וּמִי שֶׁקָּרֵב לִפְנֵי רִבּוֹנוֹ וּמִתְפַּלֵּל תְּפִלָּתוֹ, וְלֹא הִשְׁלִים אֶת הַיִּחוּד, וְלֹא חוֹשֵׁשׁ לִכְבוֹד רִבּוֹנוֹ לִקְשֹׁר קְשָׁרִים כְּמוֹ שֶׁאָמַרְנוּ, טוֹב לוֹ שֶׁלֹּא נִבְרָא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר: (ירמיה כב) כִּתְבוּ אֶת הָאִישׁ הַזֶּה עֲרִירִי גֶּבֶר לֹא יִצְלַח בְּיָמָיו. וְזֶהוּ (משלי כח) גּוֹזֵל אָבִיו וְאִמּוֹ.</p>\n<p>כָּאן נִשְׁלָם הַכֹּל, לְמַעְלָה וּלְמַטָּה, סוֹד הַשֵּׁם הַקָּדוֹשׁ שׁוֹלֵט לְמַעְלָה, מצפ\"ץ מצפ\"ץ. (שמותלד) ה' ה' אֵל רַחוּם וְחַנּוּן. כָּאן הוּא סוֹד הַשֵּׁם הַקָּדוֹשׁ הַזֶּה לְהִתְקַדֵּשׁ בְּאוֹתִיּוֹתָיו בְּבֵית עֲשָׂרָה, וְאוֹתִיּוֹת אֲחֵרוֹת בִּקְדֻשַּׁת הַיְחִידִי בַּתְּפִלָּה. אַחַר שֶׁסִּיֵּם, עוֹמֵד עַל רַגְלָיו (לכפר) לְהוֹדוֹת עַל חֲטָאָיו, כְּדֵי שֶׁלֹּא יִהְיֶה פִּתְחוֹן פֶּה לַצַּד הָאַחֵר לְהַסְטִין עָלָיו, וְנִכְנָע לְפָנָיו. וְיַעֲמֹד בְּקִיּוּמוֹ לְהִתְבָּרֵךְ מִבֵּית הַמֶּלֶךְ.</p>\n<p>וְאַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁהִתְקַדֵּשׁ בִּכְגוֹן זֶה בַּתְּפִלָּה כְּמוֹ שֶׁאָמַרְנוּ, וְקוֹשֵׁר קְשָׁרִים, וּמְיַחֵד יִחוּדִים, וּמִתְכַּוֵּן בַּכֹּל כָּרָאוּי, וְלֹא יִסְטֶה יָמִינָה וּשְׂמֹאלָה. תְּפִלָּתוֹ אֵינָהּ חוֹזֶרֶת רֵיקָם. הַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹזֵר - וְהוּא מְבַטֵּל. עַל זֶה כָּתוּב, (משלי כג) יִשְׂמַח אָבִיךְ וְאִמֶּךְ וְתָגֵל יוֹלַדְתֶּךְ. יֵשׁ לוֹ חֵלֶק בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. (אסתר ב) בערב היא באה, הינו</p>\n<p>כָּתוּב, (משלי לא) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְגוֹ', מֵאוֹתוֹ רִבּוּי שֶׁל בְּרָכוֹת וּקְדֻשָּׁה וְתוֹסֶפֶת קְדֻשָּׁה שֶׁנּוֹטֵל, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מט) וְלָעֶרֶב יְחַלֵּק שָׁלָל, שֶׁמְּחַלֶּקֶת חֵלֶק לְכֻלָּם, וַאֲפִלּוּ לַצַּד הָאַחֵר חֵלֶק לְבַדּוֹ.</p>\n<p>וְסוֹד זֶה סוֹד לִבְנֵי הָאֱמוּנָה. הַחֵלֶק שֶׁל הַצַּד הָאַחֵר כָּל אוֹתָן עֲבֵרוֹת וְכָל אוֹתָם חֲטָאִים שֶׁל אוֹתוֹ אָדָם שֶׁקָּשַׁר אֶת קֶשֶׁר הַיִּחוּד, שֶׁהִתְוַדָּה עֲלֵיהֶם, כֻּלָּם שׁוֹרִים עַל הַצַּד הָאַחֵר, וְהֵם חֵלֶק וְנַחֲלָה שֶׁל הַצַּד הָאַחֵר הַטָּמֵא. וְאִם לֹא מוֹדֶה עֲלֵיהֶם, נִמְצָא מְקַטְרֵג וְיָכוֹל לוֹ.</p>\n<p>וְאִם מוֹדֶה עַל כָּל חֲטָאָיו בְּאוֹתָהּ תְּפִלָּה, שֶׁקּוֹשֵׁר קִשְׁרֵי הַיִּחוּד וְהִתְבָּרְכוּ עֶלְיוֹנִים וְתַחְתּוֹנִים. וּמֵאוֹתוֹ הַחֵלֶק שֶׁל הַצַּד הָאַחֵר, כָּל אוֹתָם עֲבֵרוֹת וַחֲטָאִים שֶׁהוֹדָה עֲלֵיהֶם, נוֹטֵל אוֹתָם לְחֶלְקוֹ. וְסוֹד זֶה הַשָּׂעִיר, שֶׁכָּתוּב (ויקרא טז) וְהִתְוַדָּה עָלָיו אֶת כָּל עֲונוֹת וְגוֹ', וְכָתוּב וְנָשָׂא הַשָּׂעִיר וְגוֹ'. זֶהוּ חֶלְקוֹ וְגוֹרָלוֹ וְנַחֲלָתוֹ. וְאִם אוֹתוֹ אָדָם שָׁב לְסִרְחוֹן חֲטָאָיו - אוֹי לוֹ! שֶׁאֶת כֻּלָּם נוֹטֵל מֵאוֹתוֹ הַצַּד הָאַחֵר בְּעַל כָּרְחוֹ שֶׁל אוֹתוֹ הַצַּד. וּמִתּוֹךְ שֶׁנּוֹטֵל אוֹתָם מֵהַצַּד הַזֶּה בְּעַל כָּרְחוֹ שֶׁל אוֹתוֹ הַצַּד, אָז הוּא מֵרֵעַ לוֹ, וְהוֹפֵךְ אֵלָיו לִמְקַטְרֵג וּמְקַטְרֵג לוֹ. וּכְשֶׁמּוֹדֶה עֲליהֶם, נוֹטֵל אוֹתָם אוֹתוֹ הַצַּד הָאַחֵר, וְהוּא חֶלְקוֹ וְגוֹרָלוֹ.</p>\n<p>וְהַסּוֹד הַזֶּה, כָּךְ גַּם הַקָּרְבָּן - שֶׁצָּרִיךְ לְהוֹדוֹת עַל אוֹתוֹ הַקָּרְבָּן כָּל עֲונוֹתָיו וַחֲטָאָיו, לָתֵת חֵלֶק לְמִי שֶׁצָּרִיךְ. כָּל הַקָּרְבָּן לְזֶה הַצַּד חֵלֶק הַקְּדֻשָּׁה וּרְצוֹן הַקְּדֻשָּׁה. וְלַצַּד הַזֶּה אוֹתוֹ חֵלֶק שֶׁל אוֹתָם עֲונוֹת וַחֲטָאִים שֶׁנִּתְּנוּ בְּהוֹדָאָה עַל אוֹתוֹ בְּשַׂר הַקָּרְבָּן, כַּכָּתוּב (משלי כה) אִם רָעֵב שֹׂנַאֲךְ הַאֲכִילֵהוּ לָחֶם וְגוֹ', כִּי גֶחָלִים אַתָּה חֹתֶה וְגוֹ'. וְסִימָנְךְ - (אסתר ה) יָבֹא הַמֶּלֶךְ וְהָמָן אֶל הַמִּשְׁתֶּה. אַשְׁרֵי הוּא מִי שֶׁיּוֹדֵעַ דַּרְכּוֹ לָלֶכֶת בְּדֶרֶךְ אֱמֶת.</p>\n<p>וְכָל מִי שֶׁלֹּא יוֹדֵעַ לְסַדֵּר אֶת שֶׁבַח רִבּוֹנוֹ, טוֹב לוֹ שֶׁלֹּא נִבְרָא, מִשּׁוּם שֶׁצָּרִיךְ תְּפִלָּה שֶׁהִיא שְׁלֵמָה לְמַעְלָה, (משום שצריך תפלה) מִתּוֹךְ מַחֲשָׁבָה וּרְצוֹן הַלֵּב וְקוֹל וְדִבְרֵי הַשְּׂפָתַיִם, לַעֲשׂוֹת שְׁלֵמוּת וְקֶשֶׁר וְיִחוּד לְמַעְלָה, כְּמוֹ שֶׁהוּא לְמַעְלָה. כְּמוֹ שֶׁיּוֹצֵאת שְׁלֵמוּת מִמַּעְלָה לְמַטָּה, כָּךְ דֶּרֶךְ מִמַּטָּה לְמַעְלָה לִקְשֹׁר קֶשֶׁר כָּרָאוּי.</p>\n<p>הַסּוֹד לַחֲבֵרִים שֶׁיֵּלְכוּ בְּדֶרֶךְ יְשָׁרָה - מַחֲשָׁבָה וְרָצוֹן וְקוֹל וְדִבּוּר. אֵלּוּ הָאַרְבָּעָה קוֹשְׁרִים קְשָׁרִים. אַחַר קֶשֶׁר הַקְּשָׁרִים שֶׁל כֻּלָּם כְּאֶחָד, נַעֲשׂוּ כֻלָּם מֶרְכָּבָה אַחַת לְהַשְׁרוֹת עֲלֵיהֶם שְׁכִינָה, וְנַעֲשׂוּ כֻלָּם לְאַחַר אַרְבָּעָה תוֹמְכִים לְהִתְעַטֵּר בָּהֶם, וְהַשְּׁכִינָה נִסְמֶכֶת עֲלֵיהֶם בְּכָל אוֹתָם הַקְּשָׁרִים הָעֶלְיוֹנִים.</p>\n<p>מַחֲשָׁבָה מוֹצִיאָה רָצוֹן, (רצון מוציא הכל) רָצוֹן שֶׁיּוֹצֵא מִתּוֹךְ מַחֲשָׁבָה, מוֹצִיאָה קוֹל שֶׁנִּשְׁמָע, וְאוֹתוֹ קוֹל שֶׁנִּשְׁמָע עוֹלֶה לִקְשֹׁר קְשָׁרִים מִמַּטָּה לְמַעְלָה, הֵיכָלוֹת תַּחְתּוֹנִים בְּעֶלְיוֹנִים. הַקּוֹל שֶׁהוּא קוֹשֵׁר קְשָׁרִים וּמוֹשֵׁךְ בְּרָכוֹת מִמַּעְלָה לְמַטָּה בְּלַחַשׁ, תּוֹמֵךְ אֶת אַרְבַּעַת הַתּוֹמְכִים הַלָּלוּ: מַחֲשָׁבָה וְרָצוֹן, קוֹל וְדִבּוּר. סֶמֶךְ בְּסִיּוּם הַקֶּשֶׁר, הַמָּקוֹם שֶׁהַכֹּל נִקְשָׁר בּוֹ כְּאֶחָד, וְכֻלָּם נַעֲשִׂים אֶחָד.</p>\n<p>אַשְׁרֵי הָאִישׁ שֶׁקּוֹשֵׁר קִשְׁרֵי רִבּוֹנוֹ, וְסוֹמֵךְ סְמִיכוּת כָּרָאוּי, וּמִתְכַּוֵּן בְּכָל הַדְּבָרִים הַלָּלוּ שֶׁאָמַרְנוּ. אַשְׁרָיו בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. עַד כָּאן נִתְקְנוּ הַהֵיכָלוֹת שֶׁבְּצַד הַקְּדֻשָּׁה.</p>"],[9522011914,"<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (הושע ו) וְהֵמָּה כְּאָדָם עָבְרוּ בְרִית שָׁם בָּגְדוּ בִי. מִי יְגַלֶּה עָפָר מֵעֵינֶיךְ, אָדָם הָרִאשׁוֹן, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא צִוָּה אוֹתְךְ מִצְוָה אַחַת וְלֹא יָכֹלְתָּ לַעֲמֹד בָּהּ, מִשּׁוּם שֶׁהִתְפַּתֵּיתָ עַל דְּבָרִים רָעִים, שֶׁהֵסִית אוֹתְךְ אוֹתוֹ הַנָּחָשׁ הָרָע, שֶׁכָּתוּב (בראשית ג) וְהַנָּחָשׁ הָיָה עָרוּם. וּמִשּׁוּם כָּךְ הִתְפַּתֵּיתָ אַחֲרָיו וְגָרַמְתָּ מִיתָה לְעַצְמְךְ וּלְכָל אוֹתָם תּוֹלָדוֹת שֶׁיָּצְאוּ מִמְּךְ. בֹּא וּרְאֵה, שֶׁכָּל מִי שֶׁמִּתְפַּתֶּה אַחֲרָיו וְיוֹרֵד אֵלָיו לְרֶגַע אֶחָד, יֹאבַד אֶצְלוֹ.</p>\n<p>בֹּא וּרְאֵה, דָּוִד הָיָה קִיּוּמוֹ נָעוּץ בְּמָקוֹר שֶׁל מַיִם נוֹבְעִים, וּכְשֶׁנִּדְחָה לְאֶרֶץ אַחֶרֶת וְצִעֲרוּ אוֹתוֹ, וּלְפִי צַעֲרוֹ נִדְחָה מֵהָאָרֶץ הַקְּדוֹשָׁה - אַף עַל גַּב שֶׁיָּרַד מִדַּרְגָּתוֹ לְדַרְגָּה תַחְתּוֹנָה עָמַד בְּקִיּוּמוֹ, וְלֹא נִכְנַס לַצַּד הָאַחֵר וְנִשְׁמַר מִמֶּנּוּ. מַה כָּתוּב? (שמואל א כ) וְאוּלָם חַי ה' וְחֵי נַפְשֶׁךְ כִּי כְפֶשַׂע בֵּינִי וּבֵין הַמָּוֶת. שֶׁהֲרֵי יָרַד בְּדַרְגָּתוֹ עַד שֶׁהָיָה בּוֹ הַשִּׁעוּר הַזֶּה. וְאַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁנִּשְׁמָר מֵאוֹתוֹ הַצַּד הָרָע, וּמִכָּל דַּרְגוֹתָיו שֶׁל אוֹתוֹ הַצַּד שֶׁנִּמְצָאִים בָּעוֹלָם.</p>\n<p>שֶׁכַּמָּה צְדָדִים וּדְרָגוֹת יֵשׁ לַיֵּצֶר הָרָע: נָחָשׁ עֲקַלָּתוֹן, שָׂטָן, מַלְאַךְ הַמָּוֶת, יֵצֶר הָרָע. וַהֲרֵי פֵּרְשׁוּהָ. שֶׁאַף עַל גַּב שֶׁנִּקְרָא בַּשֵּׁמוֹת הַלָּלוּ, יֵשׁ לוֹ שִׁבְעָה שֵׁמוֹת: שָׂטָן, טָמֵא, שׂוֹנֵא, אֶבֶן מִכְשׁוֹל, עָרֵל, רָע, צְפוֹנִי. אֵלּוּ הֵם שִׁבְעָה שֵׁמוֹת כְּנֶגֶד שֶׁבַע דְּרָגוֹת שֶׁל הַהֵיכָלוֹת שֶׁלּוֹ, שֶׁכֻּלָּם מִצַּד הַטֻּמְאָה כְּפִי שֶׁאָמַרְנוּ. כְּנֶגֶד שִׁבְעָה הַשֵּׁמוֹת הַלָּלוּ, אוֹתָם שֶׁנִּקְרָא בָהֶם גֵּיהִנֹּם, הַמָּקוֹם שֶׁבּוֹ נִדּוֹנִים הָרְשָׁעִים שֶׁל הָעוֹלָם, וְאֵלּוּ הֵם: בּוֹר, שַׁחַת, דּוּמָה, טִיט הַיָּוֵן, שְׁאוֹל, צַלְמָוֶת, אֶרֶץ תַּחְתִּית. כָּל אֵלּוּ שִׁבְעַת מְדוֹרֵי הַגֵּיהִנֹּם כְּנֶגֶד שִׁבְעַת הַשֵּׁמוֹת הַלָּלוּ שֶׁיֵּשׁ לַיֵּצֶר הָרָע.</p>\n<p>וַהֲרֵי בֵּאַרְנוּ, שֶׁכְּמוֹ שֶׁיֵּשׁ דְּרָגוֹת וְהֵיכָלוֹת לְצַד הַקְּדֻשָּׁה - כָּךְ גַּם לְצַד הַטֻּמְאָה. וְכֻלָּם נִמְצָאִים וְשׁוֹלְטִים בָּעוֹלָם בְּצַד (השמאל) הַטֻּמְאָה. שִׁבְעָה הֵיכָלוֹת הֵם, שֶׁהֵם כְּנֶגֶד שִׁבְעָה שֵׁמוֹת, שֶׁבָּהֶם נִקְרָא גֵּיהִנֹּם (יצר הרע). וְכֻלָּם עוֹמְדִים (להשטין רע) לָדוּן וּלְטַמֵּא אֶת אוֹתָם הָרְשָׁעִים שֶׁל הָעוֹלָם שֶׁדָּבַק בָּהֶם, וְלֹא שָׁמְרוּ אֶת דַּרְכֵיהֶם מִמֶּנּוּ כְּשֶׁהֵם בָּעוֹלָם הַזֶּה.</p>\n<p>שֶׁהֲרֵי מִי שֶׁזּוֹכֶה לְהִטָּהֵר בָּעוֹלָם הַזֶּה בְּצַד הַטָּהֳרָה, מְטַהֲרִים אוֹתוֹ בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא סוֹד הָאֱמוּנָה. שֶׁכַּמָּה דְרָגוֹת הֵן וְכַמָּה מְמֻנִּים, שֶׁכֻּלָּם עוֹמְדִים לְקָרֵב בְּנֵי אָדָם לַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְטַהֵר אוֹתָם, וּמִי שֶׁבָּא לְהִטָּמֵא, מְטַמְּאִים אוֹתוֹ בַּצַּד הָאַחֵר הַזֶּה, שֶׁהוּא טָמֵא. שֶׁהֲרֵי כַּמָּה דְרָגוֹת וְכַמָּה מְמֻנִּים, כֻּלָּם עוֹמְדִים כְּדֵי לְטַמֵּא בְּנֵי אָדָם.</p>\n<p>מִי שֶׁקָּרֵב אֲלֵיהֶם וּבָא לְהִמָּשֵׁךְ אַחַר אוֹתוֹ הַצַּד הָרָע, עָלָיו כָּתוּב (תהלים פט) מִי גֶבֶר יִחְיֶה וְלֹא יִרְאֶה מָּוֶת יְמַלֵּט נַפְשׁוֹ וְגוֹ'. מִי הוּא הָאָדָם שֶׁנִּבְרָא בָּעוֹלָם שֶׁלֹּא יִרְאֶה מָוֶת? אוֹתוֹ שֶׁכָּל הָעוֹלָם נִמְשָׁכִים אַחֲרָיו. שֶׁהֲרֵי בְּאוֹתוֹ זְמַן שֶׁבָּא אָדָם לָתֵת חֶשְׁבּוֹן לִפְנֵי רִבּוֹנוֹ, טֶרֶם שֶׁיֵּצֵא מִן הָעוֹלָם הַזֶּה, רוֹאֶה אוֹתוֹ, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>וְאֵלּוּ שִׁבְעַת הַהֵיכָלוֹת, שֶׁהֵם שִׁבְעָה מָדוֹרִים לַגֵּיהִנֹּם, נִקְרָאִים שְׁנֵים עָשָׂר חֳדָשִׁים, מִשּׁוּם שֶׁהֲרֵי כְּמוֹ שֶׁיֵּשׁ לְצַד הָאֱמוּנָה שְׁנֵים עָשָׂר חֳדָשִׁים, דְּרָגוֹת קְדוֹשׁוֹת, כָּךְ יֵשׁ גַּם לַצַּד הָאַחֵר הַזֶּה שְׁנֵים עָשָׂר חֳדָשִׁים שֶׁהָרְשָׁעִים נִדּוֹנִים בָּהֶם וְנִשְׁמָתָם נִדּוֹנֵית בָּהֶם. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁמּוֹנְעִים רַגְלֵיהֶם מֵהֶם בָּעוֹלָם הַזֶּה וְלֹא מִתְקָרְבִים לְשַׁעֲרֵיהֶם, כְּדֵי לְהִנָּצֵל מֵהֶם בְּאוֹתוֹ הָעוֹלָם.</p>"],[9522011915,"<p>הַהֵיכָל הָרִאשׁוֹן - רֵאשִׁית הַצַּד שֶׁל הַיֵּצֶר הָרָע. הַהֵיכָל הָרִאשׁוֹן הַזֶּה נִקְרָא בּוֹר רֵיק מֵהַכֹּל. מִי שֶׁבָּא לְהִכָּנֵס בּוֹ, אֵין מִי שֶׁאוֹחֵז בּוֹ. כֻּלָּם דּוֹחִים אוֹתוֹ לִפֹּל שֶׁלֹּא יָקוּם. אֵין בּוֹ תְּמִיכָה לְטוֹב.</p>\n<p>בַּהֵיכָל הַזֶּה עוֹמֵד מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ דּוּמָה, וְזֶהוּ שֶׁעוֹמֵד לְמַעְלָה וּלְמַטָּה. זֶהוּ שֶׁאוֹחֵז בַּנְּשָׁמָה, כְּשֶׁנִּדְחֵית מִן הַהֵיכָל הַקָּדוֹשׁ, עַל יְדֵי אוֹתוֹ מְמֻנֶּה טַהֲרִיאֵ\"ל, וְזֶהוּ שֶׁעוֹמֵד עַל אוֹתוֹ הַשַּׁעַר שֶׁל אוֹתוֹ צַד הַקְּדֻשָּׁה, וּמִשּׁוּם כָּךְ עוֹמֵד הַדּוּמָה הַזֶּה לֶאֱחֹז אֶת הַנְּשָׁמָה, וְכַמָּה שׁוֹמְרֵי הַחֻקִּים עִמּוֹ.</p>\n<p>וְתַחַת הַמְמֻנֶּה הַזֶּה עוֹמֵד מְמֻנֶּה אַחֵר, שֶׁאֶלֶף וּרְבָבוֹת תַּחְתָּיו, וְהַמְמֻנֶּה הַזֶּה נִקְרָא פִּתּוּ\"ת. זֶהוּ שֶׁעוֹמֵד לְפַתּוֹת בְּנֵי אָדָם, וְזֶהוּ שֶׁשּׁוֹרֶה עָלָיו וּמֵסִית אוֹתוֹ לְהִסְתַּכֵּל וּלְעַיֵּן בְּמַה שֶּׁלֹּא צָרִיךְ, בְּכַמָּה זְנוּנִים וּבְכַמָּה נִאוּפִים. וְכָל אוֹתָם שֶׁעִמּוֹ, כֻּלָּם עוֹמְדִים אֶצְלוֹ וְהוֹלְכִים לְפָנָיו, וּמַכְרִיחִים אוֹתוֹ לְהָסִית עֵינָיו, לְהִסְתַּכֵּל בְּמַה שֶּׁלֹּא צָרִיךְ.</p>\n<p>וְזְהִוּ (סרסרים שהוא) סַרְסוּר רַע לְכָל אוֹתָן רָעוֹת, זֶהוּ שֶׁעוֹמֵד עַל הַקֶּבֶר בִּזְמַן שֶׁנִּדּוֹן אוֹתוֹ הַגּוּף וְשׁוֹבֵר לוֹ אֶת עֵינָיו, מִשּׁוּם שֶׁהוּא פָּתַח אוֹתָם כְּשֶׁהוּא בָּעוֹלָם הַזֶּה, וְהֵם שֶׁלּוֹ.</p>\n<p>וּבַמָּקוֹם הַזֶּה נִדּוֹנֵית הַנְּשָׁמָה, עַד שֶׁנִּכְנֶסֶת לַמָּקוֹם הַזֶּה שֶׁנִּקְרָא בּוֹר, וְכַמָּה נְחָשִׁים וְעַקְרַבִּים יֵשׁ בּוֹ שֶׁכֻּלָּם עוֹקְצִים אוֹתָהּ אֶת הַנְּשָׁמָה הַזּוֹ, וְאוֹחֲזִים בָּהּ וְדָנִים אוֹתָהּ.</p>\n<p>לִפְנִים מִזֶּה יֵשׁ רוּחַ אַחַת אַחֶרֶת טְמֵאָה, שֶׁהִיא עֶלְיוֹנָה עַל הַכֹּל. וְזוֹ עוֹמֶדֶת עַל כָּל הַהֵיכָל הַזֶּה, וְכֻלָּם נוֹסְעִים בִּשְׁבִילוֹ, וְזֶה נִקְרָא גַּמְגִימָ\"א. זֶהוּ אָדם כְּמוֹ שׁוֹשַׁנָּה, וְהוּא עוֹמֵד לְהָרַע תָּמִיד, שֶׁהֲרֵי כְּשֶׁנִּדְחֵית תְּפִלַּת הָאָדָם וְלֹא זוֹכֶה בָּהּ אוֹתוֹ אָדָם, הָרוּחַ הַזּוֹ עוֹמֶדֶת וְעוֹלָה וּמִשְׁתַּתֶּפֶת עִם רוּחַ טְמֵאָה עֶלְיוֹנָה עַל הַכֹּל, וּמַשְׂטִינָה לְמַעְלָה, וּמַזְכִּירָה חֲטָאֵי הָאָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְסִימָנְךְ - (איוב א) וַיָּבוֹא גַ\"ם הַשָּׂטָ\"ן בְּתוֹכָם, וְלֹא כָתוּב וַיָּבֹא הַשָּׂטָן, אֶלָּא גַּם.</p>\n<p>וּמֵהָרוּחַ הָרָעָה הַזּוֹ תְּלוּיִים כַּמָּה שׁוֹמְרִים אֲחֵרִים שֶׁמְּמֻנִּים לֶאֱחֹז בְּדִבּוּר רַע, אוֹ דִבּוּר מְטֻנָּף שֶׁמּוֹצִיא אָדָם מִפִּיו, וְאַחַר כָּךְ מוֹצִיא דִבּוּרִים קְדוֹשִׁים. אוֹי לָהֶם וְאוֹי לְחַיֵּיהֶם! אֵלּוּ הֵם בְּנֵי אָדָם שֶׁגּוֹרְמִים לַשּׁוֹמְרִים הַלָּלוּ הָאֲחֵרִים לִשְׁלֹט וְלִפְגֹּם אֶת הַמָּקוֹם הַקָּדוֹשׁ. אוֹי לָהֶם בָּעוֹלָם הַזֶּה, וְאוֹי לָהֶם לָעוֹלָם הַבָּא. מִשּׁוּם שֶׁאֵלּוּ הָרוּחוֹת הַטְּמֵאוֹת נוֹטְלוֹת אֶת הַדִּבּוּר הַטָּמֵא, וּכְשֶׁמּוֹצִיא אָדָם אַחַר כָּךְ דִּבּוּר קָדוֹשׁ, אֵלּוּ הָרוּחוֹת הַטְּמֵאוֹת מַקְדִּימוֹת, וְנוֹטְלוֹת אוֹתוֹ הַדִּבּוּר הַטָּמֵא, וּמְטַמְּאוֹת אֶת אוֹתוֹ הַדִּבּוּר הַקָּדוֹשׁ, וְהָאָדָם לֹא זוֹכֶה בּוֹ, וְכִבְיָכוֹל תָּשַׁשׁ כֹּחַ הַקְּדֻשָּׁה.</p>\n<p>וּמֵעַל לְאֵלֶּה יֵשׁ מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ סַפְסִירִיטָ\"א. וְכַמָּה שׁוֹמְרֵי חֹק, וְזֶה מְמֻנֶּה עֲלֵיהֶם, הֵם נוֹטְלִים אוֹתָם דִּבּוּרִים רָעִים, וְכָךְ גַּם נוֹטְלִים כָּל אוֹתָם דְּבָרִים שֶׁזּוֹרֵק אָדָם בְּיָדוֹ כְּשֶׁרֹגֶז שׁוֹרֶה עָלָיו. שֶׁהֲרֵי אָז, הַמְמֻנֶּה הַזֶּה סַפְסִירִיטָ\"א לוֹקֵחַ אֶת הַדָּבָר הַזֶּה שֶׁזָּרַק אָדָם בְּרָגְזוֹ, וְעוֹלֶה וְאוֹמֵר: זֶה קָרְבָּנוֹ שֶׁל פְּלוֹנִי שֶׁהִקְרִיב לַצַּד שֶׁלָּנוּ.</p>\n<p>מִשּׁוּם שֶׁכָּל צַד שֶׁל נַחַת הוּא מִצַּד הַיָּמִין וּמִצַּד הָאֱמוּנָה, וְכָל צַד הָרֹגֶז הוּא מֵהַצַּד הָאַחֵר הָרָע, צַד הַטֻּמְאָה. וְלָכֵן מִי שֶׁזּוֹרֵק מִיָּדוֹ דָּבָר בְּרֹגֶז, כָּל אֵלּוּ נוֹטְלִים אֶת אוֹתוֹ דָּבָר שֶׁנִּזְרָק וּמַעֲלִים אוֹתוֹ לְמַעְלָה, וְנִקְרָב לְאוֹתוֹ הַצַּד, וְאוֹמְרִים: זֶה (עבודת הקרבן) קָרְבָּנוֹ שֶׁל פְּלוֹנִי.</p>\n<p>וְהַכָּרוֹז קוֹרֵא בְּכָל אוֹתָם רְקִיעִים וְאוֹמְרִים: אוֹי לִפְלוֹנִי שֶׁסָּטָה אַחַר אֵל זָר וְעָבַד לְאֵל אַחֵר. וְהַכָּרוֹז קוֹרֵא פַּעַם שְׁנִיָּה וְאוֹמֵר: (הושע ז) אוֹי לָהֶם כִּי נָדְדוּ מִמֶּנּוּ וְגוֹ'. אַשְׁרֵי הָאִישׁ שֶׁנִּשְׁמָר מִדְּרָכָיו וְלֹא יִסְטֶה יָמִינָה וּשְׂמֹאלָה, וְלֹא יִפֹּל בְּתוֹךְ בְּאֵר עֲמֻקָּה שֶׁלֹּא יוּכַל לַעֲלוֹת מִמֶּנָּה.</p>"],[9522011916,"<p>הַהֵיכָל הַשֵּׁנִי, הַהֵיכָל הַזֶּה הוּא חָשׁוּךְ יוֹתֵר מֵהַהֵיכָל הָרִאשׁוֹן. זֶה נִקְרָא שַׁחַת, כְּנֶגֶד הַשֵּׁם שֶׁנִּקְרָא טָמֵא. מִשּׁוּם שֶׁהַהֵיכָל הָרִאשׁוֹן נִקְרָא בּוֹר, כְּנֶגֶד הַשֵּׁם שֶׁנִּקְרָא שָׂטָן. וְזֶה נִקְרָא שַׁחַת, כְּנֶגֶד הַשֵּׁם שֶׁנִּקְרָא טָמֵא. בַּהֵיכָל הַזֶּה קַיָּמִים שְׁלֹשָׁה פְתָחִים לִשְׁלֹשָׁה צְדָדִים.</p>\n<p>הַפֶּתַח הָרִאשׁוֹן, בּוֹ עוֹמֵד מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ עַסְטִירִיָּ\"א. וְכַמָּה אֲלָפִים וּרְבָבוֹת מְמֻנִּים תַּחְתָּיו, וְזֶהוּ שֶׁעוֹמֵד עַל כָּל אֵלּוּ שֶׁמַּשְׁחִיתִים דַּרְכָּם לִשְׁפֹּךְ זֶרַע עַל הָאָרֶץ, אוֹ שֶׁמּוֹצִיאִים זֶרַע שֶׁלֹּא כַדֶּרֶךְ, אוֹ לְכָל אֵלּוּ שֶׁמְּזַנִּים בִּידֵיהֶם. אֵלּוּ הֵם שֶׁלֹּא רוֹאִים פְּנֵי שְׁכִינָה כְּלָל. אֶלָּא הַמְמֻנֶּה הַזֶּה שֶׁבְּצַד הַטֻּמְאָה שֶׁאָמַרְנוּ, יוֹצֵא בְּאוֹתוֹ זְמַן, וְכַמָּה הֵם אֲלָפִים וּרְבָבוֹת, כֻּלָּם מִתְכַּנְּסִים עַל אוֹתוֹ אָדָם, וּמְטַמְּאִים אוֹתוֹ בָּעוֹלָם הַזֶּה. וְאַחַר כָּךְ כְּשֶׁיּוֹצֵאת נִשְׁמָתוֹ מֵהָעוֹלָם הַזֶּה, הַמְמֻנֶּה הַזֶּה וְכָל אֵלֶּה שֶׁעִמּוֹ, מְטַמְּאִים אֶת נִשְׁמָתוֹ, וְאוֹחֲזִים בָּהּ, (ונטמאת בהם) וּמַכְנִיסִים אוֹתָהּ לְהִדּוֹן בָּהֶם.</p>\n<p>וְאֵלֶּה נִקְרָאִים שִׁכְבַת זֶרַע רוֹתַחַת. שֶׁכָּל הַכְּעָסִים הַטְּמֵאִים כֻּלָּם עוֹמְדִים עַל זֶה, מִשּׁוּם שֶׁכֻּלָּם עוֹמְדִים וְשׁוֹרִים עַל הָאָדָם בִּזְמַן שֶׁהִרְתִּיחַ אֶת עַצְמוֹ וְחִמֵּם אוֹתוֹ בַּתְּשׁוּקָה הַזּוֹ. וְאָז הֵם נוֹטְלִים אֶת אוֹתָהּ הַתַּאֲוָה וְאֶת אוֹתוֹ הַזֶּרַע שֶׁנִּשְׁפָּךְ בָּאָרֶץ, וּמַחֲזִיקִים בּוֹ וְנוֹטְלִים אוֹתוֹ, וּמַעֲלִים אוֹתוֹ לְמַעְלָה, וְגוֹרְמִים שֶׁהַבְּרִית הַזּוֹ תִּשְׁתַּעְבֵּד לְצַד הַטֻּמְאָה.</p>\n<p>הַפֶּתַח הַשֵּׁנִי, בּוֹ עוֹמֵד מְמֻנֶּה אַחֵר שֶׁשְּׁמוֹ טַסְקִיפָ\"ה, וְזֶהוּ מְמֻנֶּה עַל כָּל אוֹתָם שֶׁמַּשְׁחִיתִים דַּרְכָּם, שֶׁלֹּא שׁוֹפְכִים זֶרַע עַל הָאָרֶץ, אֶלָּא שֶׁשּׁוֹפְכִים זֶרַע בִּבְהֵמוֹת אוֹ בְּאִסּוּרֵי תוֹרָה חֲמוּרִים, בְּאוֹתָן עֲרָיוֹת - הַמְמֻנֶּה הַזֶּה וְכַמָּה אֲלָפִים וּרְבָבוֹת שֶׁעִמּוֹ, כֻּלָּם עוֹמְדִים עָלָיו (לטמא אותו ולדון אותו) לָדוּן אוֹתוֹ כְּמוֹ שֶׁנִּתְבָּאֵר בְּאוֹתָם הָאֲחֵ רִים.</p>\n<p>בֹּא וּרְאֵה, לַמְמֻנֶּה הַזֶּה יֵשׁ כּוֹס אַחַת בְּיָדוֹ, וְנִקְרֵאת (ישעיה נא) כּוֹס הַתַּרְעֵלָה כּוֹס חֲמָתוֹ. וְכָל אוֹתָם הֲרוּגֵי בֵּית דִּין שֶׁנֶּהֶרְגוּ אוֹ נֶעֶנְשׁוּ עַל הַחֲטָאִים הַלָּלוּ, כֻּלָּם נֶעֱקָרִים מֵהַצְּדָדִים הַטְּמֵאִים הַלָּלוּ, וְאֵין לָהֶם חֵלֶק בָּהֶם, וּבַכּוֹס הַזֹּאת שֶׁנִּקְרֵאת כּוֹס הַתַּרְעֵלָה, מִשּׁוּם כּוֹס אַחֶרֶת שֶׁשָּׁתוּ בָּרִאשׁוֹנָה.</p>\n<p>וְכָל אוֹתָם שֶׁלֹּא שָׁתוּ אוֹתָהּ כּוֹס שֶׁל בֵּית דִּין כְּדֵי לְהֵעָקֵר מִכּוֹס הַתַּרְעֵלָה הַזּוֹ, אַחַר כָּךְ כְּשֶׁיּוֹצֵאת נִשְׁמָתוֹ מִן הָעוֹלָם הַזֶּה, הַמְמֻנֶּה הַזֶּה וְכָל אֵלּוּ שֶׁעִמּוֹ אוֹחֲזִים בּוֹ, וְזֶהוּ (עמוס ח) יוֹם הַמָּר, וּמַרְוֶה אֶת הַנְּשָׁמָה הַזּוֹ מִכַּמָּה דִינִים מְשֻׁנִּים אֵלֶּה מֵאֵלֶּה.</p>\n<p>בַּהֵיכָל הַזֶּה עוֹמֶדֶת רוּחַ אַחַת, שֶׁאֵלּוּ מְמֻנִּים תַּחְתֶּיהָ, וְזֶהוּ נִיאֲצִירִיאֵ\"ל. מֵהָרוּחַ הַחֲזָקָה הַזּוֹ יוֹצְאוֹת שָׁלֹשׁ טִפּוֹת מָרוֹת שֶׁנּוֹפְלוֹת לְתוֹךְ כּוֹס הַתַּרְעֵלָה הַזּוֹ. אַחַת נִקְרֵאת חָצָ\"ץ, וְאַחַת נִקְרֵאת מַר הַמָּוֶת, וְאַחַת נִקְרֵאת קוּבַּעַ\"ת. (וכלם מתכגסים לכוס הזו אחר כך) וּשְׁלֹשׁ הַטִּפּוֹת הַלָּלוּ נוֹפְלוֹת אַחַר כָּךְ מֵהַכּוֹס הַזֹּאת (יוצאות שלש טפות) (באותה) שֶׁאוֹתָהּ חֶרֶב שֶׁהוֹרֶגֶת בְּנֵי אָדָם, כְּמוֹ שֶׁבֵּאֲרוּהָ.</p>\n<p>הַפֶּתַח הַשְּׁלִישִׁי, בּוֹ עוֹמֵד מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ סְנַגְדִּיאֵ\"ל, וְזֶה מְמֻנֶּה עַל כָּל אוֹתָם שֶׁמַּכְנִיסִים אֶת בְּרִית הַקֹּדֶשׁ הַזּוֹ בְּאִשָּׁה אַחֶרֶת, שֶׁהִיא מֵאוֹתוֹ הַצַּד שֶׁל אֵל נֵכָר. וְכָל אֵלּוּ שֶׁמַּשְׁחִיתִים דַּרְכָּם בָּזֶה וּמְשַׁקְּרִים בְּאוֹת בְּרִית קֹדֶשׁ, הַמְמֻנֶּה הַזֶּה וְכָל אוֹתָם הַמְמֻנִּים שֶׁעִמּוֹ, כֻּלָּם מְצַיְּרִים בְּתוֹכָם צִיּוּרִים שֶׁל אוֹתָם נָשִׁים טְמֵאוֹת שֶׁנִּטְמָא בָהֶן אוֹתוֹ בְּרִית קֹדֶשׁ, וְכֻלָּם רְשׁוּמִים לְפָנָיו כְּשֶׁיּוֹצֵא אָדָם מִן הָעוֹלָם הַזֶּה, וּמְטַמְּאִים אוֹתוֹ אַחַר כָּךְ לְאוֹתָהּ רוּחַ.</p>\n<p>וּבַהֵיכָל הַזֶּה תְּלוּיִים כָּל סוֹדוֹת הַכְּשָׁפִים לַהֲרֹג בְּנֵי אָדָם טֶרֶם יַגִּיעַ זְמַנָּם, וְכָל הַכְּשָׁפִים שֶׁצְּרִיכִים בְּנֵי אָדָם, אוֹתָם שֶׁמְּכַשְּׁפִים בְּכִשְׁפֵיהֶם לְהִטָּמֵא בָהֶם, כְּמוֹ שֶׁהָיָה בִּלְעָם מְכַשֵּׁף בִּכְשָׁפָיו, וְנִטְמָא בַּהַתְחָלָה בְּטֻמְאַת זֶרַע רוֹתַחַת שֶׁשָּׁפַךְ בַּבְּהֵמוֹת, וּמִשּׁוּם כָּךְ נִדּוֹן בָּזֶה, בְּאוֹתָהּ שִׁכְבַת זֶרַע רוֹתַחַת שֶׁאָמַרְנוּ. וְעַל כֵּן הַהֵיכָל הַזֶּה נִקְרָא שַׁחַת טָמֵא.</p>\n<p>וּבַהֵיכָל הַזֶּה יֵשׁ רוּחַ אַחֶרֶת שֶׁמְּמֻנָּה תַּחַת אוֹתָהּ רוּחַ שֶׁלְּמַעְלָה, וְזוֹ נִקְרֵאת סַרְטַיָּ\"א, וְכַמָּה אֲלָפִים וּרְבָבוֹת תַּחְתֶּיהָ. וְכֻלָּם עוֹמְדִים עַל אוֹתוֹ הַדָּבָר שֶׁיּוֹצֵא עִם הָרוּחַ שֶׁל הָאָדָם בַּחֲלוֹם מִתּוֹךְ הַצַּד הַקָּדוֹשׁ. הָרוּחַ הַטְּמֵאָה וְכָל אוֹתָם הַשּׁוֹמְרִים שֶׁעִמָּהּ, כֻּלָּם יוֹצְאִים וּמִתְחַבְּרִים עִם הַדָּבָר הַזֶּה, וְיוֹרְדִים בּוֹ וּמִתְעָרְבִים עִמּוֹ כְּדֵי לְהַכְחִישׁ אוֹתוֹ מִמֶּנָּה, וּמוֹדִיעִים לוֹ לָאָדָם דְּבָרִים אֲחֵרִים, דְּבָרִים כּוֹזְבִים, עִם דְּבַר אֱמֶת.</p>\n<p>שֶׁכָּךָ דֶּרֶךְ הַכָּזָב - שֶׁאִלְמָלֵא לֹא לוֹקֵחַ דְּבַר אֱמֶת, לֹא יָכוֹל לְסַדֵּר אֶת כְּזָבוֹ. אַף כָּאן אֵלּוּ, כֵּיוָן שֶׁמְּעוֹרְרִים בְּדִבְרֵי אֱמֶת וּמַכְחִישִׁים אוֹתוֹ מִמֶּנּוּ, מוֹדִיעִים לוֹ דְּבַר אֱמֶת כְּדֵי לְהַעֲמִיד אֶת כְּזָבוֹ. אַחַר כָּךְ מִתְפַּשְּׁטִים כָּל אוֹתָם (אותו הדבר מתפשט באותם) הַתַּחְתּוֹנִים שֶׁלְּמַטָּה שֶׁאֵין לָהֶם קִיּוּם, וְלֹא מִתְקַיְּמִים, וּמוֹדִיעִים דְּבָרִים בָּעוֹלָם לְכַמָּה צְדָדִים (וכל אלו שלמטה בדרגות שמתפרדות לחוץ לכמה צדדים) וּלְכַמָּה מִינִים.</p>\n<p>מֵהַהֵיכָל הַזֶּה יוֹצְאוֹת שְׁתֵּי רוּחוֹת שֶׁמִּתְהַפְּכוֹת לִפְעָמִים לִגְבָרִים וְלִפְעָמִים לְנָשִׁים, וְאֵלּוּ הוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם בָּאֲוִיר, וְצוֹחֲקִים עִם אֲנָשִׁים בְּתוֹךְ הַחֲלוֹם, וְנִרְאִים לַגְּבָרִים כְּמוֹ נָשִׁים יָפוֹת בְּמַרְאֵה הַחֲלוֹם, וְנוֹטְלִים אֶת תְּשׁוּקַת הָאָדָם. אַף כָּךְ לַנָּשִׁים הֵם נִרְאִים כִּגְבָרִים, וְאֵלּוּ נִקְרָאוֹת רָעָה וְנֶגַע, כְּמוֹ שֶׁנֶּאֱמַר (תהלים צא) לֹא תְאֻנֶּה אֵלֶיךְ רָעָה וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךְ.</p>\n<p>וְאֵלּוּ נִקְרָאוֹת רוּחוֹת תַּחְתּוֹנוֹת לְמַטָּה, שֶׁיּוֹצְאוֹת מִתּוֹךְ שַׁלְהֶבֶת הָאֵשׁ. שֶׁכְּשֶׁנּוֹסְעוֹת הָרוּחוֹת הַלָּלוּ שֶׁלְּמַעְלָה שֶׁבְּתוֹךְ הַהֵיכָל הַזֶּה, יוֹצְאוֹת שְׁתֵּי שַׁלְהֲבוֹת אֵשׁ, וְאֵלּוּ טָסוֹת בָּעוֹלָם, וְאֵלּוּ נַעֲשׂוּ שְׁתֵּי רוּחוֹת כְּפִי שֶׁאָמַרְנוּ, וְהַכֹּל בְּצַד הַטֻּמְאָה הַזֶּה. אַשְׁרֵי הַצַּדִּיקִים שֶׁנִּמְנָעִים מֵהַצְּדָדִים הַלָּלוּ וְנִשְׁמָרִים מֵהֶם, וְעַל זֶה כָּתוּב, (משלי ז) לִשְׁמָרְךְ מֵאִשָּׁה זָרָה וְגוֹ'.</p>"],[9522011917,"<p>הַהֵיכָל הַשְּׁלִישִׁי. הַהֵיכָל הַזֶּה הוּא הֵיכָל אָפֵל וְחָשׁוּךְ, וְאֵין בּוֹ אוֹר כְּלָל, וְהוּא אָפֵל יוֹתֵר מֵהָרִאשׁוֹנִים. וְזֶהוּ שֶׁנִּקְרָא דּוּמָ\"ה, כְּנֶגֶד הַשֵּׁם שֶׁנִּקְרָא שׂוֹנֵ\"א. בַּהֵיכָל הַזֶּה קַיָּמִים אַרְבָּעָה פְתָחִים. אֶחָד קַיָּם בְּצַד זֶה, וְאֶחָד בְּצַד זֶה, וְכֵן בְּאַרְבַּעַת הַצְּדָדִים.</p>\n<p>מְמֻנֶּה אֶחָד עוֹמֵד עַל הַפֶּתַח הָרִאשׁוֹן הַזֶּה, וְהַמְמֻנֶּה הַזֶּה עוֹמֵד בְּאוֹתוֹ הַתֹּקֶף שֶׁל הָרֹגֶז שֶׁל הָעוֹלָם. כְּשֶׁדִּין שׁוֹרֶה בָּעוֹלָם, הַמְמֻנֶּה הַזֶּה שֶׁשּׁוֹרֶה בַּפֶּתַח הַזֶּה נוֹטֵל כְּלֵי זַיִן וּמַנִּיחַ אוֹתָם בְּאוֹתָם שַׁעֲרֵי בֵּית הַכְּנֶסֶת (של בני אדם), וְזֶה נִקְרָא סָקָפוֹרְטַיָּ\"א, וְזֶהוּ הַכִּשָּׁלוֹן שֶׁל הָעוֹלָם, וְעַל זֶה כָּתוּב, (שם ד) דֶּרֶךְ רְשָׁעִים כָּאֲפֵלָה לֹא יָדְעוּ בַּמֶּה יִכָּשֵׁלוּ. (הממגה הזה עומד על פרשת דרכים לראות) בְּאוֹתוֹ זְמַן שֶׁהוּא שׁוֹלֵט וְהַדִּין שָׁרוּי בָּעוֹלָם, הוּא עוֹמֵד לִרְאוֹת בְּמִי שֶׁהוֹלֵךְ יְחִידִי בַּשּׁוּק, וְאִם הוּא פּוֹגֵשׁ אוֹתוֹ, יָכוֹל לְהַזִּיק לוֹ וּלְהָרַע אֶת מַזָּלוֹ.</p>\n<p>הַפֶּתַח הַשֵּׁנִי, בּוֹ עוֹמֵד מְמֻנֶּה אַחֵר אֶחָד, וְזֶהוּ שֶׁעוֹמֵד לִטֹּל פִּתְקֵי דִין, וְזֶהוּ סְנַגְדִּיאֵ\"ל. וְתַחַת יָדוֹ כְּמוֹ שׁוֹמְרֵי חֹק שֶׁשּׁוֹלְטִים, שֶׁעוֹמְדִים לְקַבֵּל אוֹתָם פִּתְקֵי הַדִּין, וְזֶה עוֹמֵד בַּפֶּתַח הַזֶּה.</p>\n<p>וּכְשֶׁנּוֹטֵל פֶּתֶק שֶׁל דִּין, זֶה עוֹמֵד בַּפֶּתַח הַזֶּה, וְיוֹרֵד לְמַטָּה לְאוֹתָם הַפְּתָחִים הַחֲשׁוּכִים שֶׁלְּמַטָּה. אֶחָד לְאוֹתוֹ שֶׁנִּקְרָא שַׁחַת, וְאֶחָד לְאוֹתוֹ שֶׁנִּקְרָא בּוֹר, שֶׁהֵם לְמַטָּה, וְשָׁם כַּמָּה אֶלֶף וּרְבָבוֹת מְמֻנִּים שֶׁשּׁוֹלְטִים בָּעוֹלָם לַעֲשׂוֹת דִּין, וְנִשְׁלָם הַדִּין בְּאוֹתוֹ הַפֶּתֶק.</p>\n<p>הַפֶּתַח הַשְּׁלִישִׁי. בַּפֶּתַח הַזֶּה יֵשׁ מְמֻנֶּה אַחֵר שֶׁשְּׁמוֹ אַנְגַּרְיוֹ\"ן, וְזֶהוּ שֶׁעוֹמֵד עַל כָּל אוֹתָם מַחֲלוֹת וּמַכְאוֹבִים וְחִלְחוּלִים וְאֵשׁ הָעֲצָמוֹת, שֶׁהֲרֵי מִמֶּנּוּ יוֹצְאִים כַּמָּה וְכַמָּה אֶלֶף וּרְבָבוֹת שֶׁמְּמֻנִּים עִמּוֹ עַל כָּל אוֹתָם מַחֲלוֹת וּמַכְאוֹבִים, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>הַפֶּתַח הָרְבִיעִי. כָּאן הִיא רוּחַ אַחַת שֶׁנִּבְרְאָה בְּמִעוּט הַלְּבָנָה, וְנִקְרֵאת אַסְכָּרָ\"ה. וְזֶה עוֹמֵד עַל הֲרִיגַת הַתּינוֹקוֹת, וְזוֹ נִרְאֵית לָהֶם וְצוֹחֶקֶת עִמָּהֶם עַד שֶׁהוֹרֶגֶת אוֹתָם, וְנִדְמֵית לָהֶם כְּאִשָּׁה אֵם הַתִּינוֹק, וּמֵינִיקָה אוֹתָם וְצוֹחֶקֶת עִמָּהֶם, וְאוֹחֶזֶת אוֹתָם וְהוֹרֶגֶת אוֹתָם.</p>\n<p>בְּאֶמְצַע הַהֵיכָל הַזֶּה עוֹמֶדֶת רוּחַ אַחַת שֶׁנִּקְרֵאת אָגִירִיסוֹ\"ן. זוֹ הִתְמַנְּתָה עַל כָּל אוֹתָם שֶׁמֵּתִים מִבֶּן שְׁלֹשׁ עֶשְׂרֵה שָׁנִים עַד עֶשְׂרִים שָׁנִים. זֶהוּ הַהוֹרֵג שֶׁלָּהֶם, כְּמוֹ שֶׁבֵּאַרְנוּ, וְזֶהוּ בַּחֲבֵרוּת (בחכמה) עִם אוֹתוֹ הַנָּחָשׁ שֶׁאָמַרְנוּ, וְעוֹמֵד עִמּוֹ וְהוֹלֵךְ עִמּוֹ. וְעַל כֵּן נִקְרָא מַלְאַךְ הַמָּוֶת טוֹב מְאֹד, שֶׁכָּתוּב (בראשית א) וִהִנֵּה טוֹב מְאֹד, וּבֵאַרְנוּ.</p>\n<p>מִכָּאןֹ מִתְפַּשְּׁטוֹת וְיוֹצְאוֹת שְׁתֵּי רוּחוֹת, אַ\"ף וְחֵמָ\"ה. וְאֵלֶּה הִתְמַנּוּ עַל כָּל אוֹתָם שֶׁשּׁוֹמְעִים נְזִיפָה מִמִּי שֶׁלּוֹמֵד תּוֹרָה, וְהֵם בּוֹטְחִים בּוֹ וְלֹא חוֹשְׁשִׁים מִמֶּנּוּ. וְכֵן עַל כָּל אוֹתָם שֶׁצּוֹחֲקִים מִדִּבְרֵי תוֹרָה אוֹ מִדִּבְרֵי חֲכָמִים.</p>\n<p>מֵהָאַף וְהַחֵמָה הַלָּלוּ יוֹצְאִים כַּמָּה אֲלָפִים וְכַמָּה רְבָבוֹת, וְכֻלָּם יוֹצְאִים וְשׁוֹרִים עַל בְּנֵי אָדָם, אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה אוֹ מִשְׁתַּדְּלִים בְּדִבְרֵי מִצְוָה וְהוֹלְכִים בְּדֶרֶךְ שֶׁל מִצְוָה, כְּדֵי שֶׁיִּתְעַצְּבוּ וְלֹא יִשְׂמְחוּ בָהּ. וּמִשְּׁנֵי אֵלֶּה פָּחַד מֹשֶׁה כְּשֶׁחָטְאוּ יִשְׂרָאֵל וְיָרַד מֵהָהָר, שֶׁכָּתוּב (דברים ט) כִּי יָגֹרְתִּי מִפְּנֵי הָאַף וְהַחֵמָה.</p>\n<p>תַּחַת אֵלּוּ יֵשׁ רוּחַ אַחַת שֶׁעוֹמֶדֶת עַל כָּל אוֹתָם בַּעֲלֵי לָשׁוֹן הָרָע, שֶׁכְּשֶׁמִּתְעוֹרְרִים אֲנָשִׁים בְּלָשׁוֹן הָרָע, אוֹ שֶׁאוֹתוֹ אָדָם שֶׁמִּתְעוֹרֵר בְּלָשׁוֹן הָרָע, אָז מִתְעוֹרֶרֶת הָרוּחַ הָרָעָה הַזּוֹ הַטְּמֵאָה שֶׁלְּמַעְלָה שֶׁנִּקְרֵאת סַכְסִיכָ\"א. וְהִיא שׁוֹרָה עַל אוֹתָהּ הִתְעוֹרְרוּת שֶׁל לָשׁוֹן הָרָע שֶׁהִתְחִילוּ בָהּ בְּנֵי אָדָם, וְהוּא נִכְנָס לְמַעְלָה, וְגוֹרֵם בְּאוֹתָהּ הִתְעוֹרְרוּת שֶׁל לָשׁוֹן הָרָע מָוֶת וְחֶרֶב וְהֶרֶג בָּעוֹלָם. אוֹי לְאוֹתָם שֶׁמְּעוֹרְרִים אֶת הַצַּד הָרָע הַזֶּה וְאֵין שׁוֹמְרִים פִּיהֶם וּלְשׁוֹנָם, וְלֹא חוֹשְׁשִׁים עַל כָּךְ, וְלֹא יוֹדְעִים שֶׁהֲרֵי בַּהִתְעוֹרְרוּת שֶׁלְּמַטָּה תְּלוּיָה הַהִתְעוֹרְרוּת שֶׁלְּמַעְלָה, בֵּין לְטוֹב בֵּין לְרַע.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁהִתְעוֹרְרוּת לָשׁוֹן הָרָע הַזּוֹ מִתְעוֹרֶרֶת לְמַטָּה, אֲזַי הַנָּחָשׁ הָעֲקַלָּתוֹן הַזֶּה מַעֲלֶה אֶת קַשְׂקַשָּׂיו וּמַעֲמִיד אוֹתָם בַּעֲלִיָּה, וּמִתְעוֹרֵר מֵרֹאשׁוֹ עַד רַגְלָיו. וּכְשֶׁקַּשְׂקַשָּׂיו עוֹלִים וּמִתְעוֹרְרִים, אֲזַי כָּל הַגּוּף מִתְעוֹרֵר. קַשְׂקַשָּׂיו, אֵלּוּ הֵם כָּל אוֹתָם שׁוֹמְרֵי הַחֻקִּים שֶׁבַּחוּץ.</p>\n<p>וְכֻלָּם מִתְעוֹרְרִים וְאוֹחֲזִים בְּאוֹתוֹ דָּבָר רַע, וּמְעוֹרְרִים אֵצֶל אוֹתוֹ נָחָשׁ בָּרִיחַ (ישעיה כז). אֲזַי כָּל הַגּוּף הָרָע מִתְעוֹרֵר מֵרֹאשׁוֹ וְעַד רַגְלָיו בְּכָל הַהֵיכָלוֹת הַלָּלוּ שֶׁאָמַרְנוּ, וְכָל אוֹתָם קַשְׂקַשִּׂים שֶׁבְּאוֹתוֹ עוֹר יוֹרְדִים לְמַטָּה, וְאוֹתוֹ עוֹר מִתְפַּשֵּׁט מִמֶּנּוּ וְיוֹרֵד לְמַטָּה. וְהַגּוּף עוֹלֶה, וּמִתְעוֹרֵר לִהְיוֹת מַלְשִׁין לְמַעְלָה.</p>\n<p>בֹּא וּרְאֵה, אַף עַל גַּב שֶׁזְּמַן קָבוּעַ הוּא לְכָל הַנְּחָשִׁים שֶׁל הָעוֹלָם לִפְֹשט אֶת עוֹרָם, אֵינָם מִתְפַּשְּׁטִים אֶלָּא בִּזְמַן שֶׁמִּתְעוֹרְרִים בַּלָּשׁוֹן הָרָע לְמַטָּה, וְאָז מִתְעוֹרֵר אוֹתוֹ הָרוּחַ (הגחש) הָרָע לְמַעְלָה, וּפוֹשֵׁט אֶת עוֹרוֹ וְאֶת קַשְׂקַשָּׂיו מִמֶּנּוּ. זֶה עוֹלֶה וְזֶה יוֹרֵד. וְקָשָׁה עָלָיו אוֹתָהּ הַפְשָׁטַת הַקַּשְׂקַשִּׂים מֵעוֹרוֹ מֵהַכֹּל. מָה הַטַּעַם? מִשּׁוּם שֶׁנִּפְרָד מִזִּוּוּגוֹ. שֶׁאִלְמָלֵא הָיָה הַכֹּל בְּחִבּוּר אֶחָד, לֹא יָכְלוּ הָעוֹלָמוֹת לִסְבֹּל אוֹתָם, וְהַכֹּל מִשּׁוּם הַהִתְעוֹרְרוּת שֶׁל לָשׁוֹן הָרָע שֶׁלְּמַטָּה.</p>\n<p>וּכְשֶׁהַנְּחָשִׁים שֶׁלְּמַטָּה מִתְפַּשְּׁטוֹת מֵאוֹתוֹ הָעוֹר, אֲזַי כָּל אַחַת וְאַחַת נוֹתֶנֶת קוֹל, וּמְעוֹרֶרֶת כַּמָּה נְחָשִׁים שֶׁעוֹמְדוֹת בְּאוֹתוֹ מָקוֹם, שֶׁנִּקְרָא בּוֹר, שֶׁשָּׁם קַיָּמִים כַּמָּה נְחָשִׁים. וְכֻלָּם מַלְשִׁינִים לְעוֹרֵר אֶת הַנָּחָשׁ הַגָּדוֹל הַזֶּה לִהְיוֹת מַלְשִׁין עַל הָעוֹלָם, וְהַכֹּל מִשּׁוּם הַהִתְעוֹרְרוּת הַזּוֹ שֶׁל לָשׁוֹן הָרָע, כְּשֶׁקַּיֶּמֶת הִתְעוֹרְרוּת שֶׁלּוֹ לְמַטָּה.</p>\n<p>כְּמוֹ כֵן מִי שֶׁלּוֹמֵד תּוֹרָה, כַּמָּה הֵם שֶׁנִּקְרָאִים לְשׁוֹן הַקֹּדֶשׁ, שֶׁמִּתְחַבְּרִים וּמְעִירִים הִתְעוֹרְרוּת לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא לְשׁוֹן הַקֹּדֶשׁ. לָשׁוֹן מֵאוֹתוֹ קֹדֶשׁ שֶׁלְּמַעְלָה. וְכַמָּה קְדֻשּׁוֹת וְקִדּוּשִׁים מִתְעוֹרְרִים מִכָּל הַצְּדָדִים. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים, אוֹתָם שֶׁגּוֹרְמִים לְעוֹרֵר קְדֻשּׁוֹת לְמַעְלָה וּלְמַטָּה, קְדֻשָּׁה שֶׁלְּמַעְלָה וּקְדֻשָּׁה שֶׁלְּמַטָּה.</p>\n<p>וְעַל זֶה כָּתוּב, (ויקרא יא) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים. וְהִתְקַדִּשְׁתֶּם - אֵלּוּ מַיִם רִאשׁוֹנִים. וְהֵם נִקְרָאִים מַיִם עֶלְיוֹנִים. וִהְיִיתֶם קְדשִׁים - אֵלּוּ הַמַּיִם הַתַּחְתּוֹנִים, וְנִקְרְאוּ מַיִם אַחֲרוֹנִים. וּמָזוֹן בָּאֶמְצַע, בֵּין מַיִם רִאשׁוֹנִים לְמַיִם אַחֲרוֹנִים. וְעַל זֶה מָזוֹן אֵינוֹ בְּמַיִם אַחֲרוֹנִים, אֶלָּא בְּמַיִם רִאשׁוֹנִים. מַיִם הָרִאשׁוֹנִים מִמַּעְלָה, שֶׁהַמָּזוֹן תָּלוּי בּוֹ, וְלֹא בְּמַיִם אַחֲרוֹנִים. וְהַסּוֹד נִתָּן לִקְדוֹשִׁים עֶלְיוֹנִים. אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522011918,"<p>הַהֵיכָל הָרְבִיעִי. הַהֵיכָל הַזֶּה הוּא נִקְרָא חוֹבָ\"ה. וְזֶהוּ (תהלים מ) טִיט הַיָּוֵן, כְּנֶגֶד שֵׁם אַחֵר שֶׁנִּקְרָא אֶבֶן מִכְשׁוֹל, וְהַכֹּל אֶחָד. הוּא חוֹבָ\"ה, מִשּׁוּם שֶׁשָּׁם קַיָּמִים כָּל חֲטָאֵי הָעוֹלָם, הַכְרָעַת הַחֲטָאִים.</p>\n<p>מִשּׁוּם שֶׁכַּאֲשֶׁר חוֹטְאִים בְּנֵי אָדָם, כָּל אֵלּוּ שׁוֹמְרֵי הַחֻקִּים לוֹקְחִים אוֹתָם הַחֲטָאִים וּמַנִּיחִים אוֹתָם בַּהֵיכָל הַזֶּה שֶׁנִּקְרָא חוֹבָה. וְכָל זְכֻיּוֹת הָעוֹלָם, כָּל הַמַּלְאָכִים הַקְּדוֹשִׁים שֶׁמְּמֻנִּים עַל זְכֻיּוֹת הָעוֹלָם, כֻּלָּם נוֹטְלִים אֶת אוֹתָן הַזְּכֻיּוֹת, וּמַעֲמִידִים אוֹתָן בַּהֵיכָל הָרְבִיעִי שֶׁנִּקְרָא זְכוּת, וְשָׁם עוֹמְדוֹת זְכֻיּוֹת בְּנֵי אָדָם, וְהַחֲטָאִים עוֹמְדִים בְּהֵיכָל אַחֵר שֶׁנִּקְרָא חוֹבָה. וְנִשְׁקָלִים כְּאֶחָד בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה, כִּי (קהלת ז) גַּם אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים. וְאַחַר שֶׁהִכְרִיעוּ הַזְּכֻיּוֹת אוֹ הַחוֹבוֹת לְצַד זֶה אוֹ לְצַד זֶה, כָּךְ מְנַצֵּחַ.</p>\n<p>וְעַל זֶה, בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה, כְּשֶׁמִּתְעוֹרְרִים שְׁנֵי הַצְּדָדִים הַלָּלוּ, זְכוּת וְחוֹבָה, וּבָהֶם תְּלוּיִים חַיִּים וּמָוֶת - אִם הַזְּכֻיּוֹת הִכְרִיעוּ לַצַּד הַזֶּה שֶׁנִּקְרָא זְכוּת, נִכְתָּב הָאָדָם בְּאוֹתוֹ צַד שֶׁנִּקְרָא חַיִּים. מִשּׁוּם שֶׁשְּׁנֵי הַצְּדָדִים הַלָּלוּ עוֹמְדִים בְּאוֹתוֹ יוֹם, זֶה בְּצַד זֶה וְזֶה בְּצַד זֶה. אִם זוֹכֶה אוֹתוֹ אָדָם וְנִצְּחוּ אוֹתָן זְכֻיּוֹת, הֲרֵי נִכְתָּב אוֹתוֹ אָדָם לְחַיִּים, מִשּׁוּם שֶׁאָחַז בּוֹ הַצַּד הַקָּדוֹשׁ הַזֶּה שֶׁנִּקְרָא זְכוּת, וְהַחַיִּים אָחֲזוּ בוֹ, וְאוֹמֵר: זֶה שֶׁלִּי הוּא, וְשֶׁלִּי הָיָה. וְאָז נִכְתָּב אוֹתוֹ אָדָם לְחַיִּים (ונכתב שהוא שלו).</p>\n<p>וְאִם נִצְּחוּ הַחֲטָאִים - הַצַּד הָאַחֵר הַטָּמֵא הַזֶּה, שֶׁנִּקְרָא חוֹבָה וּמָוֶת, אוֹחֵז בּוֹ וְאוֹמֵר: זֶה שֶׁלִּי הוּא, וְשֶׁלִּי הָיָה. וְאָז נִכְתָּב שֶׁהוּא שֶׁלּוֹ. וְזֶהוּ שֶׁשָּׁנִינוּ, שֶׁהֲרֵי בַּיּוֹם הַזֶּה שֶׁל רֹאשׁ הַשָּׁנָה נִכְתָּב אָדָם אוֹ לְחַיִּים אוֹ לְמִיתָה. אִם נִכְתָּב בְּצַד הַקְּדֻשָּׁה - נִכְתָּב לְחַיִּים וּמִתְקַיֵּם שָׁם וְנִדְבָּק בּוֹ. וְאִם נִכְתָּב בַּצַּד הָאַחֵר - מִתְקַיֵּם בְּצַד הַטֻּמְאָה וְדָבֵק בּוֹ, וְזֶהוּ הֵן לְחַיִּים הֵן לַמָּוֶת. וְנִמְשָׁךְ בַּצַּד הַזֶּה אוֹ בַּצַּד הַזֶּה.</p>\n<p>כָּל זְמַן שֶׁהוּא עוֹמֵד בַּצַּד הַזֶּה שֶׁל הַקְּדֻשָּׁה, כָּל הַקִּדּוּשִׁים וְכָל הַטְּהָרוֹת נִדְבָּקִים בּוֹ. יִקְרָא - וְהַקָּדוֹשׁ בָּרוּךְ הוּא יָשׁוּב וְיִשְׁמַע לוֹ. עָלָיו כָּתוּב (תהלים צא) יִקְרָאֵנִי וְאֶעֱנֵהוּ עִמּוֹ אָנֹכִי בְצָרָה אֲחַלְּצֵהוּ וַאֲכַבְּדֵהוּ אֹרֶךְ יָמִים אַשְׂבִּיעֵהוּ וְאַרְאֵהוּ בִּישׁוּעָתִי. וְכָל זְמַן שֶׁהוּא עוֹמֵד בַּצַּד הָאַחֵר שֶׁל הַטֻּמְאָה, כָּל טֻמְאָה וְכָל חֵטְא וְכָל הָרָעוֹת נִדְבָּקוֹת בּוֹ. יִקְרָא - וְאֵין מִי שֶׁיִּשְׁמַע אוֹתוֹ, מְרֻחָק הוּא מֵהַקָּדוֹשׁ בָּרוּךְ הוּא. עָלָיו כָּתוּב, (שם קיט) רָחוֹק מֵרְשָׁעִים יְשׁוּעָה, וְכָתוּב (ישעיה א) גַּם כִּי תַרְבּוּ תְפִלָּה אֵינֶנִּי שּמֵעַ.</p>\n<p>הַהֵיכָל הַזֶּה הוּא הַמָּקוֹם שֶׁל כָּל אוֹתָם שֶׁנִּקְרָאִים אֱלֹהִים אֲחֵרִים, מִשּׁוּם שֶׁמִּתְגַּלִּים כָּאן. וְכָל אוֹתָם שֶׁמְּפַתִּים אֶת בְּנֵי הָאָדָם בְּתַעֲנוּגוֹת הָעוֹלָם הַזֶּה, לִזְנוֹת וּלְהִתְעַנֵּג בְּתַעֲנוּגוֹת שֶׁל נִאוּפִים שֶׁל הָעוֹלָם, וּמוֹשְׁכִים אוֹתָם אַחַר תַּעֲנוּגֵי וְנִאוּפֵי הָעוֹלָם הַזֶּה, כְּמוֹ שֶׁאָמַ רְנוּ.</p>\n<p>בַּהֵיכָל הַזֶּה נִרְאֵית רוּחַ אַחַת שׁוֹלֶטֶת חָזָק, שֶׁהִיא עַל כֻּלָּם, וְאַף זֶה נִקְרָא כָּךְ אֵל, כְּמוֹ הָאַחֵר שֶׁבְּצַד הַקְּדֻשָּׁה. זֶהוּ אֵ\"ל נֵכָ\"ר, וְזֶהוּ שֶׁמְּפַתֶּה אֶת הָאָדָם שֶׁלּוֹמֵד תּוֹרָה אוֹ שֶׁעוֹמֵד בְּבֵית הַמִּדְרָשׁ. הָרוּחַ הַחֲזָקָה הַזּוֹ מְפַתָּה אוֹתוֹ, וְחוֹשֵׁב כַּמָּה הִרְהוּרִים, וְאוֹמֶרֶת: מָה אַתָּה עוֹמֵד כָּאן? טוֹב לְךְ לָלֶכֶת בְּחֶבְרַת אוֹתָם שֶׁגֵּאִים עַל בְּנֵי אָדָם, וְהֵם הוֹלְכִים אַחַר נָשִׁים יָפוֹת וּמִתְעַנְּגִים בְּתַעֲנוּגוֹת הָעוֹלָם. כֵּיוָן שֶׁאָדָם מִתְפַּתֶּה אַחֲרֶיהָ, אָז כֻּלָּן מְשׁוֹטְטוֹת וְהוֹלְכוֹת וְנִמְשָׁכוֹת אַחֲרָיו.</p>\n<p>וְכַמָּה הֵם אֲחֵרִים שֶׁעוֹמְדִים תַּחְתָּיו, וְכֻלָּם מְטַמְּאִים אוֹתוֹ בָּעוֹלָם הַזֶּה, וּמְטַמְּאִים אוֹתוֹ בְּאוֹתוֹ עוֹלָם. וְהֵם נִקְרָאִים צוֹאָה רוֹתַחַת, שֶׁכָּתוּב (ישעיהל) צֵא תֹּאמַר לוֹ. אוֹתָן הַדְּרָגוֹת שֶׁקַּיָּמוֹת לְטַמֵּא תָּמִיד, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>בְּאֶמְצַע הַהֵיכָל הַזֶּה יֵשׁ רוּחַ אַחֶרֶת שֶׁנִּקְרֵאת נֶגַע. וּמִזּוֹ יוֹצֵאת רוּחַ אַחֶרֶת שֶׁנִּקְרֵאת נֶגַע צָרַעַת, וְהִיא עוֹמֶדֶת תָּמִיד לְטַמֵּא אֶת כָּל אוֹתָם בַּעֲלֵי לָשׁוֹן הָרָע יוֹתֵר עַל כָּל מַה שֶּׁמְּטַמְּאִים אוֹתוֹ. וְהַנֶּגַע הָעֶלְיוֹן הַזֶּה מְמֻנֶּה עַל כָּל אוֹתָם שֻׁלְחָנוֹת שֶׁל שַׁבָּת, שֶׁכְּשֶׁנִּכְנֶסֶת שַׁבָּת וְלֹא עָרְכוּ אֶת עֹנֶג הַשַּׁבָּת כָּרָאוּי וְהֵם מְבַזִּים אֶת עֹנֶג הַשַּׁבָּת, הַנֶּגַע הַזֶּה נוֹטֵל אוֹתָם שֻׁלְחָנוֹת שֶׁאֵינָם בְּעֹנֶג שַׁבָּת כְּפִי שֶׁאָמַרְנוּ.</p>\n<p>וּכְשֶׁזֶּה נוֹטֵל אֶת אוֹתָם הַשֻּׁלְחָנוֹת, כָּל אוֹתָם שׁוֹחֲרֵי הַחֻקִּים שֶׁעוֹמְדִים בּוֹ, כֻּלָּם פּוֹתְחִים וְאוֹמְרִים: (תהלים קט) וַיֶּאֱהַב קְלָלָה וַתְּבוֹאֵהוּ וְלֹא חָפֵץ בִּבְרָכָה וַתִּרְחַק מִמֶּנּוּ. וַיִּלְבַּשׁ וְגוֹ'. יְנַקֵּשׁ נוֹשֶׁה לְכָל אֲשֶׁר לוֹ וְגוֹ'. אַל יְהִי לוֹ מֹשֶׁךְ חָסֶד וְגוֹ'.</p>\n<p>וַהֲרֵי בֵּאַרְנוּ, שֶׁבְּאוֹתוֹ לֵיל שַׁבָּת, כְּשֶׁהַשֻּׁלְחָנוֹת נִתְּנוּ לְאוֹתוֹ הַצַּד הָרָע, אֲזַי מִתְחַזֵּק אוֹתוֹ הַצַּד הָרָע הַטָּמֵא, וְאוֹתוֹ אָדָם נִמְסָר לְאוֹתוֹ הַצַּד. אוֹי לוֹ שֶׁנֶּחְסָר מֵאוֹתוֹ הַצַּד הַקָּדוֹשׁ, צַד הָאֱמוּנָה, וְנִפְקָד בַּצַּד הָאַחֵר הַטָּמֵא. כְּמוֹ כֵן בְּכָל אוֹתָן סְעוּדוֹת שֶׁל יוֹם טוֹב.</p>\n<p>כָּאן בַּהֵיכָל הַזֶּה - בָּנִים חַיִּים וּמְזוֹנוֹת הֵם בְּהֵפֶךְ. וּבְאוֹתוֹ הֵיכָל הָאַחֵר הַקָּדוֹשׁ לֹא עוֹמְדִים שְׁלֹשֶׁת אֵלֶּה, וְהֵם תְּלוּיִים לְמַעְלָה, וְכָאן הֵם עוֹמְדִים לְרַע. שֶׁכַּאֲשֶׁר (מגיעים בניו של אדם) מַגִּיעַ אָדָם לַהֵיכָל הַזֶּה, הֲרֵי שָׁם עוֹמְדוֹת הַחַיּוֹת לְכַלּוֹת אוֹתָם. וַהֲרֵי שָׁם בָּנִים כְּשֶׁהֵם קְטַנִּים, מִכָּאן יוֹצֵא, כְּדֵי לְהִתְמַנּוֹת הַקָּטֵגוֹר עֲלֵיהֶם. וַהֲרֵי שָׁם עוֹמְדִים הַמְּזוֹנוֹת לְהַעֲבִירָם מִמֶּנּוּ, וְהַכֹּל תָּלוּי בַּחֵטְא. וְלָכֵן נִקְרָא הַהֵיכָל הַזֶּה חוֹבָה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וּמִכָּאן יוֹצֵאת רוּחַ טֻמְאָה אַחַת שֶׁנִּקְרֵאת אֲרִירִיָּ\"א, וְכַמָּה אֶלֶף וּרְבָבוֹת עִמָּהּ, וְכֻלָּם נִקְרָאִים אוֹרְרֵי יוֹם, כְּמוֹ שֶׁנֶּאֱמַר (איוב ג) יִקְּבֻהוּ אֹרְרֵי יוֹם. וְהָרוּחַ הַזּוֹ וְכָל אֵלֶּה שֶׁעִמָּהּ, כֻּלָּם קַיָּמִים לִטֹּל אוֹתוֹ דִּבּוּר שֶׁקִּלֵּל אָדָם אֶת עַצְמוֹ בְּרָגְזוֹ, וְאֵלּוּ מְעִירִים אֶת הַנָּחָשׁ הַזֶּה שֶׁנִּקְרָא (ישעיה כז) לִוְיָתָן נָחָשׁ עֲקַלָּתוֹן, כְּדֵי לְהָבִיא וּלְעוֹרֵר קְלָלוֹת עַל הָעוֹלָם. זֶהוּ שֶׁכָּתוּב יִקְּבֻהוּ אֹרְרֵי יוֹם וְגוֹ'.</p>\n<p>וְאֵלּוּ אוֹרְרֵי הַיּוֹם שׁוֹלְטִים עַל רִגְעֵי וּשְׁעוֹת הַיּוֹם, וְנוֹטְלִים אוֹתָם דִּבּוּרִים שֶׁקִּלֵּל אָדָם עַל עַצְמוֹ, בֵּין בְּרֹגֶז בֵּין בִּשְׁבוּעָה, וּבְאוֹתוֹ דִּבּוּר מְעִירִים אֶת אוֹתוֹ נָחָשׁ עֲקַלָּתוֹן שֶׁנִּקְרָא לִוְיָתָן, כְּדֵי לְהַעֲמִידוֹ לְהַשְׁחִית אֶת הָעוֹלָם. וְלָכֵן קִלֵּל אִיּוֹב אֶת יוֹמוֹ בְּצַעֲרוֹ, וְלֹא אֶת גּוּפוֹ, שֶׁכָּתוּב (איוב ג) וַיְקַלֵּל אֶת יוֹמוֹ - בַּתְּחִלָּה, וְאַחַר כָּךְ - יִקְּבֻהוּ אֹרְרֵי יוֹם. הָרַחֲמָן יַצִּילֵנוּ מֵהַצַּד הָרָע וּמִתָּקְפּוֹ וּמִכָּל דָּבָר רַע.</p>"],[9522011919,"<p>הַהֵיכָל הַחֲמִישִׁי. הַהֵיכָל הַזֶּה הוּא הֵיכָל שֶׁנִּקְרָא שְׁאוֹ\"ל, כְּנֶגֶד אוֹתוֹ הַשֵּׁם שֶׁנִּקְרָא עָרֵל, וַהֲרֵי בֵּאַרְנוּ שֶׁזֶּהוּ סוֹד הָעָרְלָה. בַּהֵיכָל הַזֶּה יֵשׁ פֶּתַח אֶחָד וּמְמֻנֶּה אֶחָד עָלָיו, וְזֶהוּ הַמְמֻנֶּה לְהָעִיר תָּמִיד קִטְרוּג עַל הָעוֹלָם, וְהָרוּחַ הַזּוֹ נִקְרֵאת אֵיבָ\"ה, מִשּׁוּם שֶׁשְּׁמוֹ שֶׁל הַפֶּתַח הַזֶּה נִקְרָא אֵיבָ\"ה, וְסִימָנְךְ - (בראשית ג) וְאֵיבָה אָשִׁית בֵּינְךְ וּבֵין הָאִשָּׁה וְגוֹ'.</p>\n<p>בַּהֵיכָל הַזֶּה עוֹמֶדֶת רוּחַ אַחַת שֶׁשּׁוֹלֶטֶת עַל הַכֹּל, וְזֶה נִקְרָא שׁוֹדֵ\"ד, וְהוּא (ישעיהנט) שׁוֹד וָשֶׁבֶר. וְזֶהוּ שׁוֹדֵד בֶּהָרִים הָרָמִים, בְּתוֹךְ סְלָעִים וְהָרִים. מֵהַהֵיכָל הַזֶּה יוֹנְקִים כָּל אוֹתָם שׁוֹדְדִים וּמַשְׁמִידִים בִּמְקוֹמוֹת חֻרְבָּן. וּמִכָּאן יוֹצְאִים כָּל אוֹתָם שֶׁהוֹרְגִים בַּחֲרָבוֹת וּבִרְמָחִים, וְהוֹלְכִים אַחַר (בראשית ג) לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, לְהַשְׁמִיד הַכֹּל.</p>\n<p>מִזֶּה יוֹצֵאת רוּחַ אַחֶרֶת שֶׁנִּקְרֵאת שׁוֹד. וּכְשֶׁשּׁוֹלֵט הָרָעָב עַל הָעלָם, הָרוּחַ הַזּוֹ שֶׁנִּקְרֵאת שׁוֹ\"ד נִמְצֵאת, וְרוּחַ אַחֶרֶת מִשְׁתַּתֶּפֶת עִמָּהּ, שֶׁנִּקְרֵאת כָּפָ\"ן. וְאֵלּוּ הוֹלְכִים בָּעוֹלָם, וְנִמְצָאִים כְּנֶגֶד בְּנֵי אָדָם. וְהַיְנוּ שֶׁכָּתוּב (איוב ה) לְשֹׁד וּלְכָפָן תִּשְׂחָק. וְאֵלּוּ עוֹשִׂים קִטְרוּג לִבְנֵי אָדָם וְשׁוֹדְדִים אֶת הַכֹּל. הָאֶחָד שֶׁנִּקְרָא שׁוֹד. שֶׁאַחַר שֶׁהוֹלֵךְ לְתוֹךְ הָרִים רָמִים וְשׁוֹדֵד וּמַחֲרִיב וּמַשְׁמִיד הַכֹּל, אָז שָׁב וְשׁוֹדֵד בְּנֵי אָדָם, וּמֵתִים בְּחֻלְשָׁתוֹ. וּכְשֶׁאוֹכְלִים בְּנֵי אָדָם, לֹא שְׂבֵעִים, מִשּׁוּם שֶׁהוּא שׁוֹלֵט בָּעוֹלָם.</p>\n<p>וּבְאוֹתוֹ זְמַן, מִי שֶׁעוֹשֶׂה חֶסֶד עִם בְּנֵי אָדָם וְנוֹתֵן לָהֶם לֶאֱכֹל וְלִשְׁתּוֹת, כְּדַאי הוּא לִדְחוֹת אֶת שְׁתֵּי הָרוּחוֹת הַחוּצָה שֶׁלֹּא יִשְׁלְטוּ בָּעוֹלָם. וּכְשֶׁיִּשְׂרָאֵל לֹא עוֹשִׂים חֶסֶד עִם בְּנֵי אָדָם, וּשְׁאָר הָעַמִּים עוֹשִׂים חֶסֶד בָּעוֹלָם, אָז שְׁתֵּי הָרוּחוֹת הַלָּלוּ, מִתְבַּשְּׂמִים (לשאר עמים, ומתחזקים וכו') דִּבְרֵיהֶם וּמִתְחַזְּקִים עַל יִשְׂרָאֵל. מִשּׁוּם שֶׁהֲרֵי אָז הִתְחַזֵּק אוֹתוֹ הַצַּד הָאַחֵר, וְיִשְׂרָאֵל נִכְנָעִים.</p>\n<p>וּכְשֶׁיִּשְׂרָאֵל עוֹשִׂים חֶסֶד, נִכְנָע אוֹתוֹ הַצַּד הָאַחֵר וְנֶחֱלָשׁ, וְצַד הַקְּדֻשָּׁה מִתְחַזֵּק. וּכְשֶׁיִּשְׂרָאֵל לֹא מְעוֹרְרִים חֶסֶד, אוֹתָן שְׁתֵּי רוּחוֹת (מתבשמות. אחת התבשמה להם לשאר העמים) וּמִתְהַפְּכוֹת כְּדֵי לְהַכְרִיעַ אוֹתָם אֶת יִשְׂרָאֵל, וְאָז אוֹתָן הַבְּרָכוֹת שֶׁיּוֹרְדוֹת מִלְמַעְלָה מִצַּד הַיָּמִין, יוֹנְקִים אוֹתָם שְׁאָר הָעַמִּים (ועומד לאותו הצד). וְזֶהוּ שֶׁכָּתוּב, (שיר א) שָׂמוּנִי נֹטֵרָה אֶת הַכְּרָמִים. אֵלּוּ שְׁאָר הָעַמִּים. כַּרְמִי שֶׁלִּי לֹא נָטַרְתִּי - אֵלּוּ יִשְׂרָאֵל. מִשּׁוּם שֶׁשְּׁאָר הָעַמִּים מוֹשְׁכִים אוֹתָם לְתוֹכָם בְּאוֹתָם חֲסָדִים שֶׁעוֹשִׂים עִם בְּנֵי אָדָם, וְיִשְׂרָאֵל מַרְחִיקִים אוֹתָם מִתּוֹכָם, מִשּׁוּם שֶׁלֹּא מִשְׁתַּדְּלִים בְּאוֹתָם חֲסָדִים כְּמוֹ שְׁאָר הָעַמִּים.</p>\n<p>וְתַחַת הָרוּחוֹת הַלָּלוּ עוֹמְדִים כָּל אוֹתָם שֶׁנִּקְרְאוּ עָרְלָה. זְמוֹרֵי עָרְלָה, עַנְפֵי עָרְלָה. וּמֵעֲלֵיהֶם מְמֻנֶּה אֶחָד שֶׁנִּקְרָא גְּזַ\"ר דִּינַיָּ\"א. וְזֶהוּ שֶׁעוֹמֵד עַל כָּל אוֹתָם שֶׁלֹּא שׁוֹמְרִים שְׁנוֹת עָרְלַת הָאִילָן, וְעַל כָּל אוֹתָם שֶׁמְּעַכְּבִים אֶת הַבְּרִית לִבְנֵיהֶם. וְלָכֵן הַנָּחָשׁ רָצָה לַהֲרֹג אֶת בְּנוֹ שֶׁל מֹשֶׁה עַד שֶׁמָּלָה אוֹתוֹ צִפּוֹרָה, שֶׁכָּתוּב (שמות ד) וַתִּקַּח צִפֹּרָה צֹר וַתִּכְרֹת אֶת עָרְלַת בְּנָהּ וְגוֹ'.</p>\n<p>וְהָרוּחַ הַזּוֹ מְמֻנָּה עַל אֲנָשִׁים שֶׁמַּשְׁחִיתִים דַּרְכֵיהֶם וְלֹא חוֹשְׁשִׁים לִכְבוֹד רִבּוֹנָם, לִשְׁמֹר אֶת אוֹת בְּרִית הַקֹּדֶשׁ, וְזוֹ מַכְנִיסָה אוֹתָם לַגֵּיהִנֹּם לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא שְׁאוֹל וַאֲבַדּוֹן, וְנִדּוֹן שָׁם כְּמוֹ שֶׁבֵּאַרְנוּ כָּאן.</p>\n<p>לְתוֹךָ אֶמְצַע הַהֵיכָל הַזֶּה עוֹמֶדֶת רוּחַ אַחַת, שֶׁעוֹמֶדֶת וְאוֹרֶבֶת עַל דְּרָכִים וּשְׁבִילִים, לִרְאוֹת אֶת כָּל אתָם שֶׁעוֹבְרִים עַל דִּבְרֵי הַתּוֹרָה, כְּדֵי לְהַכְנִיס שִׂנְאָה בֵּין מַעְלָה וּמַטָּה, מִשּׁוּם שֶׁכָּל הַהֵיכָל הַזֶּה הוּא אֵיבָה.</p>\n<p>זֶה וְכָל אוֹתָם הָאֲחֵרִים, כֻּלָּם עוֹמְדִים לְהַרְאוֹת פָּנִים מְאִירוֹת לִבְנֵי אָדָם וּלְפַתּוֹת אוֹתָם, כְּדֵי שֶׁיִּסְטוּ מִדֶּרֶךְ הָאֱמֶת וְלִמְשֹׁךְ אוֹתָם אַחֲרֵיהֶם, וְאַחַר כָּךְ הֵם הוֹרְגִים אוֹתָם, וְיָמוּתוּ בִּשְׁנֵי עוֹלָמוֹת, שֶׁכָּתוּב (משלי ה) וְאַחֲרִיתָהּ מָרָה כַלַּעֲנָה חַדָּה כְּחֶרֶב פִּיּוֹת.</p>\n<p>הָרוּחַ הַזּוֹ נִקְרֵאת אַפְרִירָ\"א. עָפָר שֶׁל אֵפֶר. שֶׁלֹּא עוֹשֶׂה תוֹלָדוֹת וּפֵרוֹת לְעוֹלָמִים, מִשּׁוּם שֶׁזֶּהוּ עָפָר שֶׁל אֵפֶר. וְאַף עַל גַּב שֶׁנִּקְרָא עָפָר, אֵינוֹ עָפָר קָדוֹשׁ שֶׁעוֹשֶׂה פֵרוֹת, וְנִקְרָא (איוב כח) עַפְרוֹת זָהָב. אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר, (במדבר יט) מֵעֲפַר שְׂרֵפַת הַחַטָּאת. וְזֶהוּ עֲפַר שְׂרֵפַת הַחַטָּאת. וְסִימָן זֶה בָּא בִּשְׁנֵי צְדָדִים. אֶחָד, מִשּׁוּם שֶׁהוּא כָּלוּל בַּחַטָּאת הַזּוֹ, הַסּוֹד שֶׁל אוֹתוֹ נָחָשׁ הַקָּשֶׁה. וְאֶחָד, שֶׁכְּשֶׁאָדָם עוֹשֶׂה חַטָּאת, הוּא מְחַזֵּק אֶת הֶעָפָר הַזֶּה וְשׁוֹלֵט בָּעוֹלָם.</p>\n<p>וְזְהִוּ הַכָּלוּל (במדבר ה) בְּמֵי הַמָּרִים הַמְאָרַרִים. וְלָכֵן צָרִיךְ אוֹתוֹ לָאִשָּׁה שֶׁסָּטְתָה תַּחַת בַּעְלָהּ וְעָשְׂתָה מַעֲשֶׂה שֶׁל אֵשֶׁת זְנוּנִים, לְהַשְׁקוֹת אוֹתָהּ מַיִם שֶׁכְּלוּלִים בְּעָפָר, שֶׁהוּא מִקַּרְקַע הַמִּשְׁכָּן, וְהֶעָפָר הַזֶּה הוּא מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא קַרְקַע, וְאוֹתוֹ שֶׁנִּקְרָא קַרְקַע שֶׁל אוֹתוֹ מִשְׁכָּן. וְהֶעָפָר הַזֶּה הוּא מֵאוֹתוֹ קַרְקַע. וּמִשּׁוּם כָּךְ צָרִיךְ הַכֹּהֵן לְהַשְׁקוֹת אֶת הָאִשָּׁה הַזּוֹ כְּמוֹ כֵן. וְהַכֹּל הוּא בְּרֶמֶז עֶלְיוֹן.</p>\n<p>אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְטַהֵר אוֹתָם בְּמַיִם טְהוֹרִים עֶלְיוֹנִים, שֶׁכָּתוּב (יחזקאל לו) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם. מַיִם טְהוֹרִים הֲרֵי אָמַרְנוּ, בֵּין מַיִם רִאשׁוֹנִים לְמַיִם אַחֲרוֹנִים. וְאַף עַל גַּב שֶׁהֲרֵי בֵּאַרְנוּ, מַיִם רִאשׁוֹנִים מִצְוָה - כָּךְ נִקְרְאוּ, וּמַיִם אַחֲרוֹנִים חוֹבָה - גַּם כָּךְ נִקְרְאוּ. וַהֲרֵי בֵּאַרְנוּ עַל שְׁנֵי הַצְּדָדִים הַלָּלוּ, הַצַּד הַזֶּה שֶׁל קְדֻשָּׁה נִקְרָא מִצְוָה, וְהַצַּד הָאַחֵר הַזֶּה נִקְרָא חוֹבָה. וּמִשּׁוּם כָּךְ נָטַל חֶלְקוֹ בְּאוֹתָם הַמַּיִם, וְעַל זֶה כָּתוּב, וְזָרַקְתִּי עֲלֵיהֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם.</p>"],[9522011920,"<p>הַהֵיכָל הַשִּׁשִּׁי. הַהֵיכָל הַזֶּה עוֹמֵד לְמַעְלָה עַל כָּל אוֹתָם שְׁאָר הַהֵיכָלוֹת הַתַּחְתּוֹנִים. אַרְבָּעָה פְתָחִים יֵשׁ לַהֵיכָל הַזֶּה. הָאֶחָד נִקְרָא מָוֶת, וְאֶחָד נִקְרָא רָע, וְאֶחָד נִקְרָא צַלְמָוֶ\"ת, וְאֶחָד נִקְרָא אֹפֶ\"ל. אֵלּוּ אַרְבַּעַת הַפְּתָחִים עוֹמְדִים תָּמִיד לְהָרַע, וְאֵלּוּ הֵם הַכְּלָל שֶׁל הַכֹּל.</p>\n<p>כְּמוֹ שֶׁיֵּשׁ בְּצַד הַקְּדֻשָּׁה בְּסוֹד הָאֱמוּנָה אַרְבָּעָה פְתָחִים לְאַרְבָּעָה צְדָדִים שֶׁמִּתְקַשְּׁרִים זֶה בָּזֶה, וְכֻלָּם קְדוֹשִׁים, כָּךְ גַּם לְמַטָּה כָּאן. וּכְשֶׁאֵלֶּה נִקְשָׁרִים וּמִתְחַבְּרִים זֶה עִם זֶה כְּאֶחָד בַּהֵיכָל הַזֶּה, אֲזַי נִקְרָא בֵּית חָבֶר, כְּמוֹ שֶׁנֶּאֱמַר, (משלי כא) מֵאֵשֶׁת מִדְיָנִים וּבֵית חָבֶר. וְהַהֵיכָל הַזֶּה עוֹמֵד תָּמִיד לְהָרַע.</p>\n<p>עֵל הַהֵיכָל הַזֶּה כָּתוּב, (שם כז) וְנַעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא, מִשּׁוּם שֶׁכָּאן עוֹמְדִים כָּל אוֹתָן נְשִׁיקוֹת רָעוֹת וְתַאֲווֹת רָעוֹת, וְכָל עִדּוּנֵי הַגּוּף שֶׁל הָעוֹלָם הַזֶּה, שֶׁבְּאוֹתָם הָעִדּוּנִים מִתְגָּרֵשׁ אָדָם מֵהָעוֹלָם הַזֶּה וּמֵהָעוֹלָם הַבָּא. וְעַל הַהֵיכָל הַזֶּה כָּתוּב, (שם ה) כִּי נֹפֶת תִּטֹּפְנָה שִׂפְתֵי זָרָה וְגוֹ'.</p>\n<p>בַּהֵיכָל הַזֶּה עוֹמֶדֶת רוּחַ אַחַת שֶׁמְּמֻנָּה עַל כָּל אֵלּוּ שֶׁלְּמַטָּה, וְהִיא כְּלָל עַל כָּל שְׁאָר הָרוּחוֹת. הַהֵיכָל הַזֶּה מִתְקַשֵּׁט בְּקִשּׁוּטֵי יֹפִי עַל כָּל אוֹתָם הַהֵיכָלוֹת. בַּהֵיכָל הַזֶּה נִלְכָּדִים רַגְלֵי הַטִּפְּשִׁים. עַל הַהֵיכָל הַזֶּה כָּתוּב, (משלי ו) אַל תַּחְמֹד יָפְיָהּ בִּלְבָבֶךְ וְאַל תִּקָּחֲךְ בְּעַפְעַפֶּיהָ.</p>\n<p>בַּהֵיכָל הַזֶּה תְּלוּיִים כָּל תַּאֲווֹת הָעוֹלָם וְכָל אוֹתָם עִנּוּגִים שֶׁל הַטִּפְּשִׁים חַסְרֵי הַלֵּב, חַסְרֵי הַדַּעַת, כְּמוֹ שֶׁנֶּאֱמַר, (שם ז) וָאֵרֶא בַפְּתָאיִם אָבִינָה בַבָּנִים נַעַר חֲסַר לֵב עֹבֵר בַּשּׁוּק אֵצֶל פִּנָּהּ וְגוֹ'. בְּנֶשֶׁף בְּעֶרֶב יוֹם וְגוֹ'. וְאָז קְרֵבוֹת רַגְלָיו לַהֵיכָל הַזֶּה, שֶׁהוּא כְּלָל שֶׁל כָּל הַתַּחְתּוֹנִים. וְאָז, (שם) וְהִנֵּה אִשָּׁה לִקְרָאתוֹ שִׁית זוֹנָה וּנְצֻרַת לֵב. שִׁית - זֶהוּ הַהֵיכָל הַזֶּה שֶׁהוּא שִׁשִּׁי לְכָל שְׁאָר הַהֵיכָלוֹת, וְכָאן עוֹמֶדֶת זוֹנָה לְפַתּוֹת אֶת הַטִּפְּשִׁים.</p>\n<p>בַּהֵיכָל הַזֶּה עוֹמֶדֶת וְאֵינָהּ עוֹמֶדֶת. יוֹרֶדֶת וּמְפַתָּה, עוֹלָה וּמַשְׂטִינָה, כְּמוֹ שֶׁנֶּאֱמַר (שם) בְּבֵיתָהּ לֹא יִשְׁכְּנוּ רַגְלֶיהָ. פַּעַם בַּחוּץ פַּעַם בָּרְחֹבוֹת - כְּשֶׁעוֹלָה לְמַעְלָה. וְאֵצֶל כָּל פִּנָּה תֶאֱרֹב - כְּשֶׁנּוֹטֶלֶת אֶת הַנְּשָׁמָה.</p>\n<p>מַה כָּתוּב? וְהֶחֱזִיקָה בּוֹ וְנָשְׁקָה לּוֹ. אֵלּוּ אוֹתָן נְשִׁיקוֹת לְטַמֵּא וּלְהַטְעוֹת בְּנֵי אָדָם אַחֲרֶיהָ, מִשּׁוּם שֶׁכָּאן הוּא מְקוֹמָם שֶׁל כָּל אוֹתָן הַנְּשִׁיקוֹת הָרָעוֹת, וּמִכָּל הַזְּנוּנִים הַזָּרִים שֶׁהֵם מְתוּקִים לְפִי שָׁעָה, אוֹי לְסוֹפָם! כְּמוֹ שֶׁכָּתוּב (שם ה) וְחָלָק מִשֶּׁמֶן חִכָּהּ.</p>\n<p>וְכָתוּב, וְאַחֲרִיתָהּ מָרָה כַלַּעֲנָה. מַה זֶּה מָרָה כַלַּעֲנָה? אֶלָּא כְּשֶׁאָדָם מִתְפַּתֶּה אַחֲרֶיהָ בָּעוֹלָם הַזֶּה וּמַגִּיעַ זְמַנּוֹ לְהִסְתַּלֵּק מֵהָעוֹלָם הַזֶּה, הִיא עוֹמֶדֶת עַל הָאָדָם וּמִתְלַבֶּשֶׁת לְפָנָיו בִּגְלִימָה שֶׁל גּוּף שֶׁל אֵשׁ וְחֶרֶב שְׁנוּנָה בְּיָדָהּ, וְשָׁלֹשׁ טִפּוֹת בָּהּ.</p>\n<p>וּפֵרְשׁוּהָ, וּבָהּ טִפָּה אַחַת מֵאוֹתָן טִפּוֹת שֶׁהִיא מָרָה, וּבְשָׁעָה שֶׁמַּטִּילָה אוֹתָהּ לְפִיו שֶׁל אָדָם, הִיא נִכְנֶסֶת לְמֵעָיו, וְאָז הַנְּשָׁמָה מִתְבַּלְבֶּלֶת, וְאוֹתָהּ טִפָּה מְשׁוֹטֶטֶת וְהוֹלֶכֶת בְּתוֹךְ הַגּוּף וְעוֹקֶרֶת אֶת הַנְּשָׁמָה מִמְּקוֹמָהּ, וְלֹא מַשְׁאִירָה לַנְּשָׁמָה מָקוֹם לָשֶׁבֶת, וְהִיא מָרָה כַלַּעֲנָה, וְטוֹעֵם אוֹתָהּ הָאָדָם בִּמְרִירוּת תְּמוּרַת אוֹתָהּ מְתִיקוּת שֶׁטָּעֲמוּ בָהּ בָּעוֹלָם הַזֶּה כְּשֶׁנִּמְשְׁכוּ אַחֲרֶיהָ. אַחַר כָּךְ זוֹרֶקֶת טִפָּה אַחֶרֶת, וְהַנְּשָׁמָה יוֹצֵאת וּמֵת הָאָדָם. וְאַחַר כָּךְ זוֹרֶקֶת טִפָּה אַחֶרֶת, וּפָנָיו מוֹרִיקוֹת, וּמַסְרִיחַ. מִשּׁוּם שֶׁהַנְּשָׁמָה קְדוֹשָׁה, וּכְשֶׁשּׁוֹלֵט עָלֶיהָ הַצַּד הָאַחֵר הַזֶּה, עוֹקֶרֶת מִלְּפָנָיו, וְלֹא מִתְיַשְּׁבִים בְּיַחַד.</p>\n<p>מִשּׁוּם כָּךְ, כְּמוֹ שֶׁנִּדְבַּק בְּאוֹתָן נְשִׁיקוֹת רָעוֹת בָּעוֹלָם הַזֶּה, אַף כָּךְ גַּם בַּשָּׁעָה הַזּוֹ. שֶׁאִם אָדָם נִמְשָׁךְ אַחֲרֶיהָ בָּעוֹלָם הַזֶּה וְעוֹזֵב אֶת הַצַּד הַקָּדוֹשׁ, אָז הַנְּשָׁמָה אֵינָהּ חוֹזֶרֶת לְאוֹתוֹ מָקוֹם קָדוֹשׁ. וּכְמוֹ שֶׁנִּמְשַׁךְ אַחֲרֶיהָ בָּעוֹלָם הַזֶּה, כָּךְ גַּם שׁוֹלֶטֶת עַל נִשְׁמָתוֹ, וְאָז הַנְּשָׁמָה יוֹצֵאת כְּמוֹ בַּחֲבָלִים, וּפֵרְשׁוּהָ. וְכָל זֶה מִשּׁוּם שֶׁאוֹתָן נְשִׁיקוֹת שֶׁנּוֹשְׁקוֹת אוֹתָהּ בָּעוֹלָם הַזֶּה, שֶׁהֵן מְתוּקוֹת, וְאַחַר כָּךְ מְרִירוֹת בַּשָּׁעָה הַזּוֹ. וְעַל כֵּן, וְהֶחֱזִיקָה בּוֹ וְנָשְׁקָה לּוֹ, בָּעוֹלָם הַזֶּה, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>הֵעֵזָה פָנֶיהָ וַתֹּאמַר לוֹ. מִשּׁוּם שֶׁבַּהֵיכָל הַזֶּה עוֹמְדִים כָּל הַקָּטֵגוֹרִים, וְכָל הַשְּׁלִיחִים הָרָעִים שֶׁנִּמְצָאִים אֵצֶל הָאָדָם וְגוֹרְמִים לוֹ שֶׁיִּתְתַּקֵּן בְּתִקּוּנָיו וִיסַלְסֵל בִּשְׂעָרוֹ וְיִתְרַחֵץ וְיִתְתַּקֵּן כְּדֵי שֶׁיִּסְתַּכְּלוּ בוֹ. כָּאן עוֹמֶדֶת רוּחַ אַחַת שֶׁנִּקְרֵאת סְקָטוּפָ\"ה, וְזֶהוּ הַמְמֻנֶּה עַל כָּל תִּקּוּן וְסִלְסוּל שֶׁל בְּנֵי אָדָם.</p>\n<p>לִפְנִים הַהֵיכָל הַזֶּה עוֹמֵד מְמֻנֶּה אַחֵר, שֶׁהַמְמֻנֶּה הָאַחֵר הַזֶּה מְעוֹרֵר אֶת הָאָדָם אַחַר כָּךְ לְעוֹרְרָם, שֶׁהֲרֵי הוּא מַתְקִין גּוּפוֹ וּמְסַלְסֵל בִּשְׂעָרוֹ, שֶׁיִּטֹּל בְּיָדוֹ מַרְאָה אַחַת לְהִסְתַּכֵּל בָּהּ, וּמַחֲזִיקָהּ בְּיָדוֹ וּמִסְתַּכֵּל בָּהּ, וְרוֹאֶה אֶת דְּמוּתוֹ בְּאוֹתוֹ מַרְאֶה. וּבָזֶה מְעוֹרֵר אֶת אוֹתָהּ הָרוּחַ לְכֹחַ אַחֵר, שֶׁנִּקְרָא עַסִירְטָ\"א, וּמִכָּאן יוֹצְאִים כָּל אוֹתָם שֶׁמַּרְאִים לָאֲנָשִׁים כְּזָבִים בַּחֲלוֹמוֹתֵיהֶם, וְכָל אוֹתָם שֶׁמַּרְאִים דְּבָרִים וְלֹא מִתְקַיְּמִים בָּהֶם, אֶלָּא לְבַלְבֵּל אוֹתָם.</p>\n<p>וְאַחַר כָּךְ, כְּשֶׁאוֹתָם אֲנָשִׁים נִמְשָׁכִים בְּאוֹתוֹ מַרְאֶה שֶׁנִּקְרָא מַרְאָה, אָז כֻּלָּם בְּגַסּוּת הָרוּחַ שֶׁלָּהֶם, וְהָרוּחַ הַזּוֹ שֶׁנִּקְרֵאת עַסִירְטָ\"א, הִיא מְעוֹרֶרֶת לְרוּחַ אַחַת הַמְמֻנָּה שֶׁהִיא תַּחַת יָדֶיהָ, וְנִכְנֶסֶת לַנֶּקֶב שֶׁלְּמַטָּה שֶׁל כָּל הַנְּקָבִים, וּמַעֲלָה מִשָּׁם רוּחַ אַחַת אַחֶרֶת שֶׁמְּמֻנָּה עִם אוֹתָהּ רוּחַ שֶׁנִּקְרֵאת אַסְכָּרָ\"ה, כְּפִי שֶׁאָמַרְנוּ. וְזוֹהִי לִילִי\"ת, אֵם הַשֵּׁדִים. וּכְשֶׁאוֹתוֹ אָדָם מְעוֹרֵר אֶת הָרוּחַ הָאַחֶרֶת שֶׁנִּקְרֵאת עַסִירְטָ\"א, אֲזַי מִתְחַבֶּרֶת עִם אוֹתוֹ אָדָם, וְנִקְשָׁר עִמָּהּ תָּמִיד. וְאָז בְּכָל רֹאשׁ חֹדֶשׁ וְחֹדֶשׁ מִתְעוֹרֶרֶת אוֹתָהּ הָרוּחַ שֶׁל מַרְאֶה רַע עִם לִילִי\"ת, וְלִפְעָמִים נִזּוֹק מֵהֶם אוֹתוֹ אָדָם וְיִפֹּל לָאָרֶץ וְלֹא יוּכַל לָקוּם, אוֹ שֶׁיָּמוּת. וְכָל זֶה גּוֹרֵם אוֹתוֹ מַרְאֵה הַמַּרְאָה שֶׁהוּא מִסְתַּכֵּל בָּהּ. שֶׁכְּמוֹ שֶׁמַּרְאֶה גַּסּוּת שֶׁל רוּחַ בְּלִבּוֹ, כָּךְ גַּם מַרְבֶּה רוּחַ רָעָה אֵלָיו. וְלָכֵן הַכֹּל עוֹמֵד בְּאוֹתָהּ הִתְעוֹרְרוּת שֶׁלְּמַטָּה.</p>\n<p>זִבְחֵי שְׁלָמִים עָלָי (משלי ז). בֹּא וּרְאֵה, שְׁלָמִים לֹא בָאִים עַל חוֹב, וְלֹא עַל חַטָּאת, אֶלָּא עַל שָׁלוֹם. מַה זֶּה שְׁלָמִים? אֶלָּא שְׁלָמִים מִשְּׁנֵי צְדָדִים, שֶׁלֹּא נִמְצָא מְקַטְרֵג עָלָיו. לֹא לְמַעְלָה וְלֹא לְמַטָּה. מִי הוּא הַמְקַטְרֵג? אֶלָּא אוֹתוֹ צַד הַשְּׂמֹאל שֶׁל יֵצֶר הָרָע, שֶׁיִּמָּצֵא בְשָׁלוֹם שֶׁל הַיָּמִין. וְעַל כֵּן, זִבְחֵי שְׁלָמִים עָלָי. (עלידוקא, אותםזבחישלמים עלי הם, כדי שלא ימצא מקטרג על העולם).</p>\n<p>דָּבָר אַחֵר זִבְחֵי שְׁלָמִים עָלָי - הֲרֵי אֲנִי בְּשַׁלְוָה לְגַבֶּיךְ, לְהַרְאוֹת לְךְ שָׁלוֹם. וּמִשּׁוּם כָּךְ, הַיּוֹם שִׁלַּמְתִּי נְדָרָי, לְפַתּוֹת אֶת בְּנֵי הָעוֹלָם תָּמִיד. עַל כֵּן יָצָאתִי לִקְרָאתֶךְ וְגוֹ' שֶׁיָּדַעְתִּי שֶׁאַתָּה חֲסַר לֵב, חֲסַר טוֹבָה. לְשַׁחֵר פָּנֶיךְ, לְהִתְחַבֵּר עִמְּךְ בְּכָל הָרָעוֹת שֶׁל הָעוֹלָם. וְנָאֶה לְךְ לֵהָנוֹת וְלִטְעוֹת אַחַת הַתְּשׁוּקוֹת שֶׁל הָעוֹלָם הַזֶּה. וּמְדַרְדֶּרֶת אוֹתוֹ מִדָּבָר לְדָבָר, וּמֵרָעָה לְרָעָה. וְחִזַּרְתִּי בֵּין הַטִּפְּשִׁים וְשִׁחַרְתִּי פָנֶיךְ, וָאֶמְצָאֶךָּ, וּכְבָר מָצָאתִי אוֹתְךְ כְּדֵי לְהִדָּבֵק בְּךְ.</p>\n<p>לְכָה נִרְוֶה דדִים עַד הַבּקֶר. זֶהוּ שֶׁכָּתוּב (איוב כד) וְעֵין נֹאֵף שָׁמְרָה נֶּשֶׁף. שֶׁהֲרֵי אָז הוּא הַזְּמַן לִשְׁלֹט. לְכָה נִרְוֶה דדִים, נֵלֵךְ כְּאֶחָד, הֲרֵינִי עִמְּךְ. שֶׁהֲרֵי עַד עַכְשָׁו אַתָּה עֶלֶם אַתָּה בְּכֹחֲךְ, אִם לֹא תְּעַנֵּג אֶת עַצְמְךְ עַכְשָׁו, אָז מָתַי? כְּשֶׁתִּהְיֶה זָקֵן?! עַכְשָׁו זֶה הַזְּמַן! מָה הַטַּעַם? כִּי אֵין הָאִישׁ בְּבֵיתוֹ. זֶה יֵצֶר הַטּוֹב, שֶׁלֹּא שׁוֹרֶה כָּאן בְּתוֹכֲךְ, וְאֵינוֹ הַזְּמַן. הָלַךְ בְּדֶרֶךְ מֵרָחוֹק - שֶׁלֹּא שָׁרוּי בָּאָדָם אֶלָּא בְּדֶרֶךְ מֵרָחוֹק, כְּשֶׁהוּא מִשְּׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַעְלָה, וְלֹא בְּכָל אָדָם, וַאֲנִי עוֹמֵד עִמְּךְ מִיּוֹם שֶׁנּוֹלַדְתָּ, זֶהוּ שֶׁכָּתוּב (בראשית ד) לַפֶּתַח חַטָּאת רֹבֵץ. וְעַכְשָׁו שֶׁאַתָּה רַוָּק, עַכְשָׁו הַזְּמַן לְעַנֵּג אֶת עַצְמְךְ.</p>\n<p>צְרוֹר הַכֶּסֶף לָקַח בְּיָדוֹ (משלי ז), לַעֲלוֹת לְמַעְלָה וּלְהִתְעַכֵּב שָׁם (ולהתעגג). לְיוֹם הַכֶּסֶא יָבוֹא בֵיתוֹ. מָתַי יָבֹא כְּנֶגְדּוֹ? לְיוֹם הַכֶּסֶא, שֶׁהוּא יוֹם הַדִּין לְהַשְׁגִּיחַ בַּדִּין, שֶׁכָּתוּב (תהלים פא) בַּכֶּסֶה לְיוֹם חַגֵּנוּ. בִּזְמַן שֶׁצָּרִיךְ אָדָם לְהִתְעַנֵּג בָּעוֹלָם וְלֵהָנוֹת בּוֹ - מִתְרַחֵק מִמֶּנּוּ. וּבִזְמַן שֶׁשּׁוֹרֶה הַדִּין בָּעוֹלָם, אֲזַי בָּא אֵלָיו לַעֲשׂוֹת עִמּוֹ דִּין. וְעַל כָּךְ, הִטַּתּוּ בְּרֹב לִקְחָהּ וְגוֹ'. עַד יְפַלַּח חֵץ כְּבֵדוֹ. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁיּוֹדְעִים דְּרָכִים קְדוֹשִׁים לָלֶכֶת בָּהֶם, וְלֹא יִסְטוּ יָמִין וּשְׂמֹאל. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522011921,"<p>הַהֵיכָל הַשְּׁבִיעִי. זֶהוּ הֵיכָל שֶׁל שִׁמְרֵי הַיַּיִן לִרְווֹת בּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ט) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל. סְחִיטַת כָּל אוֹתָם הָעֲנָבִים, כֻּלָּם עֲנָבִים רָעִים. כָּאן הִיא הַסְּחִיטָה שֶׁלָּהֶם, וְזֶהוּ (תהלים עה) יַיִן חָמַר. שְׁמָרִים שֶׁל יַיִן שֶׁאֵין מִי שֶׁשּׁוֹתֶה מִמֶּנּוּ, שֶׁלֹּא גוֹרֵם מָוֶת לְעַצְמוֹ. מִן הַיַּיִן הַזֶּה הִטְעִימָה חַוָּה אֶת בַּעְלָהּ וְהִכְנִיסָה אוֹתוֹ לַהֵיכָל הַזֶּה. שֶׁשָּׁנִינוּ, סָחֲטָה עֲנָבִים וְנָתְנָה לוֹ, וְגָרְמָה מָוֶת לוֹ וּלְכָל הָעוֹלָם אַחֲרָיו.</p>\n<p>בַּהֵיכָל הַזֶּה עוֹמְדוֹת כָּל אוֹתָן הַנְּשָׁמוֹת הַטְּמֵאוֹת שֶׁיּוֹרְדוֹת לְכָל אוֹתָם שֶׁנִּדְבָּקִים בַּצַּד הַזֶּה, וְאוֹתָהּ רוּחַ שֶׁיּוֹרֶדֶת לְכָל אוֹתָם שֶׁמִּצִּדָּהּ, מִכָּאן יוֹצְאִים. כְּמוֹ שֶׁהֵם סָטוּ דַרְכָּם בָּעוֹלָם הַזֶּה וְהִשְׁתַּדְּלוּ בִזְנוּת בְּמָקוֹם שֶׁלֹּא צָרִיךְ לְהִתְרַחֵק מִדֶּרֶךְ הָאֱמֶת. וְאָז, כְּמוֹ שֶׁהוּא נִדְבַּק בְּאוֹתוֹ צַד שֶׁל יֵצֶר הָרָע בִּזְנוּת, כָּךְ גַּם יוֹצֵאת מֵהַהֵיכָל הַזֶּה רוּחַ טֻמְאָה לְטַמֵּא אוֹתוֹ, וְלַבֵּן שֶׁיּוֹצֵא מִשָּׁם.</p>\n<p>וְאוֹתוֹ הַבֵּן נִקְרָא מַמְזֵר, שֶׁבָּא מִצַּד שֶׁל אֵל זָר. כְּמוֹ שֶׁהוּא נִמְצָא בְּאוֹתָהּ תַּאֲוָה וּבְאוֹתָהּ זְנוּת בְּאוֹתוֹ צַד שֶׁל יֵצֶר הָרָע, כָּךְ גַּם מוֹשֵׁךְ לְאוֹתוֹ בֵּן רוּחַ טֻמְאָה אַחֶרֶת, שֶׁמְּטַמֵּאת, וְכֻלָּם מְעִידִים עָלָיו שֶׁהוּא מַמְזֵר, וְכָךְ כָּל מַעֲשָׂיו וּצְדָדָיו בְּאוֹתוֹ גָּוֶן מַמָּשׁ.</p>\n<p>מֵהַהֵיכָל הַזֶּה יוֹצֵאת רוּחַ אַחַת שֶׁמְּמֻנָּה עַל אוֹתָן רוּחוֹת שֶׁנִּקְרָאוֹת צְפוֹנִי. וְסִימָנְךְ - (משלי כז) צפניה צפן רוח. וזהו הממנה על זה. וההיכל השביעי הזה כנגד אותו שם שנקרא (יחזקאל לא) ארץ תחתית. ועל זה כתוב, (יואלב) ואת הצפוני ארחיק מעליכם.</p>\n<p>כָּאן הִיא נְקֻדָּה אַחַת שֶׁעוֹמֶדֶת לִפְנַי וְלִפְנִים, וּמִכָּאן יוֹצְאוֹת כָּל רוּחוֹת אֲחֵרוֹת שֶׁמְּשׁוֹטְטוֹת בָּעוֹלָם וְשׁוֹלְטוֹת בָּעוֹלָם הַזֶּה בְּכָל אוֹתָם דְּבָרִים וּמַעֲשִׂים שֶׁנִּמְסְרוּ לְצַד הַשְּׂמֹאל. וּמִכָּאן יוֹצְאִים כָּל אוֹתָם זִיקִים וְנִיצוֹצוֹת שֶׁדּוֹעֲכִים מִיָּד, לוֹהֲטִים וְדוֹעֲכִים, וּמֵאֵלֶּה יוֹצְאוֹת רוּחוֹת אֲחֵרוֹת שֶׁשָּׁטוֹת בָּעוֹלָם וּמִשְׁתַּתְּפוֹת עִם אוֹתָן שֶׁיָּצְאוּ מִתּוֹךְ תְּהוֹם רַבָּה. וְהוּא זֶה הַהֵיכָל, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לו) מִשְׁפָּטֶיךְ תְּהוֹם רַבָּה. וְאוֹתָן רוּחוֹת שֶׁלֹּא נִמְסְרוּ לְהִתְגַּשֵּׁם בָּעוֹלָם, וְנִרְאוֹת וְאֵינָן נִרְאוֹת, נִרְאוֹת כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וְאַחַר כָּךְ אוֹתָן רוּחוֹת שֶׁמְּשׁוֹטְטוֹת בָּעוֹלָם, וְאֵלֶּה עוֹמְדוֹת לְהַרְחִישׁ נִסִּים לִבְנֵי אָדָם, מִשּׁוּם שֶׁאֵלֶּה לֹא עוֹמְדִים בְּטִנֹּפֶת שֶׁל טֻמְאָה כָּל כָּךְ כְּמוֹ הָאֲחֲרִים, וְרוּחַ אַחַת מְמֻנָּה עֲלֵיהֶן, וְנִקְרֵאת נְסִירָ\"א, שֶׁהִתְנַסְּרָה מֵאוֹתָם צְדָדִים שֶׁטְּמֵאִים יוֹתֵר, וְאֵלּוּ פּוֹרְחִים בָּאֲוִיר וּמְרֵעִים לַצַּד שֶׁלָּהֶם, כְּדֵי לַעֲשׂוֹת נִסִּים לְאוֹתָם שֶׁבְּצַד הַקְּדֻשָּׁה.</p>\n<p>וּמֵהָרוּחַ הַזּוֹ שֶׁנֻּסְּרָה, שֶׁנִּקְרֵאת נְסִירָ\"א, מִמֶּנָּה יוֹצְאִים כַּמָּה צְדָדִים אֲחֵרִים נִפְרָדִים לְמִינֵיהֶם, וְכֻלָּם עוֹמְדִים שְׁלִיחִים בָּעוֹלָם, כָּל אֶחָד כָּרָאוּי לוֹ, עַד שֶׁהִתְמַנּוּ לְמַטָּה מְלָכִים וְשָׂרִים, וְאֵין לָהֶם קִיּוּם תְּמִידִי כְּאוֹתָם הָאֲחֵרִים שֶׁלְּמַעְלָה.</p>\n<p>בַּהֵיכָל הַזֶּה הִדָּבְקוּת שֶׁל צַד הַטֻּמְאָה וְכָל אוֹתָן הַתְּשׁוּקוֹת הַטְּמֵאוֹת, וּמְטַמְּאוֹת אֶת הָעוֹלָם. זֶהוּ שֶׁעָתִיד לְהוֹצִיא אֵשׁ בְּכָל רֶגַע וְשָׁעָה, וְאֵין מִי שֶׁעוֹמֵד לְפָנָיו. מִכָּאן יוֹצֵאת אֵשׁ שֶׁל רוּחַ חֲזָקָה לְמַטָּה לָדוּן בָּהּ אֶת רִשְׁעֵי הָעוֹלָם, וּמִכָּאן יוֹצֵאת רוּחַ לוֹהֶטֶת שֶׁהִיא אֵשׁ וְשֶׁלֶג, שֶׁנִּקְרֵאת צַלְמוֹן, כְּמוֹ שֶׁנֶּאֱמַר (תהלים סח) תַּשְׁלֵג בְּצַלְמוֹן.</p>\n<p>בַּהֵיכָל הַזֶּה קַיָּמִים אַרְבָּעָה פְתָחִים שֶׁנִּפְרָדִים לְאַרְבָּעָה צְדָדִים לַחוּץ, וְאֵלּוּ אוֹחֲזִים וְלֹא אוֹחֲזִים בְּצַד הַקְּדֻשָּׁה. לֹא נֶאֱחָז, אֶלָּא שֶׁנִּרְאֶה בְּאוֹתָם הַפְּתָחִים אוֹר שֶׁמֵּאִיר, וְהוּא מָקוֹם שֶׁמְּתֻקָּן בְּכָל פֶּתַח וּפֶתַח לְאוֹתָם חֲסִידֵי שְׁאָר הָעַמִּים, אוֹתָם שֶׁלֹּא הֵרֵעוּ לְיִשְׂרָאֵל וְהִשְׁתַּדְּלוּ עִמָּהֶם בֶּאֱמֶת. אֵלּוּ עוֹמְדִים בַּפְּתָחִים וְנָחִים שָׁם (מהצד הזה, ונחים מהצד הזה).</p>\n<p>בְּפֶתַח הַהֵיכָל הַזֶּה בָּאֶמְצַע, לַחוּץ, שִׁשָּׁה פְתָחִים שֶׁנֶּאֱחָזִים בַּהֵיכָל הַזֶּה, וְכֻלָּם אֲחוּזִים בּוֹ. כָּאן יֵשׁ חַלּוֹנוֹת פְּתוּחִים לַצַּד שֶׁל הָאוֹר הַקָּדוֹשׁ, וְאוֹתָם מְקוֹמוֹת מְתֻקָּנִים לְמַלְכֵי שְׁאָר הָעַמִּים, אוֹתָם שֶׁלֹּא הֵצִיקוּ לְיִשְׂרָאֵל, וְהֵגֵנּוּ עֲלֵיהֶם תָּמִיד. לְאֵלֶּה יֵשׁ כָּבוֹד מִשּׁוּם יִשְׂרָאֵל, וְנֶהֱנִים בְּאוֹתָהּ הָאֲפֵלָה שֶׁבָּהּ יוֹשְׁבִים מִתּוֹךְ אוֹר שֶׁמֵּאִיר מִצַּד הַקְּדֻשָּׁה, כְּמוֹ שֶׁנֶּאֱמַר, (ישעיה יד) כָּל מַלְכֵי גוֹיִם כֻּלָּם שָׁכְבוּ בְכָבוֹד.</p>\n<p>וְאִם עָשׂוּ צָרוֹת לְיִשְׂרָאֵל אוֹ שֶׁדָּחֲקוּ אוֹתָם, כַּמָּה הֵם שֶׁאוֹחֲזִים בָּהֶם, וְדָנִים אוֹתָם לְמַטָּה שָׁלֹשׁ פְּעָמִים בְּיוֹם בְּכַמָּה דִינִים מְשֻׁנִּים אֵלֶּה מֵאֵלֶּה, אֶת אוֹתָם מְלָכִים שֶׁהֵצִיקוּ לָהֶם, שֶׁנִּדּוֹנוּ בְּאוֹתוֹ הָעוֹלָם בְּכַמָּה דִינִים, וְכָל יוֹם וָיוֹם מְעִידִים עֵדוּת עַל יִשְׂרָאֵל וְעַל אֱמוּנָתָם, וְיוֹרְדִים לְמַטָּה וְנִדּוֹנִים שָׁם. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>עַד כָּאן שִׁבְעָה הֵיכָלוֹת, מְדוֹרֵי צַד הַטֻּמְאָה מִצַּד הַנָּחָשׁ. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁנִּצָּל מִמֶּנּוּ וּמִלְּחִישָׁתוֹ שֶׁלֹּא יִתְנַשֵּׁךְ מִמֶּנּוּ וְלֹא יַטִּיל בּוֹ אֶרֶס, שֶׁיָּמוּת בּוֹ. יֵשׁ לְהִשָּׁמֵר מִמֶּנּוּ מִכָּל הַצְּדָדִים, מִלְמַעְלָה וּמִלְּמַטָּה. מִי שֶׁנִּצָּל מֵהָרֹאשׁ, לֹא יִנָּצֵל מִן הַזָּנָב. כְּשֶׁמְּכוֹפֵף רֹאשׁ, זוֹקֵף אֶת הַזָּנָב, מַכֶּה וְהוֹרֵג.</p>\n<p>וְעִם כָּל זֶה, (קהלתי) אִם יִשֹּׁךְ הַנָּחָשׁ בְּלֹא לָחַשׁ. כְּמוֹ שֶׁשָּׁנִינוּ, נוֹטֵל רְשׁוּת וּמוֹצִיא נְשָׁמָה. מִשּׁוּם כָּךְ צָרִיךְ אָדָם לְהִשָּׁמֵר שֶׁלֹּא יֶחֱטָא לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּדֵי שֶׁלֹּא יִלְחֲשׁוּ לוֹ לְאוֹתוֹ נָחָשׁ שֶׁיִּנְשֹׁךְ וְיַהֲרֹג. (אשריהם אותם צדיקים שיודעים דרכים קדושות ללכת בהן, שלא ללכת אחר אותו נחש רע, הצד האחר הטמא, ונפרדים ממגו ולא מתפתים אחריו. אשריהם בעולם הזה, אשריהם בעולם הבא).</p>"],[9522011922,"<p>וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה (בראשית ב). עָפָר הוּא, וְלֹא חֹמֶר. עָפָר הוּא, וְיָשׁוּב לֶעָפָר, כְּמוֹ שֶׁנֶּאֱמַר (שם ג) כִּי עָפָר אַתָּה וְאֶל עָפָר תָּשׁוּב, (לאחר שחטא נעשה מזון לגחש, ולפיכך וכו') אַחַר שֶׁחָטָא. וּמִשּׁוּם כָּךְ כָּתוּב עַל הַנָּחָשׁ, (שם) וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךְ. עָפָר זֶה הוּא אָדָם, שֶׁכָּתוּב כִּי עָפָר אַתָּה וְגוֹ'. וּמִשּׁוּם כָּךְ כָּתוּב עָפָר וְלֹא כָתוּב אֲדָמָה וְלֹא חֹמֶר, וְכָתוּב (ישעיה סה) וְנָחָשׁ עָפָר לַחְמוֹ.</p>\n<p>עֵד שֶׁיִּתְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא וִיבַעֵר אֶת אוֹתָהּ רוּחַ טֻמְאָה מִן הָעוֹלָם, שֶׁכָּתוּב (שםכה) בִּלַּע הַמָּוֶת לָנֶצַח וְגוֹ'. וְיָקִים אֶת אוֹתוֹ עָפָר וְיָעִיר אוֹתוֹ לִשְׂמֹחַ בָּעוֹלָם, שֶׁכָּתוּב (שם כו) הָקִיצוּ וְרַנְּנוּ שֹׁכְנֵי עָפָר וְגוֹ'.</p>\n<p>כָּתוּב (בראשיתג) וְהַנָּחָשׁ הָיָה עָרוּם, וַהֲרֵי בֵּאַרְנוּ. אֲבָל הַצַּד שֶׁרוֹכֵב עָלָיו נוֹתֵן לוֹ כֹּחַ לִשְׁלֹט וּלְפַתּוֹת וּלְהַשְׂטִין. וְזֶהוּ סוֹד הַזָּכָר, שֶׁהֲרֵי הַזָּכָר שׁוֹלֵט עַל הַנְּקֵבָה וְנוֹתֵן בָּהּ כֹּחַ. הַשֶּׁמֶשׁ וְהַלְּבָנָה מְשַׁמְּשִׁים כְּאֶחָד, וְלֹא נִפְרָדִים לְעוֹלָמִים. חֹשֶׁךְ וַאֲפֵלָה מְשַׁמְּשִׁים כְּאֶחָד. הוּא חֹשֶׁךְ וְהִיא אֲפֵלָה, כְּמוֹ שֶׁנֶּאֱמַר, (שמות י) וַיְהִי חֹשֶׁךְ אֲפֵלָה. חֹשֶׁךְ וַעֲרָפֶל. מִשּׁוּם שֶׁיֵּשׁ חֹשֶׁךְ וְיֵשׁ חֹשֶׁךְ.</p>"],[9522011923,"<p>שָׁנִינוּ, מִי שֶׁרוֹאֶה גָּמָל בַּחֲלוֹמוֹ, מִיתָה נִגְזְרָה עָלָיו וְנִצַּל מִמֶּנָּה, מִשּׁוּם שֶׁהוּא צַד הַטֻּמְאָה, וְזֶהוּ (בראשית ג) קֵץ כָּל בָּשָׂר.</p>"],[9522011924,"<p>יוֹם אֶחָד הָיָה יוֹשֵׁב רַבִּי אֶלְעָזָר לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר רַבִּי אֶלְעָזָר, קֵץ כָּל בָּשָׂר הַזֶּה, הַאִם נֶהֱנֶה מֵאוֹתָם קָרְבָּנוֹת שֶׁהָיוּ יִשְׂרָאֵל מַקְרִיבִים עַל גַּבֵּי הַמִּזְבֵּחַ אוֹ לֹא? אָמַר לוֹ, כֻּלָּם הָיוּ נֶהֱנִים כְּאֶחָד, לְמַעְלָה וּלְמַטָּה.</p>\n<p>וּבֹא רְאֵה, כֹּהֲנִים וּלְוִיִּם וְיִשְׂרְאֵלִים, הֵם נִקְרָאִים אָדָם עִם חִבּוּר לְאוֹתָם רְצוֹנוֹת קְדוֹשִׁים שֶׁעוֹלִים מִתּוֹכָם, וְאוֹתוֹ שֶׂה אוֹ כֶבֶשׂ אוֹ אוֹתָהּ בְּהֵמָה שֶׁמַּקְרִיבִים, צָרִיךְ שֶׁטֶּרֶם תֻּקְרַב עַל הַמִּזְבֵּחַ, לְפָרֵשׁ עָלֶיהָ אֶת כָּל הַחֲטָאִים וְכָל הָעֲווֹנוֹת וְכָל הַהִרְהוּרִים הָרָעִים שֶׁעָשָׂה, וְאָז הִיא נִקְרֵאת בְּהֵמָה בַּכֹּל, בְּתוֹךְ אוֹתָם חֲטָאִים וְרָעוֹת וְהִ רְהוּרִים.</p>\n<p>כְּמוֹ שֶׁהַקָּרְבָּן לַעֲזָאזֵל, שֶׁכָּתוּב (ויקרא טז) וְהִתְוַדָּה עָלָיו אֶת כָּל עֲונֹת בְּנֵי יִשְׂרָאֵל וְגוֹ' - כָּךְ גַּם כָּאן. וּכְשֶׁעוֹלֶה עַל גַּבֵּי הַמִּזְבֵּחַ, מַגִּיעַ לוֹ עַל כָּל אֶחָד כִּפְלַיִם. וּמִשּׁוּם כָּךְ זֶה עוֹלֶה לִמְקוֹמוֹ, וְזֶה עוֹלֶה לִמְקוֹמוֹ. זֶה בְּסוֹד אָדָם, וְזֶה בְּסוֹד בְּהֵמָה. כְּמוֹ שֶׁנֶּאֱמַר, (תהלים לו) אָדָם וּבְהֵמָה תּוֹשִׁיעַ ה'.</p>\n<p>חֲבִיתִים וְכָל שְׁאָר הַמְּנָחוֹת, לְעוֹרֵר רוּחַ הַקֹּדֶשׁ בִּרְצוֹן הַכֹּהֵן, וְשִׁירַת הַלְוִיִּם, וּתְפִלַּת יִשְׂרָאֵל. וּבְאוֹתוֹ הֶעָנָן וְהַשֶּׁמֶן וְהַקֶּמַח שֶׁעוֹלִים, נִרְוִים וְנֶהֱנִים כָּל שְׁאָר בַּעֲלֵי הַדִּין שֶׁלֹּא יוּכְלוּ לִשְׁלֹט בְּאוֹתוֹ דִּין שֶׁנִּמְסָר לָהֶם, וְהַכֹּל בְּפַעַם אַחַת. בּא וּרְאֵה, הַכֹּל נַעֲשָׂה בְּסוֹד הָאֱמוּנָה, לֵהָנוֹת זֶה בָּזֶה, וְלַעֲלוֹת לְמַעְלָה מִי שֶׁצָּרִיךְ עַד אֵין סוֹף.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, הֲרִימוֹתִי יָדִי בִּתְפִלּוֹת לְמַעְלָה, שֶׁכְּשֶׁהָרָצוֹן הָעֶלְיוֹן לְמַעְלָה לְמַעְלָה, עוֹמֵד אוֹתוֹ רָצוֹן שֶׁלֹּא נוֹדָע וְלֹא נִתְפָּס לְעוֹלָמִים, הָרֹאשׁ הַנִּסְתָּר יוֹתֵר לְמַעְלָה, וְאוֹתוֹ רֹאשׁ מוֹצִיא מַה שֶּׁמּוֹצִיא, וְלֹא יָדוּעַ. וּמֵאִיר מַה שֶּׁמֵּאִיר, הַכֹּל בְּסֵתֶר.</p>\n<p>רְצוֹן הַמַּחֲשָׁבָה הָעֶלְיוֹנָה, לִרְדֹּף אַחֲרָיו וְלִהְיוֹת נָאוֹר מִמֶּנּוּ. מָסָךְ אֶחָד נִפְרָס, וּמִתּוֹךְ אוֹתוֹ מָסָךְ בִּרְדִיפַת אוֹתָהּ הַמַּחֲשָׁבָה הָעֶלְיוֹנָה, מַגִּיעַ וְלֹא מַגִּיעַ, עַד לְאוֹתוֹ מָסָךְ מֵאִיר מַה שֶּׁמֵּאִיר. וְאָז אוֹתָהּ מַחֲשָׁבָה עֶלְיוֹנָה מְאִירָה בְּאוֹר נִסְתָּר שֶׁלֹּא יָדוּעַ, וְהַמַּחֲשָׁבָה הַזּוֹ לֹא יוֹדַעַת.</p>\n<p>אָז מַכֶּה אוֹר הַמַּחֲשָׁבָה הַזֶּה שֶׁלֹּא נוֹדָע בְּהֶאָרַת (המסך) הַפְּרִישָׂה הַפְּרִיסָה שֶׁעוֹמֵד שֶׁמֵּאִיר מִמַּה שֶּׁלֹּא יָדוּעַ וְלֹא נוֹדַע וְלֹא הִתְגַּלָּה. וְאָז הֶאָרַת הַמַּחֲשָׁבָה הַזּוֹ שֶׁלֹּא נוֹדַעַת מַכָּה בְּהֶאָרַת הַמָּסָךְ, וּמְאִירִים כְּאֶחָד.</p>\n<p>וְנַעָשִׂים תִּשְׁעָה הֵיכָלוֹת, וְהַהֵיכָלוֹת אֵינָם אוֹרוֹת, וְאֵינָם רוּחוֹת, וְאֵינָם נְשָׁמוֹת, וְאֵין מִי שֶׁיַּעֲמֹד בָּהֶם. רְצוֹנָם שֶׁל כָּל תִּשְׁעָה הָאוֹרוֹת, כֻּלָּם עוֹמְדִים בְּמַחֲשָׁבָה, שֶׁהִיא אַחַת מֵהֶן בְּחֶשְׁבּוֹן, כֻּלָּם לִרְדֹּף אַחֲרֵיהֶם. בְּשָׁעָה שֶׁעוֹמְדִים בַּמַּחֲשָׁבָה, וְלֹא מֻשָּׂגִים וְלֹא נוֹדָעִים, וְאֵלּוּ לֹא עוֹמְדִים, לֹא בְּרָצוֹן וְלֹא בְּמַחֲשָׁבָה עֶלְיוֹנָה, תּוֹפְסִים בָּהּ וְלֹא תוֹפְסִים בָּהּ. בְּאֵלּוּ עוֹמְדִים כָּל סוֹדוֹת הָאֱמוּנָה, וְכָל אוֹתָם אוֹרוֹת מִסּוֹד הַמַּחֲשָׁבָה הָעֶלְיוֹנָה וָמַטָּה, כֻּלָּם נִקְרָאִים אֵין סוֹף. עַד כָּא מַגִּיעִים הָאוֹרוֹת וְלֹא מַגִּיעִים, וְלֹא נוֹדָעִים כָּאן לֹא רָצוֹן וְלֹא מַחֲשָׁבָה.</p>\n<p>כְּשֶׁמְּאִירָה הַמַּחֲשָׁבָה וְלֹא נוֹדָע מִמַּה מְּאִירָה, אָז מִתְלַבֶּשֶׁת וְנִסְתֶּרֶת בְּתוֹךְ הַבִּינָה, וּמֵאִיר מִי שֶׁמֵּאִיר, וְנִכְנָסִים זֶה בָּזֶה, עַד שֶׁכֻּלָּם נִכְלָלִים כְּאֶחָד.</p>\n<p>וּבְסוֹד הַקָּרְבָּן כְּשֶׁהוּא עוֹלֶה, הַכֹּל נִקְשָׁר זֶה בָּזֶה וּמֵאִיר זֶה בָּזֶה. אֲזַי כֻּלָּם עוֹמְדִים בַּעֲלִיָּה, וְהַמַּחֲשָׁבָה מִתְעַטֶּרֶת בָּאֵין סוֹף. אוֹתוֹ הָאוֹר שֶׁמְּאִירָה מִמֶּנּוּ הַמַּחֲשָׁבָה הָעֶלְיוֹנָה (שאינו יודע בה כלל), נִקְרָא אֵין סוֹף, שֶׁמִּמֶּנּוּ (וממנו) נִמְצֵאת וְעוֹמֶדֶת וּמְאִירָה לְמִי שֶׁמְּאִירָה, וְעַל זֶה הַכֹּל עוֹמֵד. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>בֹּא וּרְאֵה, הַצַּד הָאַחֵר הַזֶּה שֶׁנִּקְרָא (בראשיתו) קֵץ כָּל בָּשָׂר, כְּמוֹ שֶׁהַקֶּשֶׁר נִמְצָא לְמַעְלָה בְּשִׂמְחָה, אַף כָּךְ גַּם לְמַטָּה בְּשִׂמְחָה וְרָצוֹן, לְסַפֵּק אֶת הַכֹּל לְמַעְלָה וּלְמַטָּה, וְהָאֵם עוֹמֶדֶת עַל יִשְׂרָאֵל כָּרָאוּי.</p>\n<p>בֹּא וּרְאֵה, בְּכָל רֹאשׁ חֹדֶשׁ וְחֹדֶשׁ כְּשֶׁהַלְּבָנָה מִתְחַדֶּשֶׁת, נוֹתְנִים לַקֵּץ כָּל בָּשָׂר הַזֶּה חֵלֶק אֶחָד יָתֵר עַל הַקָּרְבָּנוֹת לְהִתְעַסֵּק בּוֹ וּמִשְׁתַּמֵּשׁ בְּחֶלְקוֹ, וְיִהְיֶה הַצַּד שֶׁל יִשְׂרָאֵל לְבַדָּם, כְּדֵי שֶׁיִּתְאַחֲדוּ עִם מַלְכָּם.</p>\n<p>וְזְהִוּ הַשָּׂעִיר, מִשּׁוּם שֶׁהוּא חֶלְקוֹ שֶׁל עֵשָׂו שֶׁכָּתוּב בּוֹ שָׂעִיר. (בראשית כז) הֵן עֵשָׂו אָחִי אִישׁ שָׂעִר. וְעַל כֵּן הוּא מִשְׁתַּמֵּשׁ בְּחֶלְקוֹ, וְיִשְׂרָאֵל מִשְׁתַּמְּשִׁים בְּחֶלְקָם. מִשּׁוּם כָּךְ כָּתוּב, (תהלים קלה) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ יִשְׂרָאֵל לִסְגֻלָּתוֹ.</p>\n<p>וּבֹא רְאֵה, קֵץ כָּל בָּשָׂר הַזֶּה, כָּל רְצוֹנוֹ אֵינוֹ אֶלָּא בְּבָשָׂר תָּמִיד. וּמִשּׁוּם כָּךְ תִּקּוּן הַבָּשָׂר תָּמִיד אֵלָיו, וְעַל כָּךְ נִקְרָא קֵץ כָּל בָּשָׂר. וּכְשֶׁהוּא שׁוֹלֵט, הוּא שׁוֹלֵט עַל הַגּוּף, וְלֹא עַל הַנְּשָׁמָה. הַנְּשָׁמָה עוֹלָה לִמְקוֹמָהּ, וְהַבָּשָׂר נִתָּן לַמָּקוֹם הַזֶּה, כְּמוֹ הַקָּרְבָּן - שֶׁהָרָצוֹן עוֹלֶה לְמָקוֹם אֶחָד, וְהַבָּשָׂר לְמָקוֹם אֶחָד.</p>\n<p>וְאָדָם שֶׁהוּא צַדִּיק, הוּא קָרְבָּן מַמָּשׁ לְכַפָּרָה, וְאַחר שֶׁאֵינוֹ צַדִּיק - לֹא, מִשּׁוּם שֶׁיֵּשׁ בּוֹ מוּם, שֶׁכָּתוּב (ויקרא כב) כִּי לֹא לְרָצוֹן יִהְיֶה לָכֶם. וְעַל כֵּן הַצַּדִּיק הוּא כַּפָּרָה בָּעוֹלָם וְקָרְבָּן מַמָּשׁ. אַשְׁרֵיהֶם הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>וַיְכַס הֶעָנָן אֶת אֹהֶל מוֹעֵד. שֶׁהֲרֵי כְּשֶׁכִּסָּה הֶעָנָן אֶת הַמִּשְׁכָּן, שָׁרְתָה שְׁכִינָה בָּאָרֶץ, וְהָעָבְרָה רוּחַ הַטֻּמְאָה, שֶׁהוּא (בראשית ו) קֵץ כָּל בָּשָׂר, מֵהָעוֹלָם, וְהִסְתַּלֵּק וְנִכְנַס לְנֶקֶב תְּהוֹם רַבָּה, וְרוּחַ קְדֻשָּׁה שָׁרְתָה עַל הָעוֹלָם, שֶׁכָּתוּב וַיְכַס הֶעָנָן אֶת אֹהֶל מוֹעֵד.</p>\n<p>וְכָתוּב וְלֹא יָכֹל מֹשֶׁה לָבוֹא אֶל אֹהֶל מוֹעֵד כִּי שָׁכַן עָלָיו הֶעָנָן. מִשּׁוּם שֶׁרוּחַ קְדֻשָּׁה שָׁרְתָה עַל הָעוֹלָם, וְרוּחַ הַטֻּמְאָה הִסְתַּלְּקָה, פְּרָט לְשֶׁהִמְשִׁיכוּ אוֹתוֹ אוֹתָם רְשָׁעִים כְּמִקֹּדֶם עַל הָעוֹלָם. שֶׁאִם הֵם לֹא הָיוּ מוֹשְׁכִים אוֹתוֹ עַל הָעוֹלָם, לֹא הָיָה נִמְצָא.</p>\n<p>וְלֶעָתִיד לָבֹא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִירוֹ מֵהָעוֹלָם, שֶׁכָּתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ כִּי ה' דִּבֵּר. וְכָתוּב (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ.</p>"]]});
